window.POEM_DB=window.POEM_DB||{};POEM_DB["wanganshi"]={"n":"王安石","dyn":"宋","poems":[{"t":"楼上望湖","f":"七言绝句","c":["楼上人肠渴欲枯，楼前终日望平湖。","无舟得入沧浪去，为问渔人得意无。"]},{"t":"东城","f":"五言律诗","c":["昔予出东城，初见垄上耕。","忽忽日北至，岁月良可惊。","虽云一草死，万物尚华荣。","谁能当此时，叹息微阴生。"]},{"t":"九日","f":"七言绝句","c":["九日无欢可得追，飘然随意历山陂。","蒋陵西曲风烟惨，也有黄花一两枝。"]},{"t":"九日赐宴琼林苑作","f":"七言绝句","c":["金明驰道柳参天，投老重来听管弦。","饱食太官还惜日，夕阳临水意茫然。"]},{"t":"人间","f":"七言绝句","c":["人间投老事纷纷，才薄何能强致君。","一马黄尘南陌路，眼中唯见北山云。"]},{"t":"入瓜步望扬州","f":"七言绝句","c":["落日平林一水边，芜城掩映祇苍然。","白头追想当时事，幕府青衫最少年。"]},{"t":"八公山","f":"七言绝句","c":["淮山但有八公名，鸿宝烧金竟不成。","身与仙人守都厕，可能鸡犬得长生。"]},{"t":"又代薛肇明一首","f":"七言绝句","c":["野水荒山寂寞滨，芳条弄色最关春。","故将明艳凌霜雪，未怕青腰玉女嗔。"]},{"t":"又次叶致远韵二首 其二","f":"七言绝句","c":["明时君尚富春秋，岂比衰翁远自投。","智略未应施畎亩，上前他日望吾丘。"]},{"t":"又次叶致远韵二首 其一","f":"七言绝句","c":["庵成有兴亦寻春，风暖荒莱步始匀。","若遇好花须一笑，岂妨迦叶杜多身。"]},{"t":"万事","f":"七言绝句","c":["万事黄粱欲熟时，世间谈笑漫追随。","鸡虫得失何须算，鹏鴳逍遥各自知。"]},{"t":"三品石","f":"七言绝句","c":["草没苔侵弃道周，误恩三品竟何酬。","国亡今日顽无耻，似为当年不与谋。"]},{"t":"上元夜戏作","f":"七言绝句","c":["马头乘兴尚谁先，曲巷横街一一穿。","尽道满城无国艳，不知朱户锁婵娟。"]},{"t":"与天骘宿清凉广惠僧舍","f":"七言绝句","c":["故人不惜马虺隤，许我年年一度来。","野馆萧条无准拟，与君封殖浪山梅。"]},{"t":"与北山道人","f":"七言绝句","c":["可惜昂藏一丈夫，生来不读半行书。","子云识字终投阁，幸是元无免破除。"]},{"t":"与北山道人","f":"七言绝句","c":["莳果疏泉带浅山，柴门虽设要常关。","别开小径连松路，祗与邻僧约往还。"]},{"t":"与宝觉宿龙华院三绝句 其二","f":"七言绝句","c":["世间投老断攀缘，忽忆东游已十年。","但有当时京口月，与公随我故依然。"]},{"t":"与宝觉宿龙华院三绝句 其三","f":"七言绝句","c":["与公京口水云閒，问月何时照我还。","邂逅我还还问月，何时照我宿金山。"]},{"t":"与宝觉宿龙华院三绝句 其一","f":"七言绝句","c":["老于陈迹倦追攀，但见幽人数往还。","忆我小诗成怅望，钟山只隔数重山。"]},{"t":"与徐仲元自读书台上定林","f":"五言绝句","c":["横绝潺湲度，深寻荦确行。","百年同逆旅，一壑我平生。"]},{"t":"与耿天骘会话","f":"七言绝句","c":["邯郸四十馀年梦，相对黄粱欲熟时。","万事祇如空鸟迹，怪君强记尚能追。"]},{"t":"与道原自何氏宅步至景德寺","f":"七言绝句","c":["前时偶见花如梦，红紫纷披竞浅深。","今日重来如梦觉，静无馀馥可追寻。"]},{"t":"与道原过西庄遂游宝乘","f":"七言绝句","c":["周颙宅作阿兰若，娄约身归窣堵坡。","今日隐侯孙亦老，偶寻陈迹到烟萝。"]},{"t":"与薛肇明奕棋赌梅花诗输一首","f":"七言绝句","c":["华发寻春喜见梅，一株临路雪培堆。","凤城南陌他年忆，杳杳难随驿使来。"]},{"t":"千蹊","f":"七言绝句","c":["千蹊百隧散林丘，图画风烟一色秋。","但有兴来随处好，杨朱何苦涕横流。"]},{"t":"口占示禅师","f":"五言绝句","c":["去岁别南岳，前年返泐潭。","临机一句子，今日遇同参。"]},{"t":"子贡","f":"七言绝句","c":["一来齐境助奸臣，去误骄王亦苦辛。","鲁国存亡宜有命，区区翻覆亦何人。"]},{"t":"山中","f":"五言绝句","c":["随月出山去，寻云相伴归。","春晨花上露，芳气著人衣。"]},{"t":"山陂","f":"七言绝句","c":["山陂院落今挼种，城郭楼台已放灯。","白发逢春唯有睡，睡间啼鸟亦生憎。"]},{"t":"山鸡","f":"五言绝句","c":["山鸡照渌水，自爱一何愚。","文采为世用，适足累形躯。"]},{"t":"山前","f":"七言绝句","c":["山前溪水涨潺潺，山后云埋不见山。","不趁雨来耕水际，即穿云去卧山间。"]},{"t":"山樱","f":"七言绝句","c":["山樱抱石荫松枝，比并馀花发最迟。","赖有春风嫌寂寞，吹香渡水报人知。"]},{"t":"马毙","f":"七言绝句","c":["恩宽一老寄松筠，晏卧东窗度几春。","天厩赐驹龙化去，谩容小蹇载闲身。"]},{"t":"中书即事","f":"七言绝句","c":["投老翻为世网婴，低徊终恐负平生。","何时白土冈头路，渡水穿云取次行。"]},{"t":"中年","f":"七言绝句","c":["中年许国邯郸梦，晚岁还家圹埌游。","南望青山知不远，五湖春草入扁舟。"]},{"t":"中牟","f":"七言绝句","c":["颓城百雉拥高秋，驱马临风想圣丘。","此道门人多未悟，尔来千载判悠悠。"]},{"t":"中茅峰石上徐锴篆字题名","f":"七言绝句","c":["百年风雨草苔昏，尚有当年墨法存。","祇恐终随峄碑尽，西风吹烧满秋原。"]},{"t":"中秋夕寄平甫诸弟","f":"七言绝句","c":["浮云吹尽数秋毫，爚爚金波满满醪。","千里得君诗挑战，夜坛谁敢将风骚。"]},{"t":"乌石","f":"七言绝句","c":["乌石冈边缭绕山，柴荆细路水云间。","吹花嚼蕊长来往，祗有春风似我闲。"]},{"t":"乌江亭","f":"七言绝句","c":["百战疲劳壮士哀，中原一败势难回。","江东子弟今虽在，肯与君王卷土来。"]},{"t":"乌塘","f":"七言绝句","c":["乌塘渺渺绿平堤，堤上行人各有携。","试问春风何处好，辛夷如雪柘冈西。"]},{"t":"书汜水关寺壁","f":"七言绝句","c":["汜水鸿沟楚汉间，跳兵走马百重山。","如何咫尺商于地，便有园公绮季闲。"]},{"t":"书何氏宅壁","f":"七言绝句","c":["有兴提鱼就公煮，此言虽在已三年。","皖灊终负幽人约，空对湖山坐惘然。"]},{"t":"书陈祈兄弟屋壁","f":"七言绝句","c":["千里归来倦宦身，欲寻田宅豫求邻。","能将孝友传家世，乡邑如君更几人。"]},{"t":"书定林院窗","f":"七言绝句","c":["竹鸡呼我出华胥，起灭篝灯拥燎炉。","试问道人何所梦，但言浑忘不言无。"]},{"t":"书堂","f":"七言绝句","c":["乌石冈头上冢归，柘冈西畔下书帷。","辛夷花发白如雪，万国春风庆历时。"]},{"t":"书湖阴先生壁二首 其一","f":"七言绝句","c":["茆檐长扫静无苔，花木成畦手自栽。","一水护田将绿绕，两山排闼送青来。"]},{"t":"书湖阴先生壁二首 其二","f":"七言绝句","c":["桑条索漠楝花繁，风敛馀香暗度垣。","黄鸟数声残午梦，尚疑身属半山园。"]},{"t":"书静照禅师塔","f":"七言绝句","c":["简老已归黄土陌，渊师今作白头翁。","百忧三十馀年事，陈迹山林草野中。"]},{"t":"五更","f":"七言绝句","c":["青灯隔幔映悠悠，小雨含烟凝不流。","祇听蛩声已无梦，五更桐叶强知秋。"]},{"t":"五柳","f":"五言绝句","c":["五柳柴桑宅，三杨白下亭。","往来无一事，长得见青青。"]},{"t":"元丰二年十月政公改路故作此诗","f":"七言绝句","c":["独龙东路得平冈，始免游人屐齿妨。","更有主林身半现，与公随转作阴凉。"]},{"t":"元日","f":"七言绝句","c":["爆竹声中一岁除，东风送暖入屠苏。","千门万户曈曈日，争插新桃换旧符。"]},{"t":"六年","f":"七言绝句","c":["六年湖海老侵寻，千里归来一寸心。","西望国门搔短发，九天宫阙五云深。"]},{"t":"午枕","f":"七言绝句","c":["午枕花前簟欲流，日催红影上帘钩。","窥人鸟唤悠飏梦，隔水山供宛转愁。"]},{"t":"午睡","f":"五言绝句","c":["檐日阴阴转，床风细细吹。","翛然残午梦，何许一黄鹂。"]},{"t":"壬子偶题","f":"七言绝句","c":["黄尘投老倦匆匆，故绕盆池种水红。","落日攲眠何所忆，江湖秋梦橹声中。"]},{"t":"壬戌五月与和叔同游齐安 其一","f":"七言绝句","c":["缲成白雪桑重绿，割尽黄云稻正青。","它日玉堂挥翰手，芳时同此赋林坰。"]},{"t":"壬戌正月晦与仲元自淮上复至齐安","f":"七言绝句","c":["风暖柴荆处处开，雪乾沙净水洄洄。","意行却得前年路，看尽梅花看竹来。"]},{"t":"天童山溪上","f":"七言绝句","c":["溪水清涟树老苍，行穿溪树踏春阳。","溪深树密无人处，唯有幽花渡水香。"]},{"t":"忆金陵三首 其三","f":"七言绝句","c":["追思陈迹故难忘，翠木苍藤水一方。","闻说精庐今更好，好随残汴理归艎。"]},{"t":"忆金陵三首 其二","f":"七言绝句","c":["烟云渺渺水茫茫，缭绕芜城一带长。","蒿目黄尘忧世事，追思陈迹故难忘。"]},{"t":"忆金陵三首 其一","f":"七言绝句","c":["覆舟山下龙光寺，玄武湖畔五龙堂。","想见旧时游历处，烟云渺渺水茫茫。"]},{"t":"文成","f":"七言绝句","c":["文成五利老纷纷，方丈蓬莱但可闻。","万里出师求宝马，飘然空有意凌云。"]},{"t":"无锡寄孙正之","f":"七言绝句","c":["健席高樯送病身，乱山荒陇障归津。","应须一曲千回首，西去论心更几人。"]},{"t":"日西","f":"七言绝句","c":["日西阶影转梧桐，帘卷青山簟半空。","金鸭火销沈水冷，悠悠残梦鸟声中。"]},{"t":"木末","f":"七言绝句","c":["木末北山烟冉冉，草根南涧水泠泠。","缲成白雪桑重绿，割尽黄云稻正青。"]},{"t":"木芙蓉","f":"七言绝句","c":["水边无数木芙蓉，露染燕脂色未浓。","正似美人初醉著，强抬青镜欲妆慵。"]},{"t":"王章","f":"七言绝句","c":["壮士轩昂非自谋，近臣当为国深忧。","区区女子无高意，追念牛衣暖即休。"]},{"t":"长干释普济坐化","f":"七言绝句","c":["投老唯公最故人，相寻长恨隔城闉。","百年俯仰随薪尽，画手空传净戒身。"]},{"t":"世上","f":"七言绝句","c":["范蠡五湖收远迹，管宁沧海寄馀生。","可怜世上风波恶，最有仁贤不敢行。"]},{"t":"世故","f":"七言绝句","c":["世故纷纷漫白头，欲寻归路更迟留。","钟山北绕无穷水，散发何时一钓舟。"]},{"t":"东冈","f":"七言绝句","c":["东冈岁晚一登临，共望长河映远林。","万窍怒呺风丧我，千波竞涌水无心。"]},{"t":"东江","f":"七言绝句","c":["东江木落水分洪，伐尽黄芦洲渚空。","南涧夕阳烟自起，西山漠漠有无中。"]},{"t":"东陂二首 其二","f":"七言绝句","c":["荷叶初开笋渐抽，东陂南荡正堪游。","无端垄上翛翛麦，横起寒风占作秋。"]},{"t":"东陂二首 其一","f":"七言绝句","c":["东陂风雨卧黄云，塍水翻沟隔垄分。","舂玉取新知不晚，腰镰今日已纷纷。"]},{"t":"东流顿令罢官阻风示文有按风伯奏天阍之语答以四句","f":"七言绝句","c":["令尹犀舟失去期，怃然凭几占文移。","劝君慎莫谗风伯，会有开帆破浪时。"]},{"t":"东皋","f":"七言绝句","c":["东皋揽结知新岁，西崦攀翻忆去年。","肘上柳生浑不管，眼前花发即欣然。"]},{"t":"代白发答","f":"七言绝句","c":["从衰得白自天机，未怪长青与愿违。","看取春条随日长，会须秋叶向人稀。"]},{"t":"代陈景元书于太一宫道院壁","f":"五言绝句","c":["官身有吏责，触事遇嫌猜。","野性岂堪此，庐山归去来。"]},{"t":"代答","f":"七言绝句","c":["破车伤马亦天成，所托虽高岂自营。","四海不无容足地，行人何事此中行。"]},{"t":"出定力院作","f":"七言绝句","c":["江上悠悠不见人，十年尘垢梦中身。","慇勤为解丁香结，放出枝间自在春。"]},{"t":"出郊","f":"七言绝句","c":["川原一片绿交加，深树冥冥不见花。","风日有情无处著，初回光景到桑麻。"]},{"t":"出金陵","f":"七言绝句","c":["白石冈头草木深，春风相与散衣襟。","浮云映郭留佳气，飞鸟随人作好音。"]},{"t":"出城","f":"七言绝句","c":["惯作野人多野兴，欲为时用少时材。","出城偶与沙尘背，转觉溪山入眼来。"]},{"t":"北山","f":"七言绝句","c":["北山输绿涨横陂，直堑回塘滟滟时。","细数落花因坐久，缓寻芳草得归迟。"]},{"t":"北山","f":"七言绝句","c":["刳木为舟数丈馀，卧看风月映芙蕖。","清香一阵浑无暑，时有惊榔跃出鱼。"]},{"t":"北山荐亭","f":"五言绝句","c":["西崦水泠泠，沿冈有荐亭。","自从春草长，遥见祇青青。"]},{"t":"北山道人栽松","f":"七言绝句","c":["阳坡风暖雪初融，度谷遥看积翠重。","磊砢拂天吾所爱，他生来此听楼钟。"]},{"t":"北陂杏花","f":"七言绝句","c":["一陂春水绕花身，花影妖饶各占春。","纵被春风吹作雪，绝胜南陌碾成尘。"]},{"t":"北望","f":"七言绝句","c":["欲望淮南更白头，杖藜萧飒倚沧洲。","可怜新月为谁好，无数晚山相对愁。"]},{"t":"发粟至石陂寺","f":"七言绝句","c":["蓦水穿山近更赊，三更燃火饭僧家。","乘田有秩难逃责，从事虽勤敢叹嗟。"]},{"t":"古寺","f":"七言绝句","c":["寥寥萧寺半遗基，游客经年断履綦。","犹有齐梁旧时殿，尘昏金像雨昏碑。"]},{"t":"句容道中","f":"七言绝句","c":["荒烟寒雨暮山重，草木冥冥但有风。","二十四年三往返，一身多在百忧中。"]},{"t":"台城寺侧独行","f":"七言绝句","c":["春山撩乱水纵横，篱落荒畦草自生。","独往独来山下路，笋舆看得绿阴成。"]},{"t":"叶致远置洲田以诗言志次其韵二首 其二","f":"七言绝句","c":["若将有限计无涯，自困真同算海沙。","随顺世缘聊戏剧，莫言河渚是吾家。"]},{"t":"叶致远置洲田以诗言志次其韵二首 其一","f":"七言绝句","c":["吟叹君诗久掉头，知君兴不负沧洲。","土山欲为羊昙赌，且可专心学奕秋。"]},{"t":"外厨遗火二首 其二","f":"七言绝句","c":["青烟散入夜云流，赤焰侵寻上瓦沟。","门户便疑能炙手，比邻何苦却焦头。"]},{"t":"外厨遗火二首 其一","f":"七言绝句","c":["灶鬼何为便赫然，似嫌刀机苦无膻。","图书得免同煨烬，却赖厨人凊不眠。"]},{"t":"对客","f":"七言绝句","c":["窗壁风回午枕凉，清谈相对一胡床。","心知帝力同天地，能使人间白日长。"]},{"t":"平甫如通州寄之","f":"七言绝句","c":["北山摇落水峥嵘，想见扬帆出广陵。","平世自无忧国事，求田应不忤陈登。"]},{"t":"归庵","f":"七言绝句","c":["稻畦藏水绿秧齐，松鬣初乾尚有泥。","纵蹇寻冈归独卧，东庵残梦午时鸡。"]},{"t":"归燕","f":"五言绝句","c":["马上逢归燕，知从何处来。","贪寻旧巢去，不带锦书回。"]},{"t":"永庆院送道原还仪真作诗要之","f":"七言绝句","c":["岁暮青条已见梅，馀花次第相争开。","淮南无此山林胜，作意春风更一来。"]},{"t":"汀沙","f":"七言绝句","c":["汀沙雪漫水溶溶，睡鸭残芦晻霭中。","归去北人多忆此，每家图画有屏风。"]},{"t":"汉武","f":"七言绝句","c":["壮士悲歌出塞频，中原萧瑟半无人。","君王不负长陵约，直欲功成赏汉臣。"]},{"t":"生日次韵南郭子二首 其二","f":"七言绝句","c":["寒逼清枝故有梅，草堂先对白头开。","残骸已若鸡年梦，犹见骚人几度来。"]},{"t":"生日次韵南郭子二首 其一","f":"七言绝句","c":["救黥医劓世无方，断简陈编付药房。","祝我寿龄君好语，毗耶一夜满城香。"]},{"t":"石竹花","f":"七言绝句","c":["麝香眠后露檀匀，绣在罗衣色未真。","斜倚细丛如有恨，冷摇数朵欲无春。"]},{"t":"示公佐","f":"七言绝句","c":["残生伤性老耽书，年少东来复起予。","各据槁梧同不寐，偶然闻雨落阶除。"]},{"t":"示王铎主簿","f":"七言绝句","c":["君正忙时我正闲，如何同得到钟山。","夷门二十年前事，回首黄尘一梦间。"]},{"t":"示永庆院秀老","f":"七言绝句","c":["禅房借枕得重攲，陈迹翛然尚有诗。","嗟我与公皆老矣，拂天松柏见栽时。"]},{"t":"示报宁长老","f":"七言绝句","c":["白下亭东鸣一牛，山林陂港净高秋。","新营枣棫我檀越，曾悟布毛谁比丘。"]},{"t":"示李叔时二首 其二","f":"七言绝句","c":["千山访我几摧辀，清坐来看十日留。","势利白头何足道，古人倾盖有绸缪。"]},{"t":"示李叔时二首 其一","f":"七言绝句","c":["知子鸣弦意在山，一官聊复戏人间。","能为白下东南尉，藜杖缁巾得往还。"]},{"t":"示宝觉二首 其二","f":"七言绝句","c":["重将坏色染衣裙，共卧钟山一坞云。","客舍黄粱今始熟，鸟残红柿昔曾分。"]},{"t":"示宝觉二首 其一","f":"七言绝句","c":["火暖窗明粥一盂，晨兴相对寂无鱼。","超然圣寺山林外，别有禅天好净居。"]},{"t":"示俞处士","f":"七言绝句","c":["鲁山眉宇人不见，只有歌辞来向东。","借问楼前踏于蔿，何如云卧唱松风。"]},{"t":"示俞秀老二首 其二","f":"七言绝句","c":["君诗何以解人愁，初日红蕖碧水流。","未怕元刘妨独步，每思陶谢与同游。"]},{"t":"示俞秀老二首 其一","f":"七言绝句","c":["不见故人天际舟，小亭残日更回头。","缲成白雪三千丈，细草孤云一片愁。"]},{"t":"示黄吉甫","f":"七言绝句","c":["三山半落青天外，势比凌歊宋武台。","尘世难逢开口笑，生前相遇且衔杯。"]},{"t":"示道原","f":"五言绝句","c":["久不在城市，少留心怅然。","幽芳可揽结，伫子饮云泉。"]},{"t":"示蔡天启三首 其三","f":"七言绝句","c":["身著青衫骑恶马，日驰三百尚嫌迟。","心源落落堪为将，却是君王未备知。"]},{"t":"记梦","f":"七言绝句","c":["月入千江体不分，道人非复世间人。","钟山南北安禅地，香火他时共两身。"]},{"t":"龙泉寺石井二首 其二","f":"七言绝句","c":["人传湫水未尝枯，满底苍苔乱发粗。","四海旱多霖雨少，此中端有卧龙无。"]},{"t":"龙泉寺石井二首 其一","f":"七言绝句","c":["山腰石有千年润，海眼泉无一日乾。","天下苍生待霖雨，不知龙向此中蟠。"]},{"t":"仲元女孙","f":"七言绝句","c":["双鬟嬉戏我庭除，争挽新花比并襦。","亲结香缨知不久，汝翁那更镊髭须。"]},{"t":"传神自赞","f":"七言绝句","c":["我与丹青两幻身，世间流转会成尘。","但知此物非他物，莫问今人犹昔人。"]},{"t":"传神自赞","f":"五言绝句","c":["此物非他物，今吾即故吾。","今吾如可状，此物若为摹。"]},{"t":"光宅寺","f":"七言绝句","c":["齐安孤起宋兴前，光宅相仍一水边。","蜂分蚁争今不见，故窠遗垤尚依然。"]},{"t":"见鹦鹉戏作四句","f":"七言绝句","c":["云木何时两翅翻，玉笼金锁祇烦冤。","真须强学人间语，举世无人解鸟言。"]},{"t":"兴国寺楼上作","f":"七言绝句","c":["松篁不动翠相重，日射流尘四散红。","地上行人愁暍死，那知高处有清风。"]},{"t":"再次前韵","f":"七言绝句","c":["秋灯一点映笼纱，好读楞严莫念家。","能了诸缘如梦事，世间唯有妙莲花。"]},{"t":"再题南涧楼","f":"五言绝句","c":["北山云漠漠，南涧水悠悠。","去此非吾愿，临分更上楼。"]},{"t":"同陈和叔游北山","f":"七言绝句","c":["春风荡屋雨填沟，东閤翛然拥罽裘。","邻壁黄粱炊未熟，唤回残梦有鸣驺。"]},{"t":"同熊伯通自定林过悟真二首 其二","f":"七言绝句","c":["城郭纷纷老倦寻，幅巾来寄北山岑。","长遭客子留连我，未快穿云涉水心。"]},{"t":"同熊伯通自定林过悟真二首 其一","f":"七言绝句","c":["与客东来欲试茶，倦投松石坐攲斜。","暗香一阵连风起，知有蔷薇涧底花。"]},{"t":"后殿牡丹未开","f":"七言绝句","c":["红襆未开知婉娩，紫囊犹结想芳菲。","此花似欲留人住，山鸟无端劝我归。"]},{"t":"吐绶鸡","f":"七言绝句","c":["樊笼寄食老低摧，组丽深藏肯自媒。","天日清明聊一吐，儿童初见互惊猜。"]},{"t":"字谜诗二首 其二","f":"七言绝句","c":["将军身是五行精，日日燕山望石城。","待得功成身又退，空将心腹为苍生。"]},{"t":"字谜诗二首 其一","f":"七言绝句","c":["兄弟四人两人大，一人立地三人坐。","家中更有一两口，任是凶年也得过。"]},{"t":"州桥","f":"七言绝句","c":["州桥蹋月想山椒，回首哀湍未觉遥。","今夜重闻旧呜咽，却看山月话州桥。"]},{"t":"戏长安岭石","f":"七言绝句","c":["附巘凭崖岂易跻，无心应合与云齐。","横身势欲填沧海，肯为行人惜马蹄。"]},{"t":"戏示蒋颖叔","f":"七言绝句","c":["扶衰南陌望长楸，灯火如星满地流。","但怪传呼杀风景，岂知禅客夜相投。"]},{"t":"戏城中故人","f":"七言绝句","c":["城郭山林路半分，君家尘土我家云。","莫吹尘土来污我，我自有云持寄君。"]},{"t":"戏赠育王虚白长老","f":"七言绝句","c":["白云山顶病禅师，昔日公卿各赠诗。","行尽四方年八十，却归荒寺有谁知。"]},{"t":"戏赠段约之","f":"七言绝句","c":["竹柏相望数十楹，藕花多处复开亭。","如何更欲通南埭，割我钟山一半青。"]},{"t":"戏赠湛源","f":"七言绝句","c":["恰有三百青铜钱，凭君为算小行年。","坐中亦有江南客，自断此生休问天。"]},{"t":"壬戌五月与和叔同游齐安 其二","f":"七言绝句","c":["据梧枝策事如毛，久苦诸君共此劳。","遥望南山堪散释，故寻西路一登高。"]},{"t":"扬子","f":"七言绝句","c":["千古雄文造圣真，眇然幽思入无伦。","他年未免投天禄，虚为新都著剧秦。"]},{"t":"扬子二首 其二","f":"七言绝句","c":["道真沉溺九流浑，独溯颓波讨得源。","岁晚强颜天禄阁，祇将奇字与人言。"]},{"t":"扬子二首 其一","f":"七言绝句","c":["儒者陵夷此道穷，千秋止有一扬雄。","当时荐口终虚语，赋拟相如却未工。"]},{"t":"朱朝议移法云兰","f":"五言绝句","c":["幽兰有佳气，千载閟山阿。","不出阿兰若，岂遭乾闼婆。"]},{"t":"杂咏五首 其一","f":"七言绝句","c":["勋业无成照水羞，黄尘入眼见山愁。","烟中漠漠江南岸，更与家人一少留。"]},{"t":"杂咏五首 其五","f":"七言绝句","c":["小雨萧萧润水亭，花风飐飐破浮萍。","看花听竹心无事，风竹声中作醉醒。"]},{"t":"杂咏五首 其四","f":"七言绝句","c":["乌石冈头踯躅红，东江柳色涨春风。","物华人意曾相值，永日留连草莽中。"]},{"t":"杂咏五首 其三","f":"七言绝句","c":["朝阳映屋拥书眠，梦想钟山一慨然。","投老安能长忍垢，会当归此濯寒泉。"]},{"t":"杂咏五首 其二","f":"七言绝句","c":["白头重到太宁宫，玉佩琼琚在眼中。","歌舞可怜人暗换，花开花落几春风。"]},{"t":"杂咏四首 其四","f":"五言绝句","c":["桃李石城坞，饷田三月时。","柴荆常自闭，花发少人知。"]},{"t":"杂咏四首 其三","f":"五言绝句","c":["證圣南朝寺，三年到百回。","不知墙下路，今日几荷开。"]},{"t":"杂咏四首 其二","f":"五言绝句","c":["已作湖阴客，如何更远游。","章江昨夜月，送我到扬州。"]},{"t":"杂咏四首 其一","f":"五言绝句","c":["故畦抛汝水，新垄寄钟山。","为问扬州月，何时照我还。"]},{"t":"次吴氏女子韵","f":"七言绝句","c":["孙陵西曲岸乌纱，知汝凄凉正忆家。","人世岂能无聚散，亦逢佳节且吹花。"]},{"t":"次张唐公韵","f":"七言绝句","c":["忆昨同追八马蹄，约公投老此山栖。","公乘白凤今何处，我适新年值白鸡。"]},{"t":"次昌叔韵","f":"七言绝句","c":["寄公无国寄钟山，垣屋青松晻霭间。","长以声音为佛事，野风萧飒水潺湲。"]},{"t":"次青阳","f":"五言绝句","c":["十载九华边，归期尚渺然。","秋风一乘传，更觉负林泉。"]},{"t":"次俞秀老韵","f":"七言绝句","c":["解我葱珩脱孟劳，暮年甘与子同袍。","新诗比旧增奇峭，若许追攀莫太高。"]},{"t":"次韵张仲通水轩","f":"七言绝句","c":["池雨含烟暝不收，草根长见水交流。","爱君古锦囊中句，解道今秋似去秋。"]},{"t":"次韵杏花三首 其三","f":"七言绝句","c":["看时高艳先惊眼，折处幽香易满怀。","野女强簪看亦丑，少教憔悴逐荆钗。"]},{"t":"次韵杏花三首 其二","f":"七言绝句","c":["心怜红蕊与移栽，不惜年年粪壤培。","风雨无时谁会得，欲教零乱强催开。"]},{"t":"次韵杏花三首 其一","f":"七言绝句","c":["只愁风雨劫春回，怕见枝头烂熳开。","野鸟不知人意绪，啄教零乱点苍苔。"]},{"t":"次韵和张仲通见寄三绝句 其二","f":"七言绝句","c":["收拾乾坤付一壶，世间无物直锱铢。","醉乡旧业抛来久，更欲因君稍问涂。"]},{"t":"次韵和张仲通见寄三绝句 其三","f":"七言绝句","c":["攲枕狂歌击唾壶，直将轩冕等锱铢。","醉乡岐路君知否，不似人间足畏涂。"]},{"t":"次韵和张仲通见寄三绝句 其一","f":"七言绝句","c":["高山流水意无穷，三尺空弦膝上桐。","默默此时谁会得，坐凭江阁看飞鸿。"]},{"t":"江上","f":"五言绝句","c":["江水漾西风，江花脱晚红。","离情被横笛，吹过乱山东。"]},{"t":"江上","f":"七言绝句","c":["江北秋阴一半开，晚云含雨却低回。","青山缭绕疑无路，忽见千帆隐映来。"]},{"t":"江口","f":"七言绝句","c":["六朝文物草连空，今古无端入望中。","江上晚来堪画处，参差烟树五湖东。"]},{"t":"江宁夹口二首 其二","f":"七言绝句","c":["日西江口落征帆，却望城楼泪满衫。","从此梦归无别路，破头山北北山南。"]},{"t":"江宁夹口二首 其一","f":"七言绝句","c":["钟山咫尺被云埋，何况南楼与北斋。","昨夜月明江上梦，逆随潮水到秦淮。"]},{"t":"江宁夹口三首 其三","f":"七言绝句","c":["落帆江口月黄昏，小店无灯欲闭门。","侧出岸沙枫半死，系船应有去年痕。"]},{"t":"江宁夹口三首 其二","f":"七言绝句","c":["月堕浮云水捲空，沧洲夜溯五更风。","北山草木何由见，梦尽青灯展转中。"]},{"t":"江宁夹口三首 其一","f":"七言绝句","c":["茅屋沧洲一酒旗，午烟孤起隔林炊。","江清日暖芦花转，祇似春风柳絮时。"]},{"t":"江宁府园示元度","f":"七言绝句","c":["画船南北水遥通，日暮幅巾篁竹中。","行到月台逢翠碧，背人飞过子城东。"]},{"t":"江雨","f":"七言绝句","c":["冥冥江雨湿黄昏，天入沧洲漫不分。","北涧欲通南涧水，南山正绕北山云。"]},{"t":"江梅","f":"七言绝句","c":["江南岁尽多风雪，也有红梅漏泄春。","颜色凌寒终惨澹，不应摇落始愁人。"]},{"t":"池上看金沙花数枝过酴醾架盛开","f":"五言绝句","c":["故作酴醾架，金沙祇谩栽。","似矜颜色好，飞度雪前开。"]},{"t":"池上看金沙花数枝过酴醾架盛开二首 其二","f":"七言绝句","c":["酴醾一架最先来，夹水金沙次第栽。","浓绿扶疏云对起，醉红撩乱雪争开。"]},{"t":"池上看金沙花数枝过酴醾架盛开二首 其一","f":"七言绝句","c":["午阴宽占一方苔，映水前年坐看栽。","红蕊似嫌尘染污，青条飞上别枝开。"]},{"t":"池雁","f":"七言绝句","c":["羽毛摧落向人愁，当食哀鸣似有求。","万里衡阳冬欲暖，失身元为稻粱谋。"]},{"t":"竹窗","f":"七言绝句","c":["竹窗红苋两三根，山色遥供水际门。","只我近知墙下路，能将屐齿记苔痕。"]},{"t":"红梅","f":"五言绝句","c":["春半花才发，多应不奈寒。","北人初未识，浑作杏花看。"]},{"t":"红梨","f":"七言绝句","c":["红梨无叶庇花身，黄菊分香委路尘。","岁晚苍官才自保，日高青女尚横陈。"]},{"t":"老嫌","f":"七言绝句","c":["老嫌智巧累形躯，欲就田翁学破除。","百岁用痴能几许，救吾黥劓可无馀。"]},{"t":"自定林过西庵","f":"七言绝句","c":["午鸡声不到禅林，柏子烟中静拥衾。","忽忆西岩道人语，杖藜乘兴得幽寻。"]},{"t":"舟过长芦","f":"七言绝句","c":["木落草摇洲渚昏，泊船深闭雨中门。","回灯只欲寻归梦，儿女纷纷强笑言。"]},{"t":"观明州图","f":"七言绝句","c":["明州城郭画中传，尚记西亭一舣船。","投老心情非复昔，当时山水故依然。"]},{"t":"访隐者","f":"七言绝句","c":["童子穿云晚未归，谁收松下著残棋。","先生醉卧落花里，春去人间总不知。"]},{"t":"达本","f":"七言绝句","c":["未能达本且归根，真照无知岂待言。","枯木岩前犹失路，那堪春入武陵原。"]},{"t":"过外弟饮","f":"七言绝句","c":["一自君家把酒杯，六年波浪与尘埃。","不知乌石冈边路，至老相寻得几回。"]},{"t":"过刘全美所居","f":"七言绝句","c":["西崦晴天得强扶，出林知有故人居。","数能过我论奇字，当复令公见异书。"]},{"t":"过法云寺","f":"七言绝句","c":["路过潮沟八九盘，招提雪脊隐云端。","金钿一一花总老，翠被重重山更寒。"]},{"t":"过徐城","f":"七言绝句","c":["七年五过徐城县，自笑皇皇此世间。","安得身如仓庾氏，一官能到子孙闲。"]},{"t":"过皖口","f":"七言绝句","c":["皖城西去百重山，陈迹今埋杳霭间。","白发行藏空自感，春风江水照衰颜。"]},{"t":"两生","f":"七言绝句","c":["两生才器亦超群，黑白何劳强自分。","好与骑奴同一处，此时俱事卫将军。"]},{"t":"丽泽门","f":"七言绝句","c":["丽泽门西日未俄，水明沙净卷纤罗。","绿琼洲渚青瑶嶂，付与诗工敢琢磨。"]},{"t":"伯牙","f":"七言绝句","c":["千载朱弦无此悲，欲弹孤绝鬼神疑。","故人舍我闭黄壤，流水高山心自知。"]},{"t":"初到金陵","f":"七言绝句","c":["江湖归不及花时，空绕扶疏绿玉枝。","夜直去年看蓓蕾，昼眠今日对纷披。"]},{"t":"初夏即事","f":"七言绝句","c":["石梁茅屋有弯埼，流水溅溅度两陂。","晴日暖风生麦气，绿阴幽草胜花时。"]},{"t":"初晴","f":"七言绝句","c":["幅巾慵整露苍华，度陇深寻一径斜。","小雨初晴好天气，晚花残照野人家。"]},{"t":"别方劭秘校","f":"五言绝句","c":["迢迢建业水，中有武昌鱼。","别后应相忆，能忘数寄书。"]},{"t":"别皖口","f":"七言绝句","c":["浮烟漠漠细沙平，飞雨溅溅嫩水生。","异日不知来照影，更添华发几千茎。"]},{"t":"别鄞女","f":"七言绝句","c":["行年三十已衰翁，满眼忧伤祇自攻。","今夜扁舟来诀汝，死生从此各西东。"]},{"t":"别灊阁","f":"七言绝句","c":["一溪清泻百山重，风物能留邴曼容。","后夜肯思幽兴极，月明孤影伴寒松。"]},{"t":"即事二首 其二","f":"五言绝句","c":["云从无心来，还向无心去。","无心无处寻，莫觅无心处。"]},{"t":"即事二首 其一","f":"五言绝句","c":["云从钟山起，却入钟山去。","借问山中人，云今在何处。"]},{"t":"即事五首 其五","f":"七言绝句","c":["春光冉冉归何处，细雨斜风作夜寒。","犹有数葩红好处，老年花似雾中看。"]},{"t":"即事五首 其四","f":"七言绝句","c":["遮莫邻鸡下五更，愿为闲客此闲行。","欲知前面花多少，颠倒青苔落绛英。"]},{"t":"即事五首 其三","f":"七言绝句","c":["幽栖地僻经过少，钟梵声中掩竹门。","唯有多情枝上雪，暗香浮动月黄昏。"]},{"t":"即事五首 其二","f":"七言绝句","c":["一树笼松玉刻成，游蜂多思正经营。","攀枝弄雪时回顾，还绕樱桃树下行。"]},{"t":"即事五首 其一","f":"七言绝句","c":["渐老逢春能几回，蓬门今始为君开。","莫嫌野外无供给，更向花前把一杯。"]},{"t":"即席","f":"七言绝句","c":["曲沼融融泮尽澌，暖烟笼瓦碧参差。","人情共恨春犹浅，不问寒梅有几枝。"]},{"t":"县舍西亭二首 其二","f":"七言绝句","c":["主人将去菊初栽，落尽黄花去却回。","到得明年官又满，不知谁见此花开。"]},{"t":"县舍西亭二首 其一","f":"七言绝句","c":["山根移竹水边栽，已见新篁破嫩苔。","可惜主人官便满，无因长向此徘徊。"]},{"t":"听泉亭","f":"七言绝句","c":["逗石穿云落涧隈，无风自到枕边来。","十年客底黄粱梦，一夜水声却唤回。"]},{"t":"吴任道说应举时事","f":"七言绝句","c":["县瓠城南陂水深，春泥满眼路岖嵚。","独骑瘦马冲残雨，前伴茫茫不可寻。"]},{"t":"呈陈和叔二首 其二","f":"七言绝句","c":["数椽庳屋茨生草，三亩荒园种晚蔬。","永日终无一杯酒，可能留得故人车。"]},{"t":"呈陈和叔二首 其一","f":"七言绝句","c":["数椽生草覆莓苔，一径墙阴斸雪开。","王吉囊衣新徙舍，杖藜从此为君来。"]},{"t":"园蔬","f":"七言绝句","c":["园蔬小摘嫩还抽，畦稻新舂滑欲流。","枕簟不移随处有，饱餐甘寝更无求。"]},{"t":"宋城道中","f":"七言绝句","c":["都城花木久知春，北路馀寒尚中人。","宿草连云青未得，东风无赖只惊尘。"]},{"t":"巫峡","f":"七言绝句","c":["神女音容讵可求，青山回抱楚宫楼。","朝朝暮暮空云雨，不尽襄王万古愁。"]},{"t":"张工部庙","f":"七言绝句","c":["使节纷纷下禁中，几人曾到此城东。","独君遗像今如在，庙食真须德与功。"]},{"t":"张良","f":"七言绝句","c":["汉业存亡俯仰中，留侯当此每从容。","固陵始议韩彭地，复道方图雍齿封。"]},{"t":"怀元度四首 其一","f":"七言绝句","c":["秋水才深四五尺，扁舟斗转疾于飞。","可怜物色阻携手，正是归时君不归。"]},{"t":"怀元度四首 其三","f":"七言绝句","c":["思君携手安能得，上尽重城更上楼。","时独看云泪横臆，长安不见使人愁。"]},{"t":"怀元度四首 其二","f":"七言绝句","c":["舍南舍北皆春水，恰似蒲萄初酦醅。","不见秘书心若失，百年多病独登台。"]},{"t":"怀旧","f":"七言绝句","c":["吹破春冰水放光，山花涧草百般香。","身闲处处堪行乐，何事低徊两鬓霜。"]},{"t":"怀张唐公","f":"七言绝句","c":["直谅多为世所排，有怀长向我前开。","暮年惆怅谁知此，南陌东阡独往来。"]},{"t":"怀府园","f":"七言绝句","c":["槐阴过雨尽新秋，盆底看云映水流。","忽忆小金山下路，绿蘋稀处看游鯈。"]},{"t":"怀钟山","f":"七言绝句","c":["投老归来供奉班，尘埃无复见钟山。","何须更待黄粱熟，始觉人间是梦间。"]},{"t":"拒霜花","f":"七言绝句","c":["落尽群花独自芳，红英浑欲拒严霜。","开元天子千秋节，戚里人家承露囊。"]},{"t":"杏园即事","f":"七言绝句","c":["蟠桃移种杏园初，红抹燕脂嫩脸苏。","闻道飘零落人世，清香得似旧时无。"]},{"t":"杏花","f":"七言绝句","c":["垂杨一径紫苔封，人语萧萧院落中。","独有杏花如唤客，倚墙斜日数枝红。"]},{"t":"杖藜","f":"七言绝句","c":["杖藜随水转东冈，兴罢还来赴一床。","尧桀是非时入梦，固知馀习未全忘。"]},{"t":"杨柳","f":"七言绝句","c":["杨柳杏花何处好，石梁茅屋雨初乾。","绿垂静路要深驻，红写清陂得细看。"]},{"t":"杨德逢送米与法云二老作此诗","f":"七言绝句","c":["卢仝不出憎流俗，我卜郊居避俗憎。","仝有邻僧来乞米，我今送米乞邻僧。"]},{"t":"沈坦之将归溧阳值雨留吾庐久之三首 其三","f":"五言绝句","c":["片云头上黑，淅淅野风秋。","室妇叹鸣鹳，分为两地愁。"]},{"t":"沈坦之将归溧阳值雨留吾庐久之三首 其二","f":"五言绝句","c":["檐雨乱淋幔，风悲兰杜秋。","相看更促膝，人老自多愁。"]},{"t":"沈坦之将归溧阳值雨留吾庐久之三首 其一","f":"七言绝句","c":["天雨萧萧滞茅屋，冷猿秋雁不胜悲。","床床屋漏无乾处，独立苍茫自咏诗。"]},{"t":"沟上梅花欲发","f":"七言绝句","c":["亭亭背暖临沟处，脉脉含芳映雪时。","莫恨夜来无伴侣，月明还见影参差。"]},{"t":"沟西","f":"七言绝句","c":["沟西直下看芙蕖，叶底三三两两鱼。","若比濠梁应更乐，近人浑不畏舂锄。"]},{"t":"沟港","f":"五言绝句","c":["沟港重重柳，山坡处处梅。","小舆穿麦过，狭径碍桑回。"]},{"t":"灵山","f":"七言绝句","c":["灵山宁与世为仇，斤斧侵凌自不休。","水玉比来闻长价，市人无数起相雠。"]},{"t":"芙蕖","f":"七言绝句","c":["芙蕖耐夏复宜秋，一种今年便满沟。","南荡东陂无此物，但随深浅见游鯈。"]},{"t":"花下","f":"五言绝句","c":["花下一壶酒，定将谁举杯。","雪英飞落近，疑是故人来。"]},{"t":"苏州道中顺风","f":"七言绝句","c":["北风一夕阻东舟，清早飞帆落虎丘。","运数本来无得丧，人生万事不须谋。"]},{"t":"苏秦","f":"七言绝句","c":["已分将身死势权，恶名磨灭几何年。","想君魂魄千秋后，却悔初无二顷田。"]},{"t":"證圣寺杏接梅花未开","f":"七言绝句","c":["红蕊曾游此地来，青青今见数枝梅。","只应尚有娇春意，不肯凌寒取次开。"]},{"t":"进字说二首 其二","f":"七言绝句","c":["鼎湖龙去字书存，开辟神机有圣孙。","湖海老臣无四目，谩将糟粕污脩门。"]},{"t":"进字说二首 其一","f":"七言绝句","c":["正名百物自轩辕，野老何知强讨论。","但可与人漫酱瓿，岂能令鬼哭黄昏。"]},{"t":"邵平","f":"七言绝句","c":["天下纷纷未一家，贩缯屠狗尚雄夸。","东陵岂是无能者，独傍青门手种瓜。"]},{"t":"陂麦","f":"七言绝句","c":["陂麦连云惨淡黄，绿阴门巷不多凉。","更无一片桃花在，借问春归有底忙。"]},{"t":"陇东西二首 其二","f":"七言绝句","c":["陇西流水向西流，自古相传到此愁。","添却征人无限泪，怪来呜咽已千秋。"]},{"t":"陇东西二首 其一","f":"七言绝句","c":["陇东流水向东流，不肯相随过陇头。","祗有月明西海上，伴人征戍替人愁。"]},{"t":"驴二首 其二","f":"七言绝句","c":["虽得康庄亦好还，每逢沟堑便知难。","由来此物非他物，莫道何曾似仰山。"]},{"t":"驴二首 其一","f":"七言绝句","c":["力侔龙象或难堪，唇比仙人亦未惭。","临路长鸣有真意，盘山弟子久同参。"]},{"t":"京城","f":"七言绝句","c":["三年衣上禁城尘，抚事怊然愧古人。","明月沧波秋万顷，扁舟长寄梦中身。"]},{"t":"净相寺","f":"五言绝句","c":["净相前朝寺，荒凉二十秋。","曾遭减劫坏，今遇胜缘修。"]},{"t":"卧闻","f":"五言绝句","c":["卧闻黄栗留，起见白符鸠。","坐引鱼儿戏，行将鹿女游。"]},{"t":"和文淑","f":"七言绝句","c":["天梯云栈蜀山岑，下视嘉陵水万寻。","我得一舟江上去，恐君东望亦伤心。"]},{"t":"和平父寄道光法师","f":"七言绝句","c":["欲见道人非一朝，杖藜无路到青霄。","千岩万壑排风雨，想对铜炉柏子烧。"]},{"t":"和张仲通忆钟陵二首 其二","f":"七言绝句","c":["逸少池边有一丘，西山南浦惯曾游。","残年归去终无乐，闻说章江即泪流。"]},{"t":"和张仲通忆钟陵二首 其一","f":"七言绝句","c":["一梦章江已十年，故人重见想皤然。","祇应两岸当时柳，能到春来尚可怜。"]},{"t":"和陈辅秀才金陵书事","f":"七言绝句","c":["南郭先生比鷾鸸，年年过我未愆期。","休论王谢当时事，大抵乌衣祇旧时。"]},{"t":"和净因有作","f":"七言绝句","c":["朝红一片堕窗尘，禅客翛然感此辰。","更觉城中芳意少，不如山野早知春。"]},{"t":"和叔招不往","f":"七言绝句","c":["门前秋水可扬舲，有意西寻白下亭。","只欲往来相邂逅，却嫌招唤苦丁宁。"]},{"t":"和叔雪中见过","f":"七言绝句","c":["捐书去寄老山林，无复追缘往事心。","忽值故人乘雪兴，玉堂前话得重寻。"]},{"t":"和耿天骘以竹冠见赠四首 其四","f":"七言绝句","c":["冠工新意斲檀栾，雾卷云烝久未乾。","遗我山林真自称，何须貂暖配金寒。"]},{"t":"和耿天骘以竹冠见赠四首 其三","f":"七言绝句","c":["玉润金明信好冠，错刀剜出藓纹乾。","不忘君惠常加首，要使欢盟未可寒。"]},{"t":"和耿天骘以竹冠见赠四首 其二","f":"七言绝句","c":["无物堪持比此冠，竹皮柔脆谷皮乾。","故人恋恋绨袍意，岂为哀怜范叔寒。"]},{"t":"和耿天骘以竹冠见赠四首 其一","f":"七言绝句","c":["竹根殊胜竹皮冠，欲著先须短发乾。","要使山林人共见，不持方帽禦风寒。"]},{"t":"和郭公甫","f":"七言绝句","c":["且欲相邀卧看山，扁舟自可送君还。","留连城郭今如此，知复何时伴我閒。"]},{"t":"和崔公度家风琴八首 其六","f":"七言绝句","c":["风来风去岂尝要，随分铿锵与寂寥。","不似人间古钟磬，从来文饰到今朝。"]},{"t":"和崔公度家风琴八首 其五","f":"七言绝句","c":["南风屋角响萧萧，白日帘垂坐寂寥。","爱此宫商有真意，与君倾耳尽今朝。"]},{"t":"和崔公度家风琴八首 其四","f":"七言绝句","c":["风铁相敲固可鸣，朔兵行夜响行营。","如何清世容高卧，翻作幽窗枕上声。"]},{"t":"和崔公度家风琴八首 其三","f":"七言绝句","c":["万物能鸣为不平，世间歌哭两营营。","君知此物心何欲，自信天机自有声。"]},{"t":"和崔公度家风琴八首 其二","f":"七言绝句","c":["帘幕无风起泬寥，谁悲精铁任飘飘。","随商应角知无意，不待歌成韵已消。"]},{"t":"和崔公度家风琴八首 其一","f":"七言绝句","c":["屋山终日信飘飘，似与幽人破寂寥。","为有机心须强聒，直教悬解始声消。"]},{"t":"和崔公度家风琴八首 其七","f":"七言绝句","c":["系身高处本无心，万窍鸣时有玉音。","欲作镆耶为物使，知君能笑不祥金。"]},{"t":"和崔公度家风琴八首 其八","f":"七言绝句","c":["疏铁檐间挂作琴，清风才到遽成音。","伊人欲问无真意，向道从来不博金。"]},{"t":"和惠思岁二日二绝 其二","f":"七言绝句","c":["沙砾藏春未放来，荒庭终日守陈荄。","遥怜草色裙腰绿，湖寺西南一径开。"]},{"t":"和惠思岁二日二绝 其一","f":"七言绝句","c":["懒读书来已数年，从人嘲我腹便便。","为嫌归舍儿童聒，故就僧房借榻眠。"]},{"t":"和惠思波上鸥","f":"五言绝句","c":["翩翩白凫鸥，汎汎水中游。","西来久不见，梦想在沧洲。"]},{"t":"和惠思韵二首 其一 醴泉观","f":"七言绝句","c":["邂逅相随一日闲，或缘香火共灵山。","夕阳兴罢黄尘陌，直似蓬莱堕世间。"]},{"t":"和惠思韵二首 其二 蝉","f":"七言绝句","c":["白下长干何可见，风尘愁杀庾兰成。","去年今日青松路，亦自闻蝉第一声。"]},{"t":"咏月","f":"七言绝句","c":["追随落日尽还生，点缀浮云暗又明。","江有蛟龙山虎豹，清光虽在不堪行。"]},{"t":"咏月三首 其三","f":"七言绝句","c":["一片清光万里兼，几回圆极又纤纤。","君看出没非无意，岂为辛勤养玉蟾。"]},{"t":"咏月三首 其二","f":"七言绝句","c":["江海清明上下兼，碧天遥见一毫纤。","此时只欲浮云尽，窟穴何妨有兔蟾。"]},{"t":"咏月三首 其一","f":"七言绝句","c":["寒光乍洗山川瑩，清影遥分草树纤。","万里更无云物动，中天只有兔随蟾。"]},{"t":"咏谷","f":"五言绝句","c":["可怜台上谷，转目已阴繁。","不解诗人意，何为乐彼园。"]},{"t":"咏菊二首 其二","f":"七言绝句","c":["院落秋深数菊丛，缘花错莫两三蜂。","蜜房岁晚能多少，酒盏重阳自不供。"]},{"t":"咏菊二首 其一","f":"七言绝句","c":["补落迦山传得种，阎浮檀水染成花。","光明一室真金色，复似毗耶长者家。"]},{"t":"图书","f":"七言绝句","c":["图书老矣尚纷披，神劓天黥以有知。","茅竹结蟠聊一愒，却寻三界外愚痴。"]},{"t":"夜直","f":"七言绝句","c":["金炉香尽漏声残，剪剪轻风阵阵寒。","春色恼人眠不得，月移花影上栏干。"]},{"t":"夜闻流水","f":"七言绝句","c":["千丈崩奔落石埼，秋声散入夜云悲。","州桥月下闻流水，不忘钟山独宿时。"]},{"t":"奉和景纯十四丈三绝 其三","f":"七言绝句","c":["藏春花木望中迷，水复山长道阻跻。","怊怅老年尘世累，无因重到武陵溪。"]},{"t":"奉和景纯十四丈三绝 其二","f":"七言绝句","c":["几年相约在林丘，眼见京江更阻游。","遗我珠玑何以报，恨无瑶玉与公舟。"]},{"t":"奉和景纯十四丈三绝 其一","f":"七言绝句","c":["身先诸老斡枢机，再见王门阖左扉。","但恨东归相值晚，岂知临别更心违。"]},{"t":"孟子","f":"七言绝句","c":["沉魄浮魂不可招，遗编一读想风标。","何妨举世嫌迂阔，故有斯人慰寂寥。"]},{"t":"学士院燕侍郎画图","f":"七言绝句","c":["六幅生绡四五峰，暮云楼阁有无中。","去年今日长干里，遥望钟山与此同。"]},{"t":"定林","f":"七言绝句","c":["定林青木老参天，横贯东南一道泉。","六月杖藜寻石路，午阴多处弄潺湲。"]},{"t":"定林所居","f":"七言绝句","c":["屋绕湾溪竹绕山，溪山却在白云间。","临溪放艇依山坐，溪鸟山花共我闲。"]},{"t":"定林院昭文斋","f":"七言绝句","c":["定林斋后鸣禽散，只有提壶守屋檐。","苦劝道人沽美酒，不应无意引陶潜。"]},{"t":"庚申正月游齐安","f":"七言绝句","c":["水南水北重重柳，山后山前处处梅。","未即此身随物化，年年长趁此时来。"]},{"t":"庚申正月游齐安有诗云水南水北重重柳壬戌正月再游","f":"七言绝句","c":["招提诗壁漫黄埃，忽忽笼纱两过梅。","老值白鸡能不死，复随春色破寒来。"]},{"t":"招元度","f":"七言绝句","c":["早知皆是自拘囚，年少因何有旅愁。","自是不归归便得，陆乘肩舆水乘舟。"]},{"t":"招叶致远","f":"七言绝句","c":["白下长干一水间，竹云新笋已斑斑。","明朝若有扁舟兴，落日潮生尚可还。"]},{"t":"招叶致远","f":"七言绝句","c":["山桃野杏两三栽，嫩叶商量细细开。","最是一年春好处，明朝有意抱琴来。"]},{"t":"招杨德逢","f":"七言绝句","c":["山林投老倦纷纷，独卧看云却忆君。","云尚无心能出岫，不应君更懒于云。"]},{"t":"杭州望湖楼回马上作呈玉汝乐道","f":"七言绝句","c":["水光山气碧浮浮，落日将归又少留。","从此祇应长入梦，梦中还与故人游。"]},{"t":"松江","f":"七言绝句","c":["来时还似去时天，欲道来时已惘然。","祇有松江桥下水，无情长送去来船。"]},{"t":"松间","f":"七言绝句","c":["偶向松间觅旧题，野人休诵北山移。","丈夫出处非无意，猿鹤从来不自知。"]},{"t":"泊姚江","f":"五言绝句","c":["轧轧橹声急，苍苍江日低。","吾行有定止，潮汐自东西。"]},{"t":"泊姚江","f":"七言绝句","c":["山如碧浪翻江去，水似青天照眼明。","唤取仙人来住此，莫教辛苦上层城。"]},{"t":"泊船瓜洲","f":"七言绝句","c":["京口瓜洲一水间，钟山祇隔数重山。","春风自绿江南岸，明月何时照我还。"]},{"t":"祈泽寺见许坚题诗","f":"七言绝句","c":["蔼蔼春风入水村，森森乔木映朱门。","高人遗迹空佳句，谁识旌阳后世孙。"]},{"t":"经局感言","f":"七言绝句","c":["自古能全已不才，岂论骐骥与驽骀。","放归自食情虽适，络首犹存亦可哀。"]},{"t":"若耶溪归兴","f":"七言绝句","c":["若耶溪上踏莓苔，兴罢张帆载酒回。","汀草岸花浑不见，青山无数逐人来。"]},{"t":"范雎","f":"七言绝句","c":["范雎相秦倾九州，一言立断魏齐头。","世间祸故不可忽，箦中死尸能报雠。"]},{"t":"范增二首 其二","f":"七言绝句","c":["鄛人七十漫多奇，为汉驱民了不知。","谁合军中称亚父，直须推让外黄儿。"]},{"t":"范增二首 其一","f":"七言绝句","c":["中原秦鹿待新羁，力战纷纷此一时。","有道吊民天即助，不知何用牧羊儿。"]},{"t":"试院中 其四","f":"七言绝句","c":["萧萧疏雨吹檐角，噎噎暝蛩啼草根。","闲却荒庭归未得，一灯明灭照黄昏。"]},{"t":"试院中 其一","f":"七言绝句","c":["白发无聊病更侵，移床卧竹向秋阴。","朝来雁背西风急，吹折江湖万里心。"]},{"t":"试院中","f":"七言绝句","c":["少时操笔坐中庭，子墨文章颇自轻。","圣世选材终用赋，白头来此试诸生。"]},{"t":"试院中 其三","f":"七言绝句","c":["青灯照我梦城西，坐上传觞把菊枝。","忽忽觉来头更白，隔墙闻语趁朝时。"]},{"t":"试院中 其二","f":"七言绝句","c":["咫尺淹留可奈何，东西虚共一姮娥。","阶前枣树应摇落，此夜清光得几多。"]},{"t":"金山","f":"七言绝句","c":["怪秘阴灵与护持，重丹复碧焕参差。","沧江见底应无日，万丈孤根世不知。"]},{"t":"金山三首 其三","f":"七言绝句","c":["天日苍茫海气深，一船西去此登临。","丹楼碧阁皆时事，只有江山古到今。"]},{"t":"金山三首 其二","f":"七言绝句","c":["波澜荡沃乾坤大，气象包藏水石閒。","祇有此中宜旷望，谁令天作海门山。"]},{"t":"金山三首 其一","f":"七言绝句","c":["北楫南樯泊四垂，共怜金碧烂参差。","孤根万丈沧波底，除却蛟龙世不知。"]},{"t":"金陵","f":"七言绝句","c":["金陵陈迹老莓苔，南北游人自往来。","最忆春风石城坞，家家桃杏过墙开。"]},{"t":"金陵即事三首 其三","f":"七言绝句","c":["昏黑投林晓更惊，背人相唤百般鸣。","柴门长闭春风暖，事外还能见鸟情。"]},{"t":"金陵即事三首 其二","f":"七言绝句","c":["结绮临春歌舞地，荒蹊狭巷两三家。","东风漫漫吹桃李，非复当时仗外花。"]},{"t":"金陵即事三首 其一","f":"七言绝句","c":["水际柴门一半开，小桥分路入青苔。","背人照影无穷柳，隔屋吹香并是梅。"]},{"t":"金陵报恩大师西堂方丈二首 其二","f":"七言绝句","c":["萧萧出屋千竿玉，霭霭当窗一炷云。","心力长年人事外，种花移石尚殷勤。"]},{"t":"金陵报恩大师西堂方丈二首 其一","f":"七言绝句","c":["檐花映日午风薰，时有黄鹂隔竹闻。","香灺一炉春睡足，上方车马正纷纷。"]},{"t":"金陵郡斋","f":"七言绝句","c":["谈经投老拚悠悠，为吏文书了即休。","深炷炉烟闭斋閤，卧听檐雨泻高秋。"]},{"t":"钓者","f":"七言绝句","c":["钓国平生岂有心，解甘身与世浮沉。","应知渭水车中老，自是君王著意深。"]},{"t":"雨未止正臣欲行以诗留之","f":"七言绝句","c":["纷纷应接使人愁，与子从容喜问酬。","他日故将泥自庇，今朝欲以雨相留。"]},{"t":"雨晴","f":"七言绝句","c":["晴明山鸟百般催，不待桃花一半开。","雨后绿阴空绕舍，总将春色付莓苔。"]},{"t":"鱼儿","f":"七言绝句","c":["绕岸车鸣水欲乾，鱼儿相逐尚相欢。","无人挈入沧江去，汝死那知世界宽。"]},{"t":"临津","f":"七言绝句","c":["临津艳艳花千树，夹径斜斜柳数行。","却忆金明池上路，红裙争看绿衣郎。"]},{"t":"促织","f":"七言绝句","c":["金屏翠幔与秋宜，得此年年醉不知。","祇向贫家促机杼，几家能有一絇丝。"]},{"t":"俞秀老忽然不见","f":"七言绝句","c":["忽去飘然游冶盘，共疑枝策在梁端。","禅心暂起何妨寂，道骨虽清不畏寒。"]},{"t":"信州回车馆中作二首 其二","f":"七言绝句","c":["山木漂摇卧弋阳，因思太白夜淋浪。","西窗一榻芭蕉雨，复似当时水绕床。"]},{"t":"信州回车馆中作二首 其一","f":"七言绝句","c":["太白山根秋夜静，乱泉深水绕床鸣。","病来空馆闻风雨，恰似当年枕上声。"]},{"t":"南荡","f":"七言绝句","c":["南荡东陂水渐多，陌头车马断经过。","钟山未放朝云散，奈此黄梅细雨何。"]},{"t":"南涧楼","f":"七言绝句","c":["扑扑烟岚绕四阿，物华终恨未能多。","故应陡起三千丈，始奈重山复岭何。"]},{"t":"城东寺菊","f":"七言绝句","c":["黄花漠漠弄秋晖，无数蜜蜂花上飞。","不忍独醒孤尔去，慇勤为折一枝归。"]},{"t":"城北","f":"七言绝句","c":["青青千里乱春袍，宿雨催红出小桃。","回首北城无限思，日酣川净野云高。"]},{"t":"宣州府君丧过金陵","f":"七言绝句","c":["百年难尽此身悲，眼入春风祗涕洟。","花发鸟啼皆有思，忍寻棠棣鹡鸰诗。"]},{"t":"将母","f":"五言绝句","c":["将母邗沟上，留家白纻阴。","月明闻杜宇，南北总关心。"]},{"t":"将次镇南","f":"七言绝句","c":["豫章江面朔风惊，浩荡帆船破浪行。","目送家山无几许，千年空想蟪蛄声。"]},{"t":"急足集句","f":"七言绝句","c":["年去年来来去忙，倚他门户傍他墙。","一封朝奏缘何事，断尽苏州刺史肠。"]},{"t":"春入","f":"七言绝句","c":["春入园林百草香，池塘冰散水生光。","身闲是处堪携手，何事低徊两鬓霜。"]},{"t":"春日","f":"七言绝句","c":["柴门照水见青苔，春绕花枝漫漫开。","路远游人行不到，日长啼鸟去还来。"]},{"t":"春日即事","f":"七言绝句","c":["池北池南春水生，桃花深处好闲行。","细思扰扰梦中事，何用悠悠身后名。"]},{"t":"春日席上","f":"七言绝句","c":["十年流落负归期，临水登山各有思。","今日樽前千万恨，不堪频唱鹧鸪辞。"]},{"t":"春风","f":"七言绝句","c":["春风过柳绿如缲，晴日烝红出小桃。","池暖水香鱼出处，一环清浪涌亭皋。"]},{"t":"春郊","f":"七言绝句","c":["青秧漫漫出初齐，鸡犬遥闻路却迷。","但见山花流出水，那知不是武陵溪。"]},{"t":"春雨","f":"五言绝句","c":["苦雾藏春色，愁霖病物华。","幽奇无可奈，强釂一杯霞。"]},{"t":"春雨","f":"七言绝句","c":["城云如梦柳僛僛，野水横来强满池。","九十日春浑得雨，故应留润作花时。"]},{"t":"春怨","f":"五言绝句","c":["扫地待花落，惜花轻著尘。","游人少春恋，踏去却寻春。"]},{"t":"春雪","f":"五言绝句","c":["春雪堕如筛，浑家醉不知。","泥留虎斗迹，愁杀路傍儿。"]},{"t":"昭文斋","f":"五言绝句","c":["我自山中客，何缘有此名。","当缘琴不鼓，人不见亏成。"]},{"t":"染云","f":"五言绝句","c":["染云为柳叶，剪水作梨花。","不是春风巧，何缘有岁华。"]},{"t":"柘冈","f":"七言绝句","c":["万事纷纷祇偶然，老来容易得新年。","柘冈西路花如雪，回首春风最可怜。"]},{"t":"残菊","f":"七言绝句","c":["黄昏风雨打园林，残菊飘零满地金。","擸得一枝犹好在，可怜公子惜花心。"]},{"t":"独行","f":"七言绝句","c":["朱颜日夜不如故，深感杏花相映红。","尽日独行春色里，醉吟谁肯伴衰翁。"]},{"t":"皇祐庚寅自临川如钱塘过宿此嘉祐戊辰自番阳归临川再宿金峰","f":"七言绝句","c":["十年再宿金峰下，身世飘然岂自知。","山谷有灵应笑我，纷纷南北欲何为。"]},{"t":"相州古瓦砚","f":"七言绝句","c":["吹尽西陵歌舞尘，当时屋瓦始称珍。","甄陶往往成今手，尚托声名动世人。"]},{"t":"省中二首 其二","f":"七言绝句","c":["大梁春雪满城泥，一马常瞻落日归。","身世自知还自笑，悠悠三十九年非。"]},{"t":"省中二首 其一","f":"七言绝句","c":["万事悠悠心自知，强颜于世转参差。","移床独卧秋风里，静看蜘蛛结网丝。"]},{"t":"省中沈文通厅事","f":"七言绝句","c":["竹上秋风吹网丝，角门常闭吏人稀。","萧萧一榻卷书坐，直到日斜骑马归。"]},{"t":"神物","f":"七言绝句","c":["神物登天扰可骑，如何孔甲但能羁。","当时若更无刘累，龙意茫然岂得知。"]},{"t":"秋云","f":"七言绝句","c":["秋云放雨静山林，万壑崩湍共一音。","欲记荒寒无善画，赖传悲壮有能琴。"]},{"t":"秋日","f":"七言绝句","c":["莫言草木未知秋，今日风云已自愁。","独傍黄尘骑一马，行看萧索听飕飕。"]},{"t":"草堂一上人","f":"五言绝句","c":["一公持一钵，想复度遥岑。","地瘦无黄犊，春来草更深。"]},{"t":"赴召道中","f":"七言绝句","c":["海气冥冥涨楚氛，汀洲回薄水横分。","青松十里钟山路，祇隔西南一片云。"]},{"t":"迸月","f":"五言绝句","c":["迸月川鱼跃，开云岭鸟翻。","径斜荒草恶，台废冶花繁。"]},{"t":"送丁廓秀才归汝阴","f":"五言绝句","c":["风驶柳条乾，驼裘未胜寒。","慇勤陌上日，为客暖征鞍。"]},{"t":"送丁廓秀才归汝阴二首 其二","f":"七言绝句","c":["西州行路日萧条，执手伤怀不自聊。","游子故乡终念返，岂能无意冶城潮。"]},{"t":"送丁廓秀才归汝阴二首 其一","f":"七言绝句","c":["好去翩然丁令威，昔人且在不应非。","淮云岂与辽天阔，想复留情故一归。"]},{"t":"送方劭秘校","f":"七言绝句","c":["南浦柔条拂地垂，攀翻聊寄我西悲。","武昌官柳年年好，他日春风忆此时。"]},{"t":"送王介学士知湖州","f":"七言绝句","c":["吴兴太守美如何，柳恽诗才未足多。","遥想郡人迎下担，白蘋洲渚正沧波。"]},{"t":"送王补之行风忽作因题四句于舟中","f":"五言绝句","c":["淮口西风急，君行定几时。","故应今夜月，未便照相思。"]},{"t":"送王彦鲁","f":"五言绝句","c":["北客怜同姓，南流感似人。","相分岂相忘，临路更情亲。"]},{"t":"送吕望之","f":"五言绝句","c":["池散田田碧，台敷灼灼红。","年华岂有尽，心赏亦无穷。"]},{"t":"送张明甫","f":"七言绝句","c":["觥船一棹百分空，十五年前此会同。","南去北来人自老，桃花依旧笑春风。"]},{"t":"送李生白华岩修道","f":"七言绝句","c":["白华岩主是金仙，假作山僧学道禅。","珍重此行吾不及，为传消息结因缘。"]},{"t":"送陈令","f":"七言绝句","c":["长溪流水碧潺潺，古木苍藤暗两山。","把臂道人今在否，长官白首尚人间。"]},{"t":"送陈景初","f":"七言绝句","c":["惨淡淮山水墨秋，行人不饮奈离愁。","药囊直入长安市，谁识柴车载伯休。"]},{"t":"送陈景初金陵持服举族贫病烦君药石之功","f":"五言绝句","c":["举族贫兼病，烦君药石功。","长安何日到，一一问归鸿。"]},{"t":"送陈靖中舍归武陵","f":"七言绝句","c":["知君欲上武陵溪，水自东流人自西。","到日桃花应已谢，想君应不为花迷。"]},{"t":"送和甫至龙安微雨因寄吴氏女子","f":"七言绝句","c":["荒烟凉雨助人悲，泪染衣巾不自知。","除却春风沙际绿，一如看汝过江时。"]},{"t":"送和甫至龙安暮归","f":"七言绝句","c":["隐隐西南月一钩，春风落日澹如秋。","房栊半掩无人语，鼓角声中始欲愁。"]},{"t":"送河中通判朱郎中迎母东归","f":"七言绝句","c":["綵衣东笑上归船，莱氏欢娱在晚年。","嗟我白头生意尽，看君今日更悽然。"]},{"t":"送耿天骘至渡口","f":"七言绝句","c":["雪云江上语依依，不比寻常恨有违。","四十馀年心莫逆，故人如我与君稀。"]},{"t":"送望之赴临江","f":"五言绝句","c":["黄雀有头颅，长行万里馀。","想因君出守，暂得免包苴。"]},{"t":"送黄吉父将赴南康官归金溪三首 其三","f":"七言绝句","c":["岁晚相逢喜且悲，莫占风日恨归迟。","我如逆旅当去客，复会有无那得知。"]},{"t":"送黄吉父将赴南康官归金溪三首 其二","f":"七言绝句","c":["还家一笑即芳辰，好与名山作主人。","邂逅五湖乘兴往，相邀锦绣谷中春。"]},{"t":"送黄吉父将赴南康官归金溪三首 其一","f":"七言绝句","c":["柘冈西路白云深，想子东归得重寻。","亦见旧时红踯躅，为言春至每伤心。"]},{"t":"送僧惠思归钱塘","f":"七言绝句","c":["渌净堂前湖水渌，归时正复有荷花。","花前亦见馀杭姥，为道仙人忆酒家。"]},{"t":"送僧游天台","f":"七言绝句","c":["天台一万八千丈，岁晏老僧携锡归。","前程好景解吟否，密雪乱云缄翠微。"]},{"t":"适意","f":"七言绝句","c":["一灯相伴十馀年，旧事陈言知几编。","到了不如无累后，困来颠倒枕书眠。"]},{"t":"重过余婆冈市","f":"七言绝句","c":["忆我东游未有须，扶衰重此驻肩舆。","市中年少今谁在，鲁叟当街六十馀。"]},{"t":"重将","f":"七言绝句","c":["重将白发旁墙阴，陈迹茫然不可寻。","花鸟总知春烂熳，人间独自有伤心。"]},{"t":"钟山晚步","f":"七言绝句","c":["小雨轻风落楝花，细红如雪点平沙。","槿篱竹屋江村路，时见宜城卖酒家。"]},{"t":"哭张唐公","f":"七言绝句","c":["堂邑山林久寂寥，属车前日驻鸡翘。","冥冥独凤随云雾，南陌空闻引葬箫。"]},{"t":"宰嚭","f":"七言绝句","c":["谋臣本自系安危，贱妾何能作祸基。","但愿君王诛宰嚭，不愁宫里有西施。"]},{"t":"徐秀才园亭","f":"七言绝句","c":["茂松脩竹翠纷纷，正得山阿与水濆。","笑傲一生虽自乐，有司还欲选方闻。"]},{"t":"悟真院","f":"七言绝句","c":["野水从横漱屋除，午窗残梦鸟相呼。","春风日日吹香草，山北山南路欲无。"]},{"t":"悯儒坑","f":"七言绝句","c":["智力区区不为身，欲将何力助强秦。","只应埋没千秋后，更足诗书发冢人。"]},{"t":"晏望驿释舟走信州","f":"七言绝句","c":["病起行山山更险，下穷溪谷上通天。","乘高欲作东南望，青壁松杉满我前。"]},{"t":"殊胜渊师八十馀因见访问之近来如何答曰随缘而已至示寂作是诗","f":"七言绝句","c":["寄托荒山鬼与邻，一生黄卷不离身。","百年薪尽随缘去，莫学缁郎更误人。"]},{"t":"海棠花","f":"七言绝句","c":["绿娇隐约眉轻扫，红嫩妖饶脸薄妆。","巧笔写传功未尽，清才吟咏兴何长。"]},{"t":"病中睡起折杏花数枝二首 其二","f":"五言绝句","c":["独卧无心起，春风闭寂寥。","鸟声谁唤汝，屋角故相撩。"]},{"t":"病中睡起折杏花数枝二首 其一","f":"五言绝句","c":["独卧南窗榻，翛然五六旬。","已闻邻杏好，故挽一枝春。"]},{"t":"病起过宝觉","f":"五言绝句","c":["执手乍欣怅，霜毛应更新。","依然旧童子，却想梦前身。"]},{"t":"真州马上作","f":"七言绝句","c":["身随饥马日中行，眼入风沙困欲盲。","心气已劳形亦弊，自怜于世欲何营。"]},{"t":"真州东园作","f":"七言绝句","c":["十年历遍人间事，却绕新花认故丛。","南北此身知几日，山川长在泪痕中。"]},{"t":"破冢二首 其二","f":"七言绝句","c":["残椁穿来欲几春，萧萧长草没骐驎。","墦间或有樵苏客，未必他年醉饱人。"]},{"t":"破冢二首 其一","f":"七言绝句","c":["埋没残碑草自春，旋风时出地中尘。","墦间夜半分珠玉，犹是当时乞祭人。"]},{"t":"祥云","f":"七言绝句","c":["冰入春风涨御沟，上林花气欲飞浮。","未央屋瓦犹残雪，却为祥云映日流。"]},{"t":"离升州作","f":"五言绝句","c":["相看不忍发，惨澹暮潮平。","语罢更携手，月明洲渚生。"]},{"t":"离升州作","f":"七言绝句","c":["残菊冥冥风更吹，雨如梅子欲黄时。","相看握手总无语，愁满眼前心自知。"]},{"t":"离蒋山","f":"五言绝句","c":["出谷频回首，逢人更断肠。","桐乡岂爱我，我自爱桐乡。"]},{"t":"离鄞至菁江东望","f":"七言绝句","c":["村落萧条夜气生，侧身东望一伤情。","丹楼碧阁无处所，祇有溪山相照明。"]},{"t":"秣陵道中口占二首 其二","f":"五言绝句","c":["岁熟田家乐，秋风客自悲。","茫茫曲城路，归马日斜时。"]},{"t":"秣陵道中口占二首 其一","f":"五言绝句","c":["经世才难就，田园路欲迷。","慇勤将白发，下马照青溪。"]},{"t":"秦淮泛舟","f":"七言绝句","c":["强扶衰病牵淮舸，尚怯春风溯午潮。","花与新吾如有意，山于何处不相招。"]},{"t":"耿天骘许浪山千叶梅见寄","f":"七言绝句","c":["闻有名花即谩栽，慇勤准拟故人来。","故人岁岁相逢晚，知复同看几度开。"]},{"t":"封舒国公三首 其三","f":"七言绝句","c":["开国桐乡已白头，国人谁复记前游。","故情但有吴塘水，转入东江向我流。"]},{"t":"封舒国公三首 其二","f":"七言绝句","c":["桐乡山远复川长，紫翠连城碧满隍。","今日桐乡谁爱我，当时我自爱桐乡。"]},{"t":"封舒国公三首 其一","f":"七言绝句","c":["陈迹难寻天柱源，疏封投老误明恩。","国人欲识公归处，杨柳萧萧白下门。"]},{"t":"荷花","f":"七言绝句","c":["亭亭风露拥川坻，天放娇娆岂自知。","一舸超然他日事，故应将尔当西施。"]},{"t":"被召作","f":"五言绝句","c":["荣禄嗟何及，明恩愧未酬。","欲寻西掖路，更上北山头。"]},{"t":"诸葛武侯","f":"七言绝句","c":["恸哭杨颙为一言，馀风今日更谁传。","区区庸蜀支吴魏，不是虚心岂得贤。"]},{"t":"读开成事","f":"七言绝句","c":["奸罔纷纷不为明，有心天下共无成。","空令执笔螭头者，日记君臣口舌争。"]},{"t":"读汉书","f":"七言绝句","c":["京房刘向各称忠，诏狱当时迹自穷。","毕竟论心异恭显，不妨迷国略相同。"]},{"t":"读汉功臣表","f":"七言绝句","c":["汉家分土建忠良，铁券丹书信誓长。","本待山河如带砺，何缘菹醢赐侯王。"]},{"t":"读后汉书","f":"七言绝句","c":["锢党纷纷果是非，当时高士见精微。","可怜窦武陈蕃辈，欲与天争汉鼎归。"]},{"t":"读唐书","f":"七言绝句","c":["志士无时亦少成，中才随世就功名。","并汾诸子何为者，坐与文皇立太平。"]},{"t":"读维摩经有感","f":"七言绝句","c":["身如泡沫亦如风，刀割香涂共一空。","宴坐世间观此理，维摩虽病有神通。"]},{"t":"读蜀志","f":"七言绝句","c":["千载纷争共一毛，可怜身世两徒劳。","无人语与刘玄德，问舍求田意最高。"]},{"t":"谁将","f":"七言绝句","c":["谁将石黛染春潮，复撚黄金作柳条。","西崦东沟从此好，笋舆追我莫辞遥。"]},{"t":"贾生","f":"七言绝句","c":["一时谋议略施行，谁道君王薄贾生。","爵位自高言尽废，古来何啻万公卿。"]},{"t":"载酒","f":"七言绝句","c":["载酒欲寻江上舟，出门无路水交流。","黄昏独倚春风立，看却花开触地愁。"]},{"t":"辱井","f":"七言绝句","c":["结绮临春草一丘，尚残宫井戒千秋。","奢淫自是前王耻，不到龙沈亦可羞。"]},{"t":"郭解","f":"七言绝句","c":["藉交唯有不赀恩，汉法归成弃市论。","平日五陵多任侠，可能推刃报王孙。"]},{"t":"铁幢浦","f":"七言绝句","c":["忆昨初为海上行，日斜来往看潮生。","如今身是西归客，回首山川觉有情。"]},{"t":"骊山","f":"七言绝句","c":["六籍燃除士不磨，骊山如此盗兵何。","五陵珠玉归人世，却为诗书发冢多。"]},{"t":"鸱","f":"七言绝句","c":["依倚秋风气象豪，似欺黄雀在蓬蒿。","不知羽翼青冥上，腐鼠相随势亦高。"]},{"t":"偶书","f":"七言绝句","c":["穰侯老擅关中事，长恐诸侯客子来。","我亦暮年专一壑，每逢车马便惊猜。"]},{"t":"偶书","f":"楚辞体","c":["雄也营身足，聃兮误汝多。","捐书知圣已，绝学奈禽何。"]},{"t":"偿薛肇明秀才桤木","f":"七言绝句","c":["濯锦江边木有桤，小园封植伫华滋。","地偏或免桓魋伐，岁晚聊同庾信移。"]},{"t":"勘会贺兰溪主","f":"七言绝句","c":["贺兰溪上几株松，南北东西有几峰。","买得住来今几日，寻常谁与坐从容。"]},{"t":"商鞅","f":"七言绝句","c":["自古驱民在信诚，一言为重百金轻。","今人未可非商鞅，商鞅能令政必行。"]},{"t":"寄四侄旊二首 其二","f":"七言绝句","c":["一日东冈上几回，百重云水隔苏台。","遥知别后诗无数，黄犬归时总寄来。"]},{"t":"寄四侄旊二首 其一","f":"七言绝句","c":["数篇持往助欢咍，想见封题手自开。","春草已生无好句，阿连空复梦中来。"]},{"t":"寄伯兄","f":"七言绝句","c":["身留海上去何时，祇看春鸿北向飞。","安得先生同一饮，蕨芽香嫩䱥鱼肥。"]},{"t":"寄吴氏女子","f":"七言绝句","c":["梦想平生在一丘，暮年方此得优游。","江湖相忘真鱼乐，怪汝长谣特地愁。"]},{"t":"寄李道人","f":"七言绝句","c":["李生富汉亦贫儿，人不知渠只我知。","跳过六轮中耍峭，养成三界外愚痴。"]},{"t":"寄沈道原","f":"七言绝句","c":["城郭千家一弹丸，蜀冈拥肿作蛇蟠。","眼前不道无苍翠，偷得钟山隔水看。"]},{"t":"寄和甫","f":"七言绝句","c":["水村悲喜拆书看，闻道并州九月寒。","忆得此时花更好，举家怜女不同盘。"]},{"t":"寄育王大觉禅师","f":"七言绝句","c":["山木悲鸣水怒流，百虫专夜思高秋。","道人方丈应无梦，想复长吟拟慧休。"]},{"t":"寄金陵传神者李士云","f":"七言绝句","c":["衰容一见便疑真，李子挥毫故有神。","欲去钟山终不忍，谢渠分我死前身。"]},{"t":"寄显道","f":"七言绝句","c":["舟约刀头止岁前，故人专使手书传。","出门江口问消息，极目寒沙空渺然。"]},{"t":"寄茶与平甫","f":"七言绝句","c":["碧月团团堕九天，封题寄与洛中仙。","石楼试水宜频啜，金谷看花莫漫煎。"]},{"t":"寄茶与和甫","f":"七言绝句","c":["綵绛缝囊海上舟，月团苍润紫烟浮。","集英殿里春风晚，分到并门想麦秋。"]},{"t":"寄道光大师","f":"七言绝句","c":["秋雨漫漫夜复朝，可嗟蔀屋望重霄。","遥知宴坐无馀念，万事都从劫火烧。"]},{"t":"寄韩持国","f":"七言绝句","c":["渌绕宫城漫漫流，鹅黄小蝶弄春柔。","问知公子朝陵去，归得花时却自愁。"]},{"t":"寄碧岩道光法师","f":"七言绝句","c":["去马来车扰扰尘，自难长寄水云身。","碧岩后主今为客，何况开山说法人。"]},{"t":"寄蔡天启","f":"七言绝句","c":["杖藜缘堑复穿桥，谁与高秋共寂寥。","伫立东冈一搔首，冷云衰草暮迢迢。"]},{"t":"寄题杭州明庆院修广师明碧轩","f":"七言绝句","c":["明碧轩南竹数丛，别来江外几秋风。","道人无复人间世，嗟我今为白发翁。"]},{"t":"崇政殿后春晴即事","f":"七言绝句","c":["悠悠独梦水西轩，百舌枝头语更繁。","山鸟不应知地禁，亦逢春暖即啾喧。"]},{"t":"悼慧休","f":"五言绝句","c":["休公遂不起，难料复难忘。","玉骨随薪尽，空留一分香。"]},{"t":"惜春","f":"七言绝句","c":["满城风雨满城尘，盖紫藏红漫惜春。","春去自应无觅处，可怜多少惜花人。"]},{"t":"斜径","f":"七言绝句","c":["斜径偶通南埭路，数家遥对北山岑。","草头蛱蝶黄花晚，菱角蜻蜓翠蔓深。"]},{"t":"晚归","f":"五言绝句","c":["岸迥重重柳，川低渺渺河。","不愁南浦暗，归伴有姮娥。"]},{"t":"晚春","f":"七言绝句","c":["春残叶密花枝少，睡起茶多酒盏疏。","斜倚屏风搔首坐，满簪华发一床书。"]},{"t":"曹参","f":"七言绝句","c":["束发河山百战功，白头富贵亦成空。","华堂不著新歌舞，却要区区一老翁。"]},{"t":"望之将行","f":"七言绝句","c":["江涵秋景雁初飞，沙尾长樯发渐稀。","惆怅无因见范蠡，夕阳长送钓船归。"]},{"t":"望夫石","f":"七言绝句","c":["云鬟烟鬓与谁期，一去天边更不归。","还似九疑山下女，千秋长望舜裳衣。"]},{"t":"望淮口","f":"七言绝句","c":["白烟瀰漫接天涯，黯黯长空一道斜。","有似钱塘江上望，晚潮初落见平沙。"]},{"t":"望越亭","f":"七言绝句","c":["乱山千顷翠相围，衮衮沧江去复归。","安得病身生羽翼，长随沙鸟自由飞。"]},{"t":"梅花","f":"七言绝句","c":["白玉堂前一树梅，为谁零落为谁开。","唯有春风最相惜，一年一度一归来。"]},{"t":"梅花","f":"五言绝句","c":["墙角数枝梅，凌寒独自开。","遥知不是雪，为有暗香来。"]},{"t":"梦","f":"七言绝句","c":["黄粱欲熟且留连，漫道春归莫怅然。","蝴蝶岂能知梦事，蘧蘧飞堕晚花前。"]},{"t":"欲往北山以雨止","f":"七言绝句","c":["北山朝气澹高秋，欲往愁沾独少留。","散策缘冈初见日，兴随云尽复中休。"]},{"t":"欲雪","f":"七言绝句","c":["天上云骄未肯同，晚来雪意已填空。","欲开新酒邀嘉客，更待天花落坐中。"]},{"t":"涿州","f":"七言绝句","c":["涿州沙上望桑乾，鞍马春风特地寒。","万里如今持汉节，却寻此路使呼韩。"]},{"t":"清明","f":"七言绝句","c":["东城酒散夕阳迟，南陌鞦韆寂寞垂。","人与长瓶卧芳草，风将急管度青枝。"]},{"t":"清凉寺白云庵","f":"七言绝句","c":["庵云作顶峭无邻，衣月为衿静称身。","木落冈峦因自献，水归洲渚得横陈。"]},{"t":"移松皆死","f":"五言绝句","c":["李白今何在，桃红已索然。","君看赤松子，犹自不长年。"]},{"t":"移柳","f":"七言绝句","c":["移柳当门何啻五，穿松作径适成三。","临流遇兴还能赋，自比渊明或未惭。"]},{"t":"聊行","f":"五言绝句","c":["聊行弄芳草，独坐隐团蒲。","问客茅檐日，君家有此无。"]},{"t":"随意","f":"七言绝句","c":["随意柴荆手自开，沿冈度堑复登台。","小桥风露扁舟月，迷鸟羁雌竟往来。"]},{"t":"雪中游北山呈广州使君和叔同年","f":"七言绝句","c":["南州岁晚亦花开，有底堪随驿使来。","看取钟山如许雪，何须持寄岭头梅。"]},{"t":"雪乾","f":"七言绝句","c":["雪乾云净见遥岑，南陌芳菲复可寻。","换得千颦为一笑，春风吹柳万黄金。"]},{"t":"黄花","f":"七言绝句","c":["四月扬州芍药多，先时为别苦风波。","还家忽忽惊秋色，独见黄花出短莎。"]},{"t":"黄河","f":"七言绝句","c":["派出昆崙五色流，一支黄浊贯中州。","吹沙走浪几千里，转侧屋闾无处求。"]},{"t":"黄鹂","f":"七言绝句","c":["野花吹尽竹娟娟，尚有黄鹂最可怜。","娅姹不知缘底事，背人飞过北山前。"]},{"t":"寓言二首 其二","f":"七言绝句","c":["本来无物使人疑，却为参禅买得痴。","闻道无情能说法，面墙终日妄寻思。"]},{"t":"寓言二首 其一","f":"七言绝句","c":["太虚无实可追寻，叶落松枝谩古今。","若见桃花生圣解，不疑还自有疑心。"]},{"t":"御柳","f":"七言绝句","c":["御柳新黄已迸条，宫沟薄冻未全消。","人间今日春多少，祇看东方北斗杓。"]},{"t":"惠崇画","f":"五言绝句","c":["断取沧州趣，移来六月天。","道人三昧力，变化只和铅。"]},{"t":"散策","f":"七言绝句","c":["散策东冈亦已劳，横塘西转有亭皋。","絮飞度屋何许柳，花落填沟无数桃。"]},{"t":"晴景","f":"七言绝句","c":["雨来未见花间蕊，雨后全无叶底花。","蜂蝶纷纷过墙去，却疑春色在邻家。"]},{"t":"游城东示深之德逢","f":"七言绝句","c":["欲牵淮舸共寻源，且踏青青绕杏园。","忆我旧时光宅路，依然桑柳映花繁。"]},{"t":"游城南即事二首 其二","f":"七言绝句","c":["泰坛东路绕重营，独背朝阳信马行。","漫道城南天尺五，荒林时见一柴荆。"]},{"t":"游城南即事二首 其一","f":"七言绝句","c":["神奸变化久难知，禹鼎由来更不疑。","螭魅合谋非一日，太丘真复社亡迟。"]},{"t":"游钟山","f":"七言绝句","c":["终日看山不厌山，买山终待老山间。","山花落尽山长在，山水空流山自闲。"]},{"t":"游钟山","f":"七言绝句","c":["两山松栎暗朱藤，一水中间胜武陵。","午梵隔云知有寺，夕阳归去不逢僧。"]},{"t":"登飞来峰","f":"七言绝句","c":["飞来山上千寻塔，闻说鸡鸣见日升。","不畏浮云遮望眼，自缘身在最高层。"]},{"t":"答俞秀老","f":"五言绝句","c":["诸偶缘安有，实相非相偶。","虽神如季咸，终亦失而走。"]},{"t":"答韩持国","f":"七言绝句","c":["知公尚忆洛城中，醉里穿花满袖风。","花亦有知还有恨，今为红药主人翁。"]},{"t":"答韩持国芙蓉堂二首 其二","f":"七言绝句","c":["乞得胶胶扰扰身，五湖烟水替风尘。","祇将凫雁同为侣，不与龟鱼作主人。"]},{"t":"答韩持国芙蓉堂二首 其一","f":"七言绝句","c":["投老归来一幅巾，尚私荣禄备藩臣。","芙蓉堂下疏秋水，且与龟鱼作主人。"]},{"t":"腊享","f":"七言绝句","c":["明星惨澹月参差，万窍含风各自悲。","人散庙门灯火尽，却寻残梦独多时。"]},{"t":"舒州被召试不赴偶书","f":"七言绝句","c":["戴盆难与望天兼，自怪虚名亦自嫌。","槁壤太牢俱有味，可能蚯蚓独清廉。"]},{"t":"蒋山手种松","f":"七言绝句","c":["青青石上岁寒枝，一寸岩前手自移。","闻道近来高数尺，此身蒲柳故应衰。"]},{"t":"谢安","f":"七言绝句","c":["谢公才业自超群，误长清谈助世纷。","秦晋区区等亡国，可能王衍胜商君。"]},{"t":"谢安墩二首 其二","f":"七言绝句","c":["谢公陈迹自难追，山月淮云祗往时。","一去可怜终不返，暮年垂泪对桓伊。"]},{"t":"谢安墩二首 其一","f":"七言绝句","c":["我名公字偶相同，我屋公墩在眼中。","公去我来墩属我，不应墩姓尚随公。"]},{"t":"谢微之见过","f":"七言绝句","c":["此身已是一枯株，所记交朋八九无。","唯有微之来访旧，天寒几夕拥山炉。"]},{"t":"赐也","f":"七言绝句","c":["赐也能言未识真，误将心许汉阴人。","桔槔俯仰妨何事，抱瓮区区老此身。"]},{"t":"越人以幕养花因游其下二首 其二","f":"七言绝句","c":["尚有残红已可悲，更忧回首祇空枝。","莫嗟身世浑无事，睡过春风作恶时。"]},{"t":"越人以幕养花因游其下二首 其一","f":"七言绝句","c":["幕天无日地无尘，百紫千红占得春。","野草自花还自落，落时还有惜花人。"]},{"t":"遇雪","f":"七言绝句","c":["定知花发是归期，不奈归心日日归。","风雪岂知行客恨，向人更作落花飞。"]},{"t":"道旁大松人取以为明","f":"七言绝句","c":["龙甲虬髯不可攀，亭亭千丈荫南山。","应嗟无地逃斤斧，岂愿争明爝火间。"]},{"t":"韩子","f":"七言绝句","c":["纷纷易尽百年身，举世何人识道真。","力去陈言夸末俗，可怜无补费精神。"]},{"t":"韩信","f":"七言绝句","c":["贫贱侵凌富贵骄，功名无复在刍荛。","将军北面师降虏，此事人间久寂寥。"]},{"t":"叠翠亭","f":"七言绝句","c":["烟笼远浦迷芳草，日照澄湖浸碧峰。","幸有清樽堪酩酊，忍陪良友不从容。"]},{"t":"楚天","f":"七言绝句","c":["楚天如梦水悠悠，花底残红漫不收。","独绕去年挥泪处，还将牢落对沧洲。"]},{"t":"楼上","f":"五言绝句","c":["荡漾舟中客，徘徊楼上人。","沧波浩无主，两桨邈难亲。"]},{"t":"禁中春寒","f":"七言绝句","c":["青烟漠漠雨纷纷，水殿西廊北苑门。","已著单衣犹禁火，海棠花下怯黄昏。"]},{"t":"禁直","f":"七言绝句","c":["翠木交阴覆两檐，夜天如水碧湉湉。","帝城风月看常好，人世悲哀老自添。"]},{"t":"窥园","f":"七言绝句","c":["杖策窥园日数巡，攀花弄草兴常新。","董生只被公羊惑，肯信捐书一语真。"]},{"t":"蒲叶","f":"五言绝句","c":["蒲叶清浅水，杏花和暖风。","地偏缘底绿，人老为谁红。"]},{"t":"谩成","f":"七言绝句","c":["清时无路取封侯，病卧牛衣已数秋。","日月不胶时易失，感今怀昔使人愁。"]},{"t":"鄞县西亭","f":"七言绝句","c":["收功无路去无田，窃食穷城度两年。","更作世间儿女态，乱栽花竹养风烟。"]},{"t":"酬王微之","f":"七言绝句","c":["一雨回飙助蓐收，炎曦不复畏金流。","君家咫尺堪乘兴，想岸乌纱对奕秋。"]},{"t":"酬宋廷评请序经解","f":"七言绝句","c":["未曾相识已相怜，香火灵山亦有缘。","训释虽工君尚少，不应急务世人传。"]},{"t":"暮春","f":"七言绝句","c":["北山吹雨送残春，南涧朝来绿映人。","昨日杏花浑不见，故应随水到江滨。"]},{"t":"暮春","f":"七言绝句","c":["无限残红著地飞，溪头烟树翠相围。","杨花独得东风意，相逐晴空去不归。"]},{"t":"暮春","f":"七言绝句","c":["芙蕖的历抽新叶，苜蓿阑干放晚花。","白下门东春已老，莫嗔杨柳可藏鸦。"]},{"t":"歌元丰五首 其五","f":"七言绝句","c":["豚栅鸡埘晻霭间，暮林摇落献南山。","丰年处处人家好，随意飘然得往还。"]},{"t":"歌元丰五首 其四","f":"七言绝句","c":["放歌扶杖出前林，遥和丰年击壤音。","曾侍土阶知帝力，曲中时有誉尧心。"]},{"t":"歌元丰五首 其三","f":"七言绝句","c":["湖海元丰岁又登，稆生犹足暗沟塍。","家家露积如山垄，黄发咨嗟见未曾。"]},{"t":"歌元丰五首 其二","f":"七言绝句","c":["露积成山百种收，渔梁亦自富虾鳅。","无羊说梦非真事，岂见元丰第二秋。"]},{"t":"歌元丰五首 其一","f":"七言绝句","c":["水满陂塘谷满篝，漫移蔬果亦多收。","神林处处传箫鼓，共赛元丰第二秋。"]},{"t":"碧芜","f":"五言绝句","c":["碧芜平野旷，黄菊晚村深。","客倦留甘饮，身闲累苦吟。"]},{"t":"精卫","f":"七言绝句","c":["帝子衔冤久未平，区区微意欲何成。","情知木石无云补，待见桑田几变更。"]},{"t":"嘲白发","f":"七言绝句","c":["久应飘转作蓬飞，眷惜冠巾未忍违。","种种春风吹不长，星星明月照还稀。"]},{"t":"蝶","f":"七言绝句","c":["翅轻于粉薄于缯，长被花牵不自胜。","若信庄周尚非我，岂能投死为韩凭。"]},{"t":"题八功德水","f":"五言绝句","c":["欲寻阿练若，曳屐出东冈。","涧谷芳菲少，春风著野桑。"]},{"t":"题山寺扉","f":"七言绝句","c":["口衔天宪手持钧，已是龙墀第一人。","回首三千大千界，此身犹是一微尘。"]},{"t":"题中书壁","f":"七言绝句","c":["夜开金钥诏辞臣，对御抽毫草帝纶。","须信朝家重儒术，一时同榜用三人。"]},{"t":"题北山隐居王闲叟壁","f":"七言绝句","c":["荒村日午未开门，雨后馀花满地存。","举世但能旌隐逸，谁人知道是王孙。"]},{"t":"题半山寺壁二首 其二","f":"五言绝句","c":["寒时暖处坐，热时凉处行。","众生不异佛，佛即是众生。"]},{"t":"题半山寺壁二首 其一","f":"五言绝句","c":["我行天即雨，我止雨还住。","雨岂为我行，邂逅与相遇。"]},{"t":"题正觉院箨龙轩二首 其二","f":"七言绝句","c":["仙事茫茫不可知，箨龙空此见孙枝。","壶中若有闲天地，何苦归来问葛陂。"]},{"t":"题正觉院箨龙轩二首 其一","f":"七言绝句","c":["北轩名字经平子，爱此吾能为赋诗。","山雨江风一披拂，箨龙还自有吟时。"]},{"t":"题永庆壁有雱遗墨数行","f":"七言绝句","c":["永庆招提墨数行，岁时风露每凄伤。","残骸岂久人间世，故有情钟未可忘。"]},{"t":"题玉光亭","f":"七言绝句","c":["传闻天玉此埋堙，千古谁分伪与真。","每向小庭风月夜，却疑山水有精神。"]},{"t":"题齐安壁","f":"五言绝句","c":["日净山如染，风暄草欲薰。","梅残数点雪，麦涨一溪云。"]},{"t":"题何氏宅园亭","f":"五言绝句","c":["荷叶参差卷，榴花次第开。","但令心有赏，岁月任渠催。"]},{"t":"题张司业诗","f":"七言绝句","c":["苏州司业诗名老，乐府皆言妙入神。","看似寻常最奇崛，成如容易却艰辛。"]},{"t":"题杨溪","f":"五言绝句","c":["桥横葛仙陂，住近杨雄宅。","主人胡不归，为我炊香白。"]},{"t":"题定力院壁","f":"七言绝句","c":["溪北溪南水暗通，隔溪遥见夕阳舂。","思量诸葛成何事，只合终身作卧龙。"]},{"t":"题定林壁怀李叔时","f":"五言绝句","c":["云与渊明出，风随禦寇还。","燎炉无伏火，蕙帐冷空山。"]},{"t":"题宝岩寺寒碧亭二首 其一","f":"七言绝句","c":["两岸青山刻峭成，一溪回曲篆纹平。","绿阴隐隐无重数，欲去黄鹂又一声。"]},{"t":"题画扇","f":"七言绝句","c":["玉斧修成宝月团，月边仍有女乘鸾。","青冥风露非人世，鬓乱钗斜特地寒。"]},{"t":"题金沙","f":"七言绝句","c":["海棠开后数金沙，高架层层吐绛葩。","咫尺西城无力到，不知谁赏魏家花。"]},{"t":"题金陵驿","f":"七言绝句","c":["重冈古道春风里，草色花光似故人。","却喜此身今漫浪，回家随处得相亲。"]},{"t":"题勇老退居院","f":"七言绝句","c":["道人投老寄山林，偶坐翛然洗我心。","梦境此身能且在，明年寒食更相寻。"]},{"t":"题夏旼扇","f":"七言绝句","c":["白马津头驿路边，阴森乔木带漪涟。","夕阳一马匆匆过，梦寐如今十五年。"]},{"t":"题徐浩书法华经","f":"五言绝句","c":["一切法无差，水牛生象牙。","莫将无量义，欲觅妙莲华。"]},{"t":"题舫子","f":"五言绝句","c":["爱此江边好，留连至日斜。","眠分黄犊草，坐占白鸥沙。"]},{"t":"题景德寺试院壁","f":"七言绝句","c":["屋东瓜蔓已扶疏，小石蓝花破萼初。","从此到寒能几日，风沙还见一年除。"]},{"t":"燕","f":"七言绝句","c":["处处定知秋后别，年年长向社前逢。","行藏自欲追时节，岂是人间不见容。"]},{"t":"赠外孙","f":"七言绝句","c":["南山新长凤凰雏，眉目分明画不如。","年小从他爱梨栗，长成须读五车书。"]},{"t":"赠安大师","f":"七言绝句","c":["独龙冈北第三峰，逋客归来老更慵。","败屋数椽青缭绕，冷云深处不闻钟。"]},{"t":"赠张轩民赞善","f":"七言绝句","c":["潮打空城寂寞回，百年多病独登台。","谁人得似张公子，有底忙时不肯来。"]},{"t":"赠僧","f":"七言绝句","c":["纷纷扰扰十年间，世事何尝不强颜。","亦欲心如秋水静，应须身似岭云闲。"]},{"t":"默默","f":"七言绝句","c":["默默长年有所思，世间谈笑强追随。","苍髯欲出朱颜谢，更觉求田问舍迟。"]},{"t":"丁年","f":"七言律诗","c":["丁年结客盛游从，宛洛毡车处处逢。","吟尽物华愁笔老，醉消春色爱醅浓。","垆间寂寞相如病，锻处荒凉叔夜慵。","早晚青云须自致，立谈平取彻侯封。"]},{"t":"九日登东山寄昌叔","f":"七言律诗","c":["城上啼乌破寂寥，思君何处坐岧峣。","应须绿酒酬黄菊，何必红裙弄紫箫。","落木云连秋水渡，乱山烟入夕阳桥。","渊明久负东篱醉，犹分低心事折腰。"]},{"t":"八功德水","f":"七言律诗","c":["雪山马口出琉璃，闻说诸天与护持。","此水遥连八功德，供人真净四威仪。","当时迦叶无尘染，何事阌乡有土思。","道力起缘非一路，但知瓢饮是生疑。"]},{"t":"又段氏园亭","f":"七言律诗","c":["攲眠随水转东垣，一点炊烟映水昏。","漫漫芙蕖难觅路，翛翛杨柳独知门。","青山呈露新如染，白鸟嬉游静不烦。","朱雀航边今有此，可能摇荡武陵源。"]},{"t":"上元戏呈贡父","f":"七言律诗","c":["车马纷纷白昼同，万家灯火暖春风。","别开阊阖壶天外，特起蓬莱陆海中。","尽取繁华供侠少，祇分牢落与衰翁。","不知太乙游何处，定把青藜独照公。"]},{"t":"上西垣舍人","f":"七言律诗","c":["共说才高世所珍，诸贤谁敢望光尘。","讨论润色今为美，学问文章老更醇。","赋拟相如真复似，诗看子建的应亲。","仍闻悟主言多直，许史家儿往往嗔。"]},{"t":"与宝觉宿精舍","f":"五言律诗","c":["扰扰复翩翩，秋床烛屡昏。","真为说万物，岂止挟三言。","问义曹溪室，捐书阙里门。","若知同二妄，目击道逾存。"]},{"t":"与舍弟华藏院此君亭咏竹","f":"七言律诗","c":["一径森然四座凉，残阴馀韵去何长。","人怜直节生来瘦，自许高材老更刚。","会与蒿藜同雨露，终随松柏到冰霜。","烦君惜取根株在，欲乞伶伦学凤凰。"]},{"t":"与微之同赋梅花得香字三首 其三","f":"七言律诗","c":["浅浅池塘短短墙，年年为尔惜流芳。","向人自有无言意，倾国天教抵死香。","须袅黄金危欲堕，蒂团红蜡巧能装。","婵娟一种如冰雪，依倚春风笑野棠。"]},{"t":"与微之同赋梅花得香字三首 其二","f":"七言律诗","c":["结子非贪鼎鼐尝，偶先红杏占年芳。","从教腊雪埋藏得，却怕春风漏泄香。","不御铅华知国色，祇裁云缕想仙装。","少陵为尔牵诗兴，可是无心赋海棠。"]},{"t":"与微之同赋梅花得香字三首 其一","f":"七言律诗","c":["汉宫娇额半涂黄，粉色凌寒透薄妆。","好借月魂来映烛，恐随春梦去飞扬。","风亭把盏酬孤艳，雪径回舆认暗香。","不为调羹应结子，直须留此占年芳。"]},{"t":"小姑","f":"七言律诗","c":["小姑未嫁与兰支，何恨流传乐府诗。","初学水仙骑赤鲤，竟寻山鬼从文狸。","缤纷云䙱空棠楫，绰约烟鬟独桂旗。","弄玉有祠终或往，飞琼无梦故难知。"]},{"t":"山行","f":"五言律诗","c":["出写清浅景，归穿苍翠阴。","平头均楚制，长耳嗣吴吟。","暮岭已佳色，寒泉仍好音。","谁同此真意，倦鸟亦幽寻。"]},{"t":"山居杂言","f":"七言律诗","c":["法和衣钵过南华，正叶传师萃一花。","胜地雾迷淮水石，望星人指楚天涯。","数千松倚西山老，七百僧悲去路赊。","一片苍苔涅槃石，至今缭绕白云遮。"]},{"t":"马玘大夫挽辞","f":"五言律诗","c":["冠盖青门道，知君自少时。","从容他日喜，奄忽暮年悲。","江月明丹旐，湖风冷穗帷。","音容虽可想，材力竟何施。"]},{"t":"不到太初兄所居遂已十年以诗攀寄","f":"七言律诗","c":["一水衣巾剪翠绡，九峰环佩刻青瑶。","生才故有山川气，卜筑兼无市井嚣。","三叶素风门阀在，十年陈迹履綦销。","归荣早晚重携手，莫负幽人久见招。"]},{"t":"中书偶成","f":"五言律诗","c":["忽忽余年往，茫茫不自知。","慇勤照清浅，邂逅见衰迟。","辅世无贤业，容身有圣时。","归欤今可矣，何以长人为。"]},{"t":"为裴使君赋拟岘台","f":"七言律诗","c":["君作新台拟岘山，羊公千载得追攀。","歌钟殷地登临处，花木移春指顾间。","城似大堤来宛宛，溪如清汉落潺潺。","时平不比征吴日，缓带尤宜向此闲。"]},{"t":"乌塘","f":"五言律诗","c":["地僻居人少，山稠伏兽多。","怒狸朝搏雁，嚵虎夜窥骡。","篱落生孙竹，门庭上女萝。","未应悲寂寞，六载一经过。"]},{"t":"予求守江阴未得酬昌叔忆江阴见及之作","f":"七言律诗","c":["黄田港北水如天，万里风樯看贾船。","海外珠犀常入市，人间鱼蟹不论钱。","高亭笑语如昨日，末路尘沙非少年。","强乞一官终未得，祇君同病肯相怜。"]},{"t":"仁宗皇帝挽辞四首 其四","f":"五言律诗","c":["同执群方至，因山十月催。","永违天日表，空有肺肝摧。","帐殿流苏卷，铃歌薤露哀。","宫中垂晓轫，西去不更回。"]},{"t":"仁宗皇帝挽辞四首 其三","f":"五言律诗","c":["厌代人间世，收神天上游。","遽然虚玉座，不复望珠旒。","待旦移巾帻，饔人改膳羞。","寻常飞白几，寂寞暗尘浮。"]},{"t":"仁宗皇帝挽辞四首 其二","f":"五言律诗","c":["凭几微言绝，群臣涕泗挥。","哀号三级陛，缟素九重围。","天上仙游远，宫中御座非。","最悲帷幄侍，不复未明衣。"]},{"t":"仁宗皇帝挽辞四首 其一","f":"五言律诗","c":["去序三朝圣，行崩万国天。","忧勤无旷古，治洽最长年。","仁育齐高厚，哀思罄幅员。","欲知千载美，道德冠遗编。"]},{"t":"元珍以诗送绿石砚所谓玉堂新样者","f":"七言律诗","c":["玉堂新样世争传，况以蛮溪绿石镌。","嗟我长来无异物，愧君持赠有佳篇。","久埋瘴雾看犹湿，一取春波洗更鲜。","还与故人袍色似，论心于此亦同坚。"]},{"t":"元献晏公挽辞三首 其三","f":"五言律诗","c":["感会真奇遇，飞扬独妙龄。","他年西饯日，此夜上骑星。","宿惠留藩屏，馀忠在禁庭。","音容无处所，彷佛寄丹青。"]},{"t":"元献晏公挽辞三首 其二","f":"五言律诗","c":["终贾年方妙，萧曹地已亲。","优游太平日，密勿老成人。","抗论辞多秘，赓歌迹已陈。","功名千载下，不负汉庭臣。"]},{"t":"元献晏公挽辞三首 其一","f":"五言律诗","c":["文章晋康乐，经术汉公孙。","旧秩疑丞贵，前功保傅尊。","传呼犹在耳，会哭已填门。","萧瑟城南路，鸣笳上九原。"]},{"t":"公辟枉道见过获闻新诗因叙叹仰","f":"七言律诗","c":["青丘神父能为政，碧落仙翁好作诗。","旧事齐儿应共记，新篇楚老得先知。","怀砖大岘如迎日，供帐阊门胜去时。","若与鸱夷斗百草，锦囊佳丽敌西施。"]},{"t":"午枕","f":"七言律诗","c":["百年春梦去悠悠，不复吹箫向此留。","野草自花还自落，鸣禽相乳亦相酬。","旧蹊埋没开新径，朱户攲斜见画楼。","欲把一杯无伴侣，眼看兴废使人愁。"]},{"t":"壬辰寒食","f":"五言律诗","c":["客思似杨柳，春风千万条。","更倾寒食泪，欲涨冶城潮。","巾发雪争出，镜颜朱早雕。","未知轩冕乐，但欲老渔樵。"]},{"t":"太湖恬亭","f":"七言律诗","c":["槛临溪上绿阴围，溪岸高低入翠微。","日落断桥人独立，水涵幽树鸟相依。","清游始觉心无累，静处谁知世有机。","更待夜深同徙倚，秋风斜月钓船归。"]},{"t":"尹村道中","f":"七言律诗","c":["满眼霜吹宿草根，谩知新岁不逢春。","却疑青嶂非人世，更觉黄云是塞尘。","万里张侯能奉使，百年曾子肯辞亲。","自怜许国终无用，何事纷纷客此身。"]},{"t":"文元贾公挽辞二首 其二","f":"七言律诗","c":["铭旌萧飒九秋风，薤露悲歌落月中。","华屋几人思谢傅，佳城今日闭滕公。","名垂竹帛书勋在，神寄丹青审象同。","天上貂蝉曾梦赐，归魂应佩紫阳宫。"]},{"t":"文元贾公挽辞二首 其一","f":"七言律诗","c":["功名烜赫在三朝，经术从容辅汉条。","儒服早纡丞相绂，戎冠再插侍中貂。","开仓六塔流人复，出甲甘陵叛党销。","东第祇今空画像，当时于此识风标。"]},{"t":"王子直挽辞","f":"七言律诗","c":["多才自合至公卿，岂料青衫困一生。","太史有书能叙事，子云于世不徼名。","丘坟惨淡箕山绿，门巷萧条颍水清。","握手笑言如昨日，白头东望一伤情。"]},{"t":"王中甫学士挽辞","f":"七言律诗","c":["同学金陵最少年，奏书曾用牍三千。","盛名非复居人后，壮岁如何弃我先。","种橘园林无旧业，采蘋洲渚有新篇。","蒜山东路春风绿，埋没谁知太守阡。"]},{"t":"王村","f":"五言律诗","c":["晻霭王村路，春风北使旗。","尘催轻骑走，寒咽短箫吹。","揽辔联貂帽，投鞭各酒卮。","纷纷小儿女，何事倚墙窥。"]},{"t":"王浮梁太丞之听讼轩有水禽三巢于竹林之上恬而自得邑人作诗以美之因次元韵","f":"七言律诗","c":["水边舟动多惊散，何事林间近绝疑。","野意肯从威令至，旧巢犹有主人知。","不关饮啄春江暖，自在飞鸣夏日迟。","览德岂无丹穴凤，到时应让向南枝。"]},{"t":"王逢原挽辞","f":"五言律诗","c":["蒿里竟何在，死生从此分。","谩传仙掌籍，谁见鬼修文。","蔡琰能传业，侯芭为起坟。","伤心北风路，吹泪湿江云。"]},{"t":"长干寺","f":"七言律诗","c":["梵馆清闲侧布金，小塘回曲翠文深。","柳条不动千丝直，荷叶相依万盖阴。","漠漠岑云相上下，翩翩沙鸟自浮沈。","羁人乐此忘归思，忍向西风学越吟。"]},{"t":"长垣北","f":"五言律诗","c":["揽辔长垣北，貂寒不自持。","霜风急鼓吹，烟月暗旌旗。","骑火流星点，墙桑亚戟枝。","柴荆掩春梦，谁见我行时。"]},{"t":"世事","f":"五言律诗","c":["世事一何稠，论心日已偷。","尚蒙今士笑，宜见古人羞。","老圃聊须问，良田亦欲求。","非关畏黻冕，无责易身修。"]},{"t":"丙申八月作","f":"七言律诗","c":["秋风摧剥利如刀，漠漠昏烟玩日高。","眼看南山露崖窾，心随东水转波涛。","归期正自凭蓍蔡，生理应须问酒醪。","还有诗书能慰我，不多霜雪上颠毛。"]},{"t":"东皋","f":"五言律诗","c":["起伏晴云径，纵横暖水陂。","草长流翠碧，花远没黄鹂。","楚制从人笑，吴吟得自怡。","东皋兴不浅，游走及芳时。"]},{"t":"冬日","f":"五言律诗","c":["扰扰今非昔，漫漫夜复晨。","风沙不贷客，云日欲迷人。","散发愁边老，开颜醉后春。","转思江海上，一洗白纶巾。"]},{"t":"冬至","f":"五言律诗","c":["都城开博路，佳节一阳生。","喜见儿童色，欢传市井声。","幽闲亦聚集，珍丽各携擎。","却忆他年事，关商闭不行。"]},{"t":"出城访无党因宿斋馆","f":"七言律诗","c":["关外寻君信马蹄，漫成诗句任天倪。","花枝到眼春相照，山色侵衣晚自迷。","今日笑谈还喜共，经年劳逸固难齐。","生涯零落归心懒，多谢慇勤杜宇啼。"]},{"t":"北山三咏 其二 觉海方丈","f":"七言律诗","c":["往来城府住山林，诸法翛然但一音。","不与物违真道广，每随缘起自禅深。","舌根已净谁能坏，足迹如空我得寻。","岁晚北窗聊寄傲，蒲萄零落半床阴。"]},{"t":"北山三咏 其三 道光泉","f":"七言律诗","c":["箨龙将雨绕山行，注远投深静有声。","云涌浴槽朝自暖，虹垂斋镬午还晴。","铜瓶各满幽人意，玉甃因高正士名。","神力可嗟妨智巧，桔槔零落便苔生。"]},{"t":"北山暮归示道人","f":"五言律诗","c":["千山复万山，行路有无间。","花发蜂递绕，果垂猿对攀。","独寻寒水度，欲趁夕阳还。","天黑月未上，儿童初掩关。"]},{"t":"半山春晚即事","f":"五言律诗","c":["春风取花去，酬我以清阴。","翳翳陂路静，交交园屋深。","床敷每小息，杖屦或幽寻。","惟有北山鸟，经过遗好音。"]},{"t":"古松","f":"七言律诗","c":["森森直干百馀寻，高入青冥不附林。","万壑风生成夜响，千山月照挂秋阴。","岂因粪壤栽培力，自得乾坤造化心。","廊庙乏材应见取，世无良匠勿相侵。"]},{"t":"史教授独善堂","f":"五言律诗","c":["湖海十年旧，林塘三亩馀。","静非谈者隐，贫胜富人居。","列鼎亦何有，幅巾聊自如。","犹应不独善，学子满阶除。"]},{"t":"四月果","f":"七言律诗","c":["一春强半勒花风，几日园林几树红。","汲汲追攀常恨晚，纷纷吹洗忽成空。","行看果下苍苔地，已作人间白发翁。","岂惜解鞍留夜饮，此身醒醉与谁同。"]},{"t":"处士葛君挽辞","f":"五言律诗","c":["楚人黄歇地，晋代葛洪家。","特擅山川秀，相承黻冕华。","猗君有清尚，于世不雄夸。","令子能传业，流光未可涯。"]},{"t":"外厨遗火示公佐","f":"七言律诗","c":["刀匕初无欲凊人，如何灶鬼尚嫌嗔。","翛翛短褐方炀火，冉冉青烟已被宸。","邂逅焚巢连鸟雀，仓黄濡幕愧比邻。","王阳幸有囊衣在，报赏焦头亦未贫。"]},{"t":"平山堂","f":"七言律诗","c":["城北横冈走翠虬，一堂高视两三州。","淮岑日对朱栏出，江岫云齐碧瓦浮。","墟落耕桑公恺悌，杯觞谈笑客风流。","不知岘首登临处，壮观当时有此不。"]},{"t":"平甫与宝觉游金山思大觉并见寄及相见得诗次韵二首 其二","f":"七言律诗","c":["漳南开士好丛林，慧剑何年出水心。","独往便应诸漏尽，相逢未免故情深。","槛窥山鸟有真意，窗听海潮非世音。","一笑上方人事外，不知衰境两侵寻。"]},{"t":"平甫与宝觉游金山思大觉并见寄及相见得诗次韵二首 其一","f":"七言律诗","c":["宠参时宰道人琳，气盖诸公弟季心。","胜践肯论山在险，冥搜欲与海争深。","摇摇北下随帆影，踽踽东来想足音。","握手更知禅伯远，隔云灵鹫碧千寻。"]},{"t":"正肃吴公挽辞三首 其三","f":"五言律诗","c":["昔继吴公治，今从子产游。","里门无旧客，乡国有新丘。","谋让禆谌远，文归贾谊优。","此时辜怨宠，西望涕空流。"]},{"t":"正肃吴公挽辞三首 其二","f":"五言律诗","c":["应世文章手，宜民政事才。","朝多侧目忌，士有拊心哀。","书蠹平生简，香寒后夜灰。","悠悠国西路，空得葬车回。"]},{"t":"正肃吴公挽辞三首 其一","f":"五言律诗","c":["从容边塞议，慷慨庙堂争。","曲突非无验，方穿有不行。","搢绅终倚赖，赠襚极哀荣。","岂慕公孙贵，平生学董生。"]},{"t":"正宪吴公挽辞","f":"七言律诗","c":["丙魏虽遭汉道昌，岂如公出值虞唐。","秀钟旧国山川气，荣附中天日月光。","更化事功参虎变，赞元时序得金穰。","伤心鼓吹城南陌，回首新阡柏一行。"]},{"t":"永寿县太君周氏挽辞二首 其二","f":"五言律诗","c":["子引金闺籍，身开石窌封。","灵輴悲吉路，象服俨虚容。","楚挽虽多相，莱衣不更缝。","谁知逝川底，剑自喜相逢。"]},{"t":"永寿县太君周氏挽辞二首 其一","f":"五言律诗","c":["永寿开新邑，长沙返旧茔。","金葩冷钿轴，粉字暗铭旌。","薤久露难湿，兰馀风尚清。","庆钟知有在，令子合升卿。"]},{"t":"永济道中寄诸舅弟","f":"七言律诗","c":["灯火匆匆出馆陶，回看永济日初高。","似闻空舍鸟乌乐，更觉荒陂人马劳。","客路光阴真弃置，春风边塞祇萧骚。","辛夷树下乌塘尾，把手何时得汝曹。"]},{"t":"玉晨大桧鹤庙古松最为佳树","f":"七言律诗","c":["坛庙千年草不生，幽真曾此荫馀清。","月枝地上流云影，风叶天边过雨声。","材大贤于人有用，节高仙与世无情。","秦山陂下今迷处，苦里宫中漫得名。"]},{"t":"白云然师","f":"五言律诗","c":["白首一山中，形骸槁木同。","苔争庵径路，云补衲穿空。","尘土随车辙，波涛信柂工。","昏昏老南北，应谢此高风。"]},{"t":"石竹花","f":"七言律诗","c":["退公诗酒乐华年，欲取幽芳近绮筵。","种玉乱抽青节瘦，刻缯轻染绛花圆。","风霜不放飘零早，雨露应从爱惜偏。","已向美人衣上并，更留佳客赋婵娟。"]},{"t":"示无外","f":"五言律诗","c":["支颐横口语，椎髻曲肱眠。","莫问谁宾主，安知汝辈年。","邻鸡生午寂，幽草弄秋妍。","却忆东窗簟，蛮藤故宛然。"]},{"t":"示长安君","f":"七言律诗","c":["少年离别意非轻，老去相逢亦怆情。","草草杯盘供笑语，昏昏灯火话平生。","自怜湖海三年隔，又作尘沙万里行。","欲问后期何日是，寄书应见雁南征。"]},{"t":"示四妹","f":"七言律诗","c":["孟光求婿得梁鸿，庑下相随不讳穷。","卓荦才名今日事，萧条门巷古人风。","五噫尚与时多忤，一笑兼忘我屡空。","六月尘沙不相贷，泫然搔首又西东。"]},{"t":"示俞秀老","f":"七言律诗","c":["缭绕山如涌翠波，人家一半在烟萝。","时丰笑语春声早，地僻追寻野兴多。","窣堵朱甍开北向，招提素脊隐西阿。","暮年要与君携手，处处相烦作好歌。"]},{"t":"示耿天骘","f":"五言律诗","c":["挟策能伤性，捐书可尽年。","弦歌无旧习，香火有新缘。","白土长冈路，朱湖小洞天。","望公时顾我，于此畅幽悁。"]},{"t":"示董伯懿","f":"七言律诗","c":["穿桥度堑祇闲行，咏石嘲花亦漫成。","嚼蜡已能忘世味，画脂那更惜时名。","长干里北寒山紫，白下门西野水明。","此地一廛须卜筑，故人他日访柴荆。"]},{"t":"光宅","f":"五言律诗","c":["今知光宅寺，牛首正当门。","台殿金碧毁，丘墟桑竹繁。","萧萧新犊卧，冉冉暮鸦翻。","回首千岁梦，雨花何足言。"]},{"t":"全椒张公有诗在北山西庵僧者墁之怅然有感","f":"七言律诗","c":["十年怊怅蹑山阡，终欲持杯滴到泉。","东路角巾非故约，西州华屋漫脩椽。","幽明永隔休炊黍，真俗相妨久绝弦。","遗墨每看疑邂逅，复随人事散如烟。"]},{"t":"再至京口寄漕使曹郎中","f":"七言律诗","c":["漂流曾落此江边，忆与诗翁赋浩然。","乡国去身犹万里，驿亭分首已三年。","北城红出高枝靓，南浦青回老树圆。","还似昔时风露好，只疑谈笑在君前。"]},{"t":"冲卿席上得行字","f":"七言律诗","c":["二年相值喜同声，并辔尘沙眼亦明。","新诏各从天上得，残樽同向月边倾。","已嗟后会欢难必，更想前官责尚轻。","黾勉敢忘君所勖，古人忧乐有违行。"]},{"t":"华藏寺会故人","f":"五言律诗","c":["百忧成阻阔，一笑得留连。","城郭西风里，园林落照前。","共知官似梦，莫负酒如泉。","兴罢重携手，江湖即渺然。"]},{"t":"同长安君钟山望","f":"七言律诗","c":["解装相值得留连，一望江南万里天。","残雪离披山韫玉，新阳杳霭草含烟。","馀生不足偿多病，乐事应须委少年。","惟有爱诗心未已，东归与续棣华篇。"]},{"t":"同陈伯通钱材翁游山二君有诗因次元韵","f":"七言律诗","c":["秋来闲兴每登临，因叩精蓝望碧岑。","强策羸骖寻水石，忽惊幽鸟下烟林。","同时览物悲欢异，自古忘名趣向深。","安得湖山归我手，静看云意学无心。"]},{"t":"回桡","f":"七言律诗","c":["柴荆散策静凉飙，隐几扁舟白下潮。","紫磨月轮升霭霭，帝青云幕卷寥寥。","数家鸡犬如相识，一坞山林特见招。","尚忆木瓜园最好，兴残中路且回桡。"]},{"t":"孙威敏公挽辞","f":"五言律诗","c":["功名一世事，兴废岂人谋。","重为苍生起，终随逝水流。","凄凉归部曲，零落掩山丘。","许国言犹在，奸谀可使羞。"]},{"t":"安丰张令修芍陂","f":"七言律诗","c":["桐乡振廪得周旋，芍水修陂道路传。","日想僝功追往事，心知为政似当年。","鲂鱼鱍鱍归城市，粳稻纷纷载酒船。","楚相祠堂仍好在，胜游思为子留篇。"]},{"t":"岁晚怀古","f":"七言律诗","c":["先生岁晚事田园，鲁叟遗书废讨论。","问讯桑麻怜已长，按行松菊喜犹存。","农人调笑追寻壑，稚子欢呼出候门。","遥谢载醪袪惑者，吾今欲辩已忘言。"]},{"t":"庆老堂","f":"七言律诗","c":["板舆去国宦三年，华屋归来地一偏。","种竹常疑出冬笋，开池故合涌寒泉。","身闲楚老犹能戏，道胜邹人不更迁。","嗟我强颜无所及，想君为乐更焦然。"]},{"t":"次叶致远韵","f":"七言律诗","c":["生涯聊占水中洲，岂即乘桴逐圣丘。","身与凫飞仍雁集，心能茅靡亦波流。","由来杞梓常先伐，谁谓菰蒲可久留。","乘兴吾庐知未厌，故移脩竹拟延驺。"]},{"t":"次杨乐道韵六首 其一 后殿朝次偶题","f":"七言律诗","c":["百年文物士优游，万国今方似缀旒。","发策东堂招俊乂，回舆北苑罢倡优。","忽随诸彦登龙尾，尚忆当年应鹄头。","独望清光无补报，更惭虚食太官羞。"]},{"t":"次杨乐道韵六首 其二 御沟","f":"七言律诗","c":["渺渺金河涨欲平，数支分绿报清明。","常萦辇路漂花去，更引流杯送酒行。","静见金舆穿树影，清含玉漏过墙声。","衰颜一照自多感，回首江南春水生。"]},{"t":"次杨乐道韵六首 其三 幕次忆汉上旧居","f":"七言律诗","c":["汉水泱泱绕凤林，岘山南路白云深。","如何忧国忘家日，尚有求田问舍心。","直以文章供润色，未应风月负登临。","超然便欲遗荣去，却恐元龙会见侵。"]},{"t":"次杨乐道韵六首 其五 上巳闻苑中乐声书事","f":"七言律诗","c":["苑中谁得从春游，想见渐台瓦欲流。","御水曲随花影转，宫云低绕乐声留。","年华未破清明节，日暮初回祓禊舟。","更觉至尊思虑远，不应全为拙倡优。"]},{"t":"次杨乐道韵六首 其六 用乐道舍人韵书十日事呈乐道舍人圣从待制","f":"七言律诗","c":["东门人物乱如麻，想见新鞯照路华。","午鼓已传三刻漏，从官初赐一杯茶。","匆匆殿下催分首，扰扰宫前听卖花。","归去莫言天上事，但知呼客饮流霞。"]},{"t":"次杨乐道韵六首 其四 后苑详定书怀","f":"七言律诗","c":["文墨由来妙禁中，家传岂独赋河东。","平生听想风声早，数日追随笑语同。","御水新如鸭头绿，宫花更有鹤翎红。","看花弄水聊为乐，不晚朝廷相弱翁。"]},{"t":"次韵十四叔赐诗留别","f":"七言律诗","c":["穷冬追路出西津，得侍茫然两见春。","发册久嗟淹国士，起家初命慰乡人。","行辞北阙楼台丽，归佐南州县邑新。","班草数行衣上泪，何时杖屦却相亲。"]},{"t":"次韵子履远寄之作","f":"七言律诗","c":["飘然逐客出都门，士论应悲玉石焚。","高位纷纷谁得志，穷途往往始能文。","柴桑今日思元亮，天禄何时召子云。","直使声名传后世，穷通何必较功勋。"]},{"t":"次韵元厚之平戎庆捷","f":"七言律诗","c":["朝廷今日四夷功，先以招怀后殪戎。","胡地马牛归陇底，汉人烟火起湟中。","投戈更讲诸儒艺，免胄争趋上将风。","文武佐时惭吉甫，宣王征伐自肤公。"]},{"t":"次韵王禹玉平戎庆捷","f":"七言律诗","c":["熙河形势压西陲，不觉连营列汉旗。","天子坐筹星两两，将军归佩印累累。","称觞别殿传新曲，衔璧名王按旧仪。","江汉一篇犹未美，周宣方事伐淮夷。"]},{"t":"次韵王胜之咏雪","f":"七言律诗","c":["万户千门车马稀，行人却返鸟休飞。","玲珑剪水空中堕，的皪装春树上归。","素发联华惊老大，玉颜争好羡轻肥。","朝来已贺丰年瑞，更问田家果是非。"]},{"t":"次韵乐道送花","f":"七言律诗","c":["沁水名园好物华，露盘分送子云家。","新妆欲应何人面，彩笔知书几叶花。","曾和郢中歌白雪，亦陪天上饮流霞。","春风已得同心赏，更拟携诗载酒誇。"]},{"t":"次韵平甫村墅春日","f":"七言律诗","c":["昨日青青尚未齐，忽看春色满高低。","陂梅弄影争先舞，叶鸟藏身自在啼。","樵蹻踏云归旧径，渔蓑背雨向前溪。","似知我欲逃轩冕，谈笑相过各有携。"]},{"t":"次韵平甫金山会宿寄亲友","f":"七言律诗","c":["天末海门横北固，烟中沙岸似西兴。","已无船舫犹闻笛，远有楼台祗见灯。","山月入松金破碎，江风吹水雪崩腾。","飘然欲作乘桴计，一到扶桑恨未能。"]},{"t":"次韵平甫喜唐公自契丹归","f":"七言律诗","c":["留犁挠酒得戎心，并袷通欢岁月深。","奉使由来须陆贾，离亲何必强曾参。","燕人候望空瓯脱，胡马追随出蹛林。","万里春风归正好，亦逢佳客想挥金。"]},{"t":"次韵平甫赠三灵山人程惟象","f":"七言律诗","c":["家山松菊半荒芜，杖策穷年信所如。","占见地灵非卜筮，算知人贵自陶渔。","久谙郭璞言多验，老比颜含意更疏。","祇欲勒成方士传，借君名姓在新书。"]},{"t":"次韵冲卿上元从驾至集禧观偶成","f":"七言律诗","c":["昭陵持橐从游人，更见熙宁第四春。","宝称中开移玉座，华灯错出映朱尘。","辇前时看新歌舞，仗外还如旧徼巡。","投老逢时追往事，却含愁思度天津。"]},{"t":"次韵冲卿过睢阳","f":"五言律诗","c":["宫庙此神乡，留亲泊楚艎。","天开今壮丽，地积古悲凉。","不改山河旧，犹馀草木荒。","还闻足宾客，谁是汉邹阳。"]},{"t":"次韵冲卿除日立春","f":"五言律诗","c":["犹残一日腊，并见两年春。","物以终为始，人从故得新。","迎阳朝剪綵，守岁夜倾银。","恩赐随嘉节，无功祗自尘。"]},{"t":"次韵刘著作过茆山今平甫往游因寄","f":"七言律诗","c":["华阳仙伯有茆卿，官府今传在赤城。","三鹤不归犹地胜，二君能到亦心清。","诗中慷慨悲陈迹，篇末慇勤奖后生。","遥想青云知可附，坐看闾巷得名声。"]},{"t":"次韵吴仲庶省中画壁","f":"七言律诗","c":["画史虽非顾虎头，还能满壁写沧洲。","九衢京洛风沙地，一片江湖草树秋。","行数鯈鱼宾共乐，卧看鸥鸟吏方休。","知君定有扁舟意，却为丹青肯少留。"]},{"t":"次韵吴冲卿召赴资政殿听读诗义感事","f":"七言律诗","c":["周南麟趾圣人风，未有驺虞系召公。","雅颂兼陈为四始，笙歌合奏以三终。","讨论诏使成书上，休浣恩容著籍通。","墙面岂能知奥义，延陵听赏自为聪。"]},{"t":"次韵吴季野再见寄","f":"七言律诗","c":["衣裘南北弊风尘，志趣卑污已累亲。","流俗尚疑身察察，交游方笑党频频。","远同鱼乐思濠上，老使鸥惊耻海滨。","邂逅得君还恨晚，能明吾意久无人。"]},{"t":"次韵宋次道忆太平早梅","f":"七言律诗","c":["大梁春费宝刀催，不似湖阴有早梅。","今日盘中看剪綵，当时花下就传杯。","纷纷自向江城落，杳杳难随驿使来。","知忆旧游还想见，西南枝上月徘徊。"]},{"t":"次韵张子野竹林寺二首 其二","f":"七言律诗","c":["京岘城南隐映深，两牛鸣地得禅林。","风泉隔屋撞哀玉，竹月缘阶贴碎金。","藻井仰窥尘漠漠，青灯对宿夜沈沈。","扁舟过客十年事，一梦此山愁至今。"]},{"t":"次韵张子野竹林寺二首 其一","f":"七言律诗","c":["涧水横斜石路深，水源穷处有丛林。","青鸳几世开兰若，黄鹤当年瑞卯金。","败壁数峰连粉墨，凉烟一穗起檀沈。","十年亲友半零落，回首旧游成古今。"]},{"t":"次韵张氏女弟咏雪","f":"七言律诗","c":["天上空多地上稀，初寒风力故应微。","那能镇压黄尘起，强欲侵凌白日飞。","邑犬横来矜意气，窟蟾偷出助光辉。","都城只有袁安惫，我亦年年幸赐衣。"]},{"t":"次韵张唐公马上","f":"七言律诗","c":["揭节初悲力不任，赐身终愧谬恩临。","病来气弱归宜早，偷取官多责恐深。","膏泽未施空谤怨，疮痍犹在岂讴吟。","黄昏信马江城路，欲访何人话此心。"]},{"t":"次韵张德甫奉议","f":"七言律诗","c":["知君非我载醪人，终日相随免污茵。","赏尽高山见流水，唱残白雪值阳春。","中分香积如来钵，对现毗耶长者身。","谁拂定林幽处壁，与君图写继吾真。"]},{"t":"次韵杨乐道述怀之作","f":"七言律诗","c":["素心非不慕前修，自怪因循欲白头。","猎较趣时终琐琐，画墁营职信悠悠。","濠梁最忆知鱼乐，牢策翻惭为彘谋。","尚有故人能慰我，诗成珠玉每相投。"]},{"t":"次韵陆定远以谪往来求诗","f":"七言律诗","c":["牢落何由共一樽，相望空复叹芝焚。","济时尚负生平学，慰我应多别后文。","可但风流追甫白，由来家世出机云。","行吟强欲偷新格，自笑安能到万分。"]},{"t":"次韵陈学士小园即事","f":"七言律诗","c":["墙屋虽无好鸟鸣，池塘亦未有蛙声。","树含宿雨红初入，草倚朝阳绿更生。","万物天机何得丧，百年心事不将迎。","与君杖策聊观化，搔首春风眼尚明。"]},{"t":"次韵和吴仲庶池州齐山画图","f":"七言律诗","c":["省中何忽有崔嵬，六幅生绡坐上开。","指点便知岩石处，登临新作使君来。","雅怀重向丹青得，胜势兼随翰墨回。","更想杜郎诗在眼，一江春雪下离堆。"]},{"t":"次韵和甫咏雪","f":"七言律诗","c":["奔走风云四面来，坐看山垄玉崔嵬。","平治险秽非无德，润泽焦枯是有才。","势合便疑包地尽，功成终欲放春回。","寒乡不念丰年瑞，只忆青天万里开。"]},{"t":"次韵和甫春日金陵登台","f":"七言律诗","c":["钟山漠漠水洄洄，西有陵云百尺台。","万物已随和气动，一樽聊与故人来。","天边幽鸟鸣相和，地上晴烟扫不开。","愁眼看春长恐尽，直须去取六龙回。"]},{"t":"次韵奉和蔡枢密南京种山药法","f":"七言律诗","c":["区种抛来六七年，春风条蔓想宛延。","难追老圃莓苔径，空对珍盘玳瑁筵。","嘉种忽传河右壤，灵苗更长阙西偏。","故畦穿斸知何日，南望钟山一慨然。"]},{"t":"次韵奉酬李质夫","f":"七言律诗","c":["逸少池边有旧山，几年征泪染衣斑。","驽骀自饱方争路，騕袅长饥不在闲。","雪涨江南归浩荡，烟埋河朔去间关。","劳歌一听皆愁思，况我心非木石顽。"]},{"t":"次韵奉酬觉之","f":"七言律诗","c":["久知乘传入西州，鸡黍从容本不谋。","户外惊尘尺书至，眼中飞浪片帆收。","山林病骨烦三顾，湖海离肠欲万周。","尚有光华贲岑寂，箧中佳句得长留。"]},{"t":"次韵昌叔岁暮","f":"五言律诗","c":["城云漏日晚，树冻裹春深。","糁密鱼虽暖，巢危鹤更阴。","横风高彍弩，残溜细鸣琴。","岁换儿童喜，还伤老大心。"]},{"t":"次韵昌叔怀灊楼读书之乐","f":"七言律诗","c":["志食长年不得休，一巢无地拙于鸠。","聊为薄宦容身者，能免高人笑我不。","道德文章吾事落，尘埃波浪此生浮。","看君别后行藏意，回顾灊楼祇自羞。"]},{"t":"次韵昌叔咏尘","f":"七言律诗","c":["尘土轻飏不自持，纷纷生物更相吹。","翻成地上高烟雾，散在人间要路岐。","一世竞驰甘睬目，几家清坐得轩眉。","超然祇有江湖上，还见波涛恐我时。"]},{"t":"次韵舍弟常州官舍应客","f":"七言律诗","c":["霜雪纷纷上鬓毛，忧时自悔目空蒿。","桑麻祇欲求三亩，势利谁能算一毫。","此地旧传公子札，吾心真慕伯成高。","飘然更有乘桴兴，万里寒江正复艚。"]},{"t":"次韵舍弟赏心亭即事二首 其二","f":"七言律诗","c":["霸气消磨不复存，旧朝台殿祇空村。","孤城倚薄青天近，细雨侵凌白日昏。","稍觉野云成晚霁，却疑山月是朝暾。","此时江海无穷兴，醒客忘言醉客喧。"]},{"t":"次韵舍弟赏心亭即事二首 其一","f":"七言律诗","c":["槛折檐倾野水傍，台城佳气已消亡。","难披榛莽寻千古，独倚青冥望八荒。","坐觉尘沙昏远眼，忽看风雨破骄阳。","扁舟此日东南兴，欲尽江流万里长。"]},{"t":"次韵舍弟遇子固忆少述","f":"七言律诗","c":["归计何时就一廛，寒城回首意茫然。","野林细错黄金日，溪岸宽围碧玉天。","飞兔已闻追騕袅，太阿犹恨失龙泉。","遥知更忆河滨友，从事能忘我独贤。"]},{"t":"次韵范景仁二月五日夜风雪","f":"五言律诗","c":["何知此邂逅，谈笑接清扬。","对雪知春浅，回灯惜夜长。","密云通炫晃，残月堕冥茫。","故有临邛客，抽毫兴未忘。"]},{"t":"次韵质夫兄使君同年","f":"七言律诗","c":["楼堞相望一日程，春风吹急似摇旌。","莫言乐国无愁梦，赖把新诗有故情。","客舍五浆非所愿，私田三径会须成。","青云自致归公等，如我何缘得此声。"]},{"t":"次韵春日即事","f":"七言律诗","c":["人间尚有薄寒侵，和气先薰草树心。","丹白自分齐破蕾，青黄相向欲交阴。","潺潺嫩水生幽谷，漠漠轻烟动远林。","病得一官随太守，班春无助愧周任。"]},{"t":"次韵祖择之登紫微阁二首 其二","f":"七言律诗","c":["掖门相对敞铜镮，䡾䡾飞甍在两间。","润色平生知地禁，登临此日愧身闲。","浮云倒影移窗隙，落木回飙动屋山。","忽忆初来秋尚早，紫微花点绿苔斑。"]},{"t":"次韵祖择之登紫微阁二首 其一","f":"七言律诗","c":["漠漠秋阴护掖垣，青云祇在两楹间。","宫楼唱罢鸡人远，门阙朝归虎士闲。","华盖北瞻夭帝座，蓬莱东想道家山。","却惭久此随诸彦，文采初无豹一斑。"]},{"t":"次韵送程给事知越州","f":"七言律诗","c":["千骑东方占上头，如何误到北山游。","清明若睹兰亭月，暖热因忘蕙帐秋。","投老始知欢可惜，通宵豫以别为忧。","西归定有诗千首，想肯重来贲一丘。"]},{"t":"次韵唐公三首 其一 东阳道中","f":"五言律诗","c":["山蔽吴天密，江蟠楚地深。","浮云堆白玉，落日泻黄金。","渺渺随行旅，纷纷换岁阴。","强将诗咏物，收拾济时心。"]},{"t":"次韵唐公三首 其二 江行","f":"五言律诗","c":["材非当世用，毂有故人推。","使节春冬换，征帆日夜开。","南游取干越，东望得州来。","试尽风波恶，生涯亦可哀。"]},{"t":"次韵唐公三首 其三 旅思","f":"五言律诗","c":["此身南北老，愁见问征途。","地大蟠三楚，天低入五湖。","看云心共远，步月影同孤。","慷慨秋风起，悲歌不为鲈。"]},{"t":"次韵徐仲元咏梅二首 其二","f":"七言律诗","c":["旧挽青条冉冉新，花迟亦度柳前春。","肌冰绰约如姑射，肤雪参差是太真。","摇落会应伤岁晚，攀翻剩欲寄情亲。","终无驿使传消息，寂寞知谁笑与颦。"]},{"t":"次韵徐仲元咏梅二首 其一","f":"七言律诗","c":["溪杏山桃欲占新，高梅放蕊尚娇春。","额黄映日明飞燕，肌粉含风冷太真。","玉笛悲凉吹易散，冰纨生涩画难亲。","争妍喜有君诗在，老我翛然敢效颦。"]},{"t":"次韵耿天骘大风","f":"七言律诗","c":["云埋月缺晕寒灰，飙发齐如巨象豗。","纵勇万川冰柱立，纷披千障土囊开。","鲁门未怪爰居至，郑圃何妨禦寇来。","终夜不眠谁与共，坐忘唯有一颜回。"]},{"t":"次韵致远木人洲二首 其二","f":"七言律诗","c":["杌尔何年客此洲，飘流谁弃止谁收。","无心使口肝使目，有干作身根作头。","暴露神灵难寄托，祷祠村落几依投。","纷纷剪纸真虚负，立槁安知富可求。"]},{"t":"次韵致远木人洲二首 其一","f":"七言律诗","c":["迷子山前涨一洲，木人图志失编收。","年多但有柳生肘，地僻独无茅盖头。","河侧鲍生乾尚立，江边屈子槁将投。","未妨他日称居士，能使君疑福可求。"]},{"t":"次韵陪驾观灯","f":"七言律诗","c":["并筤含风下玉除，宫商挟奏斐然殊。","福祥周室流为火，恩泽尧樽散在衢。","伏枕但能知广乐，挥毫何以报明珠。","愿留巾箧归田日，追咏公欢每自娱。"]},{"t":"次韵景仁雪霁","f":"五言律诗","c":["新声生屋霤，残点著垣衣。","委翳无多在，飘零不更飞。","坳中馀宿润，暖处自朝晖。","稍见青青色，还从柳上归。"]},{"t":"次韵答丁端州","f":"七言律诗","c":["莫嗟荒僻又离群，且喜风谣岭北闻。","铜柱虽然蛮徼接，竹符还是汉家分。","春书来逐衡阳雁，秋骑归看陇首云。","相见会知南望苦，病骸今似沈休文。"]},{"t":"次韵答平甫","f":"七言律诗","c":["高蝉抱壳悲声切，新鸟争巢谇语忙。","长树老阴欺夏日，晚花幽艳敌春阳。","云归山去当檐静，风过溪来满坐凉。","物物此时皆可赋，悔予千里不相将。"]},{"t":"次韵答陈正叔二首 其二","f":"七言律诗","c":["田宅荒凉去复来，诗书颜发两尘埃。","忘机自许鸥相狎，得祸谁期鹤见媒。","此道未行身有待，古人不见首空回。","何当水石他年住，更把韦编静处开。"]},{"t":"次韵答陈正叔二首 其一","f":"七言律诗","c":["青衫憔悴北归来，发有霜根面有埃。","群吠我方憎猘子，一鸣谁更识龙媒。","功名落落求难值，日月沄沄去不回。","胜事与身何等近，酒樽诗卷数须开。"]},{"t":"次韵答彦珍","f":"七言律诗","c":["手得封题手自开，一篇美玉缀玫瑰。","众知圆媚难论报，自顾穷愁敢角才。","君卧南阳惟畎亩，我行西路亦风埃。","相逢不必嗟劳事，尚欲赓歌咏起哉。"]},{"t":"次韵董伯懿松声","f":"七言律诗","c":["天机自动岂关情，能作人间物外声。","暝聒一堂无客梦，晓悲千嶂有猿惊。","庙中奏瑟沈三叹，堂下吹箫失九成。","俚耳纷纷多郑卫，直须闻此始心清。"]},{"t":"次韵微之即席","f":"词","c":["酿成吴米野油囊，却爱清谈气味长。","闲日有僧来北阜，平时无盗出南塘。","风亭对竹酬孤峭，雪径寻梅认暗香。","江水中?应未变，一杯终欲就君尝。"]},{"t":"次韵酬子玉同年","f":"七言律诗","c":["盛德无心漠北窥，蕃胡亦恐势方羸。","塞垣高垒深沟地，幕府轻裘缓带时。","赵将时皆思李牧，楚音身自感钟仪。","惭君许我论边锁，俎豆平生却少知。"]},{"t":"次韵酬王太祝","f":"七言律诗","c":["尘土波澜不自期，飘然身与愿相违。","衰根要路知难植，病羽长年欲退飞。","高论已嗟能听少，力行还恨赋材微。","惭君俊少今知我，一见心如客得归。"]},{"t":"次韵酬邓子仪二首 其二","f":"七言律诗","c":["金陵邂逅府东偏，手得新蒲每共编。","采石偶耕垂百日，青溪并钓亦三年。","君才有用方求禄，我志无成稍问田。","一笑欲论心迹事，白头相就且攲眠。"]},{"t":"次韵酬邓子仪二首 其一","f":"七言律诗","c":["青溪相值各青春，老去临流辄损神。","事事只随波浪去，年年空得鬓毛新。","论心未忍遗横目，干世还忧近逆鳞。","嘉句感君邀我厚，自嗟才不异常人。"]},{"t":"次韵酬朱昌叔五首 其五","f":"七言律诗","c":["乐世闲身岂易求，岩居川观更何忧。","放怀自事如初服，买宅相招亦本谋。","名誉子真矜谷口，事功新息困壶头。","知君于此皆无累，长得追随圹埌游。"]},{"t":"次韵酬朱昌叔五首 其四","f":"七言律诗","c":["白下门东春水流，相看一噱散千忧。","穿梅入柳曾莫逆，度堑缘冈初不谋。","世事但如吹剑首，官身难即问刀头。","长临锻灶真自苦，有兴复来从我游。"]},{"t":"次韵酬朱昌叔五首 其三","f":"七言律诗","c":["乌榜登临兴未休，共言何许更消忧。","联裾萧寺寻真觉，方驾孙陵吊仲谋。","语罢每开欢笑口，诗来仍掉苦吟头。","已知轩冕真吾累，且可追随马少游。"]},{"t":"次韵酬朱昌叔五首 其二","f":"七言律诗","c":["去年音问隔淮州，百谪难知亦我忧。","前日杯盘共江渚，一欢相属岂人谋。","山蟠直渎输淮口，水抱长干转石头。","乘兴舟舆无不可，春风从此与公游。"]},{"t":"次韵酬朱昌叔五首 其一","f":"七言律诗","c":["点也自殊由与求，既成春服更何忧。","拙于人合且天合，静与道谋非食谋。","未爱京师传谷口，但知乡里胜壶头。","嗟予老矣无一事，复得此君相与游。"]},{"t":"次韵酬吴彦珍见寄二首 其二","f":"七言律诗","c":["篁竹荒茅五亩馀，生涯山蕨与泉鱼。","家贫殖货羞端木，乡里传书比仲舒。","白日忆君聊远望，青林嗟我似逃虚。","春风渺渺乌塘尾，漫得东来一纸书。"]},{"t":"次韵酬吴彦珍见寄二首 其一","f":"七言律诗","c":["君作新诗故起予，一吟聊复报双鱼。","杖藜高径谁来往，散帙空堂自卷舒。","树外鸟啼催晚种，花间人语趁朝虚。","春风处处堪携手，何事临池苦学书。"]},{"t":"次韵酬宋中散二首 其二","f":"七言律诗","c":["超然京洛谅难双，处在家庭誉在邦。","道义门中窥户牖，风骚坛上见麾幢。","素书款款谁怜杜，彩笔遒遒独胜江。","信美贤公有才子，笃诚真复类尨降。"]},{"t":"次韵酬宋中散二首 其一","f":"七言律诗","c":["初见彤庭赐履双，便参东阁寄南邦。","时闻正论除疑网，每读高辞折慢幢。","陈迹欲寻无复日，旧恩思报有如江。","风流今见佳公子，投老心旌一片降。"]},{"t":"次韵酬宋玘六首 其六","f":"七言律诗","c":["山陂畴昔从吾亲，诸父先生各佩纷。","零落长年谁语此，迟回故地却逢君。","衣冠偶坐论经术，襁褓当时刺绣文。","更怪高材终未遇，有司何日选方闻。"]},{"t":"次韵酬宋玘六首 其五","f":"七言律诗","c":["无能私愿祇求田，时物安能学计然。","凿井未成歌击壤，射熊犹得梦钧天。","遥思故国归来日，留滞新恩已去年。","携手与君游最乐，春风波上水溅溅。"]},{"t":"次韵酬宋玘六首 其四","f":"七言律诗","c":["远迹荒郊谢俊豪，春风谁与驻干旄。","故交重趼恩何厚，新句连篇韵更高。","美似狂酲初啖蔗，快如衰病得观涛。","久知坏冶成天巧，岂与人间共一陶。"]},{"t":"次韵酬宋玘六首 其三","f":"七言律诗","c":["城中灯火照青春，远引吾方避纠纷。","游衍水边追野马，啸歌林下应山君。","愁寻径草无求仲，喜对檐花有广文。","邂逅一樽聊酩酊，声名身后岂须闻。"]},{"t":"次韵酬宋玘六首 其二","f":"七言律诗","c":["东风渺渺客天涯，病眼先春已见花。","远欲报君羞强聒，老知随俗厌雄誇。","穷通往事真如梦，得失秋毫岂更嗟。","邂逅故人唯有醉，醉中衣帻任攲斜。"]},{"t":"次韵酬宋玘六首 其一","f":"七言律诗","c":["洗雨吹风一月春，山红漫漫绿纷纷。","褰裳远野谁从我，散策空陂忽见君。","青眼坐倾新岁酒，白头追诵少年文。","因嗟涉世终无补，久使高材雍上闻。"]},{"t":"次韵酬府推仲通学士雪中见寄","f":"七言律诗","c":["朝来看雪咏君诗，想见朱衣在赤墀。","为问火城将策试，何如云屋听窗知。","曲墙稍觉吹来密，穷巷终怜扫去迟。","欲访故人非兴尽，自缘无路得传卮。"]},{"t":"次韵酬徐仲元","f":"七言律诗","c":["投老逍遥屺与堂，天刑真已脱桁杨。","缘源静翳无鱼淰，度谷深追有鸟颃。","每苦交游寻五柳，最嫌尸祝扰庚桑。","相看不厌唯夫子，风味真如顾建康。"]},{"t":"次韵酬龚深甫二首 其二","f":"七言律诗","c":["握手东冈雪满簪，后期惆怅老吴蚕。","芳辰一笑真难值，暮齿相思岂久堪。","他日杜诗传渭北，几时周宅对漳南。","百年邂逅能多少，且可勤来共草庵。"]},{"t":"次韵酬龚深甫二首 其一","f":"七言律诗","c":["恩容楚老护松楸，复得一龚从我游。","讲肄剧谈兼祖谢，舞雩高蹈异求由。","北寻五柞故未憖，东挽三杨仍有樛。","陟巘降原从此始，但无瑶玉与君舟。"]},{"t":"汜水寄和甫","f":"七言律诗","c":["虎牢关下水逶迤，想汝飘然过此时。","洒血祇添波浪起，脱身难借羽翰追。","留连厚禄非朝隐，乖隔残年更土思。","已卜冶城三亩地，寄声知我有归期。"]},{"t":"江上二首 其二","f":"五言律诗","c":["书自江边使，乡邻病饿稠。","何言万里客，更作百身忧。","补败今谁恤，趋生我自羞。","西南双病眼，落日倚扁舟。"]},{"t":"江上二首 其一","f":"五言律诗","c":["潮连风浩荡，沙引客淹留。","落日更清坐，空江无近舟。","共看蒹苇宅，聊即稻粱谋。","未敢嗟艰食，凶年半九州。"]},{"t":"江亭晚眺","f":"五言律诗","c":["日下崦嵫外，秋生沆砀閒。","清江无限好，白鸟不胜闲。","雨过云收岭，天空月上湾。","归鞍侵调角，回首六朝山。"]},{"t":"江南","f":"五言律诗","c":["江南春起柂，秋至尚波涛。","问舍才能定，呼舟已复操。","行歌付浩荡，归梦得萧骚。","冉冉欲何补，纷纷为此劳。"]},{"t":"汤泉","f":"五言律诗","c":["寒泉诗所咏，独此沸如烝。","一气无冬夏，诸阳自废兴。","人游不附火，虫出亦疑冰。","更忆骊山下，歊然雪满塍。"]},{"t":"自白土村入北寺二首 其二","f":"五言律诗","c":["雨过百泉出，秋声连众山。","独寻飞鸟外，时渡乱流间。","坐石偶成歇，看云相与还。","会须营一亩，长此听潺湲。"]},{"t":"自白土村入北寺二首 其一","f":"五言律诗","c":["木杪田家出，城阴野径分。","溜渠行碧玉，畦稼卧黄云。","薄槿烟脂染，深荷水麝焚。","夕阳人不见，鸡鹜自成群。"]},{"t":"自府中归寄西庵行详","f":"五言律诗","c":["意衰难自力，扶路便思还。","强逐萧骚水，遥看惨淡山。","行寻香草遍，归漾晚云间。","西崦分明见，幽人不可攀。"]},{"t":"自金陵如丹阳道中有感","f":"七言律诗","c":["数百年来王气消，难将前事问渔樵。","苑方秦地皆芜没，山借扬州更寂寥。","荒埭暗鸡催月晓，空场老雉挟春骄。","豪华祇有诸陵在，往往黄金出市朝。"]},{"t":"至开元僧舍上方次韵舍弟二月一日之作","f":"七言律诗","c":["溪谷溅溅嫩水通，野田高下绿蒙茸。","和风满树笙簧杂，霁雪兼山粉黛重。","万里有家归尚隔，一廛无地去何从。","伤春故欲西南望，回首荒城已暮钟。"]},{"t":"舟中读书","f":"五言律诗","c":["冉冉木叶下，萧萧山水秋。","浮云带田野，落日抱汀洲。","归卧无与语，出门何所求。","未能忘感慨，聊以古人谋。"]},{"t":"舟夜即事","f":"五言律诗","c":["火炬临遥岸，馀光照客船。","水明鱼中饵，沙暖鹭忘眠。","感概无穷事，迟回欲晓天。","山泉如有意，枕上送潺湲。"]},{"t":"过山即事","f":"七言律诗","c":["却过兹山已九年，江湖身世只飘然。","曲城丘墓心空折，盐步庭闱眼欲穿。","惨惨野云生陇底，萧萧饥马立风前。","转多愁思摧华发，早晚轻舟上秀川。"]},{"t":"过故居","f":"五言律诗","c":["溯筏开新屋，扶舆绕故园。","事遗心独寄，路翳目空存。","野果寒林寂，蛮花午簟温。","难忘旧时处，欲宿愧桑门。"]},{"t":"邢太保有鹤折翼以诗伤之客有记翎经冥三韵而忘其诗者因作四韵","f":"七言律诗","c":["不为摧伤改性灵，静中犹见好仪形。","每怜今日长垂翅，却悔当时误剪翎。","医得旧创犹有法，相知多难岂无经。","稻粱且向人间觅，莫羡抟风起北冥。"]},{"t":"严陵祠堂","f":"七言律诗","c":["汉庭来见一羊裘，默默俄归旧钓舟。","迹似磻溪应有待，世无西伯可能留。","崎岖冯衍才终废，索寞桓谭道不谋。","勺水果非鳣鲔地，放身沧海亦何求。"]},{"t":"何处难忘酒二首 其二","f":"五言律诗","c":["何处难忘酒，君臣会合时。","深堂拱尧舜，密席坐皋夔。","和气袭万物，欢声连四夷。","此时无一盏，真负鹿鸣诗。"]},{"t":"何处难忘酒二首 其一","f":"五言律诗","c":["何处难忘酒，英雄失志秋。","庙堂生莽卓，岩谷死伊周。","赋敛中原困，干戈四海愁。","此时无一盏，难遣壮图休。"]},{"t":"初去临川","f":"七言律诗","c":["东浮溪水渡长林，上坂回头一拊心。","已觉省烦非仲叔，安能养志似曾参。","忧伤遇事纷纷出，疾病乘虚亹亹侵。","未有半分求自赎，恐填沟壑更沾襟。"]},{"t":"初憩和州","f":"五言律诗","c":["衣足一囊弊，粟馀三釜陈。","犹依食贫地，已愧省烦人。","尘土病催老，风波愁过春。","诗书今在眼，还欲讨经纶。"]},{"t":"别葛使君","f":"七言律诗","c":["邑屋为儒知善政，市门多粟见丰年。","追攀更觉相逢晚，谈笑难忘欲别前。","客幕雅游皆置榻，令堂清坐亦鸣弦。","轻舟后夜沧江北，回首春城空黯然。"]},{"t":"别雷国辅之皖山","f":"七言律诗","c":["侍郎忧国最贤劳，太尉西州第一豪。","家庙比来闻泽厚，公孙今果见才高。","明时尚使龙蛇蛰，壮志空传虎豹韬。","莫厌皖山穷绝处，不妨云水助风骚。"]},{"t":"即事","f":"七言律诗","c":["河流南苑岸西斜，风有晶光露有华。","门柳故人陶令宅，井桐前日总持家。","嘉招欲覆杯中渌，丽唱仍添锦上花。","便作武陵樽俎客，川源应未少红霞。"]},{"t":"即事","f":"五言律诗","c":["径暖草如积，山晴花更繁。","纵横一川水，高下数家村。","静憩鸡鸣午，荒寻犬吠昏。","归来向人说，疑是武陵源。"]},{"t":"即席次韵微之泛舟","f":"七言律诗","c":["画舸幽寻北果园，应将陈迹问桑门。","地随墙墅行多曲，天著冈峦望易昏。","故国时平空有木，荒城人少半为村。","悠悠兴废皆如此，赖付乾愁酒一樽。"]},{"t":"吴正仲谪官得故人寄蟹以诗谢之余次其韵","f":"五言律诗","c":["越客上荆舠，秋风忆把螯。","故烦分巨跪，持用佐清糟。","饮量宽沧海，诗锋捷孟劳。","甘餐饱觞咏，馀事付钧陶。"]},{"t":"吴江","f":"五言律诗","c":["莽莽昔登临，秋风一散襟。","地留孤屿小，天入五湖深。","柑橘无千里，鱼虾有万金。","吾虽轻范蠡，终欲此幽寻。"]},{"t":"呈陈和叔","f":"七言律诗","c":["毁车为屋仅容身，三岁相要薄主人。","昼寓椁砖常至夜，冬沿沟彴复寻春。","南陔不洎公归里，苍墓垂成我丧亲。","后会纵多无此乐，山林投老一伤神。"]},{"t":"呈柳子玉同年","f":"七言律诗","c":["三年不上邺王台，鸿雁归时又北来。","水底旧波吹岁换，柳梢新叶卷春回。","尘沙漠漠凋双鬓，箫鼓匆匆把一杯。","劳事欲歌无与和，衰颜思见故人开。"]},{"t":"宋中道挽辞","f":"五言律诗","c":["文史传家学，声名动帝除。","兰堂空作赋，金匮不雠书。","胜事悲畴昔，清谈想绪馀。","吹箫索上去，归国有魂车。"]},{"t":"张侍郎示东府新居诗因而和酬二首 其二","f":"七言律诗","c":["荣观流传动草莱，中官赐设上尊开。","鼓歌䆗窱听疑梦，肴果联翩馈有台。","斧藻故应宜旧德，栋梁非复称凡材。","虚堂欲踵曹参事，试问齐人或肯来。"]},{"t":"张侍郎示东府新居诗因而和酬二首 其一","f":"七言律诗","c":["得贤方慕北山莱，赤白中天二府开。","功谢萧规惭汉第，恩从隗始诧燕台。","曾留上主经过迹，更费高人赋咏才。","自古落成须善颂，扫除东阁望公来。"]},{"t":"张剑州至剑一日以亲忧罢","f":"七言律诗","c":["客舍飞尘尚满鞯，却寻东路想茫然。","白头反哺秦乌侧，流血思归蜀鸟前。","今日相逢知怅望，几时能到与留连。","行看万里云西去，倚马春风不忍鞭。"]},{"t":"怀古二首 其二","f":"五言律诗","c":["长者一床室，先生三径园。","非无饭满钵，亦有酒盈樽。","不起华边坐，常开柳际门。","漫知谈实相，欲辩已忘言。"]},{"t":"怀古二首 其一","f":"五言律诗","c":["日密畏前境，渊明欣故园。","那知饭不赐，所喜菊犹存。","亦有床座好，但无车马喧。","谁为吾侍者，稚子候柴门。"]},{"t":"怀吴显道","f":"五言律诗","c":["南郭红亭冷，西山白道曛。","江光凌翠气，洲色乱黄云。","岁暮谁邀客，情亲故忆君。","天涯独惆怅，归鸟黑纷纷。"]},{"t":"怀舒州山水呈昌叔","f":"七言律诗","c":["山下飞鸣黄栗留，溪边饮啄白符鸠。","不知此地从君处，亦有他人继我不。","尘土生涯休荡涤，风波时事只飘浮。","相看发秃无归计，一梦东南即自羞。"]},{"t":"拟寒山拾得二十首 其八","f":"五言律诗","c":["幸身无事时，种种妄思量。","张三腨口窄，李四帽檐长。","失脚落地狱，将身投镬汤。","谁知受热恼，却不解思凉。"]},{"t":"李君昆弟访别长芦至淮阴追寄","f":"七言律诗","c":["怒水凭风雪垄高，乱流追我祇鱼舠。","忽看淮月临寒食，想映江春听伯劳。","道义当成麟一角，文章已秃兔千毫。","后生可畏吾知子，南北何时见两髦。"]},{"t":"李璋下第","f":"七言律诗","c":["浩荡宫门白日开，君王高拱试群材。","学如吾子何忧失，命属天公不可猜。","意气未宜轻感慨，文章尤忌数悲哀。","男儿独患无名尔，将相谁云有种哉。"]},{"t":"每见王太丞邑事甚冗而剸剧之暇犹能过访山馆兼出佳篇为赠仰叹才力因成小诗","f":"七言律诗","c":["我看繁讼频搔首，君富才明见亦常。","尚有闲襟寻水石，更留佳句似池塘。","松苗地合分高下，凫鹤天教有短长。","徐上青云犹未晚，可无音问及沧浪。"]},{"t":"沂溪怀正之","f":"五言律诗","c":["故人何处所，天角浪漫漫。","寂寞断音驿，徘徊愁肺肝。","世情纷可怪，旅况浩难安。","愿化东南鹄，高飞托羽翰。"]},{"t":"泛舟青溪入水门登高斋奉呈叔康","f":"七言律诗","c":["簿领纷纷惜此时，起携佳客散沈迷。","十围但见诸营柳，九曲难寻故国溪。","牵埭欲随流水远，放船终碍画桥低。","子猷清兴何曾尽，想忆高斋更一跻。"]},{"t":"纸暖閤","f":"七言律诗","c":["联屏盖障一寻方，南设钩帘北置床。","侧座对敷红絮暖，仰窗分启碧纱凉。","毡庐易以梅烝坏，锦幄终于草野妨。","楚谷越藤真自称，每糊因得减书囊。"]},{"t":"苏才翁挽辞二首 其二","f":"五言律诗","c":["翰墨随谈啸，风流在弟兄。","浮名同逆旅，壮志负平生。","使节何年去，丧车故老迎。","悠悠京口外，落日照铭旌。"]},{"t":"苏才翁挽辞二首 其一","f":"五言律诗","c":["空馀一丹旐，无复两朱轓。","寂寞蒜山渡，陂陀京口原。","音容归绘画，才业付儿孙。","尚有故人泪，沧江相与翻。"]},{"t":"身闲","f":"五言律诗","c":["身闲宜晚食，岁晏忌晨兴。","人自嘲便腹，吾方乐曲肱。","睡蛇虽不去，梦虺已无凭。","寄语中林客，思禅病未能。"]},{"t":"还自河北应客","f":"五言律诗","c":["愧客问谣俗，旧传今自如。","材难知骥马，味美赛河鱼。","塞水移民久，川防动众初。","北人虽异论，时议或非疏。"]},{"t":"还自舅家书所感","f":"五言律诗","c":["行行过舅居，归路指亲庐。","日苦树无赖，天空云自如。","黄焦下泽稻，绿碎短樊蔬。","沮溺非吾意，悯嗟聊驻车。"]},{"t":"闲居遣兴","f":"七言律诗","c":["惨惨秋阴绿树昏，荒城高处闭柴门。","愁消日月忘身世，静对溪山忆酒樽。","南去干戈何日解，东来驲骑此时奔。","谁将天下安危事，一把诗书子细论。"]},{"t":"陈动之秘丞挽辞二首 其二","f":"五言律诗","c":["人间三十六，追逐孔鸾飞。","似欲来为瑞，如何去不归。","琴樽已寂寞，笔墨尚光辉。","空复平生友，西华岂易依。"]},{"t":"陈动之秘丞挽辞二首 其一","f":"五言律诗","c":["年高汉贾谊，官过楚荀卿。","望古君无憾，论今我未平。","有风吹画翣，无日照佳城。","空复文章在，流传世上名。"]},{"t":"陈师道宰乌程县","f":"五言律诗","c":["尝闻太丘长，德不负公卿。","墟墓今千载，昆云亦一城。","本怀深闭蓄，馀论略施行。","故自有仁政，能传家世声。"]},{"t":"陈君式大夫恭轩","f":"七言律诗","c":["恭轩静对北堂深，新斸檀栾一亩阴。","膝下往来前日事，眼中封植去年心。","每怀樽斝沾馀沥，独喜弦歌有嗣音。","肯搆会须门阀大，世资何用满籯金。"]},{"t":"京兆杜婴大醇能读书其言近庄其为人旷达而廉清自托于医无贵贱请之辄往卒也以诗二首伤之 其一","f":"五言律诗","c":["萧瑟野衣巾，能忘至老贫。","避嚣依市井，蒙垢出埃尘。","接物工齐物，劳身耻为身。","伤心宿昔地，不复见斯人。"]},{"t":"京兆杜婴大醇能读书其言近庄其为人旷达而廉清自托于医无贵贱请之辄往卒也以诗二首伤之 其二","f":"五言律诗","c":["叔度医家子，君平卜肆翁。","萧条昨日事，彷佛古人风。","旧宅雨生菌，新阡寒转蓬。","存亡谁一问，嗟我亦穷空。"]},{"t":"到家","f":"七言律诗","c":["五年羁旅倦风埃，旧里依然似梦回。","猿鸟不须怀怅望，溪山应亦笑归来。","身闲自觉贫无累，命在谁论进有材。","秋晚吾庐更萧洒，沙边烟树绿洄洄。"]},{"t":"到舒州次韵答平甫","f":"七言律诗","c":["夜别江船晓解骖，秋城气象亦潭潭。","山从树外青争出，水向沙边绿半涵。","行问啬夫多不记，坐论公瑾少能谈。","只愁地僻无宾客，旧学从谁得指南。"]},{"t":"程公辟转运江西","f":"七言律诗","c":["江西一节铸黄金，最慰章滨父老心。","长孺向来真强予，次公今不异重临。","馀风尚有欢谣在，陈迹非无胜事寻。","豫想新诗能寄我，十年华省故情深。"]},{"t":"和文淑湓浦见寄","f":"七言律诗","c":["多难漂零岁月赊，空馀文墨旧生涯。","相看楚越常千里，不及朱陈似一家。","发为感伤无翠葆，眼从瞻望有玄花。","唯诗与我宽愁病，报尔何妨赋棣华。"]},{"t":"和王司封会同年","f":"七言律诗","c":["收科天陛顷同时，回首相欢事亦稀。","追讲旧游犀麈脱，交酬新唱彩笺飞。","直须倾倒樽中酒，休惜淋浪坐上衣。","日暮主翁留客辖，会稽聊滞买臣归。"]},{"t":"和平甫招道光法师","f":"七言律诗","c":["鍊师投老演真乘，像劫空王爪与肱。","于总持门通一路，以光明藏续千灯。","从容发口酬摩诘，邂逅持心契慧能。","新句得公还有赖，古人诗字耻无僧。"]},{"t":"和平甫寄陈正叔","f":"七言律诗","c":["强行南仕莫辞勤，闻说田园已旷耘。","纵使一区犹有宅，可能三月尚无君。","且同元亮倾樽酒，更与灵均续旧文。","此道废兴吾命在，世间滕口任云云。"]},{"t":"和正叔怀其兄草堂","f":"七言律诗","c":["茆堂竹树水之滨，耕稼逍遥似子真。","小吏一身今倦宦，先生三亩独安贫。","欲抛县印辞黄绶，来伴山冠戴白纶。","祇恐明时收士急，不容家有两闲人。"]},{"t":"和仲庶夜过新开湖忆冲之仲涂共泛","f":"五言律诗","c":["水远浮秋色，河空洗夜氛。","行随一明月，坐失两孤云。","露发此时湿，风颜何处醺。","淹留各有趣，不比汉三君。"]},{"t":"和吴相公东府偶成","f":"七言律诗","c":["承华往岁幸踌躇，风月清谈接绪馀。","并辔趁朝今已老，连墙得屋喜如初。","诛茅我梦江皋地，浇薤公思洛水渠。","敛退故应容拙者，先营环堵祭牢蔬。"]},{"t":"和吴御史临淮感事","f":"七言律诗","c":["栅锁城扉晓一开，柂牙车轴转成雷。","黄尘欲碍龟山出，白浪空分汴水来。","澄观有材邀昧陋，霁云无力报奸回。","骚人此日追前事，悲气随风动管灰。"]},{"t":"和宋太博服除还朝简诸朋旧","f":"七言律诗","c":["呼门初起外廷臣，秀气棱棱动搢绅。","谈论坐来能慰我，篇章传出亦惊人。","生刍一束他年阙，伐木相求此地新。","便欲与君同乐处，穷通馀事不关身。"]},{"t":"和杨乐道见寄","f":"七言律诗","c":["宅带园林五亩馀，萧条还似茂陵居。","杀青满架书新缮，生白当窗室久虚。","孤学自难窥奥密，重言犹得慰空疏。","相思每欲投诗社，只待春蒲叶又书。"]},{"t":"和舍弟舟上示沈道源","f":"七言律诗","c":["还装欲尽喜舟轻，更喜嘉宾伴此行。","野饮不忘鱼可钓，旅羹何惜雁能鸣。","西山壮马先归牧，南穴残枭欲就烹。","忧国自多廊庙宰，与君诗酒尽交情。"]},{"t":"和祖仁晚过集禧观","f":"七言律诗","c":["妍暖聊随马首东，春衫犹未著方空。","烟霞送色归瑶水，山木分香绕阆风。","壮发已输尘外绿，衰颜漫到酒边红。","日斜归去人间世，却记前游似梦中。"]},{"t":"和唐公舍人访净因","f":"五言律诗","c":["西城方外士，传法自南华。","高蹈玩一世，旁通兼数家。","来游仁者静，传咏正而葩。","乘兴何时再，还能托后车。"]},{"t":"和栖霞寂照庵僧云渺","f":"五言律诗","c":["萧然一世外，所乐有谁同。","宴坐能忘老，斋蔬不过中。","无心为佛事，有客问家风。","笑谓西来意，虽空亦不空。"]},{"t":"和晚菊","f":"七言律诗","c":["不得黄花九日吹，空看野叶翠葳蕤。","渊明酩酊知何处，子美萧条向此时。","委翳似甘终草莽，栽培空欲傍藩篱。","可怜蜂蝶飘零后，始有闲人把一枝。"]},{"t":"和御制赏花钓鱼二首 其二","f":"七言律诗","c":["霭霭祥云辇路晴，传呼万岁杂春声。","蔽亏玉仗宫花密，映烛金沟御水清。","珠蕊受风天下暖，锦鳞吹浪日边明。","从容乐饮真荣遇，愿赋嘉鱼颂太平。"]},{"t":"和御制赏花钓鱼二首 其一","f":"七言律诗","c":["荫幄晴云拂晓开，传呼仙仗九天来。","披香殿上留朱辇，太液池边送玉杯。","宿蕊暖含风浩荡，戏鳞清映日徘徊。","宸章独与春争丽，恩许赓歌岂易陪。"]},{"t":"和曾子翊授舒掾之作","f":"七言律诗","c":["皖城终岁静如山，府掾应从到日闲。","一水碧罗裁缭绕，万峰苍玉刻孱颜。","旧游笔墨苔今老，浪走尘沙鬓已斑。","揽辔羡君桥北路，春风枝上鸟关关。"]},{"t":"和微之林亭","f":"七言律诗","c":["为有檀栾占雒阳，忆归杖策此徜徉。","观鱼得意还知乐，入鸟忘机肯乱行。","未敢许君轻去国，不应如我漫为郎。","中园日涉非无趣，保此千钟慰北堂。"]},{"t":"和微之重感南唐事","f":"七言律诗","c":["叔宝倾陈衍弊梁，可嗟曾不见兴亡。","斋祠父子终身费，酣咏君臣举国荒。","南狩皖山非故地，北师淮水失名王。","天移四海归真主，谁诱昏童肯用良。"]},{"t":"和蔡枢密孟夏旦日西府书事","f":"七言律诗","c":["宫阙初晴气象饶，宝车攒毂会东朝。","重轮庆自离明发，内壤阴随解泽消。","赐篚外廷纷锦绣，燕庖中禁续薪樵。","联翩入贺知君意，咫尺威颜不隔霄。"]},{"t":"和蔡副枢贺平戎庆捷","f":"七言律诗","c":["城郭名王据两陲，军前一日送降旗。","羌兵自此无传箭，汉甲如今不解累。","幕府上功联旧伐，朝廷称庆具新仪。","周家道泰西戎喙，还见诗人咏串夷。"]},{"t":"咏梅","f":"七言律诗","c":["颇怪梅花不肯开，岂知有意待春来。","灯前玉面披香出，雪后春容取胜回。","触拨清诗成走笔，淋漓红袖趣传杯。","望尘俗眼那知此，只买夭桃艳杏栽。"]},{"t":"垂虹亭","f":"七言律诗","c":["坐觉尘襟一夕空，人间似得羽翰通。","暮天窈窈山衔日，爽气骎骎客御风。","草木韵沉高下外，星河影落有无中。","飘然更待乘桴伴，一到扶桑兴未穷。"]},{"t":"夜读试卷呈君实待制景仁内翰","f":"七言律诗","c":["篝灯时见语惊人，更觉挥毫捷有神。","学问比来多可喜，文章非特巧争新。","蕉中得鹿初疑梦，牖下窥龙稍眩真。","邂逅两贤时所服，坐令孤朽得相因。"]},{"t":"奉招吉甫","f":"七言律诗","c":["经纶无地委蓬蒿，凛凛胸怀且自韬。","谁奋长谋平岭海，犹将馀力寄风骚。","名惭随俗贫中役，恨未收身物外高。","永夜西堂霜月冷，邀君相伴有松醪。"]},{"t":"奉寄子思以代别","f":"七言律诗","c":["南北蹉跎成两翁，悲欢邂逅笑言同。","全家欲出岭云外，匹马肯寻山雨中。","趋府折腰嗟踽踽，听泉分手惜匆匆。","寄声但有加餐饭，才业如君岂久穷。"]},{"t":"奉酬杨乐道","f":"七言律诗","c":["邂逅联裾殿阁春，却愁容易即离群。","相知不必因相识，所得如今过所闻。","近代声名出卢骆，前朝笔墨数渊云。","与公家世由来事，愧我初无百一分。"]},{"t":"始与韩玉汝相近居遂相与游今居复相近而两家子唱和诗相属因有此作","f":"七言律诗","c":["羁旅儿童得近邻，相知邂逅即情亲。","当时岂意两家子，此地更为同社人。","勋业弹冠知白首，文章投笔让青春。","万金虽愧君多产，比我渊明亦未贫。"]},{"t":"姑胥郭","f":"七言律诗","c":["误褫云巾别故山，抵吴由越两间关。","千家渔火秋风市，一叶归舟暮雨湾。","旅病愔愔如困酒，乡愁脉脉似连环。","情知带眼从前缓，更恐颠毛自此斑。"]},{"t":"季春上旬苑中即事","f":"七言律诗","c":["辇路行看斗柄东，帘垂殿阁转春风。","树林隐翳灯含雾，河汉攲斜月坠空。","新蕊漫知红簌簌，旧山常梦直丛丛。","赏心乐事须年少，老去应无日再中。"]},{"t":"孤桐","f":"五言律诗","c":["天质自森森，孤高几百寻。","陵霄不屈己，得地本虚心。","岁老根弥壮，阳骄叶更阴。","明时思解愠，愿斲五弦琴。"]},{"t":"定林","f":"五言律诗","c":["漱甘凉病齿，坐旷息烦襟。","因脱水边屦，就敷岩上衾。","但留云对宿，仍值月相寻。","真乐非无寄，悲虫亦好音。"]},{"t":"宜春苑","f":"词","c":["宜春旧台沼，日暮一登临。","解带行苍藓，移?坐绿阴。","树疏啼鸟远，水静落花深。","无复增修事，君王惜费金。"]},{"t":"岭云","f":"七言律诗","c":["岭云合处小盘桓，人得敷衾马解鞍。","寒荚著天榆历历，净华浮海桂团团。","交游涣散渊明喜，吏卒萧条叔夜宽。","方丈老翁无一发，更知来不为皮冠。"]},{"t":"忠献韩公挽辞二首 其二","f":"七言律诗","c":["两朝身与国安危，典策哀荣此一时。","木稼尝闻达官怕，山颓果见哲人萎。","英姿爽气归图画，茂德元勋在鼎彝。","幕府少年今白发，伤心无路送灵软。"]},{"t":"忠献韩公挽辞二首 其一","f":"七言律诗","c":["心期自与众人殊，骨相知非浅丈夫。","独斡斗杓环帝座，亲扶日毂上天衢。","锄耰万里山无盗，衮绣三朝国有儒。","爽气忽随秋露尽，但留陈迹在龟趺。"]},{"t":"招丁元珍","f":"五言律诗","c":["默默不自得，纷纷何所为。","画墁聊取食，猎较且随时。","秋入江湖暗，风生草树悲。","黄花一杯酒，思与故人持。"]},{"t":"招吕望之使君","f":"七言律诗","c":["潮沟东路两牛鸣，十亩漪涟一草亭。","委质山林如许国，寄怀鱼鸟欲忘形。","纷纷易变浮云白，落落谁钟老柏青。","尚有使君同好恶，想随秋水肯扬舲。"]},{"t":"昆山慧聚寺次张祜韵","f":"五言律诗","c":["峰岭互出没，江湖相吐吞。","园林浮海角，台殿拥山根。","百里见渔艇，万家藏水村。","地偏来客少，幽兴秪桑门。"]},{"t":"松江","f":"七言律诗","c":["宛宛虹霓堕半空，银河直与此相通。","五更缥缈千山月，万里凄凉一笛风。","鸥鹭稍回青霭外，汀洲时起绿芜中。","骚人自欲留佳句，忽忆君诗思已穷。"]},{"t":"欣会亭","f":"五言律诗","c":["数家邻水竹，一坞共云林。","晚食静适己，独谣欣会心。","移床随漫兴，操策取幽寻。","未爱神锥汝，犹怜妙斲琴。"]},{"t":"河中使君修撰陆公挽辞三首 其三","f":"七言律诗","c":["前旌一幅粉书名，行路知君亦涕零。","遂失词人空甫里，谩留悲鹤老华亭。","主张寿禄无三甲，收拾文章有六丁。","归处仙龛终不远，新坟东见海山青。"]},{"t":"河中使君修撰陆公挽辞三首 其二","f":"七言律诗","c":["皖城初得故人诗，叹息龙媒踠壮时。","太史滞留终不偶，中郎制作遂无施。","二千石禄今何有，四十车书昔漫知。","海曲冷云埋拱木，延州空挂暮年悲。"]},{"t":"河中使君修撰陆公挽辞三首 其一","f":"五言律诗","c":["文采机云后，知名实妙年。","银钩工壮丽，金薤富清妍。","批凤多新贵，凭熊数外迁。","空令猗氏监，遗爱有良田。"]},{"t":"河势","f":"五言律诗","c":["河势浩难测，禹功传所闻。","今观一川破，复以二渠分。","国论终将塞，民嗟亦已勤。","无灾等难必，从众在吾君。"]},{"t":"法喜寺","f":"七言律诗","c":["门前白道自萦回，门下青莎间绿苔。","杂树绕花莺引去，坏檐无幕雁归来。","寂寥谁共樽前酒，牢落空留案上杯。","我忆故乡诚不浅，可怜鶗鴂重相催。"]},{"t":"疟起舍弟尚未已示道原","f":"五言律诗","c":["侧足呻吟地，连甍瘴疟秋。","穷乡医自绌，小市药难求。","肝胆疑俱破，筋骸漫独瘳。","惭君远从我，契阔每同忧。"]},{"t":"苦雨","f":"七言律诗","c":["灵场奔走尚无功，去马来车道不通。","风助乱云阴更密，水争高岸气尤雄。","平时沟洫今多废，下户京囷久已空。","肉食自嗟何所报，古人忧国愿年丰。"]},{"t":"英宗皇帝挽辞二首 其二","f":"五言律诗","c":["玉册上鸿名，犹残警跸声。","忽辞千岁祝，虚卜五年征。","羽卫悲哀送，山陵指顾成。","讴歌归圣子，世孝在持盈。"]},{"t":"英宗皇帝挽辞二首 其一","f":"五言律诗","c":["御气方尊极，乘云已泬寥。","衣冠万国会，陵寝百神朝。","夏鼎传归启，虞羹想见尧。","谁当授椽笔，论德在琼瑶。"]},{"t":"诗呈节判陆君","f":"七言律诗","c":["中郎笔墨妙他年，晚与君游喜象贤。","款款故情初未慭，飘飘新句总堪传。","英才但未遭文举，明主宁当弃浩然。","投赠临分加组丽，小诗能不强雕镌。"]},{"t":"诗奉送觉之奉使东川","f":"七言律诗","c":["三秋不见每惓惓，握手山林复怅然。","后会敢期黄耇日，相看且度白鸡年。","畏途石栈王尊驭，荣路金门祖逖鞭。","一代官仪新藻拂，得瞻宸宇想留连。"]},{"t":"详定试卷二首 其二","f":"七言律诗","c":["童子常誇作赋工，暮年羞悔有杨雄。","当时赐帛倡优等，今日论才将相中。","细甚客卿因笔墨，卑于尔雅注鱼虫。","汉家故事真当改，新咏知君胜弱翁。"]},{"t":"详定试卷二首 其一","f":"七言律诗","c":["帘垂咫尺断经过，把卷空闻笑语多。","论众势难专可否，法严人更谨谁何。","文章直使看无颣，勋业安能保不磨。","疑有高鸿在寥廓，未应回首顾张罗。"]},{"t":"详定幕次呈圣从乐道","f":"七言律诗","c":["殿阁抡材覆等差，从臣今日擅文华。","杨雄识字无人敌，何逊能诗有世家。","旧德醉心如美酒，新篇清目胜真茶。","一觞一咏相从乐，传说犹堪异日誇。"]},{"t":"金山寺","f":"五言律诗","c":["重经高处寺，一与白云亲。","树木有春意，江山如故人。","幽轩含气象，偏影落风尘。","日暮临归去，徘徊欲损神。"]},{"t":"金陵怀古","f":"七言律诗","c":["六代豪华空处所，金陵王气黯然收。","烟浓草远望不尽，物换星移度几秋。","至竟江山谁是主，却因歌舞破除休。","我来不见当时事，上尽重城更上楼。"]},{"t":"金陵怀古四首 其四","f":"七言律诗","c":["忆昨天兵下蜀江，将军谈笑士争降。","黄旗已尽年三百，紫气空收剑一双。","破堞自生新草木，废宫谁识旧轩窗。","不须搔首寻遗事，且倒花前白玉缸。"]},{"t":"金陵怀古四首 其三","f":"七言律诗","c":["地势东回万里江，云间天阙古来双。","兵缠四海英雄得，圣出中原次第降。","山水寂寥埋王气，风烟萧飒满僧窗。","废陵坏冢空冠剑，谁复沾缨酹一缸。"]},{"t":"金陵怀古四首 其二","f":"七言律诗","c":["天兵南下此桥江，敌国当时指顾降。","山水雄豪空复在，君王神武自难双。","留连落日频回首，想像馀墟独倚窗。","却怪夏阳才一苇，汉家何事费罂缸。"]},{"t":"金陵怀古四首 其一","f":"七言律诗","c":["霸祖孤身取二江，子孙多以百城降。","豪华尽出成功后，逸乐安知与祸双。","东府旧基留佛刹，后庭馀唱落船窗。","黍离麦秀从来事，且置兴亡近酒缸。"]},{"t":"雨中","f":"五言律诗","c":["尚疑樱欲吐，已怪菊成漂。","紫苋凌风怯，青苔挟雨骄。","长闲故有味，多难自无聊。","牢落柴荆晚，生涯付一瓢。"]},{"t":"雨过偶书","f":"七言律诗","c":["霈然甘泽洗尘寰，南亩东郊共慰颜。","地望岁功还物外，天将生意与人间。","霁分星斗风雷静，凉入轩窗枕簟閒。","谁似浮云知进退，才成霖雨便归山。"]},{"t":"雨花台","f":"七言律诗","c":["盘互长干有绝陉，并包佳丽入江亭。","新霜浦溆绵绵净，薄晚林峦往往青。","南上欲穷牛渚怪，北寻难忘草堂灵。","箯舆却走垂杨陌，已戴寒云一两星。"]},{"t":"驾自启圣还内","f":"七言律诗","c":["衣冠原庙汉家仪，羽卫亲来此一时。","天子当怀霜露感，都人亦叹鼓箫悲。","纷纷瑞气随云汉，漠漠荣光上日旗。","尘土未惊阊阖闭，绿槐空覆影参差。"]},{"t":"将次洺州憩漳上","f":"五言律诗","c":["漠漠春风里，茸茸绿未齐。","平田鸦散啄，深树马迎嘶。","地入河流曲，天随日去低。","高城已在眼，聊复解轻赍。"]},{"t":"将次相州","f":"七言律诗","c":["青山如浪入漳州，铜雀台西八九丘。","蝼蚁往还空垄亩，骐驎埋没几春秋。","功名盖世知谁是，气力回天到此休。","何必地中馀故物，魏公诸子分衣裘。"]},{"t":"将至丹阳寄表民","f":"七言律诗","c":["晓马骎骎路阻脩，春风漠漠上衣裘。","三年衔恤空馀息，一日忘形愿少留。","末路悲欢随俯仰，此生身世信沉浮。","寄声德操家人道，炊黍吾今且暂休。"]},{"t":"将赴南徐任游茅山有作","f":"七言律诗","c":["丹阳太守意如何，先谒茅卿始下车。","展节事君三黜后，收心奉道五旬馀。","回寻灵药逢芝圃，欲叩真关借玉书。","不用从人问通塞，天教吏隐接仙居。"]},{"t":"度麾岭寄莘老","f":"七言律诗","c":["区区随传换冬春，夜半悬崖托此身。","岂慕王尊能许国，直缘毛义欲私亲。","施为已坏生平学，梦想犹归寂寞滨。","风月一歌劳者事，能明吾意可无人。"]},{"t":"思王逢原三首 其三","f":"七言律诗","c":["百年相望济时功，岁路何知向此穷。","鹰隼奋飞凰羽短，骐驎埋没马群空。","中郎旧业无儿付，康子高才有妇同。","想见江南原上墓，树枝零落纸钱风。"]},{"t":"思王逢原三首 其二","f":"七言律诗","c":["蓬蒿今日想纷披，冢上秋风又一吹。","妙质不为平世得，微言唯有故人知。","庐山南堕当书案，湓水东来入酒卮。","陈迹可怜随手尽，欲欢无复似当时。"]},{"t":"思王逢原三首 其一","f":"七言律诗","c":["布衣阡陌动成群，卓荦高才独见君。","杞梓豫章蟠绝壑，骐驎騕袅跨浮云。","行藏已许终身共，生死那知半路分。","便恐世间无妙质，鼻端从此罢挥斤。"]},{"t":"春日","f":"五言律诗","c":["冉冉春行暮，菲菲物竞华。","莺犹求旧友，雁不背贫家。","室有贤人酒，门无长者车。","醉眠聊自适，归梦到天涯。"]},{"t":"春风","f":"七言律诗","c":["一马春风北首燕，却疑身得旧山川。","阳浮树外沧江水，尘涨原头野火烟。","日借嫩黄初著柳，雨催新绿稍归田。","回头不见辛夷发，始觉看花是去年。"]},{"t":"春寒","f":"七言律诗","c":["春风满地月如霜，拂晓钟声到景阳。","花底裌衣朝宿卫，柳边新火起严妆。","冰残玉甃泉初动，水涩铜壶漏更长。","从此暄妍知几日，便应鶗鴂损年芳。"]},{"t":"段约之园亭","f":"七言律诗","c":["爱公池馆得忘机，初日留连至落晖。","菱暖紫鳞跳复没，柳阴黄鸟啭还飞。","径无凡草唯生竹，盘有嘉蔬不采薇。","胜事阆州虽或有，终非吾土岂如归。"]},{"t":"独饭","f":"五言律诗","c":["窗明两不借，榻净一籧篨。","栩栩幽人梦，夭夭老者居。","安能问香积，谁可告华胥。","独饭墙阴转，看云坐久如。"]},{"t":"癸卯追感正月十五事","f":"五言律诗","c":["正月端门夜，金舆缥缈中。","传觞三鼓罢，纵观万人同。","警跸声如在，嬉游事已空。","但令千载后，追咏太平功。"]},{"t":"神宗皇帝挽辞二首 其一","f":"五言律诗","c":["将圣由天纵，成能与鬼谋。","聪明初四达，俊乂尽旁求。","一变前无古，三登岁有秋。","讴歌归子启，钦念禹功修。"]},{"t":"秋风","f":"五言律诗","c":["揫敛一何饕，天机亦自劳。","墙隈小翻动，屋角盛呼号。","漠漠惊沙密，纷纷断柳高。","江湖岂在眼，昨夜梦波涛。"]},{"t":"秋兴和冲卿","f":"五言律诗","c":["云浮朝惨淡，风起夜飕飗。","欲作冰霜地，先回草树秋。","征人倚笛怨，思妇向砧愁。","为问随阳雁，哀鸣岂有求。"]},{"t":"秋夜二首 其二","f":"五言律诗","c":["幔逗长风细，窗留半月斜。","浮烟暝绿草，泫露冷黄花。","独曳缘云策，仍寻度水槎。","归时参夜半，邻犬静中哗。"]},{"t":"秋夜二首 其一","f":"五言律诗","c":["客卧书颠倒，虫鸣坐寂寥。","残灯生暗晕，重露集寒条。","真乐闲尤见，深禅静更超。","此怀无与晤，拥鼻一长谣。"]},{"t":"狄梁公陶渊明俱为彭泽令至今有庙在焉刁景纯作诗见示继以一篇","f":"七言律诗","c":["梁公壮节就夔魖，陶令清身托酒徒。","政在房陵成底事，年称甲子亦何须。","江山彭泽空遗像，岁月柴桑失故区。","末俗此风犹不竞，诗翁叹息未应无。"]},{"t":"秋露","f":"五言律诗","c":["日月凋何急，荒庭露送秋。","初疑宿雨泫，稍怪晓霜稠。","旷野将驰猎，华堂已御裘。","空令半夜鹤，抱此一端愁。"]},{"t":"草堂","f":"五言律诗","c":["草堂今寂寞，往事翳山椒。","蕙帐空留鹤，萝衣终换貂。","生皆堕天秩，隐或寄公朝。","叠颖何劳怒，东风汝自摇。"]},{"t":"荣上人遽欲归以诗留之","f":"七言律诗","c":["道人传业自天台，千里翛然赴感来。","梵行毗沙为外护，法筵灵曜得重开。","已能为我迂神足，便可随方长圣胎。","肯顾北山如慧约，与公西崦斸莓苔。"]},{"t":"贵州虞部使君访及道旧窃有感恻因成小诗","f":"七言律诗","c":["韶山秀拔江清写，气象还能出搢绅。","当我垂髫初识字，看君挥翰独惊人。","邮签忽报旌麾入，斋閤遥瞻组绶新。","握手更谁知往事，同时诸彦略成尘。"]},{"t":"退朝","f":"七言律诗","c":["门外鸣驺送响频，披衣强起赴鸡人。","火城夜闇云藏阙，玉座朝寒雪被宸。","邂逅欲成双白鬓，萧条难得两朱轮。","犹怜退食亲朋在，相与吟哦未厌贫。"]},{"t":"送王大卿致政归江陵","f":"七言律诗","c":["九卿初命亚三司，朝吏相瞻得老师。","南阙便还新印绶，东舟只载旧书诗。","汉庭饯客无佳句，越水归装有富赀。","回首千年见疏范，共疑今事胜当时。"]},{"t":"送王覃","f":"七言律诗","c":["分走人间十五年，尘沙吹鬓各苍然。","山林渺渺长回首，儿女纷纷忽满前。","知子有才思奋发，嗟余无地与回旋。","相看一作秦吴别，身世何时两息肩。"]},{"t":"送王蒙州","f":"七言律诗","c":["请郡东南促去程，拍堤江水照红旌。","仁声已逐春风到，使节犹占夜斗行。","箭落皂雕毚兔避，句传炎海鳄鱼惊。","麒麟不是人间物，汉诏先应召贾生。"]},{"t":"送王詹叔利州路运判","f":"七言律诗","c":["王孙旧读五车书，手把山阳太守符。","未驾朱轓辞辇毂，却分金节佐均输。","人才自古常难得，时论如君岂久孤。","去去便看归奏计，莫嗟行路有崎岖。"]},{"t":"送邓监簿南归","f":"五言律诗","c":["不见骊塘路，茫然四十春。","长为异乡客，每忆故时人。","水阅公三世，云浮我一身。","濠梁送归处，握手但悲辛。"]},{"t":"送刘贡父赴秦州清水","f":"七言律诗","c":["刘郎高论坐嘘枯，幕府调胹用绪馀。","笔下能当万人敌，腹中尝记五车书。","闻多望士登天禄，知有名臣荐子虚。","且复弦歌穷塞上，祇应非晚召相如。"]},{"t":"送刘和父奉使江西","f":"七言律诗","c":["刘郎今日拥旌麾，传到江南喜可知。","上冢还须击羊豕，下车应不问狐狸。","无人敢效公荣酒，为我聊寻逸少池。","亦见岭头花烂熳，更将春色寄相思。"]},{"t":"送孙子高","f":"五言律诗","c":["荡漾江南客，融怡席上珍。","一樽相别酒，千里独归人。","客路贫堪病，交情远更亲。","自惭儿女意，失泪滴衣巾。"]},{"t":"送孙立之赴广西","f":"七言律诗","c":["十年一别两相过，前想悲欢慷慨歌。","穷去始知风俗薄，静来犹厌事机多。","相期鼻目倾肝胆，谁伴溪山避网罗。","万里辛勤君旧识，重江应亦畏风波。"]},{"t":"送西京签判王著作","f":"七言律诗","c":["儿曹曾上洛城头，尚记清波绕驿流。","却想山川常在梦，可怜颜发已惊秋。","辟书今日看君去，著籍长年叹我留。","三十六峰应好在，寄声多谢欲来游。"]},{"t":"送何圣从龙图","f":"七言律诗","c":["射策曾称蜀郡雄，朝廷重得汉司空。","应留赐席丹涂地，误责飞刍紫塞功。","三径欲归无旧业，百城先至有清风。","潞山直与天为党，回首孙高想见公。"]},{"t":"送何正臣主簿","f":"七言律诗","c":["何郎冰雪照青春，应敌皆言笔有神。","鲁国儒人何独少，元君画史故应真。","百年冠盖风云会，万里山川日月新。","可但诸公能品藻，会须天子擢平津。"]},{"t":"送别韩虞部","f":"七言律诗","c":["客舍街南初著巾，与君兄弟即相亲。","当年岂意两家子，今日更为同社人。","京洛风尘嗟阻阔，江湖杯酒惜逡巡。","归帆岭北茫茫水，把手何时寂寞滨。"]},{"t":"送吴龙图知江宁","f":"七言律诗","c":["才高明主眷方深，属郡闻风自革心。","闾里不须多按治，山川从此数登临。","茅檐坐隔云千里，柏垄初抽翠一寻。","东望泫然知有寄，但疑公岂久分襟。"]},{"t":"送吴叔开南征","f":"五言律诗","c":["掺袂不胜情，犀舟击汰行。","倦游无万里，惜别有千名。","春草凄凄绿，江枫湛湛清。","金陵多丽景，此去属兰成。"]},{"t":"送张仲容赴杭州孙公辟","f":"七言律诗","c":["万屋相誇漆与丹，笑歌长在绮纨间。","綵船春戏城边水，画烛秋寻寺外山。","忆我屡随游客入，喜君今赴辟书还。","遥知曼倩威行久，赤笔应从到日闲。"]},{"t":"送张宣义之官越幕二首 其二","f":"五言律诗","c":["谁谓贵公子，乃如寒士家。","真宜举敦朴，已自胜浮华。","洲荻藏迷子，溪篁拥若耶。","相望只在眼，音问莫言赊。"]},{"t":"送张宣义之官越幕二首 其一","f":"五言律诗","c":["会稽游宦乡，海物错句章。","土润箭萌美，水甘茶串香。","今君诚暂屈，他日恐难忘。","唯有西兴渡，灵胥或怒张。"]},{"t":"送张卿致仕","f":"七言律诗","c":["子房筹策汉时功，身退超然慕赤松。","馀烈尚能开后世，高材今复继前踪。","执鞭始负平生愿，操几何知此地逢。","窃食一官惭未艾，绪言方赖赐从容。"]},{"t":"送张甥赴青州幕","f":"五言律诗","c":["人情每期费，之子适予心。","老饯城东陌，悲分岁暮襟。","少留班露草，遂往隔云林。","未觉青丘远，因风嗣好音。"]},{"t":"送张颉仲举知奉新","f":"七言律诗","c":["故人为邑士多称，繇赋宽赊狱讼平。","老吏闭门无重糈，荒山开陇有新粳。","方挥玉麈日边坐，又结铜章天外行。","此去料君归不久，挟材如此即名卿。"]},{"t":"送李才元校理知邛州","f":"七言律诗","c":["朝廷孝治称今日，乡郡荣归及壮时。","关吏相呼迎印绶，里儿争出望旄麾。","北堂已足誇三釜，南亩当今识两歧。","独我尚留真有命，天于人欲本无私。"]},{"t":"送李太保知仪州","f":"七言律诗","c":["北平上谷当时守，气略人推李广优。","还见子孙持汉节，欲临关塞抚羌酋。","云边鼓吹应先喜，日下旌旗更少留。","五字亦君家世事，一吟何以称来求。"]},{"t":"送李质夫之陕府","f":"七言律诗","c":["平世求才漫至公，悠悠羁旅士多穷。","十年见子尚短褐，千里随人今北风。","户外屦贫虚自满，樽中酒贱亦常空。","共嫌欲老无机械，心事还能与我同。"]},{"t":"送李秘校南归","f":"七言律诗","c":["四十青衫更旅人，悠悠饥马傍沙尘。","久留上国言空富，却走南州食转贫。","自作诗书能见志，应知时命不关身。","江湖胜事从今数，肯但悲歌寂寞滨。"]},{"t":"送李璋","f":"七言律诗","c":["湖海声名二十年，尚随乡赋已华颠。","却归甫里无三径，拟傍胥山就一廛。","朱毂风尘休怅望，青鞋云水且留连。","故人亦见如相问，为道方寻木雁篇。"]},{"t":"送杜十八之广南","f":"五言律诗","c":["东南炎海外，寻访又输君。","过岭猿啼暖，贪程马送曛。","清谈消瘴疠，秀句起烟云。","及早来乡荐，朝廷尚右文。"]},{"t":"送杨骥秀才归鄱阳","f":"七言律诗","c":["客舍风尘弊綵衣，悲吟重见雁南飞。","荆山和氏方三献，太学何生且一归。","旷野已寒谙独宿，长年多难惜分违。","巾箱所得皆幽懿，亦见乡人为发挥。"]},{"t":"送沈兴宗察院出使湖南","f":"七言律诗","c":["谏书平日皂囊中，朝路争看一马骢。","汉节饱曾冲海雾，楚帆聊复借湖风。","皇华命使今为重，直道酬君远亦同。","投老承明无补助，得为湘守即随公。"]},{"t":"送沈康知常州","f":"七言律诗","c":["作客兰陵迹已陈，为传谣俗记州民。","沟塍半废田畴薄，厨传相仍市井贫。","常恐劳人轻白屋，忽逢佳士得朱轮。","慇勤话此还惆怅，最忆荆溪两岸春。"]},{"t":"送灵仙裴太博","f":"七言律诗","c":["一官留隐太常中，生事萧然信所穷。","有力尚期当世用，无求今见古人风。","邅回旧学皆残藁，邂逅相看各老翁。","他日卜居何处好，溪山还欲与君同。"]},{"t":"送纯甫如江南","f":"七言律诗","c":["青溪看汝始蹁跹，兄弟追随各少年。","壮尔有行今纳妇，老吾无用亦求田。","初来淮北心常折，却望江南眼更穿。","此去还知苦相忆，归时快马亦须鞭。"]},{"t":"送苏屯田广西转运","f":"七言律诗","c":["置将从来欲善师，百城蹉跌起毫釐。","驱除久费兵符出，按抚纷烦使节移。","恩泽易行穷苦后，功名常见急难时。","孺文此日风流在，直笔他年岂愧辞。"]},{"t":"送陈舜俞制科东归","f":"七言律诗","c":["诸贤发策未央宫，独得菑川一老翁。","曲学暮年终汉相，高谈平日漫周公。","君今壮岁收科第，我欲它时看事功。","闻说慨然真有意，赠行聊似古人风。"]},{"t":"送叔康侍御","f":"七言律诗","c":["诏取名郎入宪台，此时方急济时才。","圣聪应已虚心待，奸党宁无侧目猜。","白笔岂知权可畏，皂囊还请上亲开。","伫闻谠论能医国，飞报频随驿骑来。"]},{"t":"送周仲章使君","f":"七言律诗","c":["看君东下霅溪船，回首纷纷已五年。","簪笔少留吾所望，剖符轻去此何缘。","高麾行路穿秦树，骏马归时著蜀鞭。","子墨文章应满箧，承明宣室正详延。"]},{"t":"送庞签判","f":"七言律诗","c":["北都两去不辞勤，仕路论材况出群。","一相开藩尝负弩，三年通籍更从军。","清谈犹得当时事，遗爱应从此日闻。","我忆荆溪山最乐，看君摩翮上青云。"]},{"t":"送明州王大卿","f":"七言律诗","c":["大历才臣有此州，昆云今驾鹿轓游。","从来所至邦人喜，真复能分圣主忧。","千里封疆何足治，一时名迹故应留。","属城旧吏虽疲懒，尚可挥毫敌李舟。"]},{"t":"送河间晁寺丞","f":"五言律诗","c":["公孙富文墨，名字世多知。","谈笑取高第，弦歌当此时。","临河薪石费，近塞茧丝移。","缓急常愁此，看君有所为。"]},{"t":"送直讲吴殿丞宰巩县","f":"七言律诗","c":["青嵩碧洛曾游地，墨绶铜章忽在身。","拥马尚多畿甸雪，随衣无复禁城尘。","古来学问须行己，此去风流定慰人。","更忆少陵诗上语，知君不负巩梅春。"]},{"t":"送经臣富顺寺丞","f":"七言律诗","c":["故人为县楚江边，海角犹闻政事传。","万井已安如赤子，一麾今去上青天。","应开醉眼酴醾下，莫起归心杜宇前。","报主代亲俱有地，几人忠孝似君全。"]},{"t":"送郊社朱兄除郎东归","f":"七言律诗","c":["手持官牒出神皋，迎客遥知贺酒醪。","照映里门非白屋，欺凌春草有青袍。","宦游虽晚何妨久，饿显从来不必高。","孝友父兄家法在，想能清白遗儿曹。"]},{"t":"送复之屯田赴成都","f":"七言律诗","c":["槃礴西南江与岷，石犀金马世称神。","桑麻接畛馀无地，锦绣连城别有春。","结绶相随通籍久，推车此去辟书新。","知君不为山川险，便忘吾家叱驭人。"]},{"t":"送契丹使还次韵答净因老","f":"五言律诗","c":["老欲求吾志，时方摭我华。","强将愁出塞，空得病还家。","日转山河暖，风含草木葩。","胜游思一往，不敢问三车。"]},{"t":"送彦珍","f":"七言律诗","c":["挟策穷乡满鬓丝，陂田荒尽岂尝窥。","未应谷口终身隐，正合菑川举国推。","握手百忧空往事，还家一笑即芳时。","柘冈定有辛夷发，亦见东风使我知。"]},{"t":"送赵学士陕西提刑","f":"七言律诗","c":["遥知彼俗经兵后，应望名公走马来。","陛下柬求今日始，胸中包畜此时开。","山西豪杰归囊牍，渭北风光入酒杯。","堪笑陋儒昏鄙甚，略无谋术赞行台。"]},{"t":"送赵燮之蜀永康簿","f":"七言律诗","c":["蜀山万里一青袍，石栈天梯箠辔高。","多学似君宁易得，小官于此亦徒劳。","行追西路聊班草，坐忆南州欲梦刀。","他日寄声能问我，应从锦水至江皋。"]},{"t":"送逊师归舒州","f":"七言律诗","c":["山川相对一悲翁，往事纷纷梦寐中。","邂逅故人恩意在，低徊今日笑言同。","看吹陌上杨花满，忽忆岩前蕙帐空。","亦见桐乡诸父老，为传衰飒病春风。"]},{"t":"送项判官","f":"七言律诗","c":["断芦洲渚落枫桥，渡口沙长过午潮。","山鸟自呼泥滑滑，行人相对马萧萧。","十年长自青衿识，千里来非白璧招。","握手祝君能强饭，华簪常得从鸡翘。"]},{"t":"送真州吴处厚使君","f":"七言律诗","c":["江上斋船驻彩桡，鸣笳应满绿杨桥。","久为汉吏知文法，当使淮人服教条。","拱木延陵瞻故国，丛祠瓜步认前朝。","登临莫负山川好，终欲东归听楚谣。"]},{"t":"送陶氏妇兼寄纯甫","f":"五言律诗","c":["云结川原暗，风连草木萎。","遥瞻季行役，正对女伤悲。","梦事中千变，生涯老百罹。","更惭无道力，临路涕交颐。"]},{"t":"送崔左藏之广东","f":"七言律诗","c":["怪石巉巉上泬寥，昔人于此奏箫韶。","水清但有嘉鱼出，风暖何曾毒草摇。","今日淹留君按节，当时嬉戏我垂髫。","因寻旧政询遗老，为作新诗变俚谣。"]},{"t":"送梅龙图","f":"七言律诗","c":["子真家世子云乡，风力才华岂易当。","回首古人多隐约，致身今日独辉光。","谟明久合分三府，治剧聊须试一方。","从此政成何所报，百城无事祇耕桑。"]},{"t":"送章宏","f":"七言律诗","c":["道合由来不易谋，岂无和氏识荆璆。","一川浊水浮文鹢，千里轻帆落武丘。","身退岂嫌吾道进，学成方悟众人求。","西风乞得东南守，杖策还能访我不。"]},{"t":"送萧山钱著作","f":"七言律诗","c":["才高诸彦故无嫌，兄弟同时举孝廉。","东观外除方墨绶，西州相见已苍髯。","灵胥引水清穿市，神禹分山翠入帘。","好去弦歌聊自慰，郡人谁敢慢陶潜。"]},{"t":"送董传","f":"五言律诗","c":["悠悠陇头水，日夜向西流。","行路未云已，归人空复愁。","文章合用世，颜发未惊秋。","一听秦声罢，还来上国游。"]},{"t":"送道光法师住持灵岩","f":"七言律诗","c":["灵岩开辟自何年，草木神奇鸟兽仙。","一路紫苔通窅窱，千崖青霭落潺湲。","山祇啸聚荒禅室，象众低摧想法筵。","雪足莫辞重趼往，东人香火有因缘。"]},{"t":"送福建张比部","f":"七言律诗","c":["画船箫鼓出都时，万里惊鸥去不追。","却望尘沙应驻节，会逢山水即吟诗。","长鱼俎上通三印，新茗斋中试一旗。","只恐远方难久滞，莫愁风物不相宜。"]},{"t":"送僧无惑归鄱阳","f":"七言律诗","c":["晚扶衰惫寄人间，应接纷纷祇强颜。","挂席每谙东汇水，采芝多梦旧游山。","故人独往今为乐，何日相随我亦闲。","归见江东诸父老，为言飞鸟会知还。"]},{"t":"送熊伯通","f":"七言律诗","c":["岁暮欣逢盖共倾，川涂南北岂忘情。","事经官路心应折，地入家山眼更明。","江上月华空自照，梅边春意恰相迎。","关河不锁真消息，野客犹能听治声。"]},{"t":"送裴如晦宰吴江","f":"七言律诗","c":["青发朱颜各少年，幅巾谈笑两欢然。","柴桑别后馀三径，天禄归来尽一廛。","邂逅都门谁载酒，萧条江县去鸣弦。","犹疑甫里英灵在，到日凭君为舣船。"]},{"t":"送潘景纯","f":"七言律诗","c":["东都曾以一当千，场屋声名十五年。","晚赐绿衣随宦牒，始操丹笔事戎旃。","明时正欲精蒐选，荣路何当力荐延。","赖有史君能好士，方看一鹗在秋天。"]},{"t":"送赞善张轩民西归","f":"五言律诗","c":["柴荆雀有罗，公子数经过。","邂逅相知晚，从容所得多。","百忧生暮齿，一笑隔沧波。","早晚西州路，遥听下坂珂。"]},{"t":"重游草堂 其二","f":"五言律诗","c":["僧残尚食少，佛古但泥多。","寒守三衣法，饥传一钵歌。","宽闲每迸竹，危朽漫牵萝。","怊怅庭前柏，西来意若何。"]},{"t":"重游草堂 其一","f":"五言律诗","c":["垣屋荒葛藟，野殿冷檀沈。","鹤有思颙意，鹰无恋遁心。","禅房闭深竹，斋钵度遥岑。","寂寞黄尘里，金身倚一寻。"]},{"t":"重游草堂 其三","f":"五言律诗","c":["野寺真兰若，山僧老病多。","疏钟挟谷响，悲梵入樵歌。","水映茅篁竹，云埋茑女萝。","拂尘书所见，因得拟阴何。"]},{"t":"重登宝公塔复用前韵二首 其二","f":"七言律诗","c":["碧玉旋螺恍隔霄，冠山仙冢亦寥寥。","空馀华构延风月，无复灵踪落市朝。","帐座追严多献宝，供盘随施有操瓢。","他方出没还如此，与物何心作迩遥。"]},{"t":"重登宝公塔复用前韵二首 其一","f":"七言律诗","c":["空见方坟涌半霄，难将生死问参寥。","应身东返知何国，瑞像西归自本朝。","遗寺有门非辇路，故池无钵但僧瓢。","独龙下视皆陈迹，追数齐梁亦未遥。"]},{"t":"钟山西庵白莲亭","f":"七言律诗","c":["山亭新破一方苔，白帝留花满四隈。","野艳轻明非傅粉，秋光清浅不凭材。","乡穷自作幽人伴，岁晚谁为静女媒。","可笑远公池上客，却因松菊赋归来。"]},{"t":"闻和甫补池掾","f":"七言律诗","c":["遭时何必问功名，自古难将力命争。","万户侯多归世胄，五车书独负家声。","才华汝尚为丞掾，老懒吾今合钓耕。","外物悠悠无得丧，春郊终日待相迎。"]},{"t":"乘日","f":"五言律诗","c":["乘日塞垣入，御风塘路归。","胡皆跃马去，雁却背人飞。","烟水吾乡似，家书驿使稀。","匆匆照颜色，恨不洗征衣。"]},{"t":"夏夜舟中颇凉因有所感","f":"五言律诗","c":["扁舟畏朝热，望夜倚桅樯。","日共火云退，风兼水气凉。","未秋轻病骨，微曙浣愁肠。","坚我江湖意，滔滔兴不忘。"]},{"t":"射亭","f":"五言律诗","c":["因射构兹亭，序贤仍阅兵。","庶民观礼教，群寇避威声。","城垒前相壮，溪山势尽倾。","宜哉百里地，桴鼓未尝鸣。"]},{"t":"挽舜元胡著作郎","f":"七言律诗","c":["德行文章里闬宗，姓名朝野尽知公。","侍亲存没皆全孝，报政初终必竭忠。","性直不从花县乐，分安求逸郁堂空。","从今永别人间去，笑入蓬瀛阆苑中。"]},{"t":"留题微之廨中清辉阁","f":"七言律诗","c":["故人名字在瀛洲，邂逅低徊向此留。","鸥鸟一双随坐啸，荷花十丈对冥搜。","水涵樽俎清如洗，山染衣巾翠欲流。","宣室应疑鬼神事，知君能复几来游。"]},{"t":"离北山寄平甫","f":"七言律诗","c":["日月沄沄与水争，披襟照见发华惊。","少年忧患伤豪气，老去经纶误半生。","休向朝廷论一鹗，只知田里守三荆。","清溪几曲春风好，已约归时载酒行。"]},{"t":"致仕邵少卿挽辞二首 其二","f":"五言律诗","c":["杯酒邗沟上，纷纷已十年。","音容常想见，风迹每流传。","老去元卿位，新开太守阡。","庆门当更大，子弟固多贤。"]},{"t":"致仕邵少卿挽辞二首 其一","f":"五言律诗","c":["谢朓城中守，梁鸿墓下归。","素车驰吉路，丹旐卷寒辉。","抚几虚容在，瞻图实貌非。","无因置一酹，空此叹长违。"]},{"t":"致仕虞部曲江谭君挽辞","f":"七言律诗","c":["同时献赋久无人，握手悲欢迹已陈。","它日白衣霄汉志，暮年朱绂水云身。","虚容剑几今长夜，小隐山林祇旧春。","岂惜埋辞追往事，齿衰才尽独伤神。"]},{"t":"葛溪驿","f":"七言律诗","c":["缺月昏昏漏未央，一灯明灭照秋床。","病身最觉风露早，归梦不知山水长。","坐感岁时歌慷慨，起看天地色凄凉。","鸣蝉更乱行人耳，正抱疏桐叶半黄。"]},{"t":"莫疑","f":"七言律诗","c":["莫疑禅伯未知禅，莫笑仙翁不学仙。","灵骨肯传黄檗烬，真心自放赤松烟。","莲华世界何关汝，楮叶工夫浪费年。","露鹤声中江月白，一灯岑寂拥书眠。"]},{"t":"读史","f":"七言律诗","c":["自古功名亦苦辛，行藏终欲付何人。","当时黮闇犹承误，末俗纷纭更乱真。","糟粕所传非粹美，丹青难写是精神。","区区岂尽高贤意，独守千秋纸上尘。"]},{"t":"读诏书","f":"七言律诗","c":["去秋东出汴河梁，已见中州旱势强。","日射地穿千里赤，风吹沙度满城黄。","近闻急诏收群策，颇说新年又亢阳。","贱术纵工难自献，心忧天下独君王。"]},{"t":"读眉山集次韵雪诗五首 其五","f":"七言律诗","c":["戏摇微缟女鬟鸦，试咀流酥已颊车。","历乱稍埋冰揉粟，消沉时点水圆花。","岂能舴艋真寻我，且与蜗牛独卧家。","欲挑青腰还不敢，直须诗胆付刘叉。"]},{"t":"读眉山集次韵雪诗五首 其四","f":"七言律诗","c":["寄声三足阿环鸦，问讯青腰小驻车。","一一照肌宁有种，纷纷迷眼为谁花。","争妍恐落江妃手，耐冷疑连月姊家。","长恨玉颜春不久，画图时展为君叉。"]},{"t":"读眉山集次韵雪诗五首 其三","f":"七言律诗","c":["惠施文字黑如鸦，于此机缄漫五车。","皭若易缁终不染，纷然能幻本无花。","观空白足宁知处，疑有青腰岂作家。","慧可忍寒真觉晚，为谁将手少林叉。"]},{"t":"读眉山集次韵雪诗五首 其二","f":"七言律诗","c":["神女青腰宝髻鸦，独藏云气委飞车。","夜光往往多联璧，白小纷纷每散花。","珠网纚连拘翼座，瑶池淼漫阿环家。","银为宫阙寻常见，岂即诸天守夜叉。"]},{"t":"读眉山集次韵雪诗五首 其一","f":"七言律诗","c":["若木昏昏末有鸦，冻雷深闭阿香车。","抟云忽散筛为屑，剪水如分缀作花。","拥帚尚怜南北巷，持杯能喜两三家。","戏挼弄掬输儿女，羔袖龙钟手独叉。"]},{"t":"读眉山集爱其雪诗能用韵复次韵一首","f":"七言律诗","c":["靓妆严饰曜金鸦，比兴难工漫百车。","水种所传清有骨，天机能织皦非花。","婵娟一色明千里，绰约无心熟万家。","长此赏怀甘独卧，袁安交戟岂须叉。"]},{"t":"读秦汉间事","f":"五言律诗","c":["秦徵天下材，入作阿房宫。","宫成非一木，山谷为穷空。","子羽一炬火，骊山三月红。","能令扫地尽，岂但焚人功。"]},{"t":"贾生","f":"五言律诗","c":["汉有洛阳子，少年明是非。","所论多感概，自信肯依违。","死者若可作，今人谁与归。","应须蹈东海，不但涕沾衣。"]},{"t":"高魏留","f":"七言律诗","c":["魏留十七助防边，埋没盐州十八年。","衣屦穷空委胡妇，糗粮辛苦待山田。","关河旧路频回首，腹背他时两受鞭。","邂逅得归耶战死，母随人去亦萧然。"]},{"t":"偶成二首 其二","f":"七言律诗","c":["怀抱难开醉易醒，晓歌悲壮动秋城。","年光断送朱颜去，世事栽培白发生。","三亩未成幽处宅，一身还逐众人行。","可怜蜗角能多少，独与区区触事争。"]},{"t":"偶成二首 其一","f":"七言律诗","c":["渐老偏谙世上情，已知吾事独难行。","脱身负米将求志，勠力求田岂为名。","高论颇随衰俗废，壮怀难值故人倾。","相逢始觉宽愁病，搔首还添白发生。"]},{"t":"宿土坊驿寄孔世长","f":"七言律诗","c":["烧夜郊原百草荒，弊裘朝去犯严霜。","残年意象偏多感，回首风烟更异乡。","往返自非名利役，辛勤应见友朋伤。","章江犹得同游处，最爱梅花蘸水香。"]},{"t":"宿北山示行详上人","f":"五言律诗","c":["都城羁旅日，独许上人贤。","谁为孤峰下，还来宴坐边。","是身犹梦幻，何物可攀缘。","坐对青灯落，松风咽夜泉。"]},{"t":"宿定林示无外名务周","f":"五言律诗","c":["天女穿林至，姮娥度陇来。","欲归今晼晚，相值且徘徊。","谁谓我忘老，如闻虫造哀。","邻衾亦不寐，共尽白云杯。"]},{"t":"宿雨","f":"五言律诗","c":["绿搅寒芜出，红争暖树归。","鱼吹塘水动，雁拂塞垣飞。","宿雨惊沙尽，晴云昼漏稀。","却愁春梦短，灯火著征衣。"]},{"t":"寄友人","f":"七言律诗","c":["飘然羁旅尚无涯，一望西南百叹嗟。","江拥涕洟流入海，风吹魂梦去还家。","平生积惨应销骨，今日殊乡又见花。","安得此身如草树，根株相守尽年华。"]},{"t":"寄友人三首 其三","f":"七言律诗","c":["一别三年各一方，此身漂荡只殊乡。","看沙更觉蓬莱浅，数日空惊霹雳忙。","渺渺水波低赤岸，濛濛云气淡扶桑。","登临旧兴无多在，但有浮槎意未忘。"]},{"t":"寄友人三首 其二","f":"七言律诗","c":["水边幽树忆同攀，曾约移居向此间。","欲语林塘迷旧径，却随车马入他山。","飞花著地容难冶，鸣鸟窥人意转闲。","物色可歌春不返，相思空复惨朱颜。"]},{"t":"寄友人三首 其一","f":"七言律诗","c":["万里书归说我愁，知君不忘北城幽。","一篇封禅才难学，三亩蓬蒿势易求。","欲与山僧论地券，愿为邻舍事田畴。","应须急作南征计，漠北风沙不可留。"]},{"t":"寄无为军张居士","f":"七言律诗","c":["南阳居士月城翁，曾习禅那问色空。","卓荦想超文字外，低徊却寄语言中。","真心妙道终无二，末学殊方自不同。","此理世间多未悟，因君往往叹西风。"]},{"t":"寄王回深甫","f":"七言律诗","c":["少年倏忽不再得，后日欢娱能几何。","顾我面颜衰更早，怜君身世病还多。","窗间暗淡月含雾，船底飘飖风送波。","一寸古心俱未试，相思中夜起悲歌。"]},{"t":"寄王补之","f":"五言律诗","c":["平居相值晚，况复道涂留。","今我思挥麈，逢君为舣舟。","人情方慕贵，吾道合归休。","吏责真难塞，聊为泮水游。"]},{"t":"寄平甫","f":"七言律诗","c":["少时为学岂身谋，欲老低徊各自羞。","乘马从徒真扰扰，求田问舍转悠悠。","弦歌旧国平生乐，鞍马新年几日留。","坐想摇鞭杨柳路，春风先我入皇州。"]},{"t":"寄石鼓寺陈伯庸","f":"七言律诗","c":["鲸海无风白日闲，天门当面险难攀。","尘埃掉臂离长陌，琴酒和云入旧山。","仁义未饶轩冕贵，功名莫信鬼神悭。","郭东一点英雄气，时伴君心夜斗间。"]},{"t":"寄孙正之","f":"七言律诗","c":["南游忽忽与谁言，共笑谋生识最昏。","万事百年能自信，一箪五鼎不须论。","友中惟子长招隐，世上何人可避喧。","千里秋风相望处，皖公溪上正开樽。"]},{"t":"寄朱昌叔","f":"七言律诗","c":["清江漫漫绕城流，尚忆城边系小舟。","射虎未能随李广，割鸡空欲戏言游。","云埋塞路惊尘合，霜入春风满鬓愁。","此日君书苦难得，谩多鸿雁起南洲。"]},{"t":"寄余温卿","f":"七言律诗","c":["云散风流不自禁，天涯无路盍朋簪。","空驰上国青泥信，谁和南山白石音。","平日离愁宽带眼，讫春归思满琴心。","终回一命翩翩驾，独过嵇山锻树阴。"]},{"t":"寄吴正仲却蒙马行之都官梅圣俞太博和寄依韵酬之","f":"七言律诗","c":["山水玄晖去后空，骚人还向此间穷。","小诗聊与论孤愤，大句安知辱两雄。","秦甲久愁荆剑利，赵兵今窘汉旗红。","背城不敢收馀烬，马首翩翩只欲东。"]},{"t":"寄吴冲卿二首 其二","f":"七言律诗","c":["塞垣花气欲飞浮，眼底纷纷绿渐抽。","悠远山川嗟我老，急难兄弟想君愁。","旧知白日诸曹满，试问红灯几客留。","时节只应无意思，亦如行路判春休。"]},{"t":"寄吴冲卿二首 其一","f":"七言律诗","c":["平生身事略相同，三岁连墙左厩中。","更得谬恩分省舍，又将衰鬓作邻翁。","联翩久傍官槐绿，契阔今看楚蓼红。","不欲与君为远别，沙台吹帽约秋风。"]},{"t":"寄吴成之","f":"七言律诗","c":["绿发溪山笑语中，岂知翻手两成翁。","辛夷屋角抟香雪，踯躅冈头挽醉红。","想见旧山茅径在，追随今日板舆空。","渭阳车马嗟何及，荣禄方当与子同。"]},{"t":"寄张氏女弟","f":"七言律诗","c":["十年江海别常轻，岂料今随寡嫂行。","心折向谁论宿昔，魂来空复梦平生。","音容想像犹如昨，岁月萧条忽已更。","知汝此悲还似我，欲为西望涕先横。"]},{"t":"寄张先郎中","f":"七言律诗","c":["留连山水住多时，年比冯唐未觉衰。","篝火尚能书细字，邮筒还肯寄新诗。","胡床月下知谁对，蛮榼花前想自随。","投老主恩聊欲报，每瞻高躅恨归迟。"]},{"t":"寄张剑州并示女弟","f":"七言律诗","c":["剑阁天梯万里寒，春风此日白衣冠。","乌辞反哺颠毛黑，鸟引思归口血丹。","行路想君今眚瘦，相逢添我老悲酸。","浮云渺渺吹西去，每到原头勒马看。"]},{"t":"寄张谔招张安国金陵法曹","f":"七言律诗","c":["我老愿为臧丈人，君今少壮岂长贫。","好须自致青冥上，可且相从寂寞滨。","深谷黄鹂娇引子，曲埼翠碧巧藏身。","寻幽触静还成兴，何必区区九陌尘。"]},{"t":"寄张襄州","f":"七言律诗","c":["襄阳州望古来雄，耆旧相传有素风。","四叶表闾唐尹氏，一门逃世汉庞公。","故家遗俗应多在，美景良辰定不空。","遥忆习池寒夜月，几人谈笑伴诗翁。"]},{"t":"寄沈鄱阳","f":"七言律诗","c":["离家当日尚炎风，叱驭归时九月穷。","朝渡藤溪霜落后，夜过麾岭月明中。","山川道路良多阻，风俗谣言苦未通。","唯有鄱君人共爱，流传名誉满江东。"]},{"t":"寄纯甫","f":"五言律诗","c":["塞上无花草，飘风急我归。","梢林听涧落，卷土看云飞。","想子当红蕊，思家上翠微。","江寒亦未已，好好著春衣。"]},{"t":"寄陈宣叔","f":"七言律诗","c":["扁舟欲动更徘徊，一笑相看病眼开。","事忤贵人今见节，政行豪县众称材。","忽惊岁月侵双鬓，却喜山川共一杯。","落日乱流江北去，离心犹与水东回。"]},{"t":"寄国清处谦","f":"七言律诗","c":["三江风浪隔天台，想见当时赋咏才。","近有高僧飞锡去，更无馀事出山来。","猿猱历历窥香火，日月纷纷付劫灰。","我欲相期谈实相，东林何必谢刘雷。"]},{"t":"寄育王大觉禅师","f":"七言律诗","c":["单已安那示入禅，草堂难望故依然。","山今岁暮终岑寂，人更天寒最静便。","隐迹亦知甘自足，凭心岂吝慰相怜。","所闻不到荆门耳，人老禾新又一年。"]},{"t":"寄胜之运使","f":"七言律诗","c":["萧然生事委江皋，壮士何尝似钓鳌。","千里得书来见约，一朝乘兴去忘劳。","已将流景休谈笑，聊为知音破郁陶。","正是东风将欲发，湖山春色助挥毫。"]},{"t":"寄致政吴虞部","f":"七言律诗","c":["白鸥生意在沧波，不为风尘有网罗。","年抵冯唐初未半，才方疏广岂能多。","孤清楚国知谁继，遗爱郴人想共歌。","嗟我欲归真未晚，雪舟乘兴会相过。"]},{"t":"寄袁州曹伯玉使君","f":"七言律诗","c":["宜春城郭绕楼台，想见登临把一杯。","湿湿岭云生竹箘，冥冥江雨熟杨梅。","政成定入邦人咏，诗就还随驿使来。","错莫风沙愁病眼，不知何日为君开。"]},{"t":"寄深州晁同年","f":"五言律诗","c":["秀色归荒陇，新声换氄毛。","日催花蕊急，云避雁行高。","驻马旌旗暖，传觞鼓吹豪。","班春不知负，短发为君搔。"]},{"t":"寄黄吉甫","f":"七言律诗","c":["朱颜去似朔风惊，白发多于野草生。","挟策读书空有得，求田问舍转无成。","解鞍乌石冈边坐，携手辛夷树下行。","今日追思真乐事，黄尘深处走鸡鸣。"]},{"t":"寄黄吉甫","f":"七言律诗","c":["学兼文武在吾曹，别后应看虎豹韬。","欲问庙堂谁镇抚，尚传边塞敢惊骚。","旌旗急引飞黄下，烽火遥连太白高。","闻说荆人亦憔悴，家家还愿献春醪。"]},{"t":"寄曾子固","f":"七言律诗","c":["斗粟犹惭报礼轻，敢嗟吾道独难行。","脱身负米将求志，戮力乘田岂为名。","高论几为衰俗废，壮怀难值故人倾。","荒城回首山川隔，更觉秋风白发生。"]},{"t":"寄谢师直","f":"五言律诗","c":["湖海三年隔，相逢塞路中。","黄金酌卯酒，白发对春风。","所愿乖平日，何知即老翁。","悠悠越溪水，好在钓鱼筒。"]},{"t":"寄酬曹伯玉因以招之","f":"七言律诗","c":["寒鸦对立西风树，幽草环生白露庭。","清坐苦无公事扰，高谈时有故人经。","思君异日投朱绂，过我何时载渌醽。","及此江湖气萧爽，最宜相值倒吾瓶。"]},{"t":"寄题程公辟物华楼","f":"七言律诗","c":["吴楚东南最上游，江山多在物华楼。","遥瞻旌节临尊俎，独卧柴荆阻献酬。","想有新诗传素壁，怪无馀墨到沧洲。","湡浯南望重重绿，章水还能向此流。"]},{"t":"崇政殿详定幕次偶题","f":"七言律诗","c":["娇云漠漠护层轩，嫩水溅溅不见源。","禁柳万条金细撚，宫花一段锦新翻。","身闲始更知春乐，地广还同避世喧。","不恨玉盘冰未赐，清谈终日自蠲烦。"]},{"t":"崇禧给事同年马兄挽辞二首 其二","f":"五言律诗","c":["藏室亡三箧，得之公最多。","露晞当晚景，川逝作前波。","惠寄舆人诵，悲传挽者歌。","竹西携手处，清泪邈山河。"]},{"t":"崇禧给事同年马兄挽辞二首 其一","f":"五言律诗","c":["庆历公偕起，元丰我独伤。","两楹终昔梦，五鼎继前丧。","薰歇曾攀桂，甘留所憩棠。","素风知不坠，能世有诸郎。"]},{"t":"得书知二弟附陈师道舟上汴","f":"五言律诗","c":["儿童闻太丘，邂逅两心投。","与汝今为伴，知吾不复忧。","园桃已解萼，沙水欲惊舟。","一见南飞雁，江边肯更留。"]},{"t":"得孙正之诗因寄呈曾子固","f":"七言律诗","c":["一岁已阑人意倦，出门风物更萧然。","水摇疏树荒城路，日带浮云欲雪天。","未有诗书论进退，谩期身世托林泉。","因思漠北离群久，此日穷居赖见贤。"]},{"t":"悼王致处士","f":"七言律诗","c":["处士生涯水一瓢，行年七十更萧条。","老妻稻下分遗秉，弱子松间拾堕樵。","岂有声名高后世，遂无饘粥永今朝。","穷魂散漫知何处，甬水东西不可招。"]},{"t":"晚兴和冲卿学士","f":"五言律诗","c":["剡剡风生晚，娟娟月上初。","白沙眠騄骥，清浪浴鲟鱼。","竟欲从君饮，犹便读我书。","斜阳不到处，墙角树扶疏。"]},{"t":"晨兴望南山","f":"五言律诗","c":["晨兴望南山，不见南山根。","草树露颠顶，樛枝空复繁。","铜瓶取井水，已至尚馀温。","天风一吹拂，的皪成玙璠。"]},{"t":"梦张剑州","f":"七言律诗","c":["万里怜君蜀道归，相逢似喜语还悲。","江淮别业依前处，日月新阡卜几时。","自说曲阿犹未稳，即寻湓水去犹疑。","茫然却是陈桥梦，昨日春风马上思。"]},{"t":"欲归","f":"五言律诗","c":["水漾青天暖，沙吹白日阴。","塞垣春错莫，行路老侵寻。","绿稍还幽草，红应动故林。","留连一杯酒，满眼欲归心。"]},{"t":"欲往净因寄泾州韩持国","f":"七言律诗","c":["紫荆山下物华新，只与都城共一春。","令节想君携绿酒，故情怜我踏黄尘。","泔鱼已悔他年事，搏虎方收末路身。","欲寄微言书不尽，试寻僧阁望西人。"]},{"t":"清风阁","f":"七言律诗","c":["飞甍孤起下州墙，胜势峥嵘压四方。","远引江山来控带，平看鹰隼去飞翔。","高蝉感耳何妨静，赤日焦心不废凉。","况是使君无一事，日陪宾从此倾觞。"]},{"t":"清明辇下怀金陵","f":"七言律诗","c":["春阴天气草如烟，时有飞花舞道边。","院落日长人寂寂，池塘风慢鸟翩翩。","故园回首三千里，新火伤心六七年。","青盖皂衫无复禁，可能乘兴酒家眠。"]},{"t":"谒曾鲁公","f":"七言律诗","c":["翊戴三朝冕有蝉，归荣今作地行仙。","且开京阙萧何第，未放江湖范蠡船。","老景已邻周吕尚，庆门方似汉韦贤。","一觞岂足为公寿，愿赋长虹吸百川。"]},{"t":"揖仙阁","f":"五言律诗","c":["结阁揖仙子，疏塘临隐扉。","水花红四出，山竹翠相围。","云度疑軿下，凫惊恐舄飞。","蜀姜宁可恃，投钓此忘归。"]},{"t":"攲眠","f":"五言律诗","c":["翠幕卷东冈，攲眠月半床。","松声悲永夜，荷气馥初凉。","清话非无寄，幽期故不忘。","扁舟亦在眼，终自懒衣裳。"]},{"t":"景福殿前柏","f":"七言律诗","c":["香叶由来耐岁寒，几经真赏驻鸣銮。","根通御水龙应蛰，枝触宫云鹤更盘。","怪石误蒙三品号，老松先得大夫官。","知君劲节无荣慕，宠辱纷纷一等看。"]},{"t":"游北山","f":"五言律诗","c":["揽辔出东城，登临目暂明。","烟云藏古意，猿鹤弄秋声。","客坐苔纹滑，僧眠樾荫清。","赏心殊未已，山日下西荣。"]},{"t":"游杭州圣果寺","f":"五言律诗","c":["登高见山水，身在水中央。","下视楼台处，空多树木苍。","浮云连海气，落日动湖光。","偶坐吹横笛，残声入富阳。"]},{"t":"游栖霞庵约平甫至因寄","f":"五言律诗","c":["渺渺林间路，萧萧物外僧。","高阴凉易入，闲貌老难增。","官事真伤锦，君恩更饮冰。","求田此山下，终欲忤陈登。"]},{"t":"游赏心亭寄虔州女弟","f":"五言律诗","c":["秀发千峰霁，清涵万里秋。","沧江天上落，明月镜中流。","眼与魂俱断，身依影独留。","为怜幽兴极，不见尔来游。"]},{"t":"登大茅山","f":"七言律诗","c":["一峰高出众山颠，疑隔尘沙道里千。","俯视烟云来不极，仰攀萝茑去无前。","人间已换嘉平帝，地下谁通句曲天。","陈迹是非今草莽，纷纷流俗尚师仙。"]},{"t":"登小茅山","f":"七言律诗","c":["扪萝路到半天穷，下视淮洲杳霭中。","物外真游来几席，人间荣愿付苓通。","白云坐处龙池杳，明月归时鹤驭空。","回首三君谁更似，子房家世有高风。"]},{"t":"登中茅山","f":"七言律诗","c":["翛然杖屦出尘嚣，鸡犬无声到泬寥。","欲见五芝茎叶老，尚攀三鹤羽翰遥。","容溪路转迷横彴，仙几风来得堕樵。","兴罢日斜归亦懒，更磨碑藓认前朝。"]},{"t":"登西楼","f":"七言律诗","c":["楼影侵云百尺斜，行人楼上忆天涯。","情多自悔登临数，目极应惊怅望赊。","一曲平芜连古树，半分残日带明霞。","潘郎何用悲秋色，祇此伤春发已华。"]},{"t":"登宝公塔","f":"七言律诗","c":["倦童疲马放松门，自把长筇倚石根。","江月转空为白昼，岭云分暝与黄昏。","鼠摇岑寂声随起，鸦矫荒寒影对翻。","当此不知谁客主，道人忘我我忘言。"]},{"t":"答冲卿","f":"五言律诗","c":["风作九衢黄，南窗坐正凉。","破瓜青玉美，浮荈白云香。","诗懒犹能强，官闲肯便忘。","贤愚各有用，尺寸果谁长。"]},{"t":"答刘季孙","f":"七言律诗","c":["偶著儒冠敢陋今，自怜多负少时心。","轾轩已任人前后，揭厉安知世浅深。","挟策有思悲慷慨，负薪无力病侵淫。","愧君绿绮虚投赠，更觉贫家报乏金。"]},{"t":"答孙正之","f":"七言律诗","c":["无才处处是穷涂，两地谁传万里书。","节物峥嵘催岁暮，溪山萧洒入吾庐。","南归犹喜寻同志，北去还闻困索居。","佳句不须论旧约，相随阳羡有篮舆。"]},{"t":"答张奉议","f":"七言律诗","c":["五马渡江开国处，一牛吼地作庵人。","结蟠茅竹才方丈，穿筑沟园未过旬。","我久欲忘言语道，君今来见句文身。","思量何物堪酬对，棒喝如今总不亲。"]},{"t":"答熊本推官金陵寄酒","f":"七言律诗","c":["郁金香是兰陵酒，枉入诗人赋咏来。","庭下北风吹急雪，坐间南客送寒醅。","渊明未得归三径，叔夜犹同把一杯。","吟罢想君醒醉处，钟山相向白崔嵬。"]},{"t":"舒州七月十一日雨","f":"七言律诗","c":["行看野气来方勇，卧听秋声落竟悭。","淅沥未生罗豆水，苍茫空失皖公山。","火耕又见无遗种，肉食何妨有厚颜。","巫祝万端曾不救，只疑天赐雨工闲。"]},{"t":"落星寺","f":"七言律诗","c":["崒云台殿起崔嵬，万里长江一酒杯。","坐见山川吞日月，杳无车马送尘埃。","雁飞云路声低过，客近天门梦易回。","胜概唯诗可收拾，不才羞作等闲来。"]},{"t":"葛兴祖挽辞","f":"七言律诗","c":["忆随诸彦附青云，场屋声名看出群。","孙宝暮年犹主簿，卜商今日更修文。","山川凛凛平生气，草木萧萧数尺坟。","欲写此哀终不尽，但令千载少知君。"]},{"t":"葛郎中挽辞二首 其二","f":"五言律诗","c":["蛮荆长往地，湖海独归时。","旅榇蛟龙护，铭旌雁鹜随。","此生要有尽，何物告无期。","一片幽堂石，公知我不欺。"]},{"t":"葛郎中挽辞二首 其一","f":"五言律诗","c":["卷卷穗帷轻，空堂昼哭声。","衣冠遗故物，杯案若平生。","白马有悲送，赤车非古行。","低徊九原日，光景在铭旌。"]},{"t":"谢郏亶秘校见访于钟山之庐","f":"七言律诗","c":["误有声名只自惭，烦君跋马过茅檐。","已知原宪贫非病，更许庄周知养恬。","世事何时逢坦荡，人情随分值猜嫌。","谁能胸臆无尘滓，使我相从久未厌。"]},{"t":"道中寄吉父","f":"七言律诗","c":["白雾青烟入马蹄，朝寒瑟瑟树声悲。","平山断垄回环失，鸣鸟游鱼上下随。","庙算未闻收策士，瘴乡谁与择军麾。","忧时自欲寻君语，行路何妨更有诗。"]},{"t":"道逢文通北使归","f":"七言律诗","c":["朱颜使者锦貂裘，笑语春风入贝州。","欲报京都近消息，传声车马少淹留。","行人尽道还家乐，骑士能吹出塞愁。","回首此时空慕羡，惊尘一段向南流。"]},{"t":"雁","f":"五言律诗","c":["北去还为客，南来岂是归。","倦投空渚泊，饥帖冷云飞。","垣栅鸡长暖，沟池鹜自肥。","怜渠不知此，更堕野人机。"]},{"t":"愁台","f":"七言律诗","c":["颓垣断堑有平沙，老木荒榛八九家。","河势东南吹地坼，天形西北倚城斜。","倾壶语罢还登眺，岸帻诗成却叹嗟。","万事因循今白发，一年容易即黄花。"]},{"t":"慈圣光献皇后挽辞二首 其二","f":"五言律诗","c":["涂山女德茂，京室母才难。","具美多前志，馀光永后观。","遗衣迁馆御，祖载出宫菆。","终始神孙孝，长留万国欢。"]},{"t":"慈圣光献皇后挽辞二首 其一","f":"五言律诗","c":["国赖姜任盛，门归马邓高。","关雎求窈窕，卷耳念勤劳。","圣淑才难拟，休明运继遭。","冈原今献卜，帷扆正攀号。"]},{"t":"慎县修路者","f":"五言律诗","c":["畚筑今三岁，康庄始一修。","何言野人意，能助令君忧。","勠力非无补，论心岂有求。","十年空志食，因汝起予羞。"]},{"t":"筹思亭","f":"七言律诗","c":["昔人何计亦何思，许国忧民适此时。","寓兴中园为远趣，托名华榜有新诗。","数株碧柳苍苔地，一丈红蕖渌水池。","坐听楚谣知岁美，想衔杯酒问花期。"]},{"t":"蒙城清燕堂","f":"七言律诗","c":["清燕新碑得自蒙，行吟如到此堂中。","吏无田甲当时气，民有庄周后世风。","庭下早知闲木索，坐间遥想御丝桐。","飘然一往何时得，俛仰尘沙欲作翁。"]},{"t":"酬王太祝","f":"七言律诗","c":["一马常随世事驰，岂论江徼与河湄。","已成白发潘常侍，更似青衫杜拾遗。","勋业傥来知有命，文章聊欲见无期。","喜君材俊能从我，力学何妨和子思。"]},{"t":"酬冲卿见别","f":"七言律诗","c":["同官同齿复同科，朋友婚姻分最多。","两地尘沙今龃龉，二年风月共婆娑。","朝伦孰与君材似，使指将如我病何。","升黜会应从此异，愿偷闲暇数经过。"]},{"t":"酬吴仲庶小园之句","f":"七言律诗","c":["旧年台榭扫流尘，职闭朱门岁又新。","花影隙中看袅袅，车音墙外去辚辚。","相逢岂少佳公子，一醉何妨薄主人。","祇向东风邀载酒，定知无奈帝城春。"]},{"t":"酬吴季野见寄","f":"七言律诗","c":["漫披陈蠹学经纶，捧檄生平祗为亲。","闻道不先从事早，课功无状取官频。","岂堪置足青冥上，终欲回身寂寞滨。","俯仰谬恩方自歉，惭君将比洛阳人。"]},{"t":"酬净因长老楼上玩月见怀有疑君魂梦在清都之句","f":"七言律诗","c":["道人心与世无求，隐几萧然在此楼。","坐对高梧倾晓月，看翻清露洗新秋。","登临更欲邀元亮，披写还能拟惠休。","顾我不知天上乐，虚疑昨夜梦仙游。"]},{"t":"酬和甫祥源观醮罢见寄","f":"七言律诗","c":["窃禄祠官久见容，每持金石荐宸衷。","钧天忽忽清都梦，方丈寥寥弱水风。","知结胜缘人意外，想寻陈迹马蹄中。","新诗起我超然兴，更感钟山蕙帐空。"]},{"t":"酬郑闳中","f":"七言律诗","c":["萧条行路欲华颠，回首山林尚渺然。","三釜祇知为养急，五浆非敢在人先。","文章满世吾谁慕，行义如君众所传。","宜有至言来助我，可能空寄好诗篇。"]},{"t":"酬俞秀老","f":"七言律诗","c":["洒扫东庵置一床，于君独觉故情长。","有言未必输摩诘，无法何曾泥饮光。","天壤此身知共弊，江湖他日要相忘。","犹贪半偈归思索，却恐提桓妄揣量。"]},{"t":"酬淮南提刑邵不疑学士","f":"七言律诗","c":["曾咏常州送主人，岂知身得两朱轮。","田畴汎滥川方壅，厨传萧条市亦贫。","以我薄材思拊伛，赖君馀教得因循。","询求故有风谣在，不独镵诗尚未泯。"]},{"t":"酬慕容员外","f":"七言律诗","c":["初驾王门学者师，晚漂湖海众人悲。","吹毛未识腰间剑，刺股犹藏袖里锥。","卫霍功名还有命，苏张才气久非时。","江尤亦见应须饮，莫放穷愁入两眉。"]},{"t":"酬裴如晦","f":"七言律诗","c":["二年羁旅越人吟，乞得东南病更侵。","殇子未安庄氏义，寿亲还慰鲁侯心。","鲜鲜细菊霜前蕊，漠漠疏桐日下阴。","浊酒一杯秋满眼，可怜同意不同斟。"]},{"t":"墙西树","f":"七言律诗","c":["墙西高树结阴稠，步屣穷年向此留。","白日屡移催我老，清风一至使人愁。","纷纷暝鸟惊还合，渺渺凉蝉咽欲休。","回首旧林归未得，看看知复几春秋。"]},{"t":"暮春","f":"五言律诗","c":["春期行晼晚，春意剩芳菲。","曲水应修禊，披香未试衣。","雨花红半堕，烟树碧相依。","怅望梦中地，王孙底不归。"]},{"t":"蓼虫","f":"七言律诗","c":["蓼虫事业无馀习，刍狗文章不更陈。","隐几自怜居丧我，倨堂谁觉似非人。","难堪藏室称中士，祗合箕山作外臣。","尚有少缘灰未死，欲持新句恼比邻。"]},{"t":"静照堂","f":"五言律诗","c":["任公蹲会稽，海上得招提。","净观堂新搆，幽寻客屡携。","飞檐出风雨，洒翰落虹蜺。","投老黄尘陌，东看路恐迷。"]},{"t":"豫章道中次韵答曾子固","f":"七言律诗","c":["离别何言邂逅同，今知相逐似云龙。","苍烟白雾千山合，绿树青天一水容。","已谢道涂多自放，将归田里更谁从。","庞公有意安巢穴，肯问箪瓢与万钟。"]},{"t":"读镇南邸报癸未四月作","f":"五言律诗","c":["赐诏宽言路，登贤壮陛廉。","相期正在治，素定不烦占。","众喜夔龙盛，予虞绛灌憸。","太平讵可致，天意慎猜嫌。"]},{"t":"题友人郊居水轩","f":"五言律诗","c":["田中三亩宅，水上一轩开。","为有渔樵乐，非无仕进媒。","槎头收晚钓，荷叶卷新醅。","坐说鱼腴美，功名挽不来。"]},{"t":"题友人壁","f":"七言律诗","c":["茆檐前后欠松萝，百里乘闲向此过。","涧水绕田山影转，野林留日鸟声和。","萧条鸡犬逢人少，想象乾坤发兴多。","世事不如闲静处，知君出处意如何。"]},{"t":"题仪真致政孙学士归来亭","f":"七言律诗","c":["彭泽陶潜归去来，素风千岁出尘埃。","明时俊老心无累，故里高门子有才。","更作园林负城郭，常留花月映池台。","却寻五柳先生传，柴水区区但可哀。"]},{"t":"题正觉相上人箨龙轩","f":"七言律诗","c":["风玉萧萧数亩秋，箨龙名为道人留。","不须乞米供高士，但与开轩作胜游。","此地七贤谁笑傲，何时六逸自赓酬。","侵寻衰境心无著，尚有家风似子猷。"]},{"t":"题朱郎中白都庄","f":"五言律诗","c":["萧洒桐庐守，沧洲寄一廛。","山光隔钓岸，江气杂炊烟。","藜杖听鸣橹，篮舆看种田。","明时须共理，此兴在他年。"]},{"t":"题汤泉壁示诸子有欲闲之意","f":"五言律诗","c":["吟哦一水上，披写众峰间。","偶运非彭泽，留名比岘山。","君才今卨稷，家行古原颜。","平世虽多士，安能易地闲。"]},{"t":"题齐安寺山亭","f":"五言律诗","c":["此山无踯躅，故国有杨梅。","怅望心常折，慇勤手自栽。","暮年逢火改，晴日对花开。","万里乌塘路，春风自往来。"]},{"t":"题雱祠堂","f":"五言律诗","c":["斯文实有寄，天岂偶生才。","一日凤鸟去，千秋梁木摧。","烟留衰草恨，风造暮林哀。","岂谓登临处，飘然独往来。"]},{"t":"赠上元宰梁之仪承议","f":"五言律诗","c":["白下有贤宰，能歌如紫芝。","民欺自不忍，县治本无为。","风月谁同赏，江山我亦思。","粉墙侵醉墨，怊怅绿苔滋。"]},{"t":"赠工部侍郎郑公挽辞","f":"七言律诗","c":["地蟠江汉久知灵，通德门中见老成。","南去伏波推将略，北来光禄擅诗名。","密章赠襚连三组，画翣丧车载一旌。","阴德故应多后福，可能生子但升卿。"]},{"t":"赠长宁僧首","f":"七言律诗","c":["秀骨厖眉倦往还，自然清誉落人间。","闲中用意归诗笔，静外安身比太山。","欲倩野云朝送客，更邀江月夜临关。","嗟予踪迹飘尘土，一对孤峰几厚颜。"]},{"t":"赠李士宁道人","f":"七言律诗","c":["季主逡巡居卜肆，弥明邂逅作诗翁。","曾令宋贾叹车上，更使刘侯惊坐中。","杳杳人传多异事，冥冥谁识此高风。","行歌过我非无谓，唯恨贫家酒盏空。"]},{"t":"赠殊胜院简道人","f":"五言律诗","c":["早悟耆山善，今为洛社豪。","有生常寂寞，所得是风骚。","露夕吟逾苦，云收思共高。","此怀差自适，千社一牛毛。"]},{"t":"藏春坞诗献刁十四丈学士","f":"七言律诗","c":["蒜山东渡得林丘，邂逅篮舆亦少留。","今日更知莱氏隐，暮年长忆武陵游。","欲营垣屋随穿斸，尚叹尘沙隔献酬。","遥约勾吴亭下路，春风深驻五湖舟。"]},{"t":"露坐","f":"五言律诗","c":["露坐看沟月，飘然风度荷。","珠跳散作点，金涌合成波。","老失芳岁易，静知良夜多。","陵秋久不寐，吾乐岂弦歌。"]},{"t":"双庙","f":"五言古诗","c":["两公天下骏，无地与腾骧。","就死得处所，至今犹耿光。","中原擅兵革，昔日几侯王。","此独身如在，谁令国不亡。","北风吹树急，西日照窗凉。","志士千年泪，泠然落奠觞。"]},{"t":"见远亭上王郎中","f":"五言古诗","c":["高亭豁可望，朝暮对溪山。","野色轩楹外，霞光几席间。","树侵苍霭没，鸟背夕阳还。","草带平沙阔，烟笼别戍闲。","圃畦荷气合，田径烧痕斑。","樵笛吟晴坞，渔帆出暝湾。","登临及芳节，宴喜发朱颜。","夹砌陈旌旝，褰帘进佩环。","观风南国最，应宿紫宸班。","康乐诗名旧，芜音讵可攀。"]},{"t":"扬雄","f":"五言古诗","c":["孔孟如日月，委蛇在苍旻。","光明所照耀，万物成冬春。","扬子出其后，仰攀忘贱贫。","衣冠渺尘土，文字烂星辰。","岁晚天禄阁，强颜为剧秦。","趋舍迹少迩，行藏意终邻。","壤壤外逐物，纷纷轻用身。","往者或可返，吾将与斯人。"]},{"t":"次韵张子野秋中久雨晚晴","f":"五言古诗","c":["天沉四山黑，池涨百泉黄。","苦湿欲千里，愿晴非一乡。","埽除供晚色，洗刷放秋光。","菊泣花犹重，粳肥穗稍长。","积阴消户牖，返照媚林塘。","想见阳台路，神归发彩凉。"]},{"t":"次韵留题僧假山","f":"五言古诗","c":["态足万峰奇，功才一篑微。","愚公谁助徙，灵鹫却愁飞。","窦雪藏银镒，檐曦散玉辉。","未应颓蚁壤，方此镇禅扉。","物理有真伪，僧言无是非。","但知名尽假，不必故山归。"]},{"t":"和子瞻同王胜之游蒋山","f":"五言古诗","c":["金陵限南北，形势岂其然。","楚役六千里，陈亡三百年。","江山空幕府，风月自觥船。","主送悲凉岸，妃埋想故莲。","台倾凤久去，城踞虎争偏。","司马壖庙域，独龙层塔颠。","森疏五愿木，蹇浅一人泉。","棁杖穷诸岭，篮舆罢半天。","朱门园渌水，碧瓦第青烟。","墨客真能赋，留诗野竹娟。"]},{"t":"和吴冲卿雪霁紫宸朝","f":"五言古诗","c":["虎士开阊阖，鸡人唱九霄。","云移银阙角，日转玉廊腰。","帚动川收潦，靴鸣海上潮。","舞袍沾宿润，拜笏拥残飘。","赐饮人何乐，归嘶马亦骄。","低徊但忘食，吟咏得逍遥。"]},{"t":"和钱学士喜雪","f":"七言古诗","c":["手把诗翁忆雪诗，坐愁穷海瘴烟霏。","谁令天上苍茫合，忽见空中散漫飞。","阊阖与风生气势，姮娥交月借光辉。","山鸦瑟缩相依立，邑犬跳梁未肯归。","点缀丘园荣树木，埋藏沟堑乱封圻。","高歌业已传都市，逸兴何当叩隐扉。","颇欲携樽邀使骑，几忘温席荐亲闱。","公今早晚班春去，强劝涝田补岁饥。"]},{"t":"奉酬约之见招","f":"五言古诗","c":["君家段干木，为义畏人侵。","冯轼信厚礼，逾垣终褊心。","川坻宁有此，园屋谅非今。","雨过梅柳净，潮来蒲稗深。","种芳弥近渚，伐翳取遥岑。","清节亦难尚，旷怀差易寻。","子猷怜水竹，逸少惬山林。","况复能招我，亲题汉上襟。"]},{"t":"送周都官通判湖州","f":"五言古诗","c":["渌水乌程地，青山顾渚滨。","酒醪犹美好，茶荈正芳新。","聚泛樽前月，分班焙上春。","仁风已入俗，乐事始关身。","橘柚供南贡，枫槐望北宸。","知君白羽扇，归日未生尘。"]},{"t":"一日不再饭","f":"五言律诗","c":["一日不再饭，饭已八九眠。","忽忽返照閒，顿羸不可迁。","筋骸徽纆束，肺腑鼎铛煎。","长往理不惜，高堂思所牵。"]},{"t":"一日归行","f":"七言律诗","c":["贱贫奔走食与衣，百日奔走一日归。","平生欢意苦不尽，正欲老大相因依。","空房萧瑟施穗帷，青灯半夜哭声稀。","音容想像今何处，地下相逢果是非。"]},{"t":"一陂","f":"七言绝句","c":["一陂焰水蒋陵西，含风却转与城齐。","周遭碧铜磨作港，逼塞绿锦剪成畦。"]},{"t":"乙巳九月登冶城作","f":"五言律诗","c":["欲望钟山岑，因知冶城路。","跻攀隐木杪，稍记曾游处。","红沉渚上日，苍起榛中雾。","即事有哀伤，山川自如故。"]},{"t":"乙未冬妇子病至春不已","f":"七言律诗","c":["天旋无穷走日月，青发能禁几回首。","儿呻妇叹冬复春，强欲笑歌难发口。","黄卷幽寻非贵嗜，藜床稳卧虽贫有。","二物长乖亦可怜，一生所得犹多苟。"]},{"t":"七星砚","f":"五言古诗","c":["余闻星堕地，往往化为石。","石上有七星，此理余莫测。","持来当白日，光彩不为匿。","恍如起鸿蒙，俛仰帝垣侧。","当由偶然似，见取参笔墨。","豪心荡珍异，乐以万金得。","南工始为伪，傅合巧无隙。","亦时疑世人，故自有能识。"]},{"t":"九井","f":"七言古诗","c":["沿崖涉涧三十里，高下荦确无人耕。","扪萝挽茑到山趾，仰见吹泻何峥嵘。","馀声投林欲风雨，末势卷土犹溪坑。","飞虫凌兢走兽慄，霜雪夏落雷冬鸣。","野人往往见神物，鳞甲漠漠云随行。","我来立久无所得，空数石上菖蒲生。","中官系龙沉玉册，小吏磔狗浇银觥。","地形偶尔藏险怪，天意未必司阴晴。","山川在理有崩竭，丘壑自古相虚盈。","谁能保此千世后，天柱不折泉常倾。"]},{"t":"九日随家人游东山遂游东园","f":"五言律诗","c":["暑往讵几时，凉归亦云暂。","相随东山乐，及此身无憾。","聊回清池柂，更伏荒城槛。","采采黄金花，持杯为君泛。"]},{"t":"九鼎","f":"七言古诗","c":["禹行掘山走百谷，蛟龙窜藏魑魅伏。","心志幽妖尚觊隙，以金铸鼎空九牧。","冶云赤天涨为黑，韛风馀吹山拔木。","鼎成聚观变怪索，夜人行歌鬼昼哭。","功施元元后无极，三姓卫守相传属。","弱周无人有宜出，沈之九幽拆地轴。","始皇区区求不得，坐令神奸窥邑屋。"]},{"t":"八月十九日试院梦冲卿","f":"七言律诗","c":["空庭得秋长漫漫，寒露入幕愁衣单。","喧喧人语已成市，白日未到扶桑间。","永怀所好却成梦，玉色彷佛开心颜。","逆知后应不复隔，谈笑明月相与閒。"]},{"t":"三战败不羞","f":"五言律诗","c":["三战败不羞，一官迁辄喜。","古人思慰亲，愧辱宁在己。","于陵避兄食，织屦仰妻子。","恩义有相权，洁身非至理。"]},{"t":"上南冈","f":"五言律诗","c":["暮坞屋荒凉，寒陂水清浅。","捐书息微倦，委辔随小蹇。","偶攀黄黄柳，却望青青巘。","幽寻复有兴，未觉西林晚。"]},{"t":"与平甫同赋槐","f":"五言律诗","c":["冰雪泊楚岸，万株同飘零。","春风都城居，初见叶青青。","岁行如车轮，荫翳忽满庭。","秋子今在眼，何时动江舲。"]},{"t":"与吕望之上东岭","f":"五言古诗","c":["靖节爱吾庐，猗玗乐吾耳。","适野无世諠，吾今亦如此。","纷纷旧可厌，俗子今扫轨。","使君气相求，眷顾未云已。","追随上东岭，俯仰多可喜。","何以况清明，朝阳丽秋水。","微云会消散，岂久污尘滓。","所怀在分衿，藉草泪如洗。"]},{"t":"与望之至八功德水","f":"五言律诗","c":["念方与子违，惝恍夜不眠。","起视明星高，整驾出东阡。","聊为山水游，以写我心悁。","知子不餔糟，相与酌云泉。"]},{"t":"与道原过西庄遂游宝乘道原游西庵遂至草堂宝乘寺二首 其一","f":"五言律诗","c":["桑杨已零落，藻荇亦消沈。","园宅在人境，岁时伤我心。","强穿西埭路，共望北山岑。","欲觅道人语，跨鞍聊一寻。"]},{"t":"与僧道升二首 其二","f":"七言古诗","c":["跋陀罗师能幻物，幻秽为净持幻佛。","佛幻诸天以戏之，幢幡香果助设施。","茫然悔欲除所幻，还为幻佛力所持。","佛天与汝本无间，汝今何恭昔何慢。","十方三世本来空，受记岂非遭佛幻。"]},{"t":"与僧道升二首 其一","f":"五言古诗","c":["升也初见我，肤腴仍洁白。","今何苦而老，手脚皴以黑。","闻有道人者，于今号禅伯。","嬲汝以一句，西归瘦如腊。","汝观青青枝，岁寒好颜色。","此松亦有心，岂问庭前柏。"]},{"t":"久雨","f":"七言律诗","c":["煤炱著天无寸空，白沫上岸吹鱼龙。","羲和推车出不得，河伯欲取山为宫。","城门昼开眠百贾，饥孙得糟夜哺翁。","老人惯事少所怪，看屋箕踞歌南风。"]},{"t":"千丈岩瀑布","f":"七言绝句","c":["拔地万重清嶂立，悬空千丈素流分。","共看玉女机丝挂，映日还成五色文。"]},{"t":"山田久欲拆","f":"五言古诗","c":["山田久欲拆，秋至尚求雨。","妇女喜秋凉，踏车多笑语。","朔云卷众水，惨淡吹平楚。","横陂与直堑，疑即没洲渚。","霍霍反照中，散丝鱼几缕。","鸿蒙不可问，且往知何许。","攲眠露下舸，侧见星月吐。","龙骨已呕哑，田家真作苦。"]},{"t":"己未耿天骘著作自乌江来予逆沈氏妹于白鹭洲遇雪作此诗寄天骘","f":"五言古诗","c":["朔风积夜雪，明发洲渚净。","开门望钟山，松石皓相映。","故人过我宿，未尽跻攀兴。","而我方渺然，长波一归艇。","款段庶可策，柴荆当未暝。","与子出东冈，墙西扫新径。"]},{"t":"飞雁","f":"七言律诗","c":["雁飞冥冥时下泊，稻粱虽少江湖乐。","人生何必慕轻肥，辛苦将身到沙漠。","汉时苏武与张骞，万里生还值偶然。","丈夫许国当如此，男子辞亲亦可怜。"]},{"t":"马上转韵","f":"七言律诗","c":["三月杨花迷眼白，四月柳条空老碧。","年光如水尽东流，风物看看又到秋。","人世百年能几许，何须戚戚长辛苦。","富贵功名自有时，箪瓢捽茹亦山雌。"]},{"t":"书八功德水庵","f":"五言古诗","c":["幽独若可厌，真实为可喜。","见山不碍目，闻水不逆耳。","翛然无所为，自得而已矣。"]},{"t":"书任村马铺","f":"七言古诗","c":["儿童系马黄河曲，近岸河流如可掬。","任村炊米朝食鱼，日暮荥阳驿中宿。","投老经过身独在，当时洲渚今平陆。","秫黍冥冥十数家，仰视荒蹊但乔木。","冰盘鲙美客自知，起看白水还东驰。","尔来百口皆年少，归与何人共此悲。"]},{"t":"书会别亭","f":"词","c":["西城路，居人送客西归处。","年年借问去何时，今日扁舟从此去。","春风吹花落高枝，飞来飞去不自知。","路上行人亦如此，应有重来此处时。"]},{"t":"书定林院窗","f":"五言绝句","c":["道人今辍讲，卷裓寄松萝。","梦说波罗蜜，当如习气何。"]},{"t":"云山诗送正之","f":"七言律诗","c":["云山参差碧相围，溪水诘曲带城陴。","溪穷壤断至者谁，予独与子相谐熙。","山城之西鼓吹悲，水风萧萧不满旗。","子今去此来无时，予有不可谁予规。"]},{"t":"今日非昨日","f":"五言古诗","c":["今日非昨日，昨日已可思。","明日异今日，如何能勿悲。","当门五六树，上有蝉鸣枝。","朝听尚壮急，暮闻已衰迟。","仰看青青叶，亦复少华滋。","万物同一气，固知当尔为。","我友南山居，笑谈解人颐。","分我秋柏实，问言归何时。","衣冠污穷尘，苟得犹苦饥。","低徊岁已晚，恐负平生期。"]},{"t":"元丰行示德逢","f":"七言古诗","c":["四山翛翛映赤日，田背坼如龟兆出。","湖阴先生坐草室，看踏沟车望秋实。","雷蟠电掣云滔滔，夜半载雨输亭皋。","旱禾秀发埋牛尻，豆死更苏肥荚毛。","倒持龙骨挂屋敖，买酒浇客追前劳。","三年五谷贱如水，今见西成复如此。","元丰圣人与天通，千秋万岁与此同。","先生在野故不穷，击壤至老歌元丰。"]},{"t":"凤凰山","f":"五言律诗","c":["驱马信所适，落日望九州。","青山满天地，何往为吾丘。","贫贱身秖辱，富贵道足羞。","涉世谅如此，惜哉去无由。"]},{"t":"凤凰山","f":"七言律诗","c":["欢乐欲与少年期，人生百年常苦迟。","白头富贵何所用，气力但为忧勤衰。","愿为五陵轻薄儿，生在贞观开元时。","斗鸡走犬过一生，天地安危两不知。"]},{"t":"勿去草","f":"词","c":["勿去草，草无恶，若比世俗俗浮薄。","君不见长安公卿家，公卿盛时客如麻。","公卿去后门无车，惟有芳草年年佳。","又不见千里万里江湖滨，触目凄凄无故人。","惟有芳草随车轮。","一日还旧居，门前草先锄。","草于主人实无负，主人于草宜何如。","勿去草，草无恶，若比世俗俗浮薄。"]},{"t":"化城阁","f":"五言古诗","c":["曾宫凭风回，两岸闻钟声。","百里见秋毫，搆云有高营。","化城若化出，仰攀日月行。","俛视大江奔，众山遥相迎。","大江蟠㠌根，旋流自成浪。","却略罗翠屏，秀色各异状。","楞伽海中山，迥出霄汉上。","中有不死庭，天龙尽回向。","惜哉不得往，侧坐渺难望。","拥掩难恕宥，意欲铲叠嶂。","登临独无语，一望一怊怅。","忽忆少年时，孤屿坐题诗。","空怀焉能果，唯有故人知。"]},{"t":"天下不用车","f":"五言古诗","c":["天下不用车，人人乘马驰。","王良虽善御，揽辔欲从谁。","汉武伐大宛，杀人若京坻。","孝文却走马，独行先安之。","万物命在天，取舍各有时。","阴阳更用事，冬暖岂所宜。","卞氏强献玉，两刖亦已痴。","幸终遇良工，已剖得不疑。"]},{"t":"太白岭","f":"七言律诗","c":["太白巃嵷东南驰，众岭环合青纷披。","烟云厚薄皆可爱，树石疏密自相宜。","阳春已归鸟语乐，溪水不动鱼行迟。","生民何由得处所，与兹鱼鸟相谐熙。"]},{"t":"孔子","f":"七言律诗","c":["圣人道大能亦博，学者所得皆秋毫。","虽传古未有孔子，蠛蠓何足知天高。","桓魋武叔不量力，欲挠一草摇蟠桃。","颜回已自不可测，至死钻仰忘身劳。"]},{"t":"少年见青春","f":"五言古诗","c":["少年见青春，万物皆妩媚。","身虽不饮酒，乐与宾客醉。","一从鬓上白，百不见可喜。","心肠非故时，更觉日月驶。","闻欢已倦往，得饱还思睡。","春归只如梦，不复悲憔悴。","寄言少年子，努力作春事。","亦勿怪衰翁，衰强自然异。"]},{"t":"少狂喜文章","f":"五言古诗","c":["少狂喜文章，颇复好功名。","稍知古人心，始欲老蚕耕。","低徊但志食，邂逅亦专城。","仰惭冥冥士，俯愧扰扰氓。","良夜未遽央，青灯数寒更。","拨书置左右，仰屋慨平生。"]},{"t":"开元行","f":"词","c":["君不闻开元盛天子，纠合俊杰披奸猖。","几年辛苦补四海，始得完好无疽疮。","一朝寄托谁家子，威福颠倒那复理。","那知赤子偏愁毒，祇见狂胡仓卒起。","茫茫孤行西万里，偪仄归来竟忧死。","子孙险不失故物，社稷陵夷从此始。","由来犬羊著冠坐庙堂，安得四鄙无豺狼。"]},{"t":"忆北山送胜上人","f":"七言律诗","c":["苍藤翠木江南山，激激流水两山间。","山高水深鱼鸟乐，车马迹绝人长闲。","云埋樵声隔葱茜，月弄钓影临潺湲。","黄尘满眼衣可濯，梦寐惆怅何时还。"]},{"t":"忆昨诗示诸外弟","f":"七言古诗","c":["忆昨此地相逢时，春入穷谷多芳菲。","短垣囷囷冠翠岭，踯躅万树红相围。","幽花媚草错杂出，黄蜂白蝶参差飞。","此时少壮自负恃，意气与日争光辉。","乘闲弄笔戏春色，脱略不省旁人讥。","坐欲持此博轩冕，肯言孔孟犹寒饥。","丙子从亲走京国，浮尘坌并缁人衣。","明年亲作建昌吏，四月挽船江上矶。","端居感慨忽自寤，青天闪烁无停晖。","男儿少壮不树立，挟此穷老将安归。","吟哦图书谢庆吊，坐室寂寞生伊威。","材疏命贱不自揣，欲与稷契遐相希。","旻天一朝畀以祸，先子泯没予谁依。","精神流离肝肺绝，眦血被面无时晞。","母兄呱呱泣相守，三载厌食钟山薇。","属闻降诏起群彦，遂自下国趋王畿。","刻章琢句献天子，钓取薄禄欢庭闱。","身著青衫手持版，奔走卒岁官淮沂。","淮沂无山四封庳，独有庙塔尤峨巍。","时时凭高一怅望，想见江南多翠微。","归心动荡不可抑，霍若猛吹翻旌旂。","腾书漕府私自列，仁者恻隐从其祈。","暮春三月乱江水，劲橹健帆如转机。","还家上堂拜祖母，奉手出涕纵横挥。","出门信马向何许，城郭宛然相识稀。","永怀前事不自适，却指舅馆接山扉。","当时髫儿戏我侧，于今冠佩何颀颀。","况复丘樊满秋色，蜂蝶摧藏花草腓。","令人感嗟千万绪，不忍苍卒回骖騑。","留当开樽强自慰，邀子剧饮毋予违。"]},{"t":"无动","f":"五言古诗","c":["无动行善行，无明流有流。","种种生住灭，念念闻思修。","终不与法缚，亦不著僧裘。"]},{"t":"无营","f":"五言律诗","c":["无营固无尤，多与亦多悔。","物随扰扰集，道与翛然会。","墨翟真自苦，庄周吾所爱。","万物莫足归，此言犹有在。"]},{"t":"日出堂上饮","f":"五言古诗","c":["日出堂上饮，日西未云休。","主人笑而歌，客子叹以愀。","指此堂上柱，始生在岩幽。","雨露饱所滋，凌云亦千秋。","所托愿求久，何言值君收。","乃令卑湿地，百蚁上穷锼。","丹青空外好，镇压已堪忧。","为君重去之，不使一蚁留。","蚁力虽云小，能生万蚍蜉。","又能高其础，不尔继者稠。","语客且勿然，百年等浮沤。","为客当酌酒，何豫主人谋。"]},{"t":"月夜二首 其二","f":"五言律诗","c":["蹋月看流水，水明摇荡月。","草木已华滋，山川复清发。","褰裳伏槛处，绿净数毛发。","谁能挽姮娥，俯濯凌波袜。"]},{"t":"月夜二首 其一","f":"五言律诗","c":["山泉堕清陂，陂月临静路。","惜哉此佳境，独赏无与晤。","埭口哆陂阴，要予水西去。","呼僮拥草垡，复使东南注。"]},{"t":"牛渚","f":"七言古诗","c":["历阳之南有牛渚，一风微吹万舟阻。","华戎蛮蜀支百川，合为大江神所躔。","山盘水怒不得泄，到此乃有无穷渊。","朱衣乘车作官府，操制生杀非无权。","阴灵秘怪不欲露，燬犀得祸岂偶然。"]},{"t":"车载板二首 其二","f":"五言古诗","c":["鸟有车载板，朝暮尝一至。","世传鵩似鸮，而此与鸮似。","唯能预人死，以此有名字。","疑即贾长沙，当时所遭值。","洛阳多少年，扰扰经世意。","粗闻方外语，便释形骸累。","吾衰久捐书，放浪无复事。","尚自不见我，安知汝为异。","怜汝好毛羽，言音亦清丽。","胡为太多知，不默而见忌。","楚人既憎汝，弹射将汝利。","且长随我游，吾不汝羹胾。"]},{"t":"车载板二首 其一","f":"五言古诗","c":["荒哉我中园，珍果所不产。","朝暮惟有鸟，自呼车载板。","楚人闻此声，莫有笑而莞。","而我更歌呼，与之相往返。","视遇若抟黍，好音而睍睆。","壤壤生死梦，久知无可拣。","物弊则归土，吾归其不晚。","归欤汝随我，可相蒿里挽。"]},{"t":"车螯","f":"五言古诗","c":["海于天地间，万物无不容。","车螯亦其一，埋没沙水中。","独取常苦易，卫生乏明聪。","机缄谁使然，含蓄略相同。","坐欲肠胃得，要令汤火攻。","置之先生盘，啖客为一空。","蛮夏怪四坐，不论壳之功。","狼籍堆左右，弃置任儿童。","何当强收拾，持问大医工。"]},{"t":"车螯二首 其一","f":"五言古诗","c":["车螯肉甚美，由美得烹燔。","壳以无味弃，弃之能久存。","予尝怜其肉，柔弱甘咀吞。","又尝怪其壳，有功不见论。","醉客快一啖，散投墙壁根。","宁能为收拾，持用讯医门。"]},{"t":"车螯二首 其二","f":"五言古诗","c":["车螯肉之弱，恃壳保厥身。","自非身有求，不敢微启唇。","尚恐擉者得，泥沙常埋堙。","往往汤火间，身尽壳空存。","维海错万物，口牙且咀吞。","尔无如彼何，可畏宁独人。","无为久自苦，含匿不暴陈。","豁然从所如，游荡四海漘。","清波濯其污，白日晒其昏。","死生或有在，岂遽得烹燔。"]},{"t":"丙戌五日京师作二首 其二","f":"七言绝句","c":["浮云离披久不合，太阳独行乾万物。","谁令昨夜雨霶沱，北风萧萧寒到骨。"]},{"t":"丙戌五日京师作二首 其一","f":"七言绝句","c":["北风阁雨去不下，惊沙苍茫乱昏晓。","传闻城外八九里，雹大如拳死飞鸟。"]},{"t":"东门","f":"五言古诗","c":["东门白下亭，摧甓蔓寒葩。","浅沙杙素舸，一水宛秋蛇。","渔商数十室，门巷隐桑麻。","翰林谪仙人，往岁酒姥家。","调笑此水上，能歌杨白花。","杨花飞白雪，枝袅绿烟斜。","舞袖卷烟雪，绮裘明紫霞。","风流翳蓬颗，故地使人嗟。","迢迢陌头青，空复可藏鸦。"]},{"t":"东方朔","f":"五言古诗","c":["平原狂先生，隐翳世上尘。","材多不可数，射覆亦绝伦。","谈辞最诙怪，发口如有神。","以此得亲幸，赐予颇不贫。","金玉本光瑩，泥沙岂能堙。","时时一悟主，惊动汉庭臣。","不肯下儿童，敢言诋平津。","何知夷与惠，空复忤时人。"]},{"t":"出巩县","f":"七言古诗","c":["昭陵落月烟雾昏，篝火度谷行山根。","投鞭委辔涉数村，寤出巩县城东门。","向来宫阙不可见，但有洛水流浑浑。"]},{"t":"北山三咏 其一 宝公塔","f":"七言律诗","c":["道林真骨葬青霄，窣堵千秋未寂寥。","宝势旁连大江起，尊形独受众山朝。","云泉别寺分三径，香火幽人止一瓢。","我亦鹫峰同听法，岁时歌呗岂辞遥。"]},{"t":"北客置酒","f":"七言古诗","c":["紫衣操鼎置客前，巾韝稻饭随粱饘。","引刀取肉割啖客，银盘擘臑薧与鲜。","殷勤劝侑邀一饱，卷牲归馆觞更传。","山蔬野果杂饴蜜，獾脯豕腊加炰煎。","酒酣众史稍欲起，小胡捽耳争留连。","为胡止饮且少安，一杯相属非偶然。"]},{"t":"北窗","f":"七言律诗","c":["病与衰期每强扶，鸡壅桔梗亦时须。","空花根蒂难寻摘，梦境烟尘费扫除。","耆域药囊真妄有，轩辕经匮或元无。","北窗枕上春风暖，漫读毗耶数卷书。"]},{"t":"发廪","f":"五言古诗","c":["先王有经制，颁赍上所行。","后世不复古，贫穷主兼并。","非民独如此，为国赖以成。","筑台尊寡妇，入粟至公卿。","我尝不忍此，愿见井地平。","大意苦未就，小官苟营营。","三年佐荒州，市有弃饿婴。","驾言发富藏，云以救鳏茕。","崎岖山谷间，百室无一盈。","乡豪已云然，罢弱安可生。","兹地昔丰实，土沃人良耕。","他州或呰窳，贫富不难评。","豳诗出周公，根本讵宜轻。","愿书七月篇，一寤上聪明。"]},{"t":"古意","f":"五言古诗","c":["采芝天门山，寒露净毛骨。","帝青九万里，空洞无一物。","倾河略西南，晶射河鼓没。","蓬莱眼中见，人世叹超忽。","当时弃桃核，闻已撑月窟。","且当呼阿环，乘兴弄溟渤。"]},{"t":"台上示吴愿","f":"五言绝句","c":["细书妨老读，长簟惬昏眠。","取簟且一息，抛书还少年。"]},{"t":"司马迁","f":"五言古诗","c":["孔鸾负文章，不忍留枳棘。","嗟子刀锯间，悠然止而食。","成书与后世，愤悱聊自释。","领略非一家，高辞殆天得。","虽微樊父明，不失孟子直。","彼欺以自私，岂啻相十百。"]},{"t":"叹息行","f":"七言律诗","c":["官驱群囚入市门，妻子恸哭白日昏。","市人相与说囚事，破家劫钱何处村。","朝廷法令亦宽大，汝罪当死谁云冤。","路傍年少叹息汝，贞观元元之子孙。"]},{"t":"四皓二首 其二","f":"五言古诗","c":["秦驱九州逃，知力起经纶。","重利诱众策，颇知聚秦民。","颓然此四老，上友千载魂。","采芝商山中，一视汉与秦。","灵珠在泥沙，光景不可昏。","道德虽避世，馀风回至尊。","嫡孽一朝正，留侯果知言。","出处但有礼，废兴岂所存。"]},{"t":"四皓二首 其一","f":"五言律诗","c":["四皓秦汉时，招招莫能致。","紫芝可以饱，粱肉非所嗜。","谷广水涣涣，山长云泄泄。","与其贵而拘，不若贱而肆。"]},{"t":"圣贤何常施","f":"五言律诗","c":["圣贤何常施，所遇有伸屈。","曲士守一隅，欲以齐万物。","丧非不欲富，言为南宫出。","世无子有子，谁敢救其失。"]},{"t":"圣俞为狄梁公孙作诗要予同作","f":"五言古诗","c":["虎豹不食子，鸱枭不乘雄。","人恶甚鸟兽，吾能与成功。","爱有以计留，去有势不容。","吾谋适合意，几亦齿奸锋。","时恩沦九泉，褒取异代忠。","堂堂社稷臣，近世孰如公。","空使苗裔孙，称扬得诗翁。","一读亦使我，慨然想馀风。"]},{"t":"对棋与道源至草堂寺","f":"七言绝句","c":["北风吹人不可出，清坐且可与君棋。","明朝投局日未晚，从此亦复不吟诗。"]},{"t":"平甫归饮","f":"楚辞体","c":["无田士相吊，亦以废燕乐。","我官虽在朝，得饮乃不数。","诗书向墙户，宾至无杯杓。","空取上古言，酬之等糟粕。","有如扬子云，岁晚天禄阁。","但无载酒人，识字真未博。","叔兮归自东，一笑堂上酌。","绪馀不及客，儿女聊相酢。","高谈非世欢，自慰亦不恶。","寄言繁华子，此趣由来各。"]},{"t":"汉文帝","f":"五言律诗","c":["轻刑死人众，丧短生者偷。","仁孝自此薄，哀哉不能谋。","露台惜百金，灞陵无高丘。","浅恩施一时，长患被九州。"]},{"t":"甘棠梨","f":"五言古诗","c":["甘棠诗所歌，自足誇众果。","爱其凌秋霜，万玉悬磊砢。","园夫盛采摘，市贾争包裹。","车输动盈箱，舟载辄连柁。","朝分不知数，暮在知几颗。","但使甘有馀，何伤小而椭。","主人捐千金，饤饾留四坐。","柑椑与橙栗，在口亦云可。","都城纷华地，内热易生火。","问客当此时，蠲烦孰如我。"]},{"t":"用王微之韵和酬即事书怀","f":"五言古诗","c":["秦惜逝者耋，晋嘉良士休。","古人皆好乐，哀此岁月遒。","嗟我抱愁毒，残年自羁囚。","但为兔得蹄，非复天上鸥。","虽知林塘美，欲往辄回辀。","名园一散策，笑语随觥筹。","探题绕梅花，高咏接应刘。","宿雨洗荒堑，寒蛟沈老湫。","沿洄信画舸，归路子城幽。","冬风不改绿，忽见新阳浮。","欢事去如梦，嘉时念难留。","明发得君句，谓将续前游。","语我饮倡乐，不如诗献酬。","淮洲奏钟鼛，雅刺德不犹。","文墨有真趣，荒淫何足收。","来篇信时女，窈窕众所求。","兹理傥可谐，华簪为君抽。"]},{"t":"用字谜","f":"词","c":["一月又一月，两月共半边。","上有可耕之田，下有长流之川。","一家有六口，两口不团圆。"]},{"t":"用前韵戏赠叶致远直讲","f":"五言古诗","c":["叶侯越著姓，胄出实楚叶。","缙云虽穷远，冠盖传累叶。","心大有所潜，肩高未尝胁。","飘飘凌云意，强禦莫能慑。","辟雍海环流，用汝作舟楫。","开胸出妙义，可发矇起魇。","词如太阿锋，谁敢触其铗。","听之心凛然，难者口因嗋。","抟飞欲峨峨，锻堕今跕跕。","忘情塞上马，适志梦中蝶。","若金静无求，在冶惟所挟。","载醪但彼惑，馈浆非我谍。","经纶安所施，有寓聊自惬。","棋经看在手，棋诀传满箧。","坐寻棋势打，侧写棋图贴。","携持山林屐，刺擿沟港艓。","一枰尝自副，当热宁忘箑。","反嗤褦襶子，但守一经笈。","亡羊等残生，朽筴何足摺。","欢然值手敌，便与对匕筴。","纵横子堕局，腷膊声出堞。","樵父弛远担，牧奴停晏馌。","旁观各技痒，窃议儿女嗫。","所矜在得丧，闻此更心惵。","熟视笼两手，徐思撚长鬣。","微吟静愔愔，坚坐高帖帖。","未快岩谷叟，斧柯尝烂浥。","趋边耻局缩，穿腹愁危嶪。","或撞关以攻，或觑眼而擪。","或羸行伺击，或猛出追蹑。","垂成忽破坏，中断俄连接。","或外示閒暇，伐事先和燮。","或冒突超越，鼓行令震叠。","或粗见形势，驱除令远蹀。","或开拓疆境，欲并包总摄。","或仅残尺寸，如黑子著靥。","或横溃解散，如尸僵血喋。","或惭如告亡，或喜如献捷。","陷敌未甘虏，报仇方借侠。","讳输宁断头，悔误乃批颊。","终朝已罢精，既夜未交睫。","翻然悟且叹，此何宜劫劫。","孟轲恶妨行，陶侃惩废业。","扬雄有前言，韦曜存往牒。","晋臣抑帝手，捘侯何啻涉。","冶城子争道，拒父乃如辄。","争也实逆德，岂如私斗怯。","艺成况穷苦，此殆天所厌。","如今刘与李，伦等安可躐。","试令取一毫，亦乏寸金镊。","以此待君子，未与回参协。","操具投诸江，道耕而德猎。"]},{"t":"田单","f":"五言古诗","c":["湣王万乘齐，走死区区燕。","田单一即墨，扫敌如风旋。","舞鸟怪不测，腾牛怒无前。","飘飖乐毅去，磊砢功名传。","掘葬与劓降，论乃愧儒先。","深诚可奋士，王蠋岂非贤。"]},{"t":"白云","f":"七言律诗","c":["英英白云浮在天，下无根蒂旁无连。","西风来吹欲消散，落日起望心悠然。","愿回羲和借光景，常使秀色当檐边。","时来不道能为雨，直以无心最可怜。"]},{"t":"白日不照物","f":"五言古诗","c":["白日不照物，浮云在寥廓。","风涛吹黄昏，屋瓦更纷泊。","行观蔡河上，负土私力弱。","隋堤散万家，乱若春蚕箔。","仍闻决数道，且用宽城郭。","妇子夜号呼，西南漫为壑。"]},{"t":"白沟行","f":"七言律诗","c":["白沟河边蕃塞地，送迎蕃使年年事。","蕃使常来射狐兔，汉兵不道传烽燧。","万里锄耰接塞垣，幽燕桑叶暗川原。","棘门灞上徒儿戏，李牧廉颇莫更论。"]},{"t":"白纻山","f":"五言古诗","c":["白纻众山顶，江湖所萦带。","浮云卷晴明，可见九州外。","肩舆上寒空，置酒故人会。","峰峦张锦绣，草木吹竽籁。","登临信地险，俯仰知天大。","留欢薄日晚，起视飞鸟背。","残年苦局束，往事嗟摧坏。","歌舞不可求，桓公井空在。"]},{"t":"白鸥","f":"五言古诗","c":["江鸥好羽毛，玉雪无尘垢。","灭没波浪间，生涯亦何有。","雄雌屡惊矫，机弋常纷纠。","顾我独无心，相随如得友。","飘然纷华地，此物乖隔久。","白发望东南，春江绿如酒。"]},{"t":"石竹花","f":"七言绝句","c":["春归幽谷始成丛，地面芬敷浅浅红。","车马不临谁见赏，可怜亦解度春风。"]},{"t":"示元度","f":"五言古诗","c":["今年钟山南，随分作园囿。","凿池搆吾庐，碧水寒可漱。","沟西雇丁壮，担土为培塿。","扶疏三百株，莳梀最高茂。","不求鹓雏实，但取易成就。","中空一丈地，斩木令结搆。","五楸东都来，斸以绕檐溜。","老来厌世语，深卧塞门窦。","赎鱼与之游，喂鸟见如旧。","独当邀之子，商略终宇宙。","更待春日长，黄鹂弄清昼。"]},{"t":"示平甫弟","f":"七言古诗","c":["汴渠西受昆崙水，五月奔湍射黄矢。","高淮夜入忽倒流，埼岸相看欲生嘴。","万樯如山矻不动，嗟我仲子行亦止。","自闻留连且一月，每得问讯犹千里。","老工取河天上落，伏砾邅沙卷无底。","土桥立马望城东，数日知有相逢喜。","墙隅返照媚槐谷，池面过雨苏篁苇。","欣然把手相与闲，所愿此时无一诡。","岂无他忧能老我，付与天地从今始。","闭门为谢载酒人，外慕纷纷吾已矣。"]},{"t":"示安大师","f":"七言律诗","c":["道人深北山为家，宴坐白露眠苍霞。","手扶棁杖虽老矣，走险尚可追麇麚。","踞堂俯视何所有，窈窕樛木垂榠楂。","深寻石路仍有栗，持以馈我因烹茶。"]},{"t":"示宝觉","f":"五言律诗","c":["宿雨转歊烦，朝云拥清迥。","萧萧碧柳软，脉脉红蕖靓。","默卧如有怀，荒乘岂无兴。","幽人适过我，共取墙阴径。"]},{"t":"示蔡天启三首 其二","f":"词","c":["蔡子勇成癖，剑可万人敌。","读书百纸过，颖锐物不隔。","开口取将相，志气方自得。","偪仄何偪仄，未见有一获。","萧条两翅蓬蒿下，未能生彼升天翼。","焉能学堂上燕，绚练新羽翮。"]},{"t":"示蔡天启三首 其一","f":"五言律诗","c":["蔡子勇成癖，能骑生马驹。","铦锋瑩鸊鹈，价重百砗磲。","脱身事幽讨，禅龛只晏如。","划然变轩昂，慎勿学哥舒。"]},{"t":"示德逢","f":"词","c":["先生贫敝古人风，?想柴桑在眼中。","怜悯鸡豚非孟子，勤劳禾黍信周公。","深藏组丽三千牍，静占宽闲五百弓。","处世但令心自可，相知何藉一刘龚。"]},{"t":"仲明父不至","f":"五言律诗","c":["月出映沟坻，烟升隐墟落。","寒鱼占窟聚，暝鸟投枝泊。","亭皋闭晚市，陇首归新穫。","伫子终不来，青灯耿林壑。"]},{"t":"仲明父至宿明日遂行","f":"五言古诗","c":["初登张公门，公子始冠帻。","于今见公子，与我偕鬓白。","山林坐语笑，宛我在公侧。","岂惟貌如之，侃侃有公德。","忆公营濑乡，许我归作客。","我归公既逝，惆怅难再得。","得子如得公，交怀我忻戚。","漂摇将安往，税驾止一昔。","寤言且勿寐，庶以永今夕。","何时复能还，裹饭冶城宅。"]},{"t":"休假大佛寺","f":"五言古诗","c":["罢惫得休假，衣冠倦趋翔。","挟书聊自娱，解带寺东廊。","六龙高徘徊，光景在我裳。","冬屋稍暄暖，病身更强梁。","从我有不思，舍我有不忘。","问谁可与言，携手此徜徉。","婉婉吾所爱，新居乃邻墙。","寄声能来游，维用写愁肠。"]},{"t":"众人","f":"七言律诗","c":["众人纷纷何足竞，是非吾喜非吾病。","颂声交作莽岂贤，四国流言旦犹圣。","唯圣人能轻重人，不能铢两为千钧。","乃知轻重不在彼，要之美恶由吾身。"]},{"t":"光宅寺","f":"七言律诗","c":["翛然光宅淮之阴，扶舆独来止中林。","千秋钟梵已变响，十亩桑竹空成阴。","昔人倨堂有妙理，高座翳绕天花深。","红葵紫苋复满眼，往事无迹难追寻。"]},{"t":"再用前韵寄蔡天启","f":"五言古诗","c":["蔡侯东方来，取友无所挟。","翛翛一囊衣，偶以一书笈。","定林朝自炊，有匕或无筴。","时时羹藜藿，镬大苦难燮。","骄顽遂敢侮，有甚观骈胁。","澹然山谷中，变色未尝辄。","始见类欺魄，寒暄粗酬接。","从容与之语，烂漫无不涉。","奇经可治疾，秘祝可解魇。","巫医之所知，瞽史之所业。","载车必百两，独以方寸摄。","微言归易悟，疾若髭赴镊。","天机信卓越，学等何足躐。","纵谈及既往，每与唐许协。","扬雄尚汉儒，韩愈真秦侠。","好大人谓狂，知微乃如谍。","惟初造文字，人惑鬼愁慑。","秦愚既改罪，新眊仍易叠。","六书遂失指，隶草矜敏捷。","谁珍坛山刻，共赏兰亭帖。","东京一祭酒，收拾偶予惬。","少尝妄思索，老懒因退怯。","侯方习篆籀，寸管静尝擪。","深原道德意，助我耕且猎。","昔功恐唐捐，异味今得馌。","京口媚学子，追师尝劫劫。","陆赢淮汴粮，水僦湖海艓。","远求而近遗，如目不见睫。","伪凤易悦楚，真龙反惊叶。","闻予再三叹，往往心不厌。","或自逸而走，或呿而不嗋。","或嗤元郎漫，或訾白翁嗫。","铄金徒欲消，韫玉岂愁浥。","贤愚有定分，咄汝无喋喋。","跨鞍随我游，曳屣联我跕。","照泉挹清泚，跂石缘嵬嶪。","东陂数鯈鱼，西崦追蛱蝶。","翳林窥抟黍，藉草听批颊。","黄寻远莲须，红阅邻杏靥。","荏苒光景流，杨园忽无叶。","扶痾归未久，吾见喜宁帖。","褰裳告我去，禄仕当随牒。","萧晨秣款段，归骑得追蹑。","谓言循东路，复出西城堞。","行矣忍羁旅，无鱼勿弹铗。","天闲久索骥，骏足方腾蹀。","长驱勿骄矜，小踠亦勿惵。","鹏飞九万里，勿借风一箑。","溟波浩难穷，勉自养鳞鬣。","爵禄实天械，功名为接摺。","宁能复与我，摇漾秦淮楫。","附书勿辞频，隔岁期满箧。"]},{"t":"再次前韵寄杨德逢","f":"五言古诗","c":["一雨洗炎蒸，旷然心志适。","如输浮幢海，灭火十八隔。","俯观风水涌，仰视电云坼。","知公开霁后，过我言不食。","翻愁陂路长，泥淖困臧获。","明明吾有怀，如日照东壁。","莫逢田父归，倚杖问消息。","渠来那得度，南荡今已白。"]},{"t":"冲卿席上得作字","f":"五言古诗","c":["咨予乏时才，始愿乃丘壑。","强走十五年，朱颜已非昨。","低回大梁下，屡叹风沙恶。","所欣同舍郎，诱我文义博。","古声无慆淫，真味有淡泊。","追攀风月久，貌简非心略。","君恩忽推徙，所望颇乖错。","尚怜得经过，未比参辰各。","留连惜馀景，从子至日落。","明灯照亲友，环坐倾杯杓。","别离宽后悲，笑语尽今乐。","论诗知不如，兴至亦同作。"]},{"t":"同王浚贤良赋龟得升字","f":"词","c":["世传一尾龟百龄，此龟逮见隋唐兴。","虽然天幸免焦灼，想屡缩颈愁严凝。","前年赴海不量力，欲替鳌负三崚嶒。","番禺使君邂逅见，知困簸荡因嗟矜。","疾呼余且设网取，以组系首?穿绳。","北归与俱度大庾，两夫赑屃苦不胜。","舣船秦淮担送我，云此一可当十朋。","昔人宝龟谓神物，奉事槁骨尤兢兢。","残民灭国递争夺，有此乃敢司黎烝。","于时睹甲别贵贱，太卜藏法传昆仍。","岂如元君须见梦，初知欢喜得未曾。","自从九江罢纳锡，众渔贱弃秋不登。","卜人官废亦已久，果猎谁复知殊称。","今君此宝世莫识，我亦坐视心瞢瞢。","支床才堪比瓦砾，当粟孰肯捐斗升。","糁头腥臊何足嗜，曳尾污秽适可憎。","盛溲除聋岂必验，蹈背出险安敢凭。","刳肠以占幸无事，卷壳而食病未能。","如闻翕息可视效，乃往有堕崖千层。","仰窥朝阳俯引气，亦得难老如冈陵。","谅能学此真寿类，世论妄以虫疑冰。","嗟余老矣倦呼吸，起晏光景难瞻承。","但知故人所玩惜，每戒异物相侵陵。","唯忧盗贼今好卜，夜半劫请无威惩。","复恐嚵夫负之走，并窃老木为薪蒸。","浅樊荒圃不可保，守视且寄钟山僧。"]},{"t":"同杜史君饮城南","f":"五言古诗","c":["山公游何处，白马鸣翩翩。","檀栾十亩碧，五月浮寒烟。","留客听其间，风吹江海县。","出樽不见日，竹外空青天。","焚蜡助月出，酒光发金船。","狂客惜不去，醉翁舞回旋。","何必吹箫人，玉枝自婵娟。","归路借红烛，雨星低马前。"]},{"t":"同沈道源游八功德水","f":"五言律诗","c":["寒云静如痴，寒日惨如戚。","解鞍寒山中，共坐寒水侧。","新甘出短绠，一酌烦可涤。","仰攀青青枝，木醴何所直。"]},{"t":"同昌叔赋雁奴","f":"五言古诗","c":["雁雁无定栖，随阳以南北。","嗟哉此为奴，至性能恳恻。","人将伺其殆，奴辄告之亟。","举群寤而飞，机巧无所得。","夜或以火取，奴鸣火因匿。","频惊莫我捕，顾谓奴不直。","嗷嗷身百忧，泯泯众一息。","相随入矰缴，岂不听者惑。","偷安与受绐，自古有亡国。","君看雁奴篇，祸福甚明白。"]},{"t":"后元丰行","f":"词","c":["歌元丰，十日五日一雨风。","麦行千里不见土，连山没云皆种黍。","水秧绵绵复多稌，龙骨长乾挂梁梠。","鲥鱼出网蔽洲渚，荻笋肥甘胜牛乳。","百钱可得酒斗许，虽非社日长闻鼓。","吴儿蹋歌女起舞，但道快乐无所苦。","老翁堑水西南流，杨柳中间杙小舟。","乘兴攲眠过白下，逢人欢笑得无愁。"]},{"t":"如归亭顺风","f":"七言律诗","c":["春江窈窈来无地，飞帆浩浩穷天际。","朝出吴川夕霅溪，回首乔林吹岸荠。","柁师高卧自啸歌，戏彼挽舟行复止。","人生万事反衍多，道路后先能几何。"]},{"t":"孙君挽辞","f":"五言律诗","c":["丧车上新垄，哀挽转空山。","名与碑长在，魂随帛暂还。","无儿漫黄卷，有母亦朱颜。","俛仰平生事，相看一梦间。"]},{"t":"扬雄二首 其二","f":"七言律诗","c":["子云平生人莫知，知者乃独称其辞。","今尊子云者皆是，得子云心亦无几。","圣贤树立自有师，人知不知无以为。","俗人贱今常贵古，子云今存谁女数。"]},{"t":"扬雄二首 其一","f":"五言古诗","c":["子云游天禄，华藻锐初学。","覃思晚有得，晦显无适莫。","寥寥邹鲁后，于此归先觉。","岂尝知符命，何苦自投阁。","长安诸愚儒，操行自为薄。","谤嘲出异己，传载因疏略。","孟轲劝伐燕，伊尹干说亳。","叩马触兵锋，食牛要禄爵。","少知羞不为，况彼皆卓荦。","史官蔽多闻，自古喜穿凿。"]},{"t":"收盐","f":"七言古诗","c":["州家飞符来比栉，海中收盐今复密。","穷囚破屋正嗟欷，吏兵操舟去复出。","海中诸岛古不毛，岛夷为生今独劳。","不煎海水饿死耳，谁肯坐守无亡逃。","尔来贼盗往往有，劫杀贾客沈其艘。","一民之生重天下，君子忍与争秋毫。"]},{"t":"有感","f":"五言古诗","c":["忆昔与胡子，戏娱西城幽。","放斥仆与马，独身步田畴。","牛竖歌我旁，听之为久留。","一接田父语，叹之胜王侯。","追逐恨不恣，暮归辄怀愁。","顾常轻千乘，只愿足一丘。","子时怪我少，好此寂寞游。","笙簧不入耳，又不甘醪羞。","那知抱孤伤，罢顿不能遒。","世味已鲜少，但馀野心稠。","乖离今十年，班发满我头。","昔兴亦略尽，食眠常百忧。","每逢佳山水，欲往辄复休。","方壮遂如此，况乃高春秋。"]},{"t":"杂咏八首 其六","f":"五言律诗","c":["关雎后之淑，棫朴王之明。","兔罝尚好德，况乃公与卿。","所以彼行苇，敦然遂其生。","谁能弦且歌，为我发古声。"]},{"t":"杂咏八首 其五","f":"五言律诗","c":["黄雀死弹丸，厥罪在啄粟。","翠鹄不近人，何为亦穷辱。","材为世所利，高下同僵仆。","能逃天地间，蠛蠓无不足。"]},{"t":"杂咏八首 其四","f":"五言律诗","c":["羔豚窘虎豹，鸠雀穷鹰鹯。","巧者具机弋，鸷猛还拘挛。","论功莫如神，论大莫如天。","悲哉区区人，乃欲逃其间。"]},{"t":"杂咏八首 其三","f":"五言律诗","c":["古风致逊悌，班白见尊优。","薄俗谬为恭，独在势权尤。","伏波迷俯仰，爱礼坐成仇。","龂龂洙泗间，岂是老者羞。"]},{"t":"杂咏八首 其二","f":"五言律诗","c":["神龙豢可致，猛虎扰亦留。","变生父子间，上圣不能谋。","常情在欲得，义养或成仇。","他人恩更轻，患祸信难周。"]},{"t":"杂咏八首 其一","f":"五言古诗","c":["万物余一体，九州余一家。","秋毫不为小，徼外不为遐。","不识寿与夭，不知贫与赊。","忘心乃得道，道不去纷华。","近迹以观之，尧舜亦泥沙。","庄周谓如此，而世以为夸。"]},{"t":"杂咏八首 其七","f":"五言律诗","c":["召公方伯尊，材亦圣人亚。","农时惮烦民，听讼甘棠下。","嗟今千室长，已耻问耕稼。","弹琴高堂上，欲以世为化。"]},{"t":"杂咏八首 其八","f":"五言律诗","c":["任公蹲海滨，一钓饱千里。","用力已云多，钩缗亦难理。","巨鱼暖更逃，壮士饥欲死。","游鯈不可数，空满沧浪水。"]},{"t":"杂咏三首 其三","f":"五言律诗","c":["商阳杀三人，每辄不忍视。","亦云食君食，报礼当如此。","波澜吹九州，金石安得止。","永怀南山阿，慷慨中夜起。"]},{"t":"杂咏三首 其二","f":"五言律诗","c":["先生善鼓瑟，齐国好吹竽。","操竽入齐人，雅郑亦复殊。","岂不得禄赐，归卧自欷歔。","寥寥朱丝弦，老矣谁与娱。"]},{"t":"杂咏三首 其一","f":"五言律诗","c":["怀王自堕马，贾傅至死悲。","古人事一职，岂敢苟然为。","哭死非为生，吾心良不欺。","滔滔声利间，绛灌亦何知。"]},{"t":"次御河寄城北会上诸友","f":"七言律诗","c":["客路花时祇搅心，行逢御水半晴阴。","背城野色云边尽，隔屋春声树外深。","香草已堪回步履，午风聊复散衣襟。","忆君载酒相追处，红萼青跗定满林。"]},{"t":"次韵公辟正议书公戏语申之以祝助发一笑","f":"七言律诗","c":["故人辞禄未忘情，语我犹能作捍城。","身不自遭如贡薛，儿应堪教比韦平。","老罴岂得长高卧，雏凤仍闻已閒生。","把盏祝公公莫拒，缁衣心为好贤倾。"]},{"t":"次韵东厅韩侍郎斋居晚兴","f":"七言律诗","c":["斋禁虽严异太常，萧然高卧意何长。","烟含欲暝宫庭紫，日映新秋省闼黄。","壮节易摧行踽踽，华年相背去堂堂。","追攀坐叹风尘隔，空听钧天梦帝乡。"]},{"t":"次韵约之谢惠诗","f":"词","c":["鱼跳桑柳阴，鸟落蒲苇侧。","已无溪姑祠，何有江令宅。","故人耽田里，老脱尚方舄。","开亭捐百金，于此扫尘迹。","地偏人罕至，心远境常寂。","我行西州旋，税驾候颜色。","相随望南山，水际因一息。","公时指岸木，谓此可寻尺。","伐之营中沚，持用自怡怿。","欢言俟其成，邀我堂上食。","百忧每多违，一诺还自惕。","春风檐楹新，坐久膝前席。","翛然忘故约，北郭疑有适。","长淫舒永怀，伫想对以臆。","摛辞甚有理，窃比书石鹢。","知公不欺我，把玩果心恻。","嘉肴既夙设，丽藻仍虚掷。","左车公自迎，右券吾敢责。","闻说芼羹臛，芬香出邻壁。","妇休机杼事，儿失刀椠职。","何胶胶扰扰，而纷纷籍籍。","携持欲一往，继此方如织。","元龙但高眠，司马勿亲涤。","几能孩童旧，握手皆鬓白。","有兴即联?，东阡与南陌。"]},{"t":"次韵吴季野题岳上人澄心亭","f":"七言律诗","c":["高亭五月尚寒生，回首尘沙自郁蒸。","砌水乱流穿石底，槛云高出蔽山层。","跻攀欲绝人间世，缔构知从物外僧。","肠胃坐来清似洗，神奇未怪佛图澄。"]},{"t":"次韵舍弟江上","f":"五言律诗","c":["岸红归欲稠，渚绿合犹晚。","晴沙上屐轻，暖水随帆远。","吹波戏鱼动，掠叶飞禽返。","著意觅幽蹊，桃花误刘阮。"]},{"t":"次韵信都公石枕蕲簟","f":"七言古诗","c":["端溪琢枕绿玉色，蕲水织簟黄金纹。","翰林所宝此两物，笑视金玉如浮云。","都城六月招客语，地上赤日流黄尘。","烛龙中天进无力，客主歊然各疲剧。","形骸直欲坐弃忘，冠带安能强修饰。","恃公宽贷更不疑，箕倨岂复论官职。","笛材平瑩家故藏，砚璞坳清此新得。","扫除堂屋就阴翳，公不自眠分与客。","知公用意每如此，真能与物同其适。","岂比法曹空自私，却愿天日长炎赫。","公才卓牵人所惊，久矣四海流声名。","天方选取欲扶世，岂特使以文章鸣。","深探力取常不寐，思以正议排纵横。","奈何甘心一榻上，欲卧颍尾为洁清。","贤愚劳佚非一轨，顾我病昏惟未死。","心于万事久翛然，身寄一官真偶尔。","便当买宅归偃休，白发溪山如愿始。","看公勠力就太平，却上青天跨箕尾。"]},{"t":"次韵唐彦猷华亭十咏 其四 始皇驰道","f":"五言律诗","c":["穆王得八骏，万事得期修。","茫茫万载间，复此好远游。","车轮与马迹，此地亦尝留。","想当治道时，劳者尸如丘。"]},{"t":"次韵唐彦猷华亭十咏 其一 顾林亭","f":"五言律诗","c":["寥寥湖上亭，不见野王居。","平林岂旧物，岁晚空扶疏。","自古圣贤人，邑国皆丘墟。","不朽在名德，千秋想其馀。"]},{"t":"次韵唐彦猷华亭十咏 其七 华亭谷","f":"五言律诗","c":["巨川非一源，源亦在众流。","此谷乃清浅，松江能覆舟。","虫鱼何所知，上下相沉浮。","徒嗟大盈北，浩浩无春愁。"]},{"t":"次韵唐彦猷华亭十咏 其九 昆山","f":"五言律诗","c":["玉人生此山，山亦传此名。","崖风与穴水，清越有馀声。","悲哉世所珍，一出受攲倾。","不如鹤与猿，栖息尚全生。"]},{"t":"次韵唐彦猷华亭十咏 其二 寒穴","f":"五言律诗","c":["神泉冽冰霜，高穴与云平。","空山渟千秋，不出呜咽声。","山风吹更寒，山月相与清。","北客不到此，如何洗烦酲。"]},{"t":"次韵唐彦猷华亭十咏 其八 陆机宅","f":"五言律诗","c":["故物一已尽，嗟此岁年深。","野桃自著花，荒棘自生针。","芊芊谷水阳，郁郁昆山阴。","俛仰但如昨，游者不可寻。"]},{"t":"次韵唐彦猷华亭十咏 其十 三女岗","f":"五言律诗","c":["自古世上雄，慷慨擅功名。","当时岂有力，能使死者生。","三女共一丘，此憾亦难平。","音容若有作，无力倾人城。"]},{"t":"次韵唐彦猷华亭十咏 其三 吴王猎场","f":"五言律诗","c":["吴王好射虎，但射不操戈。","匹马掠广场，万兵助遮罗。","时平事非昔，此地桑麻多。","猛兽亦已尽，牛羊在田坡。"]},{"t":"次韵唐彦猷华亭十咏 其五 柘湖","f":"五言律诗","c":["柘林著湖山，菱叶蔓湖滨。","秦女亦何事，能为此湖神。","年年赛鸡豚，渔子自知津。","幽妖窟险阻，祸福易欺人。"]},{"t":"次韵唐彦猷华亭十咏 其六 陆瑁养鱼池","f":"五言律诗","c":["野人非昔人，亦复水上居。","纷纷水中游，岂是昔时鱼。","吹波浮还没，竞食糟糠馀。","吞舟不可见，守此岁月除。"]},{"t":"次韵酬昌叔羁旅之作","f":"五言律诗","c":["君方困旅食，予亦误朝簪。","自索东方米，谁多季子金。","高门万马散，穷巷一灯深。","客主竟何事，萧条梁父吟。"]},{"t":"次韵酬微之赠池纸并诗","f":"七言古诗","c":["微之出守秋浦时，椎冰看捣万谷皮。","波工龟手咤今样，鱼网肯数荆州池。","霜纨夺色贾不售，虹玉丧气山无辉。","方船稳载献天子，善价徐取供吾私。","十年零落尚百一，持以赠我随清诗。","君宁久寄金谷地，方执赐笔磨坳螭。","当留此物朝上国，日侍帝侧书新仪。","不然名山副史本，褒拔元凯诛穷奇。","咨予文章非世用，画镂空尔靡冰脂。","挥毫才足记姓字，窃学又耻从师宜。","匆匆点污亦何忍，嘉贶但觉难为辞。","篇终有意责赵璧，穷国恐误连城归。","倾囊倒箧聊一报，安敢坐以秦为雌。"]},{"t":"汝瘿和王仲仪","f":"词","c":["汝水出山险，汝民多病瘿。","或如鸟粻满，或若猿嗛并。","女惭高掩襟，男大阔裁领。","饮水疑注壶，吐词侔有梗。","樗里既已闻，杜预亦不幸。","秦人号智囊，吴瓠挂狗颈。","??常柱颐，伶仃安及胫。","祗欲仰问天，无由俯窥井。","挟带岁月深，冒犯风霜冷。","厌恶虽自知，剖割且谁肯。","不惟羞把镜，仍亦愁吊影。","内疗烦羊靥，外砭废针颖。","在木曰楠榴，刳之可曰皿。","此诚无所用，既有何能屏。","膨脝厕元首，臃肿异胪顶。","难将面目施，可与胞胎逞。","贤哉临汝守，世德调金鼎。","珉俗虽丑乖，教令日修整。","风土恐随改，晨昏忧虑省。","傥欲觐慈颜，名城不难请。"]},{"t":"江","f":"五言律诗","c":["灵源开辟有，赢缩但相随。","逆折山能碍，奔流海与期。","泥沙拆蚌蛤，云南暗蛟螭。","欲问深何许，冯夷秖自知。"]},{"t":"江上","f":"七言律诗","c":["村落家家有浊醪，青旗招客解袛裯。","春风似补林塘破，野水遥连草树高。","寄食舟车随处弊，行歌天地此身劳。","迟回自负平生意，岂是明时惜一毛。"]},{"t":"江东召归","f":"七言绝句","c":["昨日君恩误赐环，归肠一夜绕钟山。","虽然眷恋明时禄，羞见琅邪有邴丹。"]},{"t":"江邻几邀观三馆书画","f":"七言古诗","c":["五月秘府始曝书，一日江君来约予。","世间虽有古画笔，可往共观临石渠。","我时冒热跨马去，开厨发匣鸣锁鱼。","羲献墨迹十一卷，水玉作轴排疏疏。","最奇小楷乐毅论，永和题尾付官奴。","又有四山绝品画，戴嵩吴牛望青芜。","李成寒林树半枯，黄筌工妙白兔图。","不知名姓貌人物，二公对奕旁观俱。","黄金错镂为投壶，粉幛复画一病夫。","后有女子执巾裾，床前红毯平火炉。","床上二姝展氍毹，绕床屏风山有无。","堂上列画三重铺，此幅巧甚意思殊。","孰真孰假丹青摹，世事若此还可吁。"]},{"t":"老人行","f":"七言律诗","c":["老人低心逐年少，年少还为老人调。","两家挟诈自相欺，四海伤真谁复诮。","翻手作云覆手雨，当面输心背面笑。","古来人事已如此，今日何须论久要。"]},{"t":"老树","f":"七言古诗","c":["去年北风吹瓦裂，墙头老树冻欲折。","苍叶蔽屈忽扶疏，野禽从此相与居。","禽鸣无时不可数，雌雄各自应律吕。","我床拨书当午眠，能惊我眠聒我语。","古诗鸟鸣山更幽，我念不若鸣声收。","但忧此物一朝去，狂风还来欺老树。"]},{"t":"老景","f":"五言律诗","c":["老景春可惜，无花可留得。","绕屋褚先生，萧萧何所直。","每嫌柳浑青，追怅李太白。","多谢安石榴，向人红蕊拆。"]},{"t":"自白门归望定林有寄","f":"五言律诗","c":["蹇驴愁石路，余亦倦跻攀。","不见道人久，忽然芳岁残。","朝随云暂出，暮与鸟争还。","杳杳青松壑，知公在两间。"]},{"t":"自讼","f":"五言古诗","c":["孔子见南子，子路为不怡。","欲从公山氏，勃郁见色辞。","道如天之苍，万物不能缁。","弟子尚不信，况余乏才资。","明知古人仁，语默各有时。","苟出不自慎，果为听者疑。","白圭尚有磨，驷马犹能追。","一言成不智，虽悔欲何为。"]},{"t":"自喻","f":"五言律诗","c":["岸凉竹娟娟，水净菱帖帖。","虾摇浮游须，鱼鼓嬉戏鬣。","释杖聊一愒，褰裳如可涉。","自喻适志欤，翩然梦中蝶。"]},{"t":"自舒州追送朱氏女弟憩独山馆宿木瘤僧舍明日度长安岭至皖口","f":"五言古诗","c":["晨霜践河梁，落日憩亭皋。","念彼千里行，恻恻我心劳。","揽辔上层冈，下临百仞濠。","寒流咽欲绝，鱼鳖久已逃。","暮行苦邅回，细路隐蓬蒿。","惊麇出马前，鸟骇亡其曹。","投僧避夜雨，古檠昏无膏。","山木鸣四壁，疑身在波涛。","平明长安岭，飞雪忽满袍。","天低浮云深，更觉所向高。"]},{"t":"自遣","f":"五言绝句","c":["闭户欲推愁，愁终不肯去。","底事春风来，留愁愁不住。"]},{"t":"舟还江南阻风有怀伯兄","f":"七言律诗","c":["几时重接汝南评，两桨留连不计程。","白浪黏天无限断，玄云垂野少晴明。","平皋望望欲何向，薄宦嗟嗟空此行。","会有开樽相劝日，鹡鸰随处共飞鸣。"]},{"t":"西山","f":"七言绝句","c":["西山映水碧潭潭，楚老长谣泪满衫。","但道使君留不得，那知肯更忆江南。"]},{"t":"西风","f":"五言古诗","c":["少年不知秋，喜闻西风生。","老大多感伤，畏此蟋蟀鸣。","况乃舍亲友，抱病独远行。","中夜卧不周，恻恻感我情。","起视天正黑，弱云乱纵横。","似有霰雪飘，不复星斗明。","时节忽如此，重令壮心惊。","谅无同忧人，樽酒安可倾。"]},{"t":"西帅","f":"七言律诗","c":["吾君英睿超光武，良将西征捍隗嚣。","誓斩郅支聊出塞，生擒颉利始归朝。","一丸岂虑封函谷，千骑无由饮渭桥。","好立功名标竹素，莫教空说霍嫖姚。"]},{"t":"观王氏雪图","f":"七言绝句","c":["崔嵬相映雪重重，茅屋柴门在半峰。","想有幽人遗世事，独临青峭倚长松。"]},{"t":"过刘贡甫","f":"七言古诗","c":["去年约子游山陂，今者仍为大梁客。","天旋日月不少留，称意人閒宁易得。","天明径欲相就语，云雪填城万家白。","冬风吹鬣马更骄，一出何由问行迹。","能言奇字世已少，终欲追攀岂辞剧。","枕中鸿宝旧所传，饮我宁辞酒或索。","吾愿与子同醉醒，颜状虽殊心不隔。","故知今有可怜人，回首纷纷斗筲窄。"]},{"t":"过杨德逢庄","f":"五言古诗","c":["携僧出西路，日晏昧所投。","循河望积谷，一饱觉易谋。","稚子举桉出，咄嗟见盘羞。","饭新粳有香，煮菜旨且柔。","暮从秀岩归，秣蹇得少留。","捧腹笑相语，果然无所求。"]},{"t":"过食新城藕","f":"七言古诗","c":["他年过食新城藕，枕藉船中载亲友。","今年却到经行处，独坐昏烟对舞柳。","甘酸向口无所适，牢落盘餐与樽酒。","冰房玉节漫自好，欲御还休涕垂手。","曾参宦学居常近，阳城离别初不久。","人间此愿两未能，西风落日空回首。"]},{"t":"阴山画虎图","f":"七言古诗","c":["阴山健儿鞭鞚急，走势能追北风及。","逶迤一虎出马前，白羽横穿更人立。","回旗倒戟四边动，抽矢当前放蹄入。","爪牙蹭蹬不得施，碛上流丹看来湿。","胡天朔漠杀气高，烟云万里埋弓刀。","穹庐无工可貌此，汉使自解丹青包。","堂上绢素开欲裂，一见犹能动毛发。","低徊使我思古人，此地抟兵走戎羯。","禽逃兽遁亦萧然，岂若封疆今晏眠。","契丹弋猎汉耕作，飞将自老南山边，还能射虎随少年。"]},{"t":"阴漫漫行","f":"七言律诗","c":["愁云怒风相追逐，青山灭没沧江覆。","少留灯火就空床，更听波涛围野屋。","忆昨踏雪度长安，夜宿木瘤还苦寒。","谁云当春便妍暖，十日九八阴漫漫。"]},{"t":"两山间","f":"五言古诗","c":["自予营北渚，数至两山间。","临路爱山好，出山愁路难。","山花如水净，山鸟与云闲。","我欲抛山去，山仍劝我还。","祗应身后冢，亦是眼中山。","且复依山住，归鞍未可攀。"]},{"t":"两马齿俱壮","f":"五言古诗","c":["两马齿俱壮，自骄千里材。","生姿何轩轩，或是龙之媒。","一马立长衢，顾影方徘徊。","一马裂衔辔，奔嘶逸风雷。","立岂饱刍豆，恋栈常思回。","奔岂欲野龁，久羁羡驽骀。","两马不同调，各为世所猜。","问之不能言，使我心悠哉。"]},{"t":"估玉","f":"七言古诗","c":["潼关西山古蓝田，有气郁郁高拄天。","雄虹雌霓相结缠，昼夜不散非云烟。","秦人挟斤上其巅，视气所出深镵镌。","得物盈尺方且坚，以斤试叩声泠然。","持归市上求百钱，人皆疑嗟莫爱怜。","大梁老估闻不眠，操金喜取走蹁跹。","深藏牢包三十年，光怪邻里惊相传，欲献天子无由缘。","朝廷昨日钟鼓县，呼工琢圭寘神筵。","玉材细琐不中权，贾孙抱物诏使前。","红罗复叠帕紫毡，发视绀碧光属联。","诏问与价当几千，众工让口无敢先。","嗟我岂识真与全。"]},{"t":"馀寒","f":"五言古诗","c":["馀寒驾春风，入我征衣裳。","扪鬓只得冻，蔽面尚疑创。","士耳恐犹坠，马毛欲吹僵。","牢持有失箸，疾饮无留汤。","曈曈扶桑日，出有万里光。","可怜当此时，不湿地上霜。","冥冥鸿雁飞，北望去成行。","谁言有百鸟，此鸟知阴阳。","岂时有必至，前识圣所臧。","把酒谢高翰，我知思故乡。"]},{"t":"初晴","f":"七言绝句","c":["一抹明霞黯淡红，瓦沟已见雪花融。","前山未放晓寒散，犹锁白云三两峰。"]},{"t":"别马秘丞","f":"五言古诗","c":["伯夷恶一世，季也皆乡人。","吾尝论夫子，有似季之伦。","人情路万殊，近世颇荆榛。","唯君游其间，坦坦得所循。","意君诚恺悌，慕向从宿昔。","奈何初相欢，鹢首已云北。","莓莓郊原青，漠漠风雨黑。","冠盖满津亭，君今去何适。"]},{"t":"别孙莘老","f":"五言古诗","c":["逢原未熟我，已与子相知。","自吾得逢原，知子更不疑。","把手湖上舟，望子欲归时。","茫然乃分散，独背东南驰。","寥寥西城居，邂逅与子期。","鸡鸣入省门，朱墨来纷披。","含意不自得，强颜聊尔为。","会合常在夜，青灯照书诗。","往往并衾语，至明不言疲。","悤悤舍我去，使我当从谁。","送子不出门，我身方羁縻。","我心得自如，今与子相随。","随子至湖上，逢原所尝嬉。","想见荷叶尽，北风卷寒漪。","已怀今日愁，更念昔日悲。","相逢亦何有，但有镜中丝。"]},{"t":"别谢师宰","f":"七言律诗","c":["阊阖城西地如水，鸡鸣黄尘波浪起。","穷年一马望扶桑，东得省门身辄止。","簿书期会老纷纷，邂逅论心喜有君。","数日未多还舍我，相看愁思乱于云。"]},{"t":"别灊皖二山","f":"七言绝句","c":["乡垒新恩借旧朱，欲辞灊皖更踌蹰。","攒峰列岫应讥我，饱食穷年报礼虚。"]},{"t":"即事三首 其三","f":"五言律诗","c":["日月随天旋，疾迟与天谋。","寒暑自有常，不顾万物求。","蜉蝣蔽朝夕，蟪蛄疑春秋。","眇眇上古历，回环今几周。"]},{"t":"即事三首 其二","f":"五言律诗","c":["昏昏白日卧，皎皎中夜愁。","明月入枕席，凉风动衾帱。","蛬蝉相鸣悲，上下无时休。","徒能感我耳，顾尔安知秋。"]},{"t":"即事三首 其一","f":"五言律诗","c":["我起影亦起，我留影逡巡。","我意不在影，影长随我身。","交游义相好，骨肉情相亲。","如何有乖睽，不得同苦辛。"]},{"t":"君难托","f":"词","c":["槿花朝开暮还坠，妾身与花宁独异。","忆昔相逢俱少年，两情未许谁最先。","感君绸缪逐君去，成君家计良辛苦。","人事反复那能知，谗言入耳须臾离。","嫁时罗衣羞更著，如今始悟君难托。","君难托，妾亦不忘旧时约。"]},{"t":"吴长文新得颜公坏碑","f":"七言古诗","c":["鲁公之书既绝伦，岁久更为时所珍。","荒坛坏冢朽崖屋，剥落风雨埋煨尘。","断碑数尺谁所得，点画入纸完如新。","延陵公子好事者，拓取持寄情相亲。","六书篆籀数变改，训诂后世多失真。","谁初妄凿妍与丑，坐使学士劳骸筋。","堂堂鲁公勇且仁，出遇世难亲经纶。","挥毫卓荦又惊俗，岂亦以此誇常民。","但疑技巧有天得，不必勉强方通神。","诗歌甘棠美召伯，爱惜蔽芾由思人。","时危忠谊常恨少，宝此勿复令埋堙。"]},{"t":"吾心","f":"五言古诗","c":["吾心童稚时，不见一物好。","意言有妙理，独恨知不早。","初闻守善死，颇复吝肝脑。","中稍历艰危，悟身非所保。","犹然谓俗学，有指当穷讨。","晚知童稚心，自足可忘老。"]},{"t":"张氏静居院","f":"五言古诗","c":["动者利进为，静者乐止居。","物性有偏得，惟贤时卷舒。","张侯始出仕，所至多名誉。","老矣归偃休，买地斸荒芜。","屋成为令名，名实与时俱。","南堂栖幽真，晨起瞻像图。","北堂画五禽，游戏养形躯。","燕有诸宾庭，学有诸子庐。","问侯年几何，矫矫八十馀。","问侯何能尔，心不藏忧愉。","问侯客何为，弦歌饮投壶。","问侯儿何读，夏商及唐虞。","嵩山填门户，洛水绕阶除。","侯于山水间，结驷有通衢。","我念老退者，古多贤大夫。","留侯亦养生，乃欲凌空虚。","闭门不饮酒，岂异山中臞。","疏傅稍喜客，挥金能自娱。","不闻喜教子，满屋青紫朱。","张侯能兼取，胜事古所无。","褒称有乐石，丞相为之书。","而我不自量，闻风亦歌呼。"]},{"t":"张良","f":"七言古诗","c":["留侯美好如妇人，五世相韩韩入秦。","倾家为主合壮士，博浪沙中击秦帝。","脱身下邳世不知，举国大索何能为。","素书一卷天与之，谷城黄石非吾师。","固陵解鞍聊出口，捕取项羽如婴儿。","从来四皓招不得，为我立弃商山芝。","洛阳贾谊才能薄，扰扰空令绛灌疑。"]},{"t":"怀元度四首 其四","f":"五言律诗","c":["自君之出矣，何其挂怀抱。","孤坐屡穷辰，山林迹如扫。","数枝石榴发，岂无一时好。","不可持寄君，思君令人老。"]},{"t":"我所思寄黄吉甫","f":"楚辞体","c":["我所思兮在彭蠡，一奁寒晶径千里。","天低绀滑风静止，月澹星渟尤可喜。","亦复可怜波浪起，琉璃崩嵌涌颠累。","万斛之舟簸一苇，超邑越都如历指。","岸沙雪积山云委，云半飞泉挂龙尾。","跳空散作平地水，牛乳芳甘那得比。","萝茑冥冥荫演迤，稍上寻源出奇诡。","像图释迦祠老子，台殿晻霭相重累。","石槽环除逗清泚，松竹静深无虎虺。","其徒翛然弃尘滓，虽未应真终适己。","黄侯可与谈妙理，视弃荣宦犹弊屣。","每采紫芝求石髓，我欲从之倦游徙。","谷城公孙能若此，五老闻之当启齿。","寄声五老吾念尔，相见无时老将死。"]},{"t":"我欲往沧海","f":"五言古诗","c":["我欲往沧海，客来自河源。","手探囊中胶，救此千载浑。","我语客徒尔，当还治昆崙。","叹息谢不能，相看涕翻盆。","客止我且往，濯发扶桑根。","春风吹我舟，万里空目存。"]},{"t":"拟和御制赏花钓鱼","f":"五言古诗","c":["云暖蓬莱日，风酣太液春。","水光承步辇，花气入钩陈。","伏槛留清跸，传觞属从臣。","霏香连钓饵，落叶乱游鳞。","镐饮恩知厚，衢樽赐愿均。","更看追夏谚，先此咏逢辰。"]},{"t":"拟寒山拾得二十首 其二十","f":"五言律诗","c":["利瞋汝刀山，浊爱汝灰河。","汝痴分别心，即汝琰魔罗。","圆成但一性，一切法依他。","遍了一切法，不如且头陀。"]},{"t":"拟寒山拾得二十首 其十九","f":"五言律诗","c":["勇有孟施舍，能无惧而已。","若人学佛法，勇亦当如此。","休来讲下坐，莫入禅门里。","但能一切舍，管取佛欢喜。"]},{"t":"拟寒山拾得二十首 其十八","f":"五言律诗","c":["汝无名高者，以见利贪叨。","汝无行实者，以取著名高。","行实尚非实，利名岂坚牢。","一朝投土窟，魂魄散逃逃。"]},{"t":"拟寒山拾得二十首 其十七","f":"五言律诗","c":["有一种贫儿，不能自营生。","若不作客走，即须随贼行。","复有一种贫，常时腹彭亨。","若有亦不畜，若无亦不营。"]},{"t":"拟寒山拾得二十首 其十六","f":"五言律诗","c":["打贼贼恐怖，看客客喜欢。","亦有客是贼，切莫受伊谩。","乐哉贫儿家，无事役心肝。","既无贼可打，岂有客须看。"]},{"t":"拟寒山拾得二十首 其十五","f":"五言律诗","c":["失志难作福，得势易造罪。","苦即念快乐，乐即生贪爱。","无苦亦无乐，无明亦无昧。","不属三界中，亦非三界外。"]},{"t":"拟寒山拾得二十首 其十四","f":"五言古诗","c":["莫嫌张三恶，莫爱李四好。","既往念即晚，未来思又早。","见之亦何有，欻然如电扫。","恶既是磨灭，好亦难长保。","若令好与恶，可积如财宝。","自始而至今，有几许烦恼。"]},{"t":"拟寒山拾得二十首 其十三","f":"五言律诗","c":["众生若有我，我何能度脱。","众生若无我，已死应不活。","众生不了此，便听佛与夺。","我无我不二，四天王献钵。"]},{"t":"拟寒山拾得二十首 其十二","f":"五言律诗","c":["李生坦荡荡，所见实奇哉。","问渠前世事，答我烧炭来。","炭成能然火，火过却成灰。","灰成即是土，随意立根栽。"]},{"t":"拟寒山拾得二十首 其九","f":"五言律诗","c":["有一即有二，有三即有四。","一二三四五，有亦何妨事。","如火能烧手，要须方便智。","若未解传薪，何须学钻燧。"]},{"t":"拟寒山拾得二十首 其六","f":"五言古诗","c":["人人有这个，这个没量大。","坐也坐不定，走也跳不过。","锯也解不断，锤也打不破。","作马便搭鞍，作牛便推磨。","若问无眼人，这个是甚么。","便遭伊缠绕，鬼窟里忍饿。"]},{"t":"拟寒山拾得二十首 其五","f":"五言律诗","c":["若言梦是空，觉后应无记。","若言梦非空，应有真实事。","燔烧阳自招，沈溺阴自致。","令汝尝惊魇，岂知安稳睡。"]},{"t":"拟寒山拾得二十首 其四","f":"五言古诗","c":["风吹瓦堕屋，正打破我头。","瓦亦自破碎，岂但我血流。","我终不嗔渠，此瓦不自由。","众生造众恶，亦有一机抽。","渠不知此机，故自认愆尤。","此但可哀怜，劝令真正脩。","岂可自迷闷，与渠作冤雠。"]},{"t":"拟寒山拾得二十首 其三","f":"五言古诗","c":["凡夫当梦时，眼见种种色。","此非作故有，亦非求故获。","不知今是梦，道我能畜积。","贪求复守护，尝怕水火贼。","既觉方自悟，本空无所得。","死生如觉梦，此理甚明白。"]},{"t":"拟寒山拾得二十首 其二","f":"五言古诗","c":["我曾为牛马，见草豆欢喜。","又曾为女人，欢喜见男子。","我若真是我，祗合长如此。","若好恶不定，应知为物使。","堂堂大丈夫，莫认物为己。"]},{"t":"拟寒山拾得二十首 其一","f":"五言律诗","c":["牛若不穿鼻，岂肯推人磨。","马若不络头，随宜而起卧。","乾地终不涴，平地终不堕。","扰扰受轮回，祗缘疑这个。"]},{"t":"拟寒山拾得二十首 其七","f":"五言律诗","c":["我读万卷书，识尽天下理。","智者渠自知，愚者谁信尔。","奇哉闲道人，跳出三句里。","独悟自根本，不从他处起。"]},{"t":"拟寒山拾得二十首 其十","f":"五言律诗","c":["昨日见张三，嫌他不守己。","归来自悔责，分别亦非理。","今日见张三，分别心复起。","若除此恶习，佛法无多子。"]},{"t":"拟寒山拾得二十首 其十一","f":"五言律诗","c":["傀儡祗一机，种种没根栽。","被我入棚中，昨日亲看来。","方知棚外人，扰扰一场呆。","终日受伊谩，更被索钱财。"]},{"t":"李氏沅江书堂","f":"七言律诗","c":["沅江水有梁与罾，沅田树桑可蚕耕。","君于其间耻射利，独岸清泚留朱甍。","诗书当前日开阖，冠带满坐相逢迎。","勉求高论出施设，无以私智为公卿。"]},{"t":"李花","f":"七言绝句","c":["朝摘桃花红破萼，莫摘李花繁满枝。","客心浩荡东风急，把酒看花能几时。"]},{"t":"杏花","f":"五言律诗","c":["石梁度空旷，茅屋临清炯。","俯窥娇饶杏，未觉身胜影。","嫣如景阳妃，含笑堕宫井。","怊怅有微波，残妆坏难整。"]},{"t":"杜甫画像","f":"词","c":["吾观少陵诗，为与元气侔。","力能排天斡九地，壮颜毅色不可求。","浩荡八极中，生物岂不稠。","丑妍巨细千万殊，竟莫见以何雕锼。","惜哉命之穷，颠倒不见收。","青衫老更斥，饿走半九州。","瘦妻僵前子仆后，攘攘盗贼森戈矛。","吟哦当此时，不废朝廷忧。","常愿天子圣，大臣各伊周。","宁令吾庐独破受冻死，不忍四海寒飕飕。","伤屯悼屈止一身，嗟时之人死所羞。","所以见公像，再拜涕泗流。","惟公之心古亦少，愿起公死从之游。"]},{"t":"杨刘","f":"五言古诗","c":["人各有是非，犯时为患害。","唯诗以谲谏，言者得无悔。","汾王昔监谤，变雅今尚载。","末俗忌讳繁，此理宁复在。","南山咏种豆，议法过四罪。","玄都戏桃花，母子受颠沛。","疑似已如此，况欲谆谆诲。","事变故不同，杨刘可为戒。"]},{"t":"求全","f":"五言律诗","c":["求全伤德义，欲速累功名。","玉要藏而待，苗非揠故生。","未妨徐出昼，何苦急堕成。","此道今亡矣，嗟谁可与明。"]},{"t":"汴水","f":"七言律诗","c":["汴水无情日夜流，不肯为我少淹留。","相逢故人昨夜去，不知今日到何州。","州州人物不相似，处处蝉鸣令客愁。","可怜南北意不就，二十起家今白头。"]},{"t":"灵山寺","f":"五言古诗","c":["灵山名谁自，波涛截孤峰。","何年佛子住，四面凭危空。","折椽与裂瓦，委弃填西东。","库廊行抑首，居者莽谁容。","吾舟维其侧，落日生秋风。","瞰崖聊寄目，万物极纤秾。","震荡江海思，洗涤堙郁中。","胡为嬉游人，过此无留踪。","景岂龙游殊，盛衰浩无穷。","吾闻世所好，楼殿浮青红。","那知山水乐，岂在豪华宫。","世好□变尔，感激难为工。"]},{"t":"秃山","f":"五言古诗","c":["吏役沧海上，瞻山一停舟。","怪此秃谁使，乡人语其由。","一狙山上鸣，一狙从之游。","相匹乃生子，子众孙还稠。","山中草木盛，根实始易求。","攀挽上极高，屈曲亦穷幽。","众狙各丰肥，山乃尽侵牟。","攘争取一饱，岂暇议藏收。","大狙尚自苦，小狙亦已愁。","稍稍受咋啮，一毛不得留。","狙虽巧过人，不善操锄耰。","所嗜在果谷，得之常似偷。","嗟此海山中，四顾无所投。","生生未云已，岁晚将安谋。"]},{"t":"纯甫出释惠崇画要予作诗","f":"七言古诗","c":["画史纷纷何足数，惠崇晚出吾最许。","旱云六月涨林莽，移我翛然堕洲渚。","黄芦低摧雪翳土，凫雁静立将俦侣。","往时所历今在眼，沙平水澹西江浦。","暮气沈舟暗鱼罟，攲眠呕轧如闻橹。","颇疑道人三昧力，异域山川能断取。","方诸承水调幻药，洒落生绡变寒暑。","金坡巨然山数堵，粉墨空多真漫与。","大梁崔白亦善画，曾见桃花净初吐。","酒酣弄笔起春风，便恐漂零作红雨。","流莺探枝婉欲语，蜜蜂掇蕊随翅股。","一时二子皆绝艺，裘马穿羸久羁旅。","华堂岂惜万黄金，苦道今人不如古。"]},{"t":"迟明","f":"五言律诗","c":["攲枕浩无情，蘧蘧独迟明。","霜繁红树老，云澹素蟾清。","倦鹊犹三匝，寒鸡未一鸣。","故山何处所，应有晓猿惊。"]},{"t":"陆忠州","f":"五言律诗","c":["虞人以士招，御者与射比。","当时尚羞为，况乃天下士。","英英陆忠州，学问辅明智。","低徊得坎坷，勋业终不遂。"]},{"t":"陈桥","f":"七言律诗","c":["走马黄昏渡河水，夜争归路春风里。","指点韦城太白高，投鞭日午陈桥市。","杨柳初回陌上尘，烟脂洗出杏花匀。","纷纷塞路堪追惜，失却新年一半春。"]},{"t":"饭祈泽寺","f":"五言古诗","c":["驾言东南游，午饭投僧馆。","山白梅蕊长，林黄柳芽短。","笭箵沙际来，略彴桑閒断。","春映一川明，雪消千壑漫。","鱼随竹影浮，鸟误人声散。","玩物岂能留，干时吾自懒。"]},{"t":"饮裴侯家","f":"七言古诗","c":["裴侯饮我日向中，四坐宾客颜皆红。","扫除高馆邀我入，自出粜麦怜民穷。","天边眼力破万里，桑麻冥冥山四起。","野心探寻殊未已，更欲湔衣北城水。","忽见碧树樱桃悬，下马恣食不论钱。","赤星磊落入我眼，恐是半醉游青天。","裴侯方坐尘沙里，役身救物当如此。","我曹偶脱簿领閒，何忍爱惜一日闲。","且归拂席饱眠睡，明日更看滁南山。"]},{"t":"到郡与同官饮","f":"七言律诗","c":["泻碧沄沄横带郭，浮苍霭霭遥连阁。","草木犹疑夏郁葱，风云已见秋萧索。","荒歌野舞同醉醒，水果山肴互酬酢。","自嫌多病少欢颜，独负嘉宾此时乐。"]},{"t":"叔孙通","f":"五言古诗","c":["先生秦博士，秦礼颇能熟。","量主欲有为，两生皆不欲。","草具一王仪，群豪果知肃。","黄金既遍赐，短衣亦已续。","儒术自此凋，何为反初服。"]},{"t":"和中甫兄春日有感","f":"七言古诗","c":["雪释沙轻马蹄疾，北城可游今暇日。","溅溅溪谷水乱流，漠漠郊原草争出。","娇梅过雨吹烂熳，幽鸟迎阳语啾唧。","分香欲满锦树园，剪綵休开宝刀室。","胡为我辈坐自苦，不念兹时去如失。","饱闻高径动车轮，甘卧空堂守经帙。","淮蝗蔽天农久饿，越卒围城盗少逸。","至尊深拱罢箫韶，元老相看进刀笔。","春风生物尚有意，壮士忧民岂无术。","不成欢醉但悲歌，回首功名古难必。"]},{"t":"和王乐道烘虱","f":"七言古诗","c":["秋暑汗流如炙輠，敝衣湿蒸尘垢涴。","施施众虱当此时，择肉甘于虎狼饿。","咀啮侵肤未云已，爬搔次骨终无那。","时时对客辄自扪，千百所除才几个。","皮毛得气强复活，爪甲流丹真暂破。","未能汤沐取一空，且以火攻令少挫。","踞炉炽炭已不暇，对灶张衣诚未过。","飘零乍若蛾赴灯，惊扰端如蚁旋磨。","欲殴百恶死焦灼，肯贷一凶生弃播。","已观细黠无所容，未放老奸终不堕。","然脐郿坞患溢世，焚宝鹿台身易货。","冢中燎入化秦尸，池上焮随迁莽坐。","彼皆势极就烟埃，况汝命轻侔涕唾。","逃藏坏絮尚欲索，埋没死灰谁复课。","熏心得祸尔莫悔，烂额收功吾可贺。","犹残众虮恨未除，自计宁能久安卧。"]},{"t":"和王乐道读进士试卷","f":"五言古诗","c":["文章始隋唐，进取归一律。","安知鸿都事，竟用程人物。","变今嗟未能，于己空自咄。","流波亦已漫，高论常见屈。","故令俶傥士，往往弃堙郁。","皋陶叙九德，固有知人术。","圣世欲尔为，徐观异人出。"]},{"t":"和王胜之雪霁借马入省","f":"七言古诗","c":["泥水填马不受辙，瓦雪得火犹藏沟。","宿雾纷纷度城阙，朔气凛凛吹衣裘。","穷阎闭门无一客，剥啄惊我有前驺。","强随传呼出屋去，鼻息冻合髭缪缪。","投缰马鬣任攲侧，欲出操箠手还抽。","行思江南悲故事，溪谷冬暖花常流。","前年腊归三见白，霁色岭上班班留。","杖藜此时将邑子，登眺置酒身优游。","岂如都城今日事，秖恐一蹶为亲忧。","因知田里驾款段，昔人岂即非良谋。","君家洛阳名实大，谈笑枯槁回春柔。","平生意气故应在，白发未敢相寻求。","从容退食想佳节，岂无歌声相献酬。","奈何亦作苦寒调，叹息朝夕无骅骝。","超然遂有江湖意，满纸为我书穷愁。","相如正应居客右，子路且莫乘桴浮。"]},{"t":"次韵王微之登高斋","f":"七言律诗","c":["台殿荒墟辱井堙，豪华不复见临春。","北山漠漠云垂地，南埭悠悠水映人。","驰道蔽亏松半死，射场埋没雉多驯。","登高一曲悲亡国，想绕红梁落暗尘。"]},{"t":"和王微之登高斋三首 其三","f":"七言古诗","c":["干戈六代战血埋，双阙尚指山崔嵬。","当时君臣但儿戏，把酒空劝长星杯。","临春美女闭黄壤，玉枝自蕊繁如堆。","后庭新声散樵牧，兴废倏忽何其哀。","咸阳龙移九州坼，遗种变化呼风雷。","萧条中原砀无水，崛强又此凭江淮。","广陵衣冠扫地去，穿筑陇亩为池台。","吴侬倾家助经始，尺土不借秦人筛。","珠犀磊落万艘入，金璧照耀千门开。","建隆天飞跨两海，南发交广东温台。","中间嶪嶪地无几，欲久割据诚难哉。","灵旗指麾尽貔虎，谈笑力可南山排。","楼船蔽川莫敢动，扶伏但有谋臣来。","百年沧洲自潮汐，事往不与波争回。","黄云荒城失苑路，白草废畤空坛垓。","使君新篇韵险绝，登眺感悼随嘲咍。","嗟予愁惫气已竭，对垒每欲相劘挨。","挥毫更想能一战，数窘乃见诗人才。"]},{"t":"和王微之登高斋三首 其二","f":"七言古诗","c":["六朝人物随烟埃，金舆玉几安在哉。","钟山石城已寂寞，祇见江水云端来。","百年故老有存者，尚忆世宗初伐淮。","魏王兵马接踵出，旗纛千里相搪挨。","当时谋臣非不众，上国拔取多陪台。","龙腾九天跨四海，一水欲阻为可咍。","降王北归楼殿坼，弃屋尚锁残金堆。","神灵变化自真主，将帅何力求公台。","山川清明草木静，天地不复屯云雷。","使君登高访古昔，伤此陈迹聊持杯。","因留嘉客坐披写，酃渌笑语倾如筛。","酒酣重惜功业晚，老矣万卷徒兼该。","攒峰列壑动归兴，忧端落笔何崔嵬。","馀年无欢易感激，亦愧庄叟能安排。","青灯明灭照不寐，但把君诗阖且开。"]},{"t":"和王微之登高斋三首 其一","f":"七言古诗","c":["寒云沈屯白日埋，河汉荡坼天如筛。","衡门兼旬限泥潦，卧听窾木鸣相挨。","萧辰忽扫纤翳尽，北岭初出青嵬嵬。","微之新诗动我目，烂若火齐金盘堆。","想携诸彦眺平野，高论历诋秦以来。","觥船淋浪始快意，忽忆归云胡为哉。","念君少壮辍游衍，发挥春秋名玉杯。","书成不得断国论，但此空语传八垓。","登临兴罢因感触，更欲远引追宗雷。","君知富贵亦何有，谄誉未足偿讥排。","风豪雨横费调燮，坐使发背为黄台。","留宾往往夜参半，虽有樽俎无由开。","江南佳丽非一日，况乃故园名池台。","能招过客饮文字，山水又足供欢咍。","剩留官屋贮酒母，取醉不竭当如淮。"]},{"t":"和圣俞农具诗十五首 其七 田漏","f":"五言律诗","c":["占星昏晓中，寒暑已不疑。","田家更置漏，寸晷亦欲知。","汗与水俱滴，身随阴屡移。","谁当哀此劳，往往夺其时。"]},{"t":"和圣俞农具诗十五首 其八 牛衣","f":"五言律诗","c":["百兽冬自暖，独牛非氄毛。","无衣与卒岁，坐恐得空牢。","主人覆护恩，岂啻一绨袍。","问尔何以报，离离满东皋。"]},{"t":"和圣俞农具诗十五首 其一 田庐","f":"五言律诗","c":["田父结田庐，聊容一身息。","呼儿取茅竹，不借乡人力。","起行庐旁朝，归卧庐下夕。","悠悠各有愿，勿笑田庐窄。"]},{"t":"和圣俞农具诗十五首 其九 耧种","f":"五言律诗","c":["富家种论石，贫家种论斗。","富贫同一时，倾泻应心手。","行看万垄空，坐使千箱有。","利物博如此，何惭在牛后。"]},{"t":"和圣俞农具诗十五首 其二 樵斧","f":"五言律诗","c":["百金聚一冶，所赋以所遭。","此岂异莫耶，奈何独当樵。","朝出在人手，暮归在人腰。","用舍各有时，此日两无邀。"]},{"t":"和圣俞农具诗十五首 其十一 钱镈","f":"五言律诗","c":["于易见耒耜，于诗闻钱镈。","百工圣人为，此最功不薄。","欲收禾黍善，先去蒿莱恶。","愿同攲器悟，更使臣工作。"]},{"t":"和圣俞农具诗十五首 其十二 耰锄","f":"五言律诗","c":["锻金以为曲，揉木以为直。","直曲相后先，心手始两得。","秦人望屋食，以此当金革。","君勿易耰锄，耰锄胜锋镝。"]},{"t":"和圣俞农具诗十五首 其十三 袯襫","f":"五言律诗","c":["采采霜露下，披披烟雨中。","蒲茅以为友，短褐相与同。","勿妒市门人，绮纨被奴僮。","当惭边城戍，擐甲徂春冬。"]},{"t":"和圣俞农具诗十五首 其十五 耘鼓","f":"五言律诗","c":["逢逢戏场声，壤壤战时伍。","日落未云休，田家亦良苦。","问儿今垄上，听此何莽卤。","昨日应官繇，州前看歌舞。"]},{"t":"和圣俞农具诗十五首 其十四 台笠","f":"五言律诗","c":["耕有春雨濡，耘有秋阳暴。","二物应时须，九州同我服。","欲为生少慕，得此自云足。","君思周伯阳，所愿岂华毂。"]},{"t":"和圣俞农具诗十五首 其十 耒耜","f":"五言律诗","c":["耒耜见于易，圣人取风雷。","不有仁智兼，利端谁与开。","神农后稷死，般尔相寻来。","山林尽百巧，揉斲无良材。"]},{"t":"和圣俞农具诗十五首 其三 耕牛","f":"五言律诗","c":["朝耕草茫茫，暮耕水潏潏。","朝耕及露下，暮耕连月出。","自无一毛利，主有千箱实。","睆彼天上星，空名岂余匹。"]},{"t":"和圣俞农具诗十五首 其五 牧笛","f":"五言律诗","c":["绿草无端倪，牛羊在平地。","芊绵杳霭间，落日一横吹。","超遥送逸响，澶漫写真意。","岂比卖饧人，吹箫贩童稚。"]},{"t":"和圣俞农具诗十五首 其六 飏扇","f":"五言律诗","c":["精良止如留，疏恶去如摈。","如摈非尔憎，如留岂吾吝。","无心以择物，谁喜亦谁愠。","翁乎勤簸飏，可使糠秕尽。"]},{"t":"和圣俞农具诗十五首 其四 水车","f":"五言律诗","c":["取车当要津，膏润及远野。","与天常斡旋，如雨自潨泻。","置心亦何有，在物偶相假。","此理乃可言，安得圆机者。"]},{"t":"和平甫舟中望九华山二首 其二","f":"五言古诗","c":["谁谓九华远，吾身未尝詹。","唱篇每起予，予口安能钳。","忆在秋浦北，空江上新蟾。","光洁写一镜，回环两堤奁。","露坐引衣襋，风行攲帽檐。","维舟当此时，巨细得尽瞻。","试尝论大略，次乃述微纤。","此山广以深，包畜万物兼。","嘘云吐雾雨，生育靡不渐。","巍然如九皇，德泽四海沾。","此山相后先，各出群峰尖。","毅然如九官，罗立在堂廉。","挺身百辟上，附丽无奸憸。","此山高且寒，五月不觉炎。","草树萋已绿，冰霜尚涵淹。","颓然如九老，白发连苍髯。","此山当无云，秀色郁以添。","姹然如九女，靓饰出重帘。","佩环与巾裙，绀玉青纨缣。","远之妍西施，近或丑无盐。","变态不可穷，诗者徒呫呫。","我初勇一往，役世难安恬。","浪荒不走职，民瘼当谁砭。","乖离今数旬，梦想欲窥觇。","自期得所如，何啻释囚钳。","念昔太白巅，下视海日暹。","朅来天柱游，屐齿尚苔黏。","犹之健饮食，屡飨亦云餍。","胡为慕攀踏，已惫且不嫌。","岂其仁智心，山水固所潜。","男儿有所学，进退不在占。","功名苟不谐，廊庙等闾阎。","况乃抡椽杙，其谁辨楩楠。","归欤岩崖居，料理带与签。","得石坐兀兀，逢泉饮厌厌。","取舍断在独，岂必询谋佥。","子语实慰我，宁殊邑中黔。","玉枝将在山，当倚以葭蒹。","诗力我已屈，锋铓子犹铦。","扶伤更一战，语汝其无谦。"]},{"t":"和平甫舟中望九华山二首 其一","f":"五言古诗","c":["楚越千万山，雄奇此山兼。","盘根虽巨壮，其末乃脩纤。","去县尚百里，侧身勇前瞻。","萧条烟岚上，缥缈浮青尖。","徐行稍复逼，所瞩亦已添。","精神去亹亹，气象来渐渐。","卸席取近岸，移船傍苍蒹。","窥观坐穷晡，未觉晷刻淹。","江空万物息，四面波澜恬。","峨然九女鬟，争出一镜奁。","卧送秋月没，起看朝阳暹。","游氛荡无馀，琐细得尽觇。","陵空翠纛直，照影寒铓铦。","冢木立绀发，崖林张紫髯。","变态生倏忽，虽神讵能占。","当留老吾身，少驻谁云餍。","惜哉秦汉君，黄屋上衡灊。","等之事嬉游，舍此何其廉。","我疑二后荒，神物久已厌。","埋藏在云雾，不欲登昏憸。","又疑避褒封，蔽匿以为谦。","或是古史书，脱落简与签。","当时备巡游，今不在缃缣。","终南秦之望，泰山鲁所詹。","天王与秩祭，俎豆罗醯盐。","苟能泽下民，维此远亦沾。","方今东南旱，土脉燥不黏。","尚无肤寸功，岂免窃食嫌。","神莽吾难知，士病吾能砭。","文章巧傅会，智术工飞钳。","荐宝互圭璧，论材自楩楠。","苟以饰妇妾，谬云活苍黔。","岂如幽人乐，兹山谢闾阎。","穴石作户牖，垂泉当门帘。","寻奇出后径，览胜倚前檐。","超然往不返，举世徒呫呫。","高兴寄日月，千秋伴乌蟾。","遐追商洛翁，秦火不能炎。","近慕楚穆生，竟脱楚人钳。","吾意窃所尚，人谋谅难佥。"]},{"t":"和仲求即席分题得庶字","f":"五言古诗","c":["刀笔漫无营，图书纷不御。","平生携手人，邂逅赏心处。","名卿邵朱邑，肤使超严助。","都官富篇章，博士熟经据。","岂特好微言，又多知大虑。","从容故天幸，倜傥尽人誉。","千艘来交荆，万舸去扬豫。","良无此嘉客，式饮吾所庶。"]},{"t":"和冲卿雪诗并示持国","f":"五言古诗","c":["地卷江海浮，天吹河汉涌。","北风散作花，巧丽世无种。","霾昏得照曜，尘滓归掩拥。","荒林无空枝，幽瓦有高陇。","分才一毛细，聚或千钧重。","飞飏窥已眩，摧压听还凶。","渔舟平系舷，樵屩没归踵。","空令物象瑩，岂免川涂壅。","争光姮娥妒，失色羲和恐。","赖逢阳气蒸，转作水波溶。","舞庭称贺严，扫路传呼宠。","冲游谢壮少，避卧甘闲冗。","吴侯绝俗唱，韩子当敌勇。","胜负观两豪，吾衰但阴拱。"]},{"t":"和刘贡甫燕集之作","f":"七言古诗","c":["冯侯天马壮不羁，韩侯白鹭下清池。","刘侯羽翰秋欲击，吴侯葩萼春争披。","沈侯玉雪照人洁，萧洒已见江湖姿。","唯予貌丑骇公等，自镜亦正如蒙倛。","忘形论交喜有得，杯酒邂逅今良时。","心亲不复异新旧，便脱巾屦相谐嬉。","空堂无尘小雨定，浓绿翳水浮秋曦。","高谈四坐扫炎热，木末更送凉风吹。","此欢不尽忽分散，明月照屋空参差。","平明馀清在心耳，洗我重得刘侯诗。","刘侯未见闻已熟，吾友称诵多文辞。","才高意大方用世，自有豪俊相攀追。","咨予后会恐不数，魂梦久向东南驰。","何时扁舟却顾我，还欲迎子游山陂。"]},{"t":"和吴冲卿鸦鸣树石屏","f":"词","c":["寒林昏鸦相与还，下有跂石苍孱颜。","曾于古图见彷佛，已怪刀笔非人间。","君家石屏谁为写，古图所传无似者。","鸦飞历乱止且鸣，林叶惨惨风烟生。","高斋日午坐中见，意似落日空上行。","君诗雄盛付君手，云此非人乃天巧。","嗟哉浑沌死，乾坤至，造作万物丑妍巨细各有理。","问此谁主何其精，恢奇谲诡多可喜。","人于其间乃复雕镵刻画出智力，欲与造化追相倾。","拙者婆娑尚欲奋，工者固已穷夸矜。","吾观鬼神独与人意异，虽有至巧无所争。","所以虢山间，埋没此宝千万岁，不为见者惊。","吾又以此知妙伟之作不在百世后，造始乃与元气并。","画工粉墨非不好，岁久剥烂空留名。","能从太古到今日，独此不朽由天成。","世人尚奇轻货力，山珍海怪采掇今欲索。","此屏后出为君得，胡贾欲价著不识。","吾知金帛不足论，当与君诗两相直。"]},{"t":"和吴冲卿雪","f":"五言古诗","c":["阳回力犹邅，阴合势方巩。","填空忽汗漫，造物谁怂恿。","轻于擘絮纷，细若吹毛氄。","云连昼已瞀，风助宵仍汹。","凭陵虽一时，变态亦千种。","帘深卷或避，户隘关犹拥。","滔天有冻浪，匝地无荒陇。","飞扬类挟富，委翳等辞宠。","穿幽偶相重，值险辄孤耸。","积惨会将舒，群轻那久重。","纷华始满眼，消释不旋踵。","槁树散飞花，空檐落县湩。","还当困炎热，以此涤烦壅。","共约市南人，收藏不为冗。"]},{"t":"和吴冲卿集禧斋祠","f":"五言古诗","c":["缄封祝辞密，占写御名真。","帝坐遥临物，星图俯映人。","风含烟外节，月点雾中茵。","沈藿升烟远，槐檀取燎新。","羽衣归寂寞，金锼立逡巡。","却想来时路，还疑隔一尘。"]},{"t":"和吴御史汴渠","f":"五言古诗","c":["郑国欲弊秦，渠成秦富彊。","本始意已陋，末流功更长。","维汴亦如此，浚源在淫荒。","归作万世利，谁能弛其防。","夷门筑天都，横带国之阳。","漕引天下半，岂云独荆扬。","货入空外府，租输陈太仓。","东南一百年，寡老无残粻。","自宜富京师，乃亦窘盖藏。","征求过夙昔，机巧到莛芒。","御史闵其然，志欲穷舟航。","此言信有激，此水存何伤。","救世讵无术，习传自先王。","念非老经纶，岂易识其方。","我懒不足数，君材仍自强。","他日听施设，无乃弃篇章。"]},{"t":"和甫如京师微之置酒","f":"五言古诗","c":["季子将北征，貂裘解亭皋。","使君拥鸣驺，出饯载酒醪。","作诗宠行色，坐客多贤豪。","信知大夫才，能赋在登高。","陟峰忧未已，强歌反哀号。","问言归何时，逮此冬风饕。","川涂良阻脩，箠辔慎所操。","黄屋初启圣，万灵归一陶。","询谋及疏贱，拔取皆时髦。","往矣果有合，可辞州县劳。"]},{"t":"和耿天骘同游定林","f":"五言律诗","c":["道人深闭门，二客来不速。","摄衣负朝暄，一笑皆捧腹。","逍遥烟中策，放浪尘外躅。","晤言或世闻，谁谓非绝俗。"]},{"t":"和微之药名劝酒","f":"七言古诗","c":["赤车使者锦帐郎，从客珂马留闲坊。","紫芝眉宇倾一坐，笑语但闻鸡舌香。","药名劝酒诗实好，陟釐为我书数行。","真珠的皪鸣槽床，金罂琥珀正可尝。","史君子细看流光，莫惜觅醉衣淋浪。","独醒至死诚可伤，欢华易尽悲酸早，人间没药能医老。","寄言歌管众少年，趁取乌头未白前。"]},{"t":"咏风","f":"五言古诗","c":["风从北海起，至此南海上。","问风来何事，去复欲何向。","谁遣汝而号，谁应汝而唱。","汝于何时息，汝作无乃妄。","风初无一言，试以问云将。"]},{"t":"垂虹亭","f":"五言古诗","c":["三江五湖口，地与天不隔。","日月所蔽亏，东西渺然白。","漫漫浸北斗，浩浩浮南极。","谁投此虹蜺，欲济两间阨。","中流杂蜃气，栏楯相承翼。","初疑神所为，灭没在顷刻。","晨兴坐其上，傲兀至中昃。","犹怜变化功，不谓因人役。","今君持酒浆，谈笑顾宾客。","颇誇九州物，壮丽此无敌。","荧煌丹砂柱，璀璨黄金壁。","中家不虑始，助我皆豪殖。","喟予独感此，剥烂有终极。","改作不可无，还当采民力。"]},{"t":"夜梦与和甫别如赴北京时和甫作诗觉而有作因寄纯甫","f":"楚辞体","c":["水菽中岁乐，鼎茵暮年悲。","同胞苦零落，会合尚凄其。","况乃梦乖阔，伤怀而赋诗。","诗言道路寒，乃似北征时。","叔兮今安否，季也来何迟。","中夜遂不眠，辗转涕流离。","老我孤主恩，结草以为期。","冀叔善事国，有知无不为。","千里永相望，昧昧我思之。","幸唯季优游，岁晚相携持。","于焉可晤语，水木有茅茨。","畹兰伫归憩，绕屋正华滋。"]},{"t":"奉使道中寄育王山长老常坦","f":"七言古诗","c":["道人少贾海上游，海舶破散身沈浮。","抱金满箧人所寄，吹簸偶得还中州。","裸身归金不受报，秖取斗酒相献酬。","欢娱慈母终一世，脱弃妻子藏岩幽。","苍烟寥寥池水漫，白玉菡萏吹高秋。","夜燃柏子煮山药，忆此东望无时休。","塞垣春枯积雪溜，沙砾盛怒黄云愁。","五更匹马随雁起，想见鄮郭花今稠。","百年夸夺终一丘，世上满眼真悠悠。","寄声万里心绸缪，莫道异趣无相求。"]},{"t":"奉酬圣从待制","f":"七言律诗","c":["班行想望岁空多，知有龙门未敢过。","和近圣人师展季，勇为君子盗荆轲。","三刀旧协庭闱梦，五腨今传里巷歌。","复道谏书尝满箧，不唯诗句似阴何。"]},{"t":"奉酬永叔见赠","f":"七言律诗","c":["欲传道义心犹在，强学文章力已穷。","他日若能窥孟子，终身何敢望韩公。","抠衣最出诸生后，倒屣尝倾广座中。","祇恐虚名因此得，嘉篇为贶岂宜蒙。"]},{"t":"孤城","f":"七言律诗","c":["孤城回望距几何，记得好处常经过。","最思东山烟树色，更忆南湖秋水波。","百年颠倒如梦寐，万事乖隔徒悲歌。","应须饮酒不复道，今夜江头明月多。"]},{"t":"定林示道原","f":"五言古诗","c":["昨登定林山，俯视东南陔。","但见一方白，莫知所从来。","湿银注寒晶，奁以青培堆。","迢迢晻霭中，疑有白玉台。","是夕清风兴，烦云豁然开。","常娥攀桂枝，顾景久徘徊。","杖藜忽高秋，陈迹与子陪。","壮观非复昔，平芜夜莓苔。"]},{"t":"定林寺","f":"五言律诗","c":["众木凛交覆，孤泉静横分。","楚老一枝筇，于此傲人群。","城市少美蔬，想今困惔焚。","且凭东北风，持寄岭头云。"]},{"t":"宝应二三进士见送乞诗","f":"七言律诗","c":["少喜功名尽坦涂，那知干世最崎岖。","草庐有客歌梁甫，狗监无人荐子虚。","解玩山川消积愤，静忘岁月赖群书。","惭君枉盖如平昔，不笑谋生万事疏。"]},{"t":"招同官游东园","f":"五言古诗","c":["青青石上檗，霜至亦已凋。","冉冉水中蒲，尔生信无聊。","感此岁云晚，欲欢念谁邀。","嘉我二三子，为回东城镳。","幽菊尚可泛，取鱼系榆条。","毋为百年忧，一日以逍遥。"]},{"t":"招约之职方并示正甫书记","f":"五言古诗","c":["往时江总宅，近在青溪曲。","井灭非故桐，台倾尚馀竹。","池塘三四月，菱蔓芙蕖馥。","蒲柳亦竞时，冥冥一川绿。","方坻最所爱，意谓可穿筑。","欲往无舟梁，长年寄心目。","故人晚得此，心事付草木。","消摇檐宇新，揽结蹊隧熟。","更能适我愿，中水开茆屋。","鬼营诛荒梗，人境扫喧黩。","濠鱼净留连，海鸟暖追逐。","岂无方外客，于此停高躅。","忆初桑落时，要我岂非夙。","蚕眠忽欲老，一个未言速。","当缘东门水，尚涩南浦舳。","吾庐虽隐翳，赏眺还自足。","横陂受后涧，直堑输前渎。","跳鳞出重锦，舞羽堕软玉。","碧筒递舒卷，紫角联出缩。","千枝孙峄阳，万本毋淇澳。","满门陶令株，弥岸韩侯蔌。","尚复有野物，与公新听瞩。","金钿拥芜菁，翠被敷苜蓿。","虾蟆能作技，科斗似可读。","棂轩俯北渚，花气时度谷。","耘锄聊效颦，缔搆行可续。","荒乘傥不倦，一昼敢辞卜。","虽无北海酒，乃有平津肉。","翛翛仙李枝，城市久烦促。","寄声与俱来，荫我台上谷。"]},{"t":"放鱼","f":"五言律诗","c":["捉鱼浅水中，投置最深处。","当暑脱煎熬，翛然泳而去。","岂无良庖者，可使供七箸。","物我皆畏苦，舍之宁啖茹。"]},{"t":"昆山慧聚寺次孟郊韵","f":"五言律诗","c":["僧蹊蟠青苍，莓苔上秋床。","露翰饥更清，风蘤远亦香。","扫石出古色，洗松纳空光。","久游不忍还，迫迮冠盖场。"]},{"t":"明妃曲","f":"词","c":["我本汉家子，早入深宫里。","远嫁单于国，憔悴无复理。","穹庐为室旃为墙，胡尘暗天道路长。","去住彼此无消息，明明汉月空相识。","死生难有却回身，不忍回看旧写真。","玉颜不是黄金少，爱把丹青错画人。","朝为汉宫妃，暮作胡地妾。","独留青冢向黄昏，颜色如花命如叶。"]},{"t":"明妃曲二首 其一","f":"词","c":["明妃初出汉宫时，泪湿春风鬓脚垂。","低徊顾影无颜色，尚得君王不自持。","归来却怪丹青手，入眼平生几曾有。","意态由来画不成，当时枉杀毛延寿。","一去心知更不归，可怜著尽汉宫衣。","寄声欲问塞南事，只有年年鸿雁飞。","家人万里传消息，好在毡城莫相忆。","君不见咫尺长门闭阿娇，人生失意无南北。"]},{"t":"明州钱君倚众乐亭","f":"七言古诗","c":["使君幕府开东部，名高海曲人知慕。","舣船谈笑政即成，洗涤山川作嘉趣。","平泉浩荡银河注，想见明星弄机杼。","载沙筑成天上路，投虹为桥取孤屿。","扫除荆棘水中央，碧瓦朱甍随指顾。","春风满城金版舫，来看置酒新亭上。","百女吹笙綵凤悲，一夫伐鼓灵鼍壮。","安期羡门相与游，方丈蓬莱不更求。","酒酣忽跨鲸鱼去，陈迹空令此地留。"]},{"t":"杭州修广师法喜堂","f":"七言古诗","c":["浮屠之法与世殊，洗涤万事求空虚。","师心以此不挂物，一堂收身自有馀。","堂阴置石双嵽嵲，石脚立竹青扶疏。","一来已觉肝胆豁，况乃宴坐穷朝晡。","忆初救时勇自许，壮大看俗尤崎岖。","丰车肥马载豪杰，少得志愿多忧虞。","始知进退各有理，造次未可分贤愚。","会将筑室返耕钓，相与此处吟山湖。"]},{"t":"河北民","f":"词","c":["河北民，生近二边长苦辛。","家家养子学耕织，输与官家事夷狄。","今年大旱千里赤，州县仍催给河役。","老小相携来就南，南人丰年自无食。","悲愁白日天地昏，路旁过者无颜色。","汝生不及贞观中，斗粟数钱无兵戎。"]},{"t":"河间","f":"五言古诗","c":["北行出河间，千岁想贤王。","胡麻生蓬中，诘曲终自伤。","好德尚如此，恃材宜见戕。","乃知阴自脩，彼不为倾商。","区区三世家，庙册富文章。","教子以空言，得祚果不良。"]},{"t":"泊舟姑苏","f":"五言律诗","c":["朝游盘门东，暮出阊门西。","四顾茫无人，但见白日低。","荒林带昏烟，上有归鸟啼。","物皆得所托，而我无安栖。"]},{"t":"法云","f":"词","c":["法云但见脊，细路埋桑麻。","扶舆度焰水，窈窕一川花。","一川花好泉亦好，初晴涨绿深于草。","汲泉养之花不老，花底幽人自衰槁。"]},{"t":"虎图","f":"七言古诗","c":["壮哉非罴亦非貙，目光夹镜当坐隅。","横行妥尾不畏逐，顾盼欲去仍踌躇。","卒然我见心为动，熟视稍稍摩其须。","固知画者巧为此，此物安肯来庭除。","想当槃礴欲画时，睥睨众史如庸奴。","神闲意定始一扫，功与造化论锱铢。","悲风飒飒吹黄芦，上有寒雀惊相呼。","槎牙死树鸣老乌，向之俛噣如哺雏。","山墙野壁黄昏后，冯妇遥看亦下车。"]},{"t":"试茗泉","f":"五言律诗","c":["此泉地何偏，陆羽曾未阅。","坻沙光散射，窦乳甘潜泄。","灵山不可见，嘉草何由啜。","但有梦中人，相随掬明月。"]},{"t":"郑子宪西斋","f":"七言律诗","c":["漫搆轩窗意亦深，滔滔浮俗倦登临。","诗书千载经纶志，松竹四时萧洒心。","晓枕不容春梦到，夜灯唯许月华侵。","行看富贵酬勤苦，车马重来拾翠阴。"]},{"t":"金山寺","f":"五言古诗","c":["招提凭高冈，四面断行旅。","胜地犹在险，浮梁袅相拄。","大江当我前，飐滟翠绡舞。","通流与厨会，甘美胜牛乳。","扣栏出鼋鼍，幽姿可时睹。","夜深殿突兀，太微凝帝宇。","壁立两崖对，迢迢隔云雨。","天多剩得月，月落闻津鼓。","夜风一何喧，大舶夹双橹。","颠沉在须臾，我自楫迎汝。","始知像教力，但度无所苦。","忆昨狼狈初，只见石与土。","荣华一朝尽，土梗空俯偻。","人事随转烛，苍茫竟谁主。","咄嗟檀施开，绣楹盘万础。","高阁切星辰，新秋照牛女。","汤休起我病，转上青天去。","摄身凌苍霞，同凭朱栏语。","我歌尔其聆，幽愤得一吐。","谁言张处士，雄笔映千古。"]},{"t":"青青西门槐","f":"五言律诗","c":["人情甘阿谀，我独倦请谒。","尤于权门疏，万事亦已拙。","平生江湖期，梦寐不可遏。","青青西门槐，少解马上暍。"]},{"t":"临吴亭作","f":"七言绝句","c":["补穿葺漏仅区区，志义殊嗟士大夫。","欲致太平非一日，谩劳使者报新书。"]},{"t":"信都公家白兔","f":"七言古诗","c":["水精为宫玉为田，姮娥缟衣洗朱铅。","宫中老兔非日浴，天使洁白宜婵娟。","扬须弭足桂树间，桂花如霜乱后前。","赤鸦相望窥不得，空疑两瞳射日丹。","东西跳梁自长久，天毕横施亦何有。","凭光下视罝网繁，衣褐纷纷漫回首。","去年惊堕滁山云，出入虚莽犹无群。","奇毛难藏果亦得，千里今以穷归君。","空衢险幽不可返，食君庭除嗟亦窘。","令予得为此兔谋，丰草长林且游衍。"]},{"t":"信陵坊有笼山乐官","f":"五言律诗","c":["万里山林姿，羽毛何璀璀。","鸣声应律吕，唯有知者爱。","都门市井儿，谁玩汝文采。","应须锁樊笼，勿受丸矰害。"]},{"t":"前日石上松 其一","f":"五言律诗","c":["前日石上松，斸移沙水际。","青青折钗股，俯映幽人砌。","蟠根今鬯茂，落子还苍翠。","三年一楮叶，世事真期费。"]},{"t":"哀贤亭","f":"五言古诗","c":["黄鸟哀子车，强埋非天为。","天夺不待老，还能使人悲。","马侯东南秀，鞭策要路驰。","归骨万里州，乃当强壮时。","墓门闭空原，白日无履綦。","苍苍柏与松，浩浩山风吹。","我初羞夷吾，鲍叔亦我知。","终欲往一恸，咏言慰孤嫠。"]},{"t":"复至曹娥堰寄剡县丁元珍","f":"七言古诗","c":["溪水浑浑来自北，千山抱水清相射。","山深水急无艇子，欲从故人安可得。","故人昔日此水上，樽酒扁舟慰行役。","津亭把手坐一笑，我喜满怀君动色。","论新讲旧惜未足，落日低徊已催客。","离心自醉不复饮，秋果寒花空满席。","今年却坐相逢处，怊怅难求别时迹。","可怜溪水自南流，安得溪船问消息。"]},{"t":"客至当饮酒二首 其二","f":"五言古诗","c":["天提两轮光，环我屋角走。","自从红颜时，照我至白首。","累累地上土，往往平生友。","少年所种树，磥砢行复朽。","古人有真意，独在无好丑。","冥冥谁与论，客至当饮酒。"]},{"t":"客至当饮酒二首 其一","f":"五言古诗","c":["结屋在墙阴，闭门读诗书。","怀我平生友，山水异秦吴。","杖藜出柴荆，岂无马与车。","穷通适异趣，谈笑不相愉。","岂复求古人，浩荡与之俱。","客至当饮酒，日月无根株。"]},{"t":"幽谷引","f":"楚辞体","c":["云翳翳兮谷之幽，天将雨我兮田者之稠。","有绳于防兮有畚于沟，我公不出兮谁省吾忧。","日晖晖兮山之下，岁则熟兮收者舞。","吾收满车兮弃者满筥，谁吾与乐兮我公燕语。","山有木兮谷有泉，公与客兮醉其间。","芳可搴兮甘可漱，无壮无稚兮环公以笑。","公归而醉兮人则喜，公好我州兮殆其肯止。","公归不醉兮我之忧，岂其不怿兮将舍吾州。","公一朝兮去我，我岁岁兮来游。","完公亭兮使勿毁，以慰吾兮岁岁之愁。"]},{"t":"弯埼","f":"五言古诗","c":["残暑安所逃，弯埼北窗北。","伐翳作清旷，培芳卫岑寂。","投衣挂青枝，敷簟取一息。","凉风过碧水，俯见游鱼食。","永怀少陵诗，菱叶净如拭。","谁当共新甘，紫角方可摘。"]},{"t":"思王逢原","f":"五言古诗","c":["自吾失逢原，触事辄愁思。","岂独为故人，抚心良自悲。","我善孰相我，孰知我瑕疵。","我思谁能谋，我语听者谁。","朝出一马驱，暝归一马驰。","驰驱不自得，谈笑强追随。","仰屋卧太息，起行涕淋漓。","念子冢上土，草茅已纷披。","婉婉妇且少，茕茕一女嫠。","高义动闾里，尚闻致财赀。","嗟我衣冠朝，略能具饘糜。","葬祭无所助，哀颜亦何施。","闻妇欲北返，跂予常望之。","寒汴已闭口，此行又参差。","又说当产子，产子知何时。","贤者宜有后，固当梦熊罴。","天方不可恃，我愿适在兹。","我疲学更误，与世不相宜。","宿昔心已许，同冈结茅茨。","此事今已矣，已矣尚谁知。","渺渺江与潭，茫茫山与陂。","安能久窃食，终负故人期。"]},{"t":"思北山","f":"五言绝句","c":["日日思北山，而今北山去。","寄语白莲庵，迎我青松路。"]},{"t":"思古","f":"五言古诗","c":["古之士方穷，材行已云贵。","大臣公听采，左右不得蔽。","或从蒿藜间，入据廊庙势。","小夫不敢望，云我非其汇。","朝游俊者羞，暮出逢者避。","所以后世愚，人人愿高位。"]},{"t":"既别羊王二君与同官会饮于城南因成一篇追寄","f":"七言古诗","c":["赤车使者白头翁，当归入见天门冬。","与山久别悲匆匆，泽泻半天河汉空。","羊王不留行薄晚，酒肉从容追路远。","临流黄昏席未卷，玉壶倒尽黄金盏。","罗列当辞更缱绻，预知子不空青眼。","严徐长卿误推挽，老年挥翰天子苑。","送车陆续随子返，坐听城鸡肠宛转。"]},{"t":"春山","f":"五言律诗","c":["春山春水流，曲折方屡渡。","荒乘不知疲，行到水穷处。","依然旧童子，要予竹西去。","归时始觉远，草蔓已多露。"]},{"t":"春从沙碛底","f":"五言古诗","c":["春从沙碛底，转上青天际。","霭霭桑柘墟，浮云变姿媚。","游人出暄暖，鸟语辞阴翳。","心知归有日，我亦无愁思。","所嗟独季子，尚客江湖澨。","万里卜凤凰，飘飘何时至。"]},{"t":"春日晚行","f":"七言古诗","c":["门前杨柳二三月，枝条绿烟花白雪。","呼僮羁我果下骝，欲寻南冈一散愁。","缘冈初日沟港净，与我门前绿相映。","隔淮仍见袅袅垂，伫立怊怅去年时。","杏花园西光宅路，草暖沙晴正好渡。","兴尽无人楫迎我，却随倦鸦归薄暮。"]},{"t":"春风","f":"七言律诗","c":["春风吹园杂花开，青天露坐始此回。","一杯一杯复一杯，笑言溢口何欢咍。","古人白骨生青苔，我独不饮何为哉。","何时出得禁酒国，垒曲便筑糟丘台。"]},{"t":"春晴","f":"五言绝句","c":["新春十日雨，雨晴门始开。","静看苍苔纹，莫上人衣来。"]},{"t":"昼寝","f":"五言律诗","c":["井径从芜漫，青藜亦倦扶。","百年唯有且，万事总无如。","弃置蕉中鹿，驱除屋上乌。","独眠窗日午，往往梦华胥。"]},{"t":"独山梅花","f":"七言律诗","c":["独山梅花何所似，半开半谢荆棘中。","美人零落依草木，志士憔悴守蒿蓬。","亭亭孤艳带寒日，漠漠远香随野风。","移栽不得根欲老，回首上林颜色空。"]},{"t":"独归","f":"七言古诗","c":["钟山独归雨微冥，稻畦夹冈半黄青。","疲农心知水未足，看云倚木车不停。","悲哉作劳亦已久，暮歌如哭难为听。","而我官闲幸无事，北窗枕簟风泠泠。","于时荷花拥翠盖，细浪嬲雪千娉婷。","谁能攲眠共此乐，秋港虽浅可扬舲。"]},{"t":"独卧有怀","f":"五言律诗","c":["午鸠鸣春阴，独卧林壑静。","微云过一雨，淅沥生晚听。","红绿纷在眼，流芳与时竞。","有怀无与言，伫立钟山暝。"]},{"t":"疥","f":"五言古诗","c":["浮阳燥欲出，阴湿与之战。","燥湿相留连，虫出乃投间。","搔肤血至股，解衣燎炉炭。","方其惬心时，更自无可患。","呼医急治之，莫惜千金散。","有乐即有苦，惬心非所愿。"]},{"t":"相国寺启同天节道场行香院观戏者","f":"五言绝句","c":["侏优戏场中，一贵复一贱。","心知本自同，所以无欣怨。"]},{"t":"相送行效张籍","f":"词","c":["一车南，一车北，身世悤悤俱有役。","忆昔论心两绸缪，那知相送不得留。","但闻马嘶觉已远，欲望应须上前坂。","秋风忽起吹泥尘，双目空回不见人。"]},{"t":"省兵","f":"五言古诗","c":["有客语省兵，兵省非所先。","方今将不择，独以兵乘边。","前攻已破散，后距方完坚。","以众亢彼寡，虽危犹幸全。","将既非其才，议又不得专。","兵少败孰继，胡来饮秦川。","万一虽不尔，省兵当何缘。","骄惰习已久，去归岂能田。","不田亦不桑，衣食犹兵然。","省兵岂无时，施置有后前。","王功所由起，古有七月篇。","百官勤俭慈，劳者已息肩。","游民慕草野，岁熟不在天。","择将付以职，省兵果有年。"]},{"t":"神宗皇帝挽辞二首 其二","f":"五言律诗","c":["城阙宫车转，山林隧路归。","苍梧云未远，姑射露先晞。","玉暗蛟龙蛰，金寒雁鹜飞。","老臣他日泪，湖海想遗衣。"]},{"t":"秋日不可见","f":"五言律诗","c":["秋日不可见，林端但馀黄。","杖藜思平野，俛仰畏无光。","栗栗涧谷风，吹我衣与裳。","娟娟空山月，照我冠上霜。"]},{"t":"秋日在梧桐","f":"五言律诗","c":["秋日在梧桐，转阴如急毂。","冥冥蔽中庭，下视今可暴。","高蝉不复嘒，稍得寒鸦宿。","百绕有衰翁，行歌待春绿。"]},{"t":"秋早","f":"五言律诗","c":["暮寻蔡墩西，独觉秋尚早。","山路葩卉繁，野田风日好。","禅林乌未泊，经屋尘初扫。","蛮藤五花簟，复足休吾老。"]},{"t":"秋怀","f":"七言律诗","c":["城南平野寒多露，窗壁含风秋气度。","邻桑槭槭已欲空，悲虫啾啾促机杼。","柴门半掩扫鸟迹，独抱残编与神遇。","韩公既去岂能追，孟子有来还不拒。"]},{"t":"秋夜泛舟","f":"五言律诗","c":["池堑秋水净，扁舟溯凉飙。","的皪荷上珠，俯映疏星摇。","深寻畏鱼淰，中路且回桡。","冥冥菰蒲中，乃复有惊跳。"]},{"t":"秋枝如残人","f":"五言律诗","c":["秋枝如残人，颜色先憔悴。","微寒吹已空，性命一何脆。","宁当记畴昔，葩叶相妩媚。","岁行谁使然，好杀岂天意。"]},{"t":"秋庭午吏散","f":"五言律诗","c":["秋庭午吏散，予亦归息偃。","岂无嘉宾客，欲往心独懒。","北窗古人篇，一读三四反。","悲哉不蚤计，失道行晼晚。"]},{"t":"秋热","f":"七言古诗","c":["火腾为虐不可摧，屋窄无所逃吾骸。","织芦编竹继檐宇，架以松栎之条枚。","岂惟宾至得清坐，因有馀地苏陪台。","愆阳陵秋更暴横，焮我欲作昆明灰。","金流玉熠何足怪，鸟焚鱼烂为可哀。","忆我少时亦值此，翛然但以书自埋。","老衰奄奄气易夺，抚卷岂复能低徊。","西风忽送中夜湿，六合一气窑新开。","帘窗幕户便防冷，且恐霰雪相寻来。"]},{"t":"结屋山涧曲","f":"五言古诗","c":["结屋山涧曲，挂瓢秋树颠。","鸣不中律吕，时时惊我眠。","吾儿亦恶聒，勠力事弃捐。","止我为尔歌，不如恣其然。","狂风动地至，万窍各啾喧。","一瓢虽易除，岂在有无间。","皪皪山下石，泠泠手中弦。","临流写所爱，坐听以穷年。"]},{"t":"美玉","f":"五言律诗","c":["美玉小瑕疵，国工犹珍之。","大贤小玷缺，良交岂其绝。","小缺可以补，小瑕可以磨。","不补亦不磨，人为奈尔何。"]},{"t":"胡氏逢原堂","f":"词","c":["我爱铜官好，君实家其间。","山水相萦萃，花卉矜春妍。","有鸣林间禽，有跃池中鲜。","叶山何嗟峨，秀峙东南偏。","峰峦日在望，远色涵云边。","宾客此遴集，觞饮常留连。","君家世儒雅，子弟清风传。","前日辟书堂，名之曰逢原。","有志在古道，驰情慕高贤。","深哉堂名意，推此宜勉?。","木茂贵培本，流长思养源。","左右无不宜，愿献小诗篇。"]},{"t":"胡笳十八拍十八首 其十八","f":"楚辞体","c":["春风似旧花仍笑，人生岂得长年少。","我与儿兮各一方，憔悴看成两鬓霜。","如今岂无騕袅与骅骝，安得送我置汝傍。","胡尘暗天道路长，遂令再往之计堕眇芒。","胡笳本出自胡中，此曲哀怨何时终。","笳一会兮琴一拍，此心炯炯君应识。"]},{"t":"胡笳十八拍十八首 其十七","f":"七言律诗","c":["燕山雪花大如席，与儿洗面作光泽。","恍然天地半夜白，闺中祇是空相忆。","点注桃花舒小红，与儿洗面作华容。","欲问平安无使来，桃花依旧笑春风。"]},{"t":"胡笳十八拍十八首 其十六","f":"楚辞体","c":["此身饮罢无归处，心怀百忧复千虑。","天翻地覆谁得知，魏公垂泪嫁文姬。","天涯憔悴身，托命于新人。","念我出腹子，使我叹恨劳精神。","新人新人听我语，我所思兮在何所。","母子分离兮意难任，死生不相知兮何处寻。"]},{"t":"胡笳十八拍十八首 其十五","f":"七言律诗","c":["当时悔来归又恨，洛阳宫殿焚烧尽。","纷纷黎庶逐黄巾，心折此时无一寸。","恸哭秋原何处村，千家今有百家存。","争持酒食来相馈，旧事无人可共论。"]},{"t":"胡笳十八拍十八首 其十四","f":"楚辞体","c":["鞠之育之不羞耻，恩情亦各言其子。","天寒日暮山谷里，肠断非关陇头水。","儿呼母兮啼失声，依然离别难为情。","洒血仰头兮诉苍苍，知我如此兮不如无生。"]},{"t":"胡笳十八拍十八首 其十三","f":"七言律诗","c":["自断此生休问天，生得胡儿拟弃捐。","一始扶床一初坐，抱携抚视皆可怜。","宁知远使问名姓，引袖拭泪悲且庆。","悲莫悲于生别离，悲在君家留二儿。"]},{"t":"胡笳十八拍十八首 其十二","f":"七言律诗","c":["归来展转到五更，起看北斗天未明。","秦人筑城备胡处，扰扰唯有牛羊声。","万里飞蓬映天过，风吹汉地衣裳破。","欲往城南望城北，三步回头五步坐。"]},{"t":"胡笳十八拍十八首 其九","f":"楚辞体","c":["柳絮已将春去远，攀条弄芳畏晼晚。","忧患众兮欢乐鲜，一去可怜终不返。","日夕思归不得归，山川满目泪沾衣。","罼圭苑里西风起，叹息人间万事非。"]},{"t":"胡笳十八拍十八首 其六","f":"七言律诗","c":["青天漫漫覆长路，一纸短书无寄处。","月下长吟久不归，当时还见雁南飞。","弯弓射飞无远近，青冢路边南雁尽。","两处音尘从此绝，唯向东西望明月。"]},{"t":"胡笳十八拍十八首 其五","f":"七言古诗","c":["十三学得琵琶成，并幕重重卷画屏。","一见郎来双眼明，劝我酤酒花前倾。","齐言此夕乐未央，岂知此声能断肠。","如今正南看北斗，言语传情不如手。","低眉信手续续弹，弹看飞鸿劝胡酒。"]},{"t":"胡笳十八拍十八首 其四","f":"七言古诗","c":["汉家公主出和亲，御厨络绎送八珍。","明妃初嫁与胡时，一生衣服尽随身。","眼长看地不称意，同是天涯沦落人。","我今一食日还并，短衣数挽不掩胫。","乃知贫贱别更苦，安得康强保天性。"]},{"t":"胡笳十八拍十八首 其三","f":"楚辞体","c":["身执略兮入西关，关山阻脩兮行路难。","水头宿兮草头坐，在野只教心胆破。","更鞴彫鞍教走马，玉骨瘦来无一把。","几回抛鞚抱鞍桥，往往惊堕马蹄下。"]},{"t":"胡笳十八拍十八首 其二","f":"楚辞体","c":["天不仁兮降乱离，嗟余去此其从谁。","自胡之反持干戈，翠蕤云旓相荡摩。","流星白羽腰间插，叠鼓遥翻瀚海波。","一门骨肉散百草，安得无泪如黄河。"]},{"t":"胡笳十八拍十八首 其一","f":"七言律诗","c":["中郎有女能传业，颜色如花命如叶。","命如叶薄将奈何，一生抱恨常咨嗟。","良人持戟明光里，所慕灵妃媲箫史。","空房寂寞施穗帷，弃我不待白头时。"]},{"t":"胡笳十八拍十八首 其七","f":"七言律诗","c":["明明汉月空相识，道路只今多拥隔。","去住彼此无消息，时独看云泪横臆。","豺狼喜怒难姑息，自倚红颜能骑射。","千言万语无人会，漫倚文章真末策。"]},{"t":"胡笳十八拍十八首 其八","f":"七言律诗","c":["死生难有却回身，不忍重看旧写真。","暮去朝来颜色改，四时天气总愁人。","东风漫漫吹桃李，尽日独行春色里。","自经丧乱少睡眠，莺飞燕语长悄然。"]},{"t":"胡笳十八拍十八首 其十","f":"七言律诗","c":["寒声一夜传刁斗，云雪埋山苍兕吼。","诗成吟咏转凄凉，不如独坐空搔首。","漫漫胡天叫不闻，胡人高鼻动成群。","寒尽春生洛阳殿，回首何时复来见。"]},{"t":"胡笳十八拍十八首 其十一","f":"楚辞体","c":["晚来幽独恐伤神，唯见沙蓬水柳春。","破除万事无过酒，虏酒千杯不醉人。","含情欲说更无语，一生长恨奈何许。","饥对酪肉兮不能餐，强来前帐临歌舞。"]},{"t":"草端无华滋","f":"五言律诗","c":["草端无华滋，阴气已盘固。","暄妍却如春，岁晚曾不寤。","一裘可以暖，贫士终难豫。","忽忽远枝空，寒虫欲坏户。"]},{"t":"荐亭","f":"五言古诗","c":["朝寻东郭来，西路历荐亭。","众山若怨思，惨澹长眉青。","迸水泣幽咽，复如语丁宁。","岂予久忘之，而欲我小停。","歇鞍松柏间，坐起俯轩棂。","秋日幸未暮，奈何雨冥冥。"]},{"t":"要望之过我庐","f":"五言古诗","c":["念子且行矣，要子过我庐。","汲我山下泉，煮我园中蔬。","知子有仁心，不忍钩我鱼。","我池在人境，不与猵獭居。","亦复无虫蛆，出没争腐馀。","食罢往游观，鱍鱍藻与蒲。","清波映白日，摆尾扬其须。","岂鱼有此乐，而我与子无。","击壤谣圣时，自得以为娱。"]},{"t":"送子思兄参惠州军","f":"五言古诗","c":["沄沄曲江水，天借九秋色。","楼台飞半空，秀气盘韶石。","载酒填里闾，吹花换朝夕。","笙箫震河汉，锦绣烂冠帻。","地灵瘴疠绝，人物倾南极。","先朝有名臣，卧理讼随息。","稍稍延诸生，谈笑与宾客。","子来适妙年，谒入交履舄。","寂寥九龄后，此独望一国。","虞翻礼丁览，韩愈俟赵德。","孤岸镇颓波，俗流未易识。","我方文葆中，旋逐旌旗迹。","去思今岂忘，耳目熟遗迹。","吏含殷勤言，俛仰问乖隔。","当时府中儿，侵寻鬓边白。","下帷虽著书，不救寒饥迫。","谓宜门阑士，宦路久烜赫。","奈何犹差池，更捧丞掾檄。","骥摧千里蹄，鹏堕九霄翮。","人生无巧愚，天运有通塞。","试观驰骋人，意气宇宙窄。","荣华去路尘，谤辱与山积。","优游禄仕间，较计谁失得。","送君强成歌，陟岵翻感激。"]},{"t":"送元厚之待制知福州","f":"五言古诗","c":["海隅山谷閒，人物最多处。","平旦息相吹，连城黕如雾。","闽王旧宫室，丹漆美无度。","今为大帅府，千里来赴愬。","元侯文章翁，更以吏能著。","峨峨中天阁，鸣玉新改步。","衔诏出梨岭，方为远人慕。","旌旗满流水，冠盖东门驻。","四坐共咨嗟，疑侯不当去。","张仲称孝友，樊侯正求助。","名城虽云乐，行矣未宜遽。"]},{"t":"送文学士倅邛州","f":"五言古诗","c":["文翁出治蜀，蜀士始文章。","司马唱成都，嗣音得王扬。","荦荦汉守孙，千秋起相望。","操笔赋上林，脱巾选为郎。","拥书天禄阁，奇字校偏傍。","忽乘驷马车，牛酒过故乡。","时平无谕檄，不访碧鸡祥。","问君行何为，关陇正繁霜。","中和助宣布，循吏缀前芳。","岂特为亲荣，区区夸一方。"]},{"t":"送王龙图守荆南","f":"七言律诗","c":["壮志高才偃一藩，更嗟贤路此时难。","长幡欲动何妨屈，老骥能行岂易闲。","沙市放船寒月白，渚宫留御古苔斑。","知公未厌还随诏，归看功名重太山。"]},{"t":"送石赓归宁","f":"五言古诗","c":["虚名误长者，邂逅肯经过。","所操十馀篇，浩荡决江河。","侧身朝市间，乐少悲惭多。","文章旧所好，久已废吟哦。","开编喜有得，一读瘳沉痾。","裹饭北城阴，永怀从晤歌。","又欲及岁晚，空堂扫丝窠。","稍出平生言，道艺相琢磨。","忽随雁南飞，当此叶辞柯。","去去梨岭高，想见青坡陀。","黄花一杯酒，为寿乐如何。","微诗等瓦砾，持用报隋和。"]},{"t":"送乔执中秀才归高邮","f":"五言古诗","c":["薄饭午不羹，空炉夜无炭。","寥寥日避席，烈烈风欺幔。","谓予勿恶此，何为向子叹。","长年客尘沙，无妇助亲爨。","寒暄慰白首，我弟才将冠。","邅回岁又晚，想见淮湖漫。","古人一日养，不以三公换。","田园在戮力，且欲归锄灌。","行矣子诚然，光阴未宜玩。","负米力有馀，能无读书伴。"]},{"t":"送刘贡甫谪官衡阳","f":"词","c":["刘郎刘郎莫先起，遇酒当歌且欢喜。","船头朝转暮千里，眼中之人吾老矣。","九疑联绵皆相似，负雪崔嵬插花里。","万里衡阳雁，寻常到此回。","行逢二三月，好与雁同来。","雁来人不来，如何不饮令心哀。","莫厌潇湘少人处，谪官樽俎定常开。"]},{"t":"送孙长倩归辉州","f":"五言律诗","c":["溪涧得雨潦，奔溢不可航。","江海收百川，浩浩谁能量。","溪涧之日短，江海之日长。","愿生畜道德，江海以自方。"]},{"t":"送孙叔康赴御史府","f":"五言古诗","c":["古人喜经纶，万事惭强聒。","时来上青冥，俯仰但一节。","危言回丘山，声利尽毫末。","由来治乱体，宿昔心已达。","肯随俗好恶，议论轻自决。","遗风何寥寥，梦寐待豪杰。","天书下东南，趣召赴严阙。","长材晦朝伦，高行隐家闼。","新除酬问望，宿蕴行施设。","念吾非忘形，此理未易说。"]},{"t":"送江宁彭给事赴阙","f":"词","c":["西江望士众长兼，卓荦传家在一男。","壮志异时开史牒，妙龄终日对书龛。","桂堂发策收科选，樱苑颁诗豫宴酣。","大邑援琴聊试可，小州怀绂果才堪。","分台拜职荣先入，抗疏辞恩耻横覃。","劲操比松寒不挠，忠言如药苦非甘。","龙鳞直为当官触，虎穴宁关射利探。","朱毂兽头终协梦，粉闱鸡舌更须含。","均输北转荆门鹢，劝课西临蜀市蚕。","期信有儿迎郭伋，食贫无地乞羊昙。","櫜垂铃栈驼鸣?，节拥棠郊虎视眈。","归见广墀瞻斧藻，对扬初服改朱蓝。","进班华省财方阜，出按穷边虏稍戡。","帝命贾琮当冀北，民歌姬奭次周南。","投壶飨客鱼无乙，伐鼓蒐兵马有驔。","鲸鬣掀红旗杳杳，虬髯吒黑纛鬖鬖。","威加诸部风霜肃，惠浸连营雨露涵。","大斗时时能剧饮，轻裘往往祇清谈。","乾龙已应天飞五，晋马徐观昼接三。","道在君臣方自合，德侔卿长亦谁惭。","便蕃肯较平生宠，放旷皆知雅性媅。","委佩去辞廷殖殖，扬舲来得府潭潭。","一尊客语从容尽，千里人情委曲谙。","岂但搢绅称召杜，故多扶杖祝彭聃。","幕中俊乂闲刀笔，帐下骁雄冷剑镡。","楚地怪须留汲黯，萧规疑欲付曹参。","从来贵势公何慕，自是贤名上所贪。","未信逸身今以老，且当忧国每如惔。","论心邂逅胶投漆，搔首低徊雪满簪。","镇抚未惊移岁月，追攀曾许赏烟岚。","馀欢遽隔新亭饯，宿惠难忘旧馆骖。","卷曲尚谁知散栎，峥嵘空此咏枯楠。"]},{"t":"送吴仲庶出守潭州","f":"五言古诗","c":["吴公治河南，名出汉廷右。","高才有公孙，相望千岁后。","平明省门开，吏接堂上肘。","指撝谈笑间，静若在林薮。","连墙画山水，隐几诗千首。","浩然江湖思，果得东南守。","传鼓上清湘，旌旗蔽牛斗。","方今河南治，复在荆人口。","自古楚有材，酃渌多美酒。","不知樽前客，更得贾生否。"]},{"t":"送吴显道五首 其五","f":"七言绝句","c":["百年多病独登台，知有归日眉放开。","功名富贵何足道，且赋渊明归去来。"]},{"t":"送吴显道五首 其四","f":"七言绝句","c":["忽忆旧乡头已白，牙齿欲落真可惜。","临江把臂难再得，江水江花岂终极。"]},{"t":"送吴显道五首 其三","f":"七言律诗","c":["临川楼上柅园中，罗帏绣幕围香风。","觥船一棹百分空，看朱成碧颜始红。","杏花杨柳年年好，南去北来人自老。","旧事无人可共论，惟君与我同怀抱。"]},{"t":"送吴显道五首 其二","f":"词","c":["滕王高阁临江渚，东边日出西边雨。","十五年前此会同，天际张帷列樽俎。","公今此去何时归，我今停杯一问之。","春风两岸水杨柳，昔日青青今在否。","偶向东湖更向东，杏花两株能白红。","落拓旧游应记得，插花走马月明中。","荏苒荏苒瞻西海，明年花开复谁在。","杏花杨柳年年好，南去北来人自老。","少壮几时奈老何，与君把箸击盘歌。","歌罢仰天叹，六龙忽蹉跎。","眼中了了见乡国，自是不归归便得。","欲往城南望城北，此心炯炯君应识。"]},{"t":"送吴显道五首 其一","f":"词","c":["五湖大浪如银山，问君西游何当还。","以手抚膺坐长叹，空手无金行路难。","丈夫意有在，吾徒且加餐。","屏风九叠云锦张，千峰如连环。","上有横河断海之浮云，可望不可攀。","飞空结楼台，动影袅窕冲融间。","沛然乘天游，下看尘世悲人寰。","泊舟浔阳郭，去去翔寥廓。","君今幸未成老翁，衰老不复如今乐。"]},{"t":"送吴显道南归","f":"词","c":["君不见蔡泽栖迟世看丑，豪气英风亦何有。","忽然变轩昂，盛事传不朽。","君今幸未成老翁，二十八宿罗心胸。","何不上书自荐达，封侯起第一日中。","秋月春风等闲度，山中旧宅无人住。","宅中青桑叶宛宛，涧水流过田中路。","遥知杨柳是门处，万里苍苍烟水暮。","我欲寻之不惮远，君又暂来还径去。","红亭驿路挂城头，忆君祇欲苦死留。","天际张帷列樽俎，君歌声酸辞且苦。","人生憔悴生理难，使人听此凋朱颜。","劝君更尽一杯酒，明日路长山复山。"]},{"t":"送宋中道倅洺州","f":"词","c":["漳水不灌邺，不知几何时。","后世有史起，乃能为可为。","余尝怜洺民，?卤半不治。","颇觉漳可引，但为谈者嗤。","高议不同俗，功成人始思。","夫子到官日，勿忘吾此诗。"]},{"t":"送张公仪宰安丰","f":"七言律诗","c":["楚客来时雁为伴，归期祇待春冰泮。","雁飞南北三两回，回首湖山空梦乱。","秘书一官聊自慰，安丰百里谁复叹。","扬鞭去去及芳时，寿酒千觞花烂熳。"]},{"t":"送张拱微出都","f":"五言古诗","c":["归卧不自得，出门无所投。","独寻城隅水，送子因远游。","荒林缠悲风，惨惨吹驼裘。","捉手共笑语，顾瞻中河舟。","嗟人皆行乐，而我方坐愁。","肠胃绕钟山，形骸空此留。","念始读诗书，岂非亦有求。","一来裹青衫，触事自悔尤。","误为世所容，荣禄今白头。","塞责以区区，一毛施万牛。","不足助时治，但为故人羞。","宽恩许自劾，终欲东南流。","子今涉冬江，船必泊蔡洲。","寄声冶城人，为我问一丘。"]},{"t":"送李屯田守桂阳二首 其二","f":"七言古诗","c":["苍黄离家问南北，中路思归归不得。","风涛何处不惊人，雨雪前村更欺客。","旧交旌旆此盘桓，见我即令儿解鞍。","荒山乐官歌舞拙，提壶沽酒聊一欢。","行藏欲语眉不展，互叹别离心缱绻。","行年半百劳如此，南亩催耕未宜晚。"]},{"t":"送李屯田守桂阳二首 其一","f":"词","c":["泊船香炉峰，始与子相识。","寄书邗江上，诒我峰下石。","缘以湘水竹，携持与南北。","永怀故人欢，不愿百金易。","竹枯归樵苏，石烂弃沙砾。","夷门得邂逅，绿发皆半白。","追思少时事，俛仰如一夕。","老矣无所为，空知念畴昔。","常思一杯酒，要子相解释。","出门事纷纷，归卧意还?。","闻当上湓水，持诏守岭阨。","方为万里别，执手先惨戚。","兹游信浩荡，山水多所得。","为我谢香炉，风尘每相忆。"]},{"t":"送李宣叔倅漳州","f":"五言古诗","c":["闽山到漳穷，地与南越错。","山川郁雾毒，瘴疠春冬作。","荒茅篁竹閒，蔽亏有城郭。","居人特鲜少，市井宜萧索。","野花开无时，蛮酒持可酌。","穷年不值客，谁与分杯杓。","朝廷尚贤俊，磊砢充台阁。","君能喜节行，文艺又该博。","超然万里去，识者为不乐。","予闻君子居，自可救民瘼。","苟能禦外物，得地无美恶。","似闻最南方，北客今勿药。","林麓换风气，兽蛇凋毒蠚。","如漳犹近州，气冷又销铄。","珍足海物味，其厚不为薄。","章举马甲柱，固已轻羊酪。","蕉黄荔子丹，又胜楂梨酢。","逢衣比多士，往往在丘壑。","从容与笑语，岂不慰寂寞。","太守好觞咏，嘉宾应在幕。","想即有新诗，流传至京洛。"]},{"t":"送陈谔","f":"七言律诗","c":["有司昔者患不公，糊名誊书今故密。","论才相若子独弃，外物有命真难必。","乡闾孝友莫如子，我愿卜邻非一日。","朱门奕奕行多惭，归矣无为恶蓬荜。"]},{"t":"送郑叔熊归闽","f":"五言古诗","c":["郑子喜论兵，魁然万人敌。","尝持一尺箠，跨马河南北。","方今边利害，口手能讲画。","疑师谷城翁，方略已自得。","天兵卷甲老，壮士不肉食。","低徊向诗书，文字锐镌刻。","科名又龃龉，弃置非人力。","黄尘彫罽裘，逆旅同偪仄。","秋风吹残汴，霰雪已惊客。","浩歌随东舟，别我无惨恻。","闽生今好游，往往老妻息。","南陔子所慕，天命岂终塞。"]},{"t":"送郓州知府宋谏议","f":"五言古诗","c":["盛世千龄合，宗工四海瞻。","天心初吁俊，云翼首离潜。","德望完圭角，仪形壮陛廉。","徐鸣苍玉佩，尽校碧牙签。","纶掖清光注，銮坡茂渥沾。","文明诚得主，政瘼尚烦砭。","右府参机务，东涂赞景炎。","庙谟资石画，兵略倚珠钤。","坐镇均劳逸，斋居养智恬。","讴谣喧井邑，惠化穆苍黔。","进律朝章旧，疏恩物议佥。","通班三殿邃，徙部十城兼。","申甫周之翰，龟蒙鲁所詹。","地灵奎宿照，野沃汶河渐。","首路龙旗盛，提封虎节严。","赐衣缠紫艾，卫甲缀朱綅。","海谷移文省，溪堂燕豆添。","班春回绀幰，问俗卷彤襜。","舟楫商岩命，熊罴渭水占。","治装行入觐，金鼎重调盐。"]},{"t":"送春","f":"七言古诗","c":["武陵山下朝买船，风吹宿雾山花鲜。","万家笑语横青天，绮窗罗幕舞婵娟。","小鬟折花叩船舷，玉盏写酒酬金钱。","朱甍飞动浮云巘，天外筦箫来宛转。","断桥人行夕阳路，楼观琉璃影中见。","酡颜未分骅骝催，烛入坐客犹徘徊。","岂知阊阖门边住，春尽不见芳菲开。","日月纷纷车走坂，少年意气何由挽。","洞庭浪与天地白，尘昏万里东浮眼。","黑貂裘敝归几时，相见绿树啼黄鹂。","荣华俯仰忧患随，命驾吾与高人期。"]},{"t":"送黄吉甫入京题清凉寺壁","f":"七言绝句","c":["薰风洲渚荠花繁，看上征鞍立寺门。","投老难堪与君别，倚江从此望还辕。"]},{"t":"送裴如晦宰吴江","f":"五言古诗","c":["霜泽与天杳，旁临无限情。","他时散发处，最爱垂虹亭。","飘然平生游，舍我戴吴星。","欲往独不得，都门看扬舲。","到县问疾苦，为予求所经。","当知耕牧地，往往茭蒲青。","三江断其二，洚水何由宁。","微子好古者，此歌尚谁听。"]},{"t":"送惠思上人","f":"五言古诗","c":["黄鹤抚四海，翻然落中州。","一听笙与镛，低回如有求。","飞鸣阿阁上，好与凤皇游。","顾怜鲁东门，无事反悲愁。","岁晏忽惊矫，问胡不少留。","因知网罗外，犹有稻粱谋。"]},{"t":"送程公辟守洪州","f":"七言古诗","c":["画船插帜摇秋光，鸣铙传鼓水洋洋。","豫章太守吴郡郎，行指斗牛先过乡。","乡人出郭航酒浆，炰鳖鲙鱼炊稻粱。","芡头肥大菱腰长，釂酬喧呼坐满床。","怪君三年寓瞿塘，又驱传马登太行。","缨旄脱尽归大梁，翻然出走天南疆。","九江左投贡与章，扬澜吹漂浩无旁。","老蛟戏水风助狂，盘涡忽坼千丈强。","君闻此语悲慨慷，迎吏乃前持一觞。","鄙州历选多俊良，镇抚时有诸侯王。","拂天高阁朱鸟翔，西山蟠绕鳞鬣苍。","下视城堑真金汤，雄楼杰屋郁相望。","中户尚有千金藏，漂田种粳出穰穰。","沉檀珠犀杂万商，大舟如山起牙樯。","输泻交广流荆扬，轻裾利屣列名倡。","春风蹋谣能断肠，平湖湾坞烟渺茫。","树石珍怪花草香，幽处往往闻笙簧。","地灵人秀古所臧，胜兵可使酒可尝。","十州将吏随低昂，谈笑指麾回雨旸。","非君才高力方刚，岂得跨有此一方。","无为听客欲沾裳，使君谢吏趣治装。","我行乐矣未渠央。"]},{"t":"送董伯懿归吉州","f":"五言古诗","c":["我来以丧归，君至因谪徙。","苍黄忧患中，邂逅遇于此。","去年服初除，听赦相助喜。","看君数归月，但屈两三指。","茫然冬更秋，一笑非愿始。","篮舆杨柳下，明月芙蕖水。","僮饥屡窥门，客罢方隐几。","是非评众诗，成败断前史。","时时对奕石，漫浪争生死。","送迎皆幅巾，设食但陈米。","亦曾戏篇章，挥翰疾蒿矢。","君豪才有馀，我老惫先止。","东城景阳陌，南望长干紫。","欲斸三亩蔬，于焉寄残齿。","经过许后日，唱和犹在耳。","新恩忽舍我，欣怅生彼己。","江湖北风帆，捩柂即千里。","相逢知何时，莫惜缣与纸。"]},{"t":"送谢师宰赴任楚州 其一","f":"五言古诗","c":["珠玉不自贵，故为人所怜。","贤愚亦如此，好恶有自然。","闻子欲东南，使我抱幽悁。","炎风沙土中，甘与子留连。","大梁非无客，跪起废食眠。","相看独不厌，以此知子贤。","衰气已难强，壮心方少年。","才高岂易得，勖子在雕镌。"]},{"t":"送裴如晦即席分题三首 其三","f":"五言古诗","c":["邂逅君子堂，一杯相与持。","便应取酩酊，万事不足惟。","平明蔡河风，回首成差池。","独我漫浪者，尚得行相追。","磨刀鲙严冬，宿昔少陵诗。","还当捕鲈鱼，载酒与我期。","甫里松菊盛，洞庭柑橘垂。","文章为我唱，不数陆与皮。"]},{"t":"送裴如晦即席分题三首 其二","f":"五言古诗","c":["十月颍水冰，问君行何为。","行不顾斗米，自与五湖期。","平生湖上游，幽事略能知。","此后君最乐，穷年得游嬉。","彩鲸抗波涛，风作鳞之而。","鸣鼓上洞庭，笑看红橘垂。","漠漠大梁下，黄沙吹酒旗。","应怜故人愁，回首一相思。"]},{"t":"送裴如晦即席分题三首 其一","f":"五言古诗","c":["飘然五湖长，昨日国子师。","绿发约略白，青衫欲成缁。","牵舟推河冰，去与山水期。","春风垂虹亭，一杯湖上持。","傲兀何宾客，两忘我与而。","能复记此饮，诗成酒淋漓。"]},{"t":"送潮州吕使君","f":"五言古诗","c":["韩君揭阳居，戚嗟与死邻。","吕使揭阳去，笑谈面生春。","当复进赵子，诗书相讨论。","不必移鳄鱼，诡怪以疑民。","有若大颠者，高材能动人。","亦勿与为礼，听之汩彝伦。","同朝叙朋友，异姓接婚姻。","恩义乃独厚，怀哉余所陈。"]},{"t":"闻望之解舟","f":"五言律诗","c":["子来我乐只，子去悲如何。","谓言且少留，大舸已凌波。","闇黮虽莫测，皇明迈羲娥。","脩门归有时，京水非汨罗。"]},{"t":"食黍行","f":"七言古诗","c":["周公兄弟相杀戮，李斯父子夷三族。","富贵常多患祸婴，贫贱亦复难为情。","身随衣食南与北，至亲安能常在侧。","谓言黍熟同一炊，欻见陇上黄离离。","游人中道忽不返，从此食黍还心悲。"]},{"t":"骅骝","f":"五言古诗","c":["龙德不可系，变化谁能谋。","骅骝亦骏物，卓荦地上游。","怒行追疾风，忽忽跨九州。","辙迹古所到，山川略能周。","鸿蒙无人梯，沆漭绕天浮。","巉岩拔青冥，仙圣所止留。","欲往辄不能，视龙乃知羞。"]},{"t":"兼并","f":"五言古诗","c":["三代子百姓，公私无异财。","人主擅操柄，如天持斗魁。","赋予皆自我，兼并乃奸回。","奸回法有诛，势亦无自来。","后世始倒持，黔首遂难裁。","秦王不知此，更筑怀清台。","礼义日已偷，圣经久堙埃。","法尚有存者，欲言时所咍。","俗吏不知方，掊克乃为材。","俗儒不知变，兼并可无摧。","利孔至百出，小人私阖开。","有司与之争，民愈可怜哉。"]},{"t":"哭梅圣俞","f":"七言古诗","c":["诗行于世先春秋，国风变衰始柏舟。","文辞感激多所忧，律吕尚可谐鸣球。","先王泽竭士已偷，纷纷作者始可羞。","其声与节急以浮，真人当天施再流。","笃生梅公应时求，颂歌文武功业优。","经奇纬丽散九州，众皆少锐老则不。","翁独辛苦不能休，惜无采者人名遒。","贵人怜公青两眸，吹嘘可使高岑楼。","坐令隐约不见收，空能乞钱助饙馏。","疑此有物司诸幽，栖栖孔孟葬鲁邹。","后始卓荦称轲丘，圣贤与命相楯矛。","势欲强达诚无由，诗人况又多穷愁。","李杜亦不为公侯，公窥穷阨以身投。","坎轲坐老当谁尤，吁嗟岂即非善谋。","虎豹虽死皮终留，飘然载丧下阴沟。","粉书轴幅悬无旒，高堂万里哀白头。","东望使我商声讴。"]},{"t":"徐熙花","f":"七言律诗","c":["徐熙丹青盖江左，杏枝偃蹇花婀娜。","一见真谓值芳时，安知有人槃礴裸。","同朝众史共排媢，亦欲学之无自可。","锦囊深贮几春风，借问此木何时果。"]},{"t":"桃源行","f":"七言古诗","c":["望夷宫中鹿为马，秦人半死长城下。","避时不独商山翁，亦有桃源种桃者。","此来种桃经几春，采花食实枝为薪。","儿孙生长与世隔，虽有父子无君臣。","渔郎漾舟迷远近，花间相见因相问。","世上那知古有秦，山中岂料今为晋。","闻道长安吹战尘，春风回首一沾巾。","重华一去宁复得，天下纷纷经几秦。"]},{"t":"桑","f":"五言绝句","c":["溪桥接桑畦，钩笼晓群过。","今朝去何早，向晚蚕恐饿。"]},{"t":"烝然来思","f":"楚辞体","c":["念我独兮，亦莫我顾。","烝然来思，程伯休父。","我有旨酒，尔殽伊脯。","酌言酬之，式歌且舞。","不留不处，适彼乐土。","言秣其马，率西水浒。","有客宿宿，于时语语。","山有桥松江有渚，式遄其归不我与。","作此好歌，倡予和女。"]},{"t":"爱日","f":"五言古诗","c":["雁生阴沙春，冬息阳海澨。","冥冥取南北，岂以食为累。","咨予愁病躯，朴鄙人所戏。","无才治时难，量力当自弃。","岂知塞上霜，飘然亦何事。","高堂已白发，爱日负明义。","悲风吹平原，秣马聊一愒。","含怀孰与语，仰屋思叹喟。","孟母知身从，莱妻耻人制。","一肉傥易谋，万钟非得计。"]},{"t":"留题曲亲盆山","f":"七言律诗","c":["巧与天成未觉殊，国工施手岂须臾。","根连沧海蓬莱阔，势压黄河砥柱孤。","坐上烟岚生紫翠，影中楼阁见青朱。","为山观水皆良喻，谁向君家识所趋。"]},{"t":"病起","f":"五言律诗","c":["稚金敷新凉，老火灺残浊。","桃枝煖淟涊，散发晞晓捉。","烦痾脱然愈，静若遗身觉。","移榻攲独眠，欣佳恐难数。"]},{"t":"真人","f":"五言古诗","c":["予常值真人，能藏毒而宁。","能纳秽若净，能易膻使馨。","能解身赫赫，能逆知冥冥。","日唯汝心撄，而汝耳目荧。","廓然而无营，其孰扰汝灵。","神奇实主汝，厥通莫之令。","嘻予岂不知，黄帝与焦螟。","死心而废形，乃可少闻霆。","顾今亲遘之，于吾独剽聆。","刳心事斯语，自儆以书铭。"]},{"t":"秦始皇","f":"五言古诗","c":["天方猎中原，狐兔在所憎。","伤哉六孱王，当此鸷鸟膺。","搏取已扫地，翰飞尚凭凌。","游将跨蓬莱，以海为丘陵。","勒石颂功德，群臣助骄矜。","举世不读易，但以刑名称。","蚩蚩彼少子，何用辨坚冰。"]},{"t":"诸葛武侯","f":"五言古诗","c":["汉日落西南，中原一星黄。","群盗伺昏黑，联翩各飞扬。","武侯当此时，龙卧独摧藏。","掉头梁甫吟，羞与众争光。","邂逅得所从，幅巾起南阳。","崎岖巴汉间，屡以弱攻强。","晖晖若长庚，孤出照一方。","势欲起六龙，东回出扶桑。","惜哉沦中路，怨者为悲伤。","竖子祖馀策，犹能走强梁。"]},{"t":"读墨","f":"五言古诗","c":["谁为尧舜徒，孔子而已矣。","人皆是尧舜，未必知孔子。","伯夷不辱身，柳下援而止。","孔子尚有言，我则异于是。","兼爱为无父，排斥固其理。","孔墨必相用，自古宁有此。","退之嘲鲁连，顾未知之耳。","如何蔽于斯，独有见于彼。","凡人工自私，翟也信奇伟。","惜乎不见正，遂与中庸诡。","退之醇孟轲，而駮荀杨氏。","至其趣舍间，亦又蔽于己。","化而不自知，此语孰云俚。","咏言以自警，吾诗非好诋。"]},{"t":"陪友人中秋夕赏月","f":"五言律诗","c":["海雾看如洗，秋阳望却昏。","光明疑不夜，清瑩欲无坤。","扫掠风前坐，留连露下尊。","苦吟应到晓，况有我思存。"]},{"t":"陶缜菜示德逢","f":"七言律诗","c":["江南种菜漫阡陌，紫芥绿菘何所直。","陶生画此共言好，一幅往往黄金百。","北山老圃不外慕，但守荒畦斸荆棘。","陶生养目渠养腹，各以所能为物役。"]},{"t":"偶书","f":"五言绝句","c":["惠施说万物，槃特忘一句。","寄语读书人，呶呶非胜处。"]},{"t":"寄丁中允","f":"五言古诗","c":["人生九州閒，泛泛水中木。","漂浮随风波，邂逅得相触。","始我与夫子，得官同一州。","相逢皆偶然，情义乃绸缪。","我于人事疏，而子久矣修。","磨砻以成我，德大不可酬。","乖离今六年，念子未尝休。","岂不道相逢，但得顷刻留。","欢喜不满颜，长年抱离忧。","古人有所思，千里驾车牛。","如何咫尺间，而不与予游。","顾惜五斗米，无辜自拘囚。","念彼磊落者，心颜两惭羞。","剡山碧榛榛，剡水日夜流。","山行苦无巇，水浅亦可舟。","使君子所善，来檄自可求。","何时子来意，待子南山头。"]},{"t":"寄二弟时往临川","f":"五言古诗","c":["萧条冬风高，吹我冠上霜。","我行岁已寒，悲汝道路长。","持以犬马心，千里不得将。","使汝身百忧，辛苦冒川梁。","青灯照诗书，仰屋涕数行。","不有亲戚思，讵知远游伤。"]},{"t":"寄王逢原","f":"七言古诗","c":["北风吹云埋九垓，草木零落空池台。","六龙避逃不敢出，地上独有寒崔嵬。","披衣起行愁不惬，归坐把卷阖且开。","永怀古人今已矣，感此近世何为哉。","申韩百家爇火起，孔子大道寒于灰。","儒衣纷纷欲满地，无复气焰空煤炱。","力排异端谁助我，忆见夫子真奇材。","楩楠豫章概白日，秖要匠石聊穿裁。","我方官拘不得往，子有闲暇宜能来。","晤言相与入圣处，一取万古光芒回。"]},{"t":"寄平甫弟衢州道中","f":"七言律诗","c":["浅溪受日光烱碎，野林参天阴翳长。","幽鸟不见但闻语，小梅欲空犹有香。","长年无可自娱戏，远游虽好更悲伤。","安得冬风一吹汝，手把诗书来我旁。"]},{"t":"寄孙正之","f":"七言律诗","c":["少时已感韩子诗，东西南北俱欲往。","新年尤觉此语悲，恨无羽翼超惚恍。","肺肝欲绝形骸外，涕洟自落衣巾上。","此忧难与世共知，忆子论心更惆怅。"]},{"t":"寄朱氏妹","f":"五言古诗","c":["昔来高邮居，我始得朱子。","从容谈笑间，已足见奇伟。","行寻城阴田，坐钓渠下沚。","归来同食眠，左右皆图史。","入视尔诸幼，欢言亦多祉。","当时独张倩，远在庐山趾。","沈君未言昏，名已习吾耳。","安知十年来，乖隔非愿始。","相逢辄念远，悲吒多于喜。","今兹岂人力，所念皆聚此。","诸甥昔未有，满眼秀而美。","低徊吾亲侧，亦足慰劳止。","嗟予迫时恩，一传日千里。","尔舟亦已戒，五两翩然起。","萧萧东南县，望尔何时已。","空知梦为鱼，逆上西安水。"]},{"t":"寄朱昌叔","f":"七言律诗","c":["西安春风花几树，花边饮酒今何处。","一杯塞上看黄云，万里寄声无雁去。","世事纷纷洗更新，老来空得满衣尘。","青山欲买江南宅，归去相招有此身。"]},{"t":"寄吴氏女子","f":"五言古诗","c":["伯姬不见我，乃今始七龄。","家书无虚月，岂异常归宁。","汝夫缀卿官，汝儿亦搢綎。","儿已受师学，出蓝而更青。","女复知女功，婉嫕有典刑。","自吾舍汝东，中父继在廷。","小父数往来，吉音汝每聆。","既嫁可愿怀，孰如汝所丁。","而吾与汝母，汤熨幸小停。","丘园禄一品，吏卒给使令。","膏粱以晚食，安步而车軿。","山泉皋壤间，适志多所经。","汝何思而忧，书每说涕零。","吾庐所封殖，岁久愈华菁。","岂特茂松竹，梧楸亦冥冥。","芰荷美花实，瀰漫争沟泾。","诸孙肯来游，谁谓川无舲。","姑示汝我诗，知嘉此林坰。","末有拟寒山，觉汝耳目荧。","因之授汝季，季也亦淑灵。"]},{"t":"寄吴冲卿","f":"五言古诗","c":["物变极万殊，心通才一曲。","读书谓已多，抚事知不足。","与君语承华，念此非不夙。","恨无数顷田，归耕使成熟。","当官拙自计，易用忤流俗。","穷年走区区，得谤大于屋。","归来污省舍，又继故人躅。","相逢祇数步，吏桉常填目。","切嗟非无朋，阻阔嗟何速。","孤危失所助，把卷常恨独。","虚名终自误，谬恩何见蹙。","清明有冲卿，奥美如晦叔。","时谓当选升，屈指尚五六。","揆才最不称，饕宠宁无恧。","殷勤故人书，纸尾又见勖。","君虽好德言，我自望忠告。","易称动不括，传论大明服。","进为非成材，罪恐不容赎。","岁残东风生，陕树尘翳曲。","何缘一杯酒，谈笑相追逐。"]},{"t":"寄李士宁先生","f":"七言古诗","c":["楼台高耸间晴霞，松桧阴森夹柳斜。","渴愁如箭去年华，陶情满满倾榴花。","自嗟不及门前水，流到先生云外家。"]},{"t":"寄杨德逢","f":"五言古诗","c":["山樊老惮暑，独寤无所适。","湖阴宛在眼，旷若千里隔。","遥闻青秧底，复作龟兆坼。","占岁以知子，将勤而后食。","穿沟取西港，此计当未获。","翛翛两龙骨，岂得长挂壁。","晤言久不嗣，作苦何时息。","炎天不可触，怅望新舂白。"]},{"t":"寄岳州张使君","f":"七言古诗","c":["昔人宁饮建业水，共道不食武昌鱼。","公来建业每自如，亦复不厌武昌居。","武昌山川今可想，绿水逶迤烟莽苍。","白鸥晴飞随两桨，岸荠茸茸映鱼网。","投老留连陌上尘，思公一语何由往。"]},{"t":"寄郎侍郎","f":"七言律诗","c":["两朝人物叹贤豪，凛凛清风晚见褒。","江汉但归沧海阔，丘陵难学太山高。","放怀诗酒机先息，回首功名世自劳。","久愿作公樽俎客，恨无三亩斲蓬蒿。"]},{"t":"寄虔州江阴二妹","f":"五言古诗","c":["贡水日夜下，下与章水期。","我行二水间，无日不尔思。","飘若越鸟北，心常在南枝。","又如岐首蛇，南北两欲驰。","逝者日已远，百忧讵能追。","生存苦乖隔，邂逅亦何时。","女子归有道，善怀见于诗。","庶云留汝车，慰我堂上慈。"]},{"t":"寄曾子固","f":"词","c":["吾少莫与合，爱我君为最。","君名高山岳，嵑?嵩与泰。","低心收憃友，似不让尘?。","又如沧江水，不逆沟畎浍。","君身揭日月，遇辄破氛霭。","我材特穷空，无用补仓廥。","谓宜从君久，垢污得洮汰。","人生不可必，所愿每颠沛。","乖离五年馀，牢落千里外。","投身落俗阱，薄宦自钳釱。","平居每自守，高论从谁丐。","摇摇西南心，梦想与君会。","思君挟奇璞，愿售无良侩。","穷阎抱幽忧，凶祸费禳禬。","州穷吉士少，谁可婿诸妹。","仍闻病连月，医药谁可赖。","家贫奉养狭，谁与通货贝。","诗人刺曹公，贤者荷戈祋。","奈何遭平时，德泽盛汪濊。","鸾凤鸣且下，万羽来翙翙。","呦呦林间鹿，争出噬苹藾。","乃令高世士，动辄遭狼狈。","人事既难了，天理尤茫昧。","圣贤多如此，自古云无奈。","周人贵妇女，扁鹊名医滞。","今世无常势，趋舍唯利害。","而君信斯道，不闵身穷泰。","弃捐人间乐，濯耳受天籁。","谅知安肥甘，未肯顾糠糩。","龙螭虽蟠屈，不慕蛇蝉蜕。","令人重感奋，意勇忘身蕞。","何由日亲灸，病体同砭艾。","功名未云合，岁月尤须愒。","怀思切劘效，中夜泪霶霈。","君尝许过我，早晚治车轪。","山溪虽峻恶，高眺发蒙?。","峰峦碧参差，木树青晻蔼。","桐江路尤驶，飞桨下鸣濑。","鱼村指暮火，酒舍瞻晨旆。","清醪足消忧，玉鲫行可脍。","行行愿无留，日夕伫倾盖。","会将见颜色，不复谋蓍蔡。","延陵古君子，议乐耻言郐。","细事岂足论，故欲论其大。","披披发鞬櫜，懔懔见戈锐。","探深犯严壁，破惑翻强旝。","离行步荃兰，偶坐阴松桧。","宵床连衾帱，昼食共粗粝。","兹欢何时合，清瘦见衣带。","作诗寄微诚，诚语无綵绘。"]},{"t":"寄曾子固二首 其二","f":"五言古诗","c":["崔嵬天门山，江水绕其下。","寒渠已胶舟，欲往岂无马。","时恩缪拘缀，私养难乞假。","低徊适为此，含忧何时写。","吾能好谅直，世或非诡诈。","安得有一廛，相随问耕者。"]},{"t":"寄曾子固二首 其一","f":"五言古诗","c":["严严中天阁，蔼蔼层云树。","为子望江南，蔽亏无行路。","平生湖海士，心迹非无素。","老矣不自知，低徊如有慕。","伤怀西风起，心与河汉注。","哀鸿相随飞，去我终不顾。"]},{"t":"寄慎伯筠","f":"七言古诗","c":["世网挂士如蛛丝，大不及取小缀之。","宜乎倜傥不低敛，醉脚踏倒青天低。","前日才能始谁播，一口惊张万誇和。","雷公诉帝喘欲吹，咸恐声名塞天破。","文章喜以怪自娱，不肯裁缩要有馀。","多为峭句不姿媚，天骨老硬无皮肤。","人传书染莫对当，破卵惊出鸾凤翔。","人间下笔不肯屈，铁索急缠蛟龙僵。","少年意气强不羁，虎胁插翼白日飞。","欲将独立誇万世，笑诮李白为痴儿。","四天无壁才可家，醉胆愤痒遣酒拿。","欲偷北斗酌竭酒，力拔太华镳鲸牙。","世儒口软声似蝇，好于壮士为忌憎。","我独久仰愿一见，浩歌不敢儿女声。"]},{"t":"寄福公道人","f":"五言律诗","c":["帝力护禅林，沧洲侧布金。","楼依水月观，门接海潮音。","开士但软语，游人多苦吟。","曾同方丈宿，灯火夜沉沉。"]},{"t":"寄虞氏兄弟","f":"七言律诗","c":["一身兼抱百忧虞，忽忽如狂久废书。","畴昔心期俱丧勇，此来腰疾更乘虚。","久闻阳羡安家好，自度渊明与世疏。","亦有未归沟壑日，会应相近置田庐。"]},{"t":"寄阙下诸父兄兼示平甫兄弟","f":"七言律诗","c":["父兄为学众人知，小弟文章亦自奇。","家势到今宜有后，士才如此岂无时。","久闻阳羡溪山好，颇与渊明性分宜。","但愿一门皆贵仕，时将车马过茆茨。"]},{"t":"寄蔡氏女子二首 其二","f":"楚辞体","c":["我营兮北渚，有怀兮归女。","石梁兮以苫盖，绿阴阴兮承宇。","仰有桂兮俯有兰，嗟汝归兮路岂难。","望超然之白云，临清流而长叹。"]},{"t":"寄蔡氏女子二首 其一","f":"楚辞体","c":["建业东郭，望城西堠。","千嶂承宇，百泉绕霤。","青遥遥兮纚属，绿宛宛兮横逗。","积李兮缟夜，崇桃兮炫昼。","兰馥兮众植，竹娟兮常茂。","柳蔫绵兮含姿，松偃蹇兮献秀。","鸟跂兮下上，鱼跳兮左右。","顾我兮适我，有斑兮伏兽。","感时物兮念汝，迟汝归兮携幼。"]},{"t":"寄题众乐亭","f":"七言古诗","c":["陵阳游观吾所好，恨不即过众乐亭。","尝闻彷佛入梦寐，吟笔自欲图丹青。","千峰秀出百里外，忽于其上峥檐楹。","朝云嘘岩日暖暖，夜水落涧风泠泠。","春花窈窕鸟争舞，夏木荫郁猿哀鸣。","潦收叶落天地爽，海月影到山川明。","篮舆晨出谁与适，坐与万物观虚盈。","令思民事不忍后，田间笑语催蚕耕。","吏休归舍狱讼少，墟落饮酒欲秋成。","唯愁一日夺令去，出来老稚交逢迎。","彼民安知方禄仕，徒喜使我宽逋征。","令知道义士林服，遗爱岂用吾诗评。"]},{"t":"寄题睡轩","f":"五言古诗","c":["刘侯少慷慨，天马脱絷羁。","一官不得意，州县老委蛇。","新居当中条，墙屋稍补治。","疏轩以睡名，从我远求诗。","朝廷法令具，百吏但循持。","又况佐小邑，有才安所施。","赋租如簿领，狱讼了鞭笞。","翛然即高枕，于此乐可知。","王官有空谷，隐者常栖迟。","拂榻梦其人，亦足慰所思。","嗟予久留连，窃食坐无为。","浩歌临西风，更欲往从之。"]},{"t":"寄赠胡先生","f":"七言古诗","c":["先生天下豪杰魁，胸臆广博天所开。","文章事业望孔孟，不复睥睨蔡与崔。","十年留滞东南州，饱足藜藿安蒿莱。","独鸣道德惊此民，民之闻者源源来。","高冠大带满门下，奋如百蛰乘春雷。","恶人沮服善者起，昔时蹻蹠今骞回。","先生不试乃能尔，诚令得志如何哉。","吾愿圣帝营太平，补葺廊庙枝倾颓。","披旒发纩广耳目，照彻山谷多遗材。","先收先生作梁柱，以次构架桷与榱。","群臣面向帝深拱，仰戴堂陛方崔嵬。"]},{"t":"得曾子固书因寄","f":"五言古诗","c":["始吾居扬日，重问每见及。","云将自亲侧，万里同讲习。","子行何舒舒，吾望已汲汲。","穷年梦东南，颜色不可挹。","仁贤岂欺我，正恐事维絷。","严亲抱忧衰，生理赖以给。","不然航江外，天寒北风急。","无乃山路恶，仆弱马行涩。","孤怀未肯开，岁物忽如蛰。","朅来高邮住，巷屋颇卑湿。","蓬蒿稍芟除，茅竹随补葺。","苟云禦风气，尚恐忧雨汁。","故人莫在眼，屡独开巾笈。","忠信盖未见，吾敢诬兹邑。","出关谁与语，念子百忧集。","眺听聊自放，日暮城头立。","徐归坐当户，使者操书入。","时开识子意，如渴得美湆。","骊驹日就道，玉手行可执。","旧学待镌磨，新文得删拾。","重登城头望，喜气满原隰。"]},{"t":"悼四明杜醇","f":"五言古诗","c":["杜生四五十，孝友称乡里。","隐约不外求，耕桑有妻子。","藜杖牧鸡豚，筠筒钓鲂鲤。","岁时沽酒归，亦不乏甘旨。","天涯一杯饭，夙昔相逢喜。","谈辞足诗书，篇咏又清泚。","都城问越客，安否常在耳。","日月未渠央，如何弃予死。","古风久凋零，好学少为己。","悲哉四明山，此士今已矣。"]},{"t":"惜日","f":"五言古诗","c":["白日照四方，当在中天留。","春风地上行，当与时周游。","和气所披拂，槁乾却湿柔。","爱欲传万物，势难停一州。","栖栖孔子者，惜日此之由。","不能使此邦，利泽施诸侯。","岂若驾以行，使我遇者稠。","当时三千人，齐宋楚陈周。","小者传吾粗，大能传奥幽。","道散学以圣，众源乃常流。","吾初如匏瓜，彼亦孰知丘。","唯士欲自达，穷通非外求。","岂必相天子，乃能经九畴。","行虽耻强勉，闭户非良谋。"]},{"t":"望钟山","f":"五言绝句","c":["伫立望钟山，阳春更萧瑟。","暮寻北郭归，故绕东冈出。"]},{"t":"望晼山马上作","f":"五言古诗","c":["亘天青郁郁，千峰互崷崒。","放马倚长崖，烟云争吐没。","远疑嵩华低，近岂潜衡匹。","奚为鲜眺览，过者辄仓卒。","吾将凌其巅，震荡睨溟渤。","旁行告予言，世孰于此忽。","邃深不可俯，储藏尽妖物。","踊跃狼虎群，蜿蜒蛇虺窟。","惜哉危绝山，岁久沉汨没。","谁将除茀涂，万里游人出。"]},{"t":"梁王吹台","f":"五言古诗","c":["繁台繁姓人，埋灭为蒿蓬。","况乃汉骄子，魂游谁肯逢。","缅思当盛时，警跸在虚空。","蛾眉倚高寒，环佩吹玲珑。","大梁千万家，回首云濛濛。","仰不见王处，云间指青红。","宾客有司马，邹枚避其锋。","洒笔飞鸟上，为王赋雌雄。","惜今此不传，楚辞擅无穷。","空馀一丘土，千载播悲风。"]},{"t":"梦","f":"七言绝句","c":["知世如梦无所求，无所求心普空寂。","还似梦中随梦境，成就河沙梦功德。"]},{"t":"梦中作","f":"七言绝句","c":["青门道北云为屋，大垆贮酒千万斛。","独龙注雨如车轴，不畏不售畏不续。"]},{"t":"清凉寺送王彦鲁","f":"五言绝句","c":["空怀谁与论，梦境偶相值。","莫将漱流齿，欲挂功名事。"]},{"t":"移桃花示俞秀老","f":"七言古诗","c":["舍南舍北皆种桃，东风一吹数尺高。","枝柯蔫绵花烂熳，美锦千两敷亭皋。","晴沟涨春绿周遭，俯视红影移渔舠。","山前邂逅武陵客，水际彷佛秦人逃。","攀条弄芳畏晼晚，已见黍雪盘中毛。","仙人爱杏令虎守，百年终属樵苏手。","我衰此果复易朽，虫来食根那得久。","瑶池绀绝谁见有，更值花时且追酒。","君能酩酊相随否。"]},{"t":"跃马泉","f":"五言古诗","c":["古水缩蛟螭，憎山欲隳突。","山祇来伐之，半岭跳齧膝。","玉珂鸣塞空，组练光照日。","崩腾赴不测，一陷常万匹。","神战异人间，千秋为倏忽。","泉旁往来客，夜寄幽人室。","但听鸣萧萧，何由见神物。"]},{"t":"骐骥在霜野","f":"五言律诗","c":["骐骥在霜野，低徊向衰草。","入枥闻秋风，悲鸣思长道。","黄金作鞭辔，粲粲空外好。","人生贵得意，不必恨枯槁。"]},{"t":"黄菊有至性","f":"五言律诗","c":["团团城上日，秋至少光辉。","积阴欲滔天，况乃草木微。","黄菊有至性，孤芳犯群威。","采采霜露閒，亦足慰朝饥。"]},{"t":"寓言九首 其九","f":"五言律诗","c":["猛虎卧草间，群鸟从噪之。","万物忌强梁，宁独以其私。","虎终机械得，鸟亦弹丸随。","山鸡不忤物，默与凤凰期。"]},{"t":"寓言九首 其六","f":"五言律诗","c":["言失于须臾，百世不可除。","行失几席间，恶名满八区。","百年养不足，一日毁有馀。","谅彼耻不仁，戒哉惟厥初。"]},{"t":"寓言九首 其五","f":"五言律诗","c":["贞观业万世，经营岂非艰。","其子一摇之，宗庙灵几殚。","开元始聪明，一眚奔岷山。","功高后毁易，德薄人存难。"]},{"t":"寓言九首 其四","f":"五言律诗","c":["婚丧孰不供，贷钱免尔萦。","耕收孰不给，倾粟助之生。","物赢我收之，物窘出使营。","后世不务此，区区挫兼并。"]},{"t":"寓言九首 其三","f":"五言律诗","c":["周公歌七月，耕稼乃王术。","宣王追祖宗，考牧与宫室。","甘棠能听讼，召伯圣人匹。","后生论常高，于世复何实。"]},{"t":"寓言九首 其二","f":"五言古诗","c":["不得君子居，而与小人游。","疵瑕不相摩，况乃祸衅稠。","高语不敢出，鄙辞强颜酬。","始云避世患，自觉日已偷。","如傅一齐人，以万楚人咻。","云复学齐言，定复不可求。","仁义多在野，欲从苦淹留。","不悲道难行，所悲累身修。"]},{"t":"寓言九首 其一","f":"五言律诗","c":["诜诜古之士，出必见礼乐。","群游与群饮，仁义待扬搉。","心疲歌舞荒，耳聒米盐浊。","所以后世贤，绝俗乃为学。"]},{"t":"寓言九首 其七","f":"五言律诗","c":["钟鼓非乐本，本末犹相因。","仁声入人深，孟子言之醇。","如何贞观君，从古同隋陈。","风俗不粹美，惜哉世无臣。"]},{"t":"寓言九首 其八","f":"五言律诗","c":["游鲸厌海浊，出戏清江湄。","风涛助翻腾，网罟不敢窥。","失身洲渚间，蝼蚁乘其机。","物大苦易穷，一穷无所归。"]},{"t":"寓言六首 其六","f":"五言律诗","c":["好乐世所共，欲禁安能舍。","孰能开其淫，要在习以雅。","驱人必如己，墨子见何寡。","惜哉后世音，至美不如野。"]},{"t":"寓言六首 其五","f":"五言律诗","c":["明者好自蔽，况乃知我匹。","每行悔其然，所见定万一。","不求攻尔短，欲议世之失。","耘而舍其田，辛苦亦何实。"]},{"t":"寓言六首 其四","f":"五言律诗","c":["始就诗赋科，雕镌久才成。","一朝复弃之，刀笔事刑名。","中材蔽末学，斯道苦难明。","忽贵不自期，何施就升平。"]},{"t":"寓言六首 其三","f":"五言律诗","c":["瞢瞢俗所共，察察与世违。","违世有百善，一疵恶皆归。","就求无所得，犹以好名讥。","彼哉负且乘，能使正日微。"]},{"t":"寓言六首 其二","f":"五言律诗","c":["小夫谨利害，不讲义与仁。","读书疑夷齐，古岂有此人。","其才一莛芒，所欲势万钧。","求多卒自困，馀祸及生民。"]},{"t":"寓言六首 其一","f":"五言律诗","c":["父母子所养，子肥父母充。","欲富搉其子，惜哉术之穷。","霸者擅一方，窘彼足自丰。","四海皆吾家，奈何不知农。"]},{"t":"强起","f":"五言古诗","c":["寒堂耿不寐，辘辘闻车声。","不知谁家儿，先我霜上行。","叹息夜未央，遽呼置前楹。","推枕欲强起，问知星正明。","昧旦圣所勉，齐诗有鸡鸣。","嗟予以窃食，更觉负平生。"]},{"t":"彭蠡","f":"七言古诗","c":["茫茫彭蠡春无地，白浪春风湿天际。","东西捩柂万舟回，千岁老蛟时出戏。","少年轻事镇南来，水怒如山帆正开。","中流蜿蜒见脊尾，观者胆堕予方咍。","衣冠今日龙山路，庙下沽酒山前住。","老矣安能学佽飞，买田欲溯江湖去。"]},{"t":"悲哉孔子没","f":"五言律诗","c":["悲哉孔子没，千岁无麒麟。","蚩蚩尽锄商，此物谁能珍。","汉武得一角，燔烹诬鬼神。","更以铸黄金，传夸后世人。"]},{"t":"散发一扁舟","f":"五言律诗","c":["散发一扁舟，夜长眠屡起。","秋水泻明河，迢迢藕花底。","爱此露的皪，复怜云绮靡。","谅无与歌弦，幽独亦可喜。"]},{"t":"朝日一曝背","f":"五言律诗","c":["朝日一曝背，欣然忘夜寒。","樵松煮涧水，既食取琴弹。","弹作南风歌，歌罢坐长叹。","寤彼栖栖者，遗世良独难。"]},{"t":"游土山示蔡天启秘校","f":"五言古诗","c":["定林瞰土山，近乃在眉睫。","谁谓秦淮广，正可藏一艓。","朝予欲独往，扶惫强登涉。","蔡侯闻之喜，喜色见两颊。","呼鞍追我马，亦以两黥挟。","敛书付衣囊，裹饭随药笈。","翛翛阿兰若，土木老山胁。","鼓钟卧空旷，簨簴雕捷业。","升堂廓无主，考击谁敢辄。","坡陀谢公冢，藏椁久穿劫。","百金买酒地，野老今行馌。","缅怀起东山，胜践比稠叠。","于时国累卵，楚夏血常喋。","外实备艰梗，中仍费调燮。","公能觉如梦，自喻一蝴蝶。","桓温适自毙，苻坚方天厌。","且可缓九锡，宁当快一捷。","彼哉斗筲人，得丧易矜怯。","妄言屐齿折，吾欲刊史牒。","伤心新城埭，归意终难惬。","漂摇五城舟，尚想浮河楫。","千秋陇东月，长照西州堞。","岂无华屋处，亦捉蒲葵箑。","碎金谅可惜，零落随秋叶。","好事所传玩，空残法书帖。","清谈眇不嗣，陈迹恍如接。","东阳故侯孙，少小同鼓箧。","一官初岭海，仰视飞鸢跕。","穷归放款段，高卧停远蹀。","牵襟肘即见，著帽耳才擪。","数椽危败屋，为我炊陈浥。","虽无膏污鼎，尚有羹濡筴。","纵言及平生，相视开笑靥。","邯郸枕上事，且饮且田猎。","或昏眠委翳，或妄走超躐。","或叫号而寤，或哭泣而魇。","幸哉同圣时，田里老安帖。","易牛以宝剑，击壤胜弹铗。","追怜衰晋末，此土方岌业。","强偷须臾乐，抚事终愁惵。","予虽天戮民，有械无接摺。","翁今贫而静，内热非复叶。","予衰极今岁，傥与鸡梦协。","委蜕亦何恨，吾儿已长鬣。","翁虽齿长我，未见白可镊。","祝翁尚难老，生理归善摄。","久留畏年少，讥我两呫嗫。","束火扶路还，宵明狐兔慑。","蔡侯雄俊士，心憭形亦谍。","异时能飞鞚，快若五陵侠。","胡为阡陌间，踠足仅相蹑。","谅欲交辔语，呿予不能嗋。"]},{"t":"游章义寺","f":"五言古诗","c":["九日章义寺，倦游因解镳。","拂榻寄午梦，起寻北山椒。","岑蔚鸟绝迹，悲鸣唯一蜩。","欢言与僧期，于此共箪瓢。","斩松八九根，窗壁具一朝。","伏槛何所见，苍苍围寂寥。","岩谷寒更静，水泉清不摇。","安得有车马，尚无渔与樵。","神茂真观复，心明众尘消。","阴岭有嘉客，傥来不须招。"]},{"t":"登景德塔","f":"五言古诗","c":["放身千仞高，北望太行山。","邑屋如蚁冢，蔽亏尘雾间。","念此屋中人，当复几人闲。","鸡鸣起四散，暮夜相与还。","物物各自我，谁为贤与顽。","贱气即易凌，贵气即难攀。","愧予心未齐，俛首一破颜。"]},{"t":"登越州城楼","f":"七言律诗","c":["越山长青水长白，越人长家山水国。","可怜客子无定宅，一梦三年今复北。","浮云缥缈抱城楼，东望不见空回头。","人间未有归耕处，早晚重来此地游。"]},{"t":"答扬州刘原甫","f":"五言古诗","c":["少食苦不足，一官聊自谋。","为生晚更拙，怀禄尚迟留。","黾勉讵有补，强颜包众羞。","谓我古人风，知君以相优。","君实高世才，主恩正绸缪。","哿矣哀此民，华簪宁易投。"]},{"t":"答许秀才","f":"五言律诗","c":["高阳有才子，负笈求晨饘。","所趣少知者，其辞多慨然。","樵妻竟谢绝，漂母尝哀怜。","尚友古之人，于今犹壮年。"]},{"t":"答陈正叔","f":"五言古诗","c":["天马志万里，驾盐不如闲。","壮士困局束，不如弃之完。","利行有阨辙，势涉无恬澜。","明明千年羞，促促一日欢。","孰肯避此世，引身取平宽。","超然子有意，为我歌考槃。","予方慕孔氏，委吏久盘桓。","得失未云殊，聊各趋所安。"]},{"t":"答客","f":"五言律诗","c":["士常疑西伯，何至羑里辱。","瞽鳏亲父子，尚脱井廪酷。","昏主虽圣臣，飞祸安可卜。","致命遂其志，虽穷不为戮。"]},{"t":"答曾子固南丰道中所寄","f":"五言古诗","c":["吾子命世豪，术学穷无閒。","直意慕圣人，不问闵与颜。","彼昏何为者，诬构来㘖㘖。","应逮犯秋阳，动为人所叹。","不恤我躬瘁，乃嗟天泽悭。","令人念公卿，烨烨趋王班。","泊无悯世意，狙猿而佩环。","爱子所守卓，忧予不能攀。","永矢从子游，合如扉上镮。","愿言借馀力，迎浦疏潺潺。","亦有衣上尘，可攀禆泰山。","大江秋正清，岛溆相萦弯。","四盼浩无主，日暮烟霞斑。","水竹密以劲，霜枫衰更殷。","赏托亦云健，行矣非閒关。","相期东北游，致馆淮之湾。","无为袭宁嬴，悠然及温还。"]},{"t":"答瑞新十远","f":"五言律诗","c":["远水悠然碧，远山天际苍。","中有山水人，寄我十远章。","我时在高楼，徙倚观八荒。","亦复有远意，千载不相忘。"]},{"t":"答虞醇翁","f":"五言古诗","c":["辍学以从仕，仕非吾本谋。","欲归谅不能，非敢忘林丘。","临餐耻苟得，冀以尽心酬。","万事等画墁，虽勤亦何收。","扬扬古之人，彼职乃无忧。","感子抚我厚，欲言秪惭羞。"]},{"t":"答裴煜道中见寄","f":"七言律诗","c":["君游苦数归苦晚，一驿险有千里远。","知君陟降旦暮间，马力不劲厌长坂。","雨脚坠地花枝低，风头入溪蒲叶偃。","此处登临不奈愁，琼树森森遮叠巘。"]},{"t":"翛然","f":"七言绝句","c":["翛然三月闭柴荆，绿叶阴阴忽满城。","自是老年游兴少，春风何处不堪行。"]},{"t":"葛蕴作巫山高爱其飘逸因亦作两篇 其一","f":"词","c":["巫山高，十二峰。","上有往来飘忽之猿猱，下有出没瀺灂之蛟龙，中有倚薄缥缈之神宫。","神人处子冰雪容，吸风饮露虚无中。","千岁寂寞无人逢，邂逅乃与襄王通。","丹崖碧嶂深重重，白月如日明房栊。","象床玉几来自从，锦屏翠幔金芙蓉。","阳台美人多楚语，秖有纤腰能楚舞，争吹凤管鸣鼍鼓。","那知襄王梦时事，但见朝朝暮暮长云雨。"]},{"t":"葛蕴作巫山高爱其飘逸因亦作两篇 其二","f":"词","c":["巫山高，偃薄江水之滔滔。","水于天下实至险，山亦起伏为波涛。","其巅冥冥不可见，崖岸斗绝悲猿猱。","赤枫青栎生满谷，山鬼白日樵人遭。","窈窕阳台彼神女，朝朝暮暮能云雨。","以云为衣月为褚，乘光服暗无留阻。","昆崙曾城道可取，方丈蓬莱多伴侣。","块独守此嗟何求，况乃低徊梦中语。"]},{"t":"董伯懿示裴晋公平淮右题名碑诗用其韵和酬","f":"词","c":["元和伐蔡何危哉，朝廷百口无一谐。","盗伤中丞偶不死，利剑白日投天街。","裹疮入相议军旅，国火一再更檀槐。","上前慷慨语发涕，誓出按抚除睽乖。","指撝光颜战洄曲，阚如怒虎搏虺豺。","愬能捕虏取肝鬲，护送密乞完形骸。","笞兵夜半投死地，雪湿不敢燃薪䕸。","空城竖子已可缚，中使尚作啼儿哇。","退之道此尤俊伟，当镂玉牒东燔柴。","欲编诗书播后嗣，笔墨虽巧终类俳。","唐从天宝运中圮，廊庙往往非忠佳。","诸侯纵横代割据，疆土岂得无离?。","德宗末年惩战祸，一矢不试尘蒙靫。","宪皇初起众未信，意欲立扫除昏霾。","追还清明救薄蚀，屡敕主府拘穷蛙。","王师伤夷征赋窘，千里亦忌毫釐差。","小夫偷安自非计，长者远虑或可怀。","桓桓晋公忠且壮，时命适与功名偕。","是非末世主成败，烜赫今古谁讥排。","贤哉韦纯议北赦，仓卒两伐尤难皆。","重华声明弥万国，服苗干羽舞两阶。","宣王侧身内脩政，常德立武能平淮。","昔人经纶初若缓，欲弃此道非吾侪。","千秋事往踪迹在，岳石款记如湘崖。","文严字丽皆可喜，黄埃蔽没苍藓埋。","当时将佐尽豪杰，想此兵祷陪祠斋。","君曾西迁为拓本，濡麝割蜜亲劘揩。","新篇波澜特浩荡，把卷熟读迷津涯。","褒贤乐善自为美，当挂庙壁为诗牌。"]},{"t":"谢公墩","f":"五言古诗","c":["走马白下门，投鞭谢公墩。","昔人不可见，故物尚或存。","问樵樵不知，问牧牧不言。","摩挲苍苔石，点检屐齿痕。","想此絓长樯，想此倚短辕。","想此玩云月，狼籍盘与樽。","井径亦已没，漫然禾黍村。","摧藏羊昙骨，放浪李白魂。","亦已同山丘，缅怀莳兰荪。","小草戏陈迹，甘棠咏遗恩。","万事付鬼箓，耻荣何足论。","天机自开阖，人理孰畔援。","公色无惧喜，傥知祸福根。","涕泪对桓伊，暮年无乃昏。"]},{"t":"赋枣","f":"词","c":["种桃昔所传，种枣予所欲。","在实为美果，论材又良木。","馀甘入邻家，尚得馋妇逐。","况余秋盘中，快啖取餍足。","风包堕朱缯，日颗皱红玉。","贽享古已然，豳诗自宜录。","?怀青齐间，万树荫平陆。","谁云食之昏，匿知乃成俗。","广庭觞圣寿，以此参肴蔌。","愿比赤心投，皇明傥予烛。"]},{"t":"道人北山来","f":"五言古诗","c":["道人北山来，问松我东冈。","举手指屋脊，云今如此长。","开田故岁收，种果今年尝。","告叟去复来，耘锄尚康强。","死狐正首丘，游子思故乡。","嗟我行老矣，坟墓安可忘。"]},{"t":"集禧观池上咏野鹅","f":"七言律诗","c":["池上野鹅无数好，晴天镜里雪毰毸。","似怜暄暖鸣相逐，疑恋宽闲去却回。","京洛尘沙工点污，江湖矰弋饱惊猜。","羽毛的的人难近，嗟此谋身或有才。"]},{"t":"韩信","f":"七言古诗","c":["韩信寄食常歉然，邂逅漂母能哀怜。","当时哙等何由伍，但有淮阴恶少年。","谁道萧曹刀笔吏，从容一语知人意。","坛上平明大将旗，举军尽惊王不疑。","救兵半楚潍半沙，从初龙且闻信怯。","鸿沟天下已横分，谈笑重来卷楚氛。","但以怯名终得羽，谁为孔费两将军。"]},{"t":"韩持国从富并州辟","f":"词","c":["韩侯冰玉人，不可尘土杂。","官虽众俊后，名字久訇磕。","并州天下望，抚士威爱惬。","千金弃不惜，宾客常满閤。","遥闻馀风高，为子置一榻。","亲交西门饯，百马骄杂遝。","子材宜用世，谈者为呜唈。","矧今名主人，气力足呵欱。","推贤为时辅，势若朽易拉。","会当荐还朝，立子在阊阖。","惜哉秣骐骥，赋以升龠合。","咨予栖栖者，气象已摧塌。","他年佐方州，说将尚不纳。","况于声势尊，岂易取酬答。","有如持寸莛，未足撼鞺鞳。","顾于山水閒，意愿多所合。","匡庐与韶石，少小已尝蹋。","风游会稽春，雪宿天柱腊。","淮湖江海上，惯食虾蟹蛤。","西南穷岷嶓，东北尽济漯。","身虽未尝历，魂梦已稠沓。","荆溪最所爱，映烛多庙塔。","溪果点丹漆，溪花团并罨。","扁舟信所过，行不废樽榼。","一从舍之去，霜雪行满颌。","思之不能寐，蹙若虻蚋噆。","方将筑其滨，毕景谢噂?。","安能孤此意，颠倒就衰飒。","唯子余所向，嗜好比鹣鲽。","何时归相过，游屐尚可蜡。"]},{"t":"韩持国见访","f":"五言古诗","c":["余生非匏瓜，于世不无求。","弱力惮耕稼，衣食当周流。","起家始二十，南北今白头。","愁伤意已败，罢病恐难瘳。","江湖把一节，屡乞东南州。","治民岂吾能，閒僻庶可偷。","谬恩当徂冬，黾勉始今秋。","岂敢事高蹇，茫然乖本谋。","抚心私自怜，仰屋窃叹愀。","强骑黄饥马，欲语将谁投。","赖此城下宅，数蒙故人留。","揽衣坐中庭，仰视白云浮。","白云御西风，一一向沧洲。","安得两黄鹄，跨之与云游。"]},{"t":"塞翁行","f":"七言律诗","c":["塞翁少小垄上锄，塞翁老来能捕鱼。","鱼长如人水满眼，桑柘死尽生芙蕖。","汉家新堤广能筑，胡儿壮马休南牧。","北风卷却波浪声，祇放田车行轣辘。"]},{"t":"感事","f":"五言古诗","c":["贱子昔在野，心哀此黔首。","丰年不饱食，水旱尚何有。","虽无剽盗起，万一且不久。","特愁吏之为，十室灾八九。","原田败粟麦，欲诉嗟无赇。","间关幸见省，笞扑随其后。","况是交冬春，老弱就僵仆。","州家闭仓庾，县吏鞭租负。","乡邻铢两徵，坐逮空南亩。","取赀官一毫，奸桀已云富。","彼昏方怡然，自谓民父母。","朅来佐荒郡，懔懔常惭疚。","昔之心所哀，今也执其咎。","乘田圣所勉，况乃余之陋。","内讼敢不勤，同忧在僚友。"]},{"t":"新花","f":"五言律诗","c":["老年少忻豫，况复病在床。","汲水置新花，取慰此流芳。","流芳秪须臾，我亦岂久长。","新花与故吾，已矣两可忘。"]},{"t":"蒙亭","f":"五言古诗","c":["隐者委所逢，在物无不足。","山林与城市，语道归一毂。","诗人论巨细，此指尚局束。","颇知区区者，自屏忍所欲。","孰识古之人，超然遗耳目。","岂于喧与静，趣舍有偏独。","命亭今何为，似乃畏惊俗。","至意不标揭，小名聊自属。","夏风檐楹寒，冬雪窗户燠。","春樊乱梅柳，秋径深松菊。","壶觞日笑傲，裙屣相追逐。","此乐已难言，持琴作新曲。"]},{"t":"解使事泊棠阴时三弟皆在京师二首 其二","f":"五言古诗","c":["泊船棠阴下，滩水清且浅。","回首望孤城，浮云一何缅。","久留非吾意，欲去犹缱绻。","驰心故人侧，一望三四反。","萧萧东堂竹，异日留息偃。","无恩被南国，疑此行当剪。"]},{"t":"解使事泊棠阴时三弟皆在京师二首 其一","f":"五言古诗","c":["始吾泊棠阴，三子不在舟。","今当舍之去，三子还远游。","茫然千里水，今见荻花洲。","俛仰换春冬，纷纷空百忧。","怀哉山川异，往矣霰雪稠。","登高一涕泗，寄此寒江流。"]},{"t":"酬王伯虎","f":"五言古诗","c":["吾闻人之初，好恶尚无朕。","帝与凿耳目，贤愚遂殊品。","尔来百千年，转化薄愈甚。","父翁相贩卖，浮诈谁能审。","睢盱猴缨冠，狼籍鼠穴寝。","沧海恐值到，谁论鱼鳖淰。","鸮声虽云恶，革去在食葚。","嗟谁职教化，独使此风稔。","恬观不知救，坐费太官廪。","予生少而戆，好古乃天禀。","念此俗衰坏，何尝敢安枕。","有时不能平，悲吒失食饮。","唯子同我病，亦或涕沾衽。","谓予可告语，密以诗来谂。","烂然辞满纸，秋水濯新锦。","穷观何拳拳，静念复凛凛。","贱贫欲救世，无宁犹拾沈。","说穷且版筑，尹屈唯烹饪。","逢时岂遽废，避俗聊须噤。","徂年幸未暮，此意可勤恁。"]},{"t":"酬王浚贤良松泉二诗 其一 松","f":"七言古诗","c":["世传寿可三松倒，此语难为常人道。","人能百岁自古稀，松得千年未为老。","我移两松苦不早，岂望见渠身合抱。","但怜众木总漂摇，颜色青青终自保。","兔丝茯苓会当有，邂逅食之能寿考。","不知篝火定何人，且看森垂覆荒草。","君诗爱我亦古意，秀眉昔比南山栲。","复谓留侯不及我，人或笑君无白皂。","求仙辟谷彼诚误，未见赤松饥已槁。","岂如强饭适志游，封殖苍官荫华皓。","赤松复自无特操，上下随烟何慅慅。","苍官受命与舜同，真可从之忘发缟。","诗虽祝我以再黑，积雪已多安可扫。","试问苍官值岁寒，戴白孰与苍然好。"]},{"t":"酬王浚贤良松泉二诗 其二 泉","f":"七言古诗","c":["宋兴古刹今长干，灵曜台殿荒檀栾。","二泉相望弃不渫，西泉尚累三石槃。","其流散漫为沮洳，稍集小砾生微澜。","东泉土梗久蔽塞，穿治乃见甃甓完。","道人慈哀波及远，沟荡两取合土山。","山前灌输各自足，辘轳罢转井口闲。","取遥比甘觉近美，与旧争冽知新寒。","爞爞夏秋百源乾，抱瓮复道愁蹒跚。","疾倾横逗势未足，嗟此善利何时殚。","虑长易脆有大檀，伐坚羌庐窟孱颜。","金多匠手肯出巧，风水千里安知难。","没羽之虎行林间，箨龙失职因藏跧。","循除静投悲瑟瑟，映瓦微见清潺潺。","三年营之一日就，有口共以成为欢。","论功信可侈后观，何似当时万竹蟠。"]},{"t":"酬王詹叔奉使江南访茶法利害见寄","f":"五言古诗","c":["余闻古之人，措法贻厥后。","命官惟贤材，职事又习狃。","止能权轻重，王府则多有。","岂尝搉其子，而为民父母。","当时所经营，今十已毁九。","其一虽幸在，漂摇亦将朽。","公卿患才难，州县固多苟。","诏令虽数下，纷纷谁与守。","官居甚传舍，位以声势受。","既不责施为，安能辨贤不。","区区欲救弊，万谤不容口。","天下大安危，谁当执其咎。","劳心适有罪，养誉终天丑。","岂惟祖子孙，教戒及朋友。","贵者大其领，诗人歌四牡。","至尊空独忧，不敢乐饮酒。","哿矣富阡陌，哀哉此无糗。","乡闾人所怀，今或弃而走。","岂无济时术，使尔安畎亩。","故今二三公，戮力思矫揉。","永惟东南害，茶法盖其首。","私藏与窃贩，犴狱常纷纠。","输将一不足，往往死鞭杻。","贩陈彼杂恶，强卖曾非诱。","已云困关市，且复搔林薮。","将更百年弊，谓民知可否。","出节付群材，询谋欲经久。","朝廷每若此，自可跻仁寿。","因知从今始，渐欲人财阜。","吾宗恢奇士，选使自朝右。","聪明谅多得，为上归析剖。","王程虽薄遽，邦法难卤莽。","愿君博咨诹，无择壮与耇。","余知茶山民，不必生皆厚。","独当征求任，尚恐难措手。","孔称均无贫，此语今可取。","譬欲轻万钧，当令众人负。","强言岂宜当，聊用报琼玖。"]},{"t":"酬冲卿月晦夜有感","f":"五言古诗","c":["夜云不见天，况乃星与月。","萧萧暗尘走，坎坎寒更发。","楼歌客尚饮，酩酊不畏雪。","巷哭复有人，邻风送幽咽。","纷然各所遇，悲喜孰优劣。","君方感庄周，浩荡摆羁绁。","归来亦置酒，玉指调弦拨。","独我坐无为，青灯对明灭。"]},{"t":"酬微之梅暑新句","f":"七言律诗","c":["江梅落尽雨昏昏，去马来牛漫不分。","当此沈阴无白日，岂知炎旱有彤云。","琴弦欲缓何妨促，画蠹微生故可熏。","回首凉秋知未远，会须重曝阮郎裈。"]},{"t":"鲍公水","f":"词","c":["村南鲍公山，山北鲍公水。","高穴逗远源，泠泠落山嘴。","玉色与饴味，不可他味比。","竹树四蒙密，翠藤相披靡。","漫郎昔少年，幽居得之此。","临窥若有遇，爱叹无时已。","浮名未污染，永矢终焉尔。","奈何中弃入长安，十载风尘化旧颜。","欢嚣满耳不可洗，此水泠泠空在山。"]},{"t":"僧德殊家水帘求予咏","f":"七言律诗","c":["淙淙万音落石颠，皎皎一派当檐前。","清风高吹鸾鹤唳，白日下照蛟龙涎。","浮云妆额自能卷，缺月琢钩相与县。","朱门试问幽人价，翡翠鲛绡不直钱。"]},{"t":"臧仓","f":"五言律诗","c":["位在万乘师，孟轲犹不遇。","岂云贫与贱，世道非吾趣。","意行天下福，事忤由然去。","命也固有在，臧仓汝何与。"]},{"t":"酴醾金沙二花合发","f":"七言律诗","c":["相扶照水弄春柔，发似矜夸敛似羞。","碧合晚云霞上起，红争朝日雪边流。","我无丹白知如梦，人有朱铅见即愁。","疑此冶容诗所忌，故将樛木比绸缪。"]},{"t":"嘲叔孙通","f":"七言绝句","c":["马上功成不喜文，叔孙绵蕝共经纶。","诸君可笑贪君赐，便许当时作圣人。"]},{"t":"题永昭陵","f":"五言绝句","c":["神阙澹朝晖，苍苍露未晞。","龙车不可望，投老涕沾衣。"]},{"t":"题定林壁","f":"五言绝句","c":["定林自有主，我为林下客。","客主各有心，还能共岑寂。"]},{"t":"题宝岩寺寒碧亭二首 其二","f":"五言绝句","c":["风吹洞口云，水动山头月。","野老时问人，前村多少雪。"]},{"t":"题南康晏史君望云亭","f":"七言古诗","c":["南康父老传史君，疾呼急索初不闻。","未尝遣汲谷帘水，三岁只望香炉云。","云徐无心澹无滓，史君恬静亦如此。","飙然一去扫遗阴，便觉歊烦怅千里。","归田负戴子与妻，圃蔬园果西山西。","出门亭皋百顷绿，望云才喜雨一犁。","我知新亭望云好，欲斸比邻成二老。","莫嫌鸡黍数往来，为报襄阳德公嫂。"]},{"t":"澶州","f":"七言古诗","c":["去都二百四十里，河流中间两城峙。","南城草草不受兵，北城楼橹如边城。","城中老人为予语，契丹此地经钞虏。","黄屋亲乘矢石间，胡马欲踏河冰渡。","天发一矢胡无酋，河冰亦破沙水流。","欢盟从此至今日，丞相莱公功第一。"]},{"t":"澶州","f":"五言古诗","c":["津津河北流，嶭嶭两城峙。","春秋诸侯会，澶渊乃其地。","书留后世法，岂独讥当世。","野老岂知此，为予谈近事。","边关一失守，北望皆胡骑。","黄屋亲乘城，穹庐矢如猬。","纷纭擅将相，谁为开长利。","焦头收末功，尚足誇一是。","欢盟从此数，日月行人至。","驰迎传马单，走送牛车疲。","征求事供给，厮养犹珍丽。","戈甲久已销，澶人益憔悴。","能将大事小，自合文王意。","语翁无叹嗟，小雅今不废。"]},{"t":"燕侍郎山水","f":"七言古诗","c":["往时濯足潇湘浦，独上九疑寻二女。","苍梧之野烟漠漠，断垄连冈散平楚。","暮年伤心波浪阻，不意画中能更睹。","燕公侍书燕王府，王求一笔终不与。","奏论谳死误当赦，全活至今何可数。","仁人义士埋黄土，祗有粉墨归囊褚。"]},{"t":"赠王居士","f":"五言绝句","c":["武林王居士，与子俱学佛。","以财供佛事，不自费一物。"]},{"t":"赠约之","f":"五言律诗","c":["君胸寒而痞，我齿热以摇。","无方可救药，相值久无憀。","欲寻秦越人，魂逝莫能招。","但当观此身，不实如芭蕉。"]},{"t":"赠张康","f":"五言古诗","c":["昔在历阳时，得子初江津。","手中紫团参，一饮宽吾亲。","舍舟城南居，杖屦日相因。","百口代起伏，呻呼聒比邻。","叩门或夜半，屡费药物珍。","欲报恨不得，肠胃盘车轮。","今逢又坎坷，令子驰风尘。","颠倒车马间，起先冰雪晨。","嗟我十五年，得禄尚辞贫。","所读漫累车，岂能苏一人。","无求愧子义，有施惭子仁。","逝将收桑榆，邀子寂寞滨。"]},{"t":"赠李士云","f":"五言古诗","c":["李子山水人，而常寓城郭。","毫端出窈窕，心手初不著。","我闻大梵天，擎跨鸡孔雀。","执铃扬赤幡，浩劫净无作。","佳哉子能图，可以慰寂寞。","相与验其真，他年在寥廓。"]},{"t":"赠陈君景初","f":"五言古诗","c":["吾尝奇华佗，肠胃真割剖。","神膏既傅之，顷刻活残朽。","昔闻今则信，绝伎世尝有。","堂堂颍川士，察脉极渊薮。","珍丸起病瘠，鲙虫随泄呕。","挛足四五年，下针使之走。","一言傥不合，万金莫可诱。","又复能赋诗，往往吹琼玖。","卷纸誇速成，语怪若神授。","名声动京洛，踪迹晦莨莠。","相逢但长啸，遇饮辄掩口。","独醒竟何如，无乃寡俗偶。","顾非避世翁，疑是壁中叟。","安得斯人术，付之经国手。"]},{"t":"赠宝觉","f":"五言古诗","c":["大师京国旧，兴趣江湖迥。","往与惠询辈，一宿金山顶。","怀哉苦留恋，王事有朝请。","别来能几时，浮念剧含梗。","今朝忽相见，眸子清炯炯。","夜阑接软语，令人发深省。","化城出天半，远色有诸岭。","白首对汀洲，犹思理烟艇。"]},{"t":"赠彭器资","f":"七言古诗","c":["鄱水滔天竟东注，气泽所钟贤可慕。","文章浩渺足波澜，行义迢迢有归处。","中江秋浸两崖间，溯洄与我相往还。","我挹其清久未竭，复得纵观于波澜。","放言深入妙云海，示我仙圣本所寰。","楞伽我亦见彷佛，岁晚所悲行路难。"]},{"t":"赠曾子固","f":"七言律诗","c":["曾子文章众无有，水之江汉星之斗。","挟才乘气不媚柔，群儿谤伤均一口。","吾语群儿勿谤伤，岂有曾子终皇皇。","借令不幸贱且死，后日犹为班与扬。"]},{"t":"戴不胜","f":"五言律诗","c":["昔在宋王所，皆非薛居州。","区区一不胜，辛苦亦何求。","怀禄讵有耻，知命乃无忧。","此士自可怜，能复识此不。"]},{"t":"霹雳沟","f":"五言绝句","c":["霹雳沟西路，柴荆四五家。","忆曾骑款段，随意入桃花。"]},{"t":"霾风","f":"五言律诗","c":["霾风摧万物，暴雨膏九州。","卉花何其多，天阙亦已稠。","白日不照见，乾坤莽悲愁。","时也独奈何，我歌无有求。"]},{"t":"云之祁祁答董传","f":"楚辞体","c":["云之祁祁，或雨于渊。","苗之翘翘，或槁于田。","云之祁祁，或雨于野。","有槁于田，岂不自我。","荟兮其隮，其在西郊。","匪我为之，我歌且谣。","蔚兮其复，南山之侧。","我歌且谣，维以育德。"]},{"t":"示杨德逢","f":"词","c":["我行其野，春日迟迟。","有菀者柳，在水之湄。","有鸣仓庚，岂曰不时。","求其友声，颉之颃之。","嗟我怀人，何日忘之。","六日不詹，方何为期。","期逝不至，我心西悲。","跂予望之，其室则迩。","一者之来，我心则喜。","我之怀矣，升彼虚矣。","爱而不见，云何吁矣。"]},{"t":"示道光及安大师","f":"词","c":["春日载阳，陟彼高冈。","乐彼之园，维水泱泱。","维笋及蒲，既生既育。","拚飞维鸟，集于灌木。","嘤其鸣矣，乱我心曲。","有怀二人，在彼空谷。","既往既来，独寐寤宿。","陟则在巘，或降于阿。","瞻望弗及，伤如之何。"]},{"t":"猎较诗","f":"词","c":["猎较猎较，谁禽我有。","国人之惏，君子所丑。","猎较猎较，祭占其祥。","国人之序，君子何伤。"]},{"t":"新田诗","f":"词","c":["离离新田，其下流水。","孰知其初，灌莽千里。","其南背江，其北逾淮。","父抱子扶，十百其来。","其来仆仆，镘我新屋。","赵侯劬之，作者不饥。","岁仍大熟，饱及鸡鹜。","僦船与车，四鄙出谷。","今游者处，昔止者流。","维昔牧我，不如今侯。","侯来适野，不有观者。","税于水滨，问我鳏寡。","侯其归矣，三岁于兹。","谁能止侯，我往求之。"]},{"t":"潭州新学诗","f":"词","c":["有嘉新学，潭守所作。","守者谁欤，仲庶氏吴。","振养矜寡，衣之褰襦。","黔首鼓歌，吏静不求。","乃相庙序，生师所庐。","上漏旁穿，燥湿不除。","曰嘻迁哉，迫阨卑污。","当其坏时，适可以谋。","营地虑工，伐楩楠槠。","撤故就新，为此渠渠。","潭人来止，相语而喜。","我知视成，无豫经始。","公升在堂，从者如水。","公曰诲汝，潭之士子。","古之读书，凡以为己。","躬行孝悌，由义而仕。","神听汝助，况于闾里。","无实而荂，非圣自是。","虽大得意，吾犹汝耻。","士下其手，公言无尤。","请诗我歌，以远公休。"]},{"t":"西太一宫楼","f":"词","c":["草际芙蕖零落，水边杨柳攲斜。","日暮炊烟孤起，不知鱼网谁家。"]},{"t":"宫词","f":"词","c":["六宅新妆促锦，三宫巧仗丛花。","一片黄云起处，内人遥认官家。"]},{"t":"题西太一宫壁二首 其二","f":"词","c":["三十年前此路，父兄持我东西。","今日重来白首，欲寻陈迹都迷。"]},{"t":"题西太一宫壁二首 其一","f":"词","c":["草色浮云漠漠，树阴落日潭潭。","三十六陂流水，白头想见江南。"]},{"t":"题舒州山谷寺石牛洞泉穴","f":"词","c":["水泠泠而北出，山靡靡而旁围。","欲穷源而不得，竟怅望以空归。"]},{"t":"入塞","f":"七言绝句","c":["荒云凉雨水悠悠，鞍马东西鼓吹休。","尚有燕人数行泪，回身却望塞南流。"]},{"t":"千秋岁引 其三 秋景","f":"词","c":["别馆寒砧，孤城画角，一派秋声入寥廓。","东归燕从海上去，南来雁向沙头落。","楚台风，庾楼月，宛如昨。","无奈被些名利缚！","无奈被它情耽阁！","可惜风流总闲却！","当初谩留华表语，而今误我秦楼约。","梦阑时，酒醒后，思量著。"]},{"t":"忆江南","f":"七言绝句","c":["城南城北万株花，池面冰消水见沙。","回首江南春更好，梦为蝴蝶亦还家。"]},{"t":"出塞","f":"七言绝句","c":["涿州沙上饮盘桓，看舞《春风小契丹》。","塞雨巧催燕泪落，濛濛吹湿汉衣冠。"]},{"t":"甘露歌","f":"词","c":["折得一枝香在手。","人间应未有。","疑是经春雪未消。","今日是何朝。","尽日含毫难比兴。","都无色可并。","万里晴天何处来。","真是屑琼瑰。","天寒日暮山谷里。","的砾愁成水。","池上渐多枝上稀。","唯有故人知。"]},{"t":"伤春怨","f":"词","c":["雨打江南树。","一夜花开无数。","绿叶渐成阴，下有游人归路。","与君相逢处。","不道春将暮。","把酒祝东风，且莫恁、匆匆去。"]},{"t":"西江月 红梅","f":"词","c":["梅好惟嫌淡伫，天教薄与胭脂。","真妃初出华清池。","酒入琼姬半醉。","东阁诗情易动，高楼玉管休吹。","北人浑作杏花疑。","惟有青枝不似。"]},{"t":"芳草","f":"五言绝句","c":["芳草知谁种，缘阶已数丛。","无心与时竞，何苦绿匆匆。"]},{"t":"诉衷情令 其三 和俞秀老鹤词","f":"词","c":["茫然不肯住林间。","有处即追攀。","将他死语图度，怎得离真丹。","浆水价，匹如闲。","也须还。","何如直截，踢倒军持，赢取沩山。"]},{"t":"诉衷情令 其四 和俞秀老鹤词","f":"词","c":["营巢燕子逞翱翔。","微志在雕梁。","碧云举翮千里，其奈有鸾皇。","临济处，德山行。","果承当。","自时降住，一切天魔，扫地焚香。"]},{"t":"诉衷情令 其五 又和秀老","f":"词","c":["莫言普化祗颠狂。","真解作津梁。","蓦然打个筋斗，直跳过羲皇。","临济处，德山行。","果承当。","将他建立，认作心诚，也是寻香。"]},{"t":"诉衷情令 其一 和俞秀老鹤词","f":"词","c":["常时黄色见眉间。","松桂我同攀。","每言天上辛苦，不肯饵金丹。","怜水静，爱云闲。","便忘还。","高歌一曲，岩谷迤逦，宛似商山。"]},{"t":"诉衷情令 其二 和俞秀老鹤词","f":"词","c":["练巾藜杖白云间。","有兴即跻攀。","追思往昔如梦，华毂也曾丹。","尘自扰，性长闲。","更无还。","达如周召，穷似丘轲，祗个山山。"]},{"t":"郊行","f":"七言绝句","c":["柔桑采尽绿阴稀，芦箔蚕成密茧肥。","聊向村家问风俗，如何勤苦尚凶饥。"]},{"t":"金明池","f":"七言律诗","c":["宜秋西望碧参差，忆看乡人禊饮时。","斜倚水开花有思，缓随风转柳如痴。","青天白日春常好，绿发朱颜老自悲。","跋马未堪尘满眼，夕阳偷理钓鱼丝。"]},{"t":"雨霖铃","f":"词","c":["孜孜矻矻。","向无明里、强作窠窟。","浮名浮利何济，堪留恋处，轮回仓猝。","幸有明空妙觉，可弹指超出。","缘底事、抛了全潮，认一浮沤作瀛渤。","本源自性天真佛。","祗些些、妄想中埋没。","贪他眼花阳艳，谁信道、本来无物。","一旦茫然，终被阎罗老子相屈。","便纵有、千种机筹，怎免伊唐突。"]},{"t":"南乡子 其一","f":"词","c":["嗟见世间人。","但有纤毫即是尘。","不住旧时无相貌，沈沦。","祗为从来认识神。","作么有疏亲。","我自降魔转法轮。","不是摄心除妄想，求真。","幻化空身即法身。"]},{"t":"南乡子 其二","f":"词","c":["自古帝王州。","郁郁葱葱佳气浮。","四百年来成一梦，堪愁。","晋代衣冠成古丘。","绕水恣行游。","上尽层城更上楼。","往事悠悠君莫问，回头。","槛外长江空自流。"]},{"t":"南浦","f":"七言绝句","c":["南浦东冈二月时，物华撩我有新诗。","含风鸭绿粼粼起，弄日鹅黄袅袅垂。"]},{"t":"南浦","f":"五言绝句","c":["南浦随花去，回舟路已迷。","暗香无觅处，日落画桥西。"]},{"t":"钟山即事","f":"七言绝句","c":["涧水无声绕竹流，竹西花草弄春柔。","茅檐相对坐终日，一鸟不鸣山更幽。"]},{"t":"桂枝香","f":"词","c":["登临送目。","正故国晚秋，天气初肃。","千里澄江似练，翠峰如簇。","归帆去棹斜阳里，背西风，酒旗斜矗。","彩舟云淡，星河鹭起，画图难足。","念往昔、繁华竞逐，叹门外楼头，悲恨相续。","千古凭高，对此漫嗟荣辱。","六朝旧事如流水，但寒烟、衰草凝绿。","至今商女，时时犹唱，《后庭》遗曲。"]},{"t":"浣溪沙","f":"七言古诗","c":["百亩中庭半是苔。","门前白道水萦回。","爱闲能有几人来。","小院回廊春寂寂，山桃溪杏两三栽。","为谁零落为谁开。"]},{"t":"浪淘沙令","f":"词","c":["伊吕两衰翁。","历遍穷通。","一为钓叟一耕佣。","若使当时身不遇，老了英雄。","汤武偶相逢。","风虎云龙。","兴王祗在笑谈中。","直至如今千载后，谁与争功。"]},{"t":"望江南 其三 归依三宝赞","f":"词","c":["归依佛，弹指越三祗。","愿我速登无上觉，还如佛坐道场时。","能智又能悲。"]},{"t":"望江南/忆江南 其一 归依三宝赞","f":"词","c":["归依众，梵行四威仪。","愿我遍游诸佛土。","十方贤圣不相离。","永灭世间痴。"]},{"t":"望江南/忆江南 其二 归依三宝赞","f":"词","c":["归依法，法法不思议。","愿我六根常寂静，心如宝月映琉璃。","了法更无疑。"]},{"t":"望江南 其四 归依三宝赞","f":"词","c":["三界里，有取总灾危。","普愿从生同我愿，能于空有善思惟。","三宝共住持。"]},{"t":"清平乐","f":"词","c":["云垂平野。","掩映竹篱茅舍。","阒寂幽居实潇洒。","是处绿娇红冶。","丈夫运用堂堂。","且莫五角六张。","若有一卮芳酒，逍遥自在无妨。"]},{"t":"渔家傲 其一","f":"词","c":["灯火已收正月半。","山南山北花撩乱。","闻说荐亭新水漫。","骑款段。","穿云入坞寻游伴。","却拂僧床褰素幔。","千岩万壑春风暖。","一弄松声悲急管。","吹梦断。","西看窗日犹嫌短。"]},{"t":"渔家傲 其二","f":"词","c":["平岸小桥千嶂抱，揉蓝一水萦花草。","茅屋数间窗窈窕。","尘不到，时时自有春风扫。","午枕觉来闻语鸟，攲眠似听朝鸡早。","忽忆故人今总老。","贪梦好，茫然忘了邯郸道。"]},{"t":"忆王孙 梦中作","f":"词","c":["隔岸桃花红未半。","枝头已有蜂儿乱。","惆怅武陵人不管。","清梦断。","亭亭伫立春宵短。"]},{"t":"菩萨蛮 集句","f":"词","c":["海棠乱发皆临水。","君知此处花何似。","凉月白纷纷。","香风隔岸闻。","啭枝黄鸟近。","隔岸声相应。","随意坐莓苔。","飘零酒一杯。"]},{"t":"菩萨蛮","f":"词","c":["数家茅屋闲临水。","单衫短帽垂杨里。","花是去年红，吹开一夜风。","梢梢新月偃。","午醉醒来晚。","何物最关情。","黄鹂三两声。"]},{"t":"谒金门","f":"词","c":["春又老。","南陌酒香梅小。","遍地落花浑不扫。","梦回情意悄。","红笺寄与添烦恼。","细写相思多少。","醉后几行书字小。","泪痕都揾了。"]},{"t":"棋","f":"七言绝句","c":["莫将戏事扰真情，且可随缘道我赢。","战罢两奁分白黑，一枰何处有亏成。"]},{"t":"虞美人","f":"楚辞体","c":["虞美人，态浓意远淑且真。","同辇随君侍君侧，六宫粉黛无颜色。","楚歌四面起，形势反苍黄。","夜闻马嘶晓无迹，蛾眉萧飒如秋霜。","汉家离宫三十六，缓歌慢舞凝丝竹。","人间举眼尽堪悲，独在阴崖结茅屋。","美人为黄土，草木皆含愁。","红房紫莟处处有，听曲低昂如有求。","青天漫漫覆长路，今人犁田昔人墓。","虞兮虞兮奈若何，不见玉颜空死处。"]},{"t":"句 其十一","f":"七言古诗","c":["萧萧抟黍声中日，漠漠舂锄影外天。"]},{"t":"句","f":"七言古诗","c":["雪底黄精与不疏。"]},{"t":"句 其四","f":"七言古诗","c":["隐几先生未忘物，葛陂犹问化龙身。"]},{"t":"句","f":"七言古诗","c":["大木百围生远籁，朱玄三叹有一音。"]},{"t":"句 其十","f":"五言古诗","c":["青山扪虱坐，黄鸟挟书眠。"]},{"t":"句 其九","f":"七言古诗","c":["夕阳到处花偏暖。"]},{"t":"句","f":"七言古诗","c":["哀俗易高名已振，途险难尽学须强。"]},{"t":"句 其八","f":"七言古诗","c":["霜筠雪竹钟山寺，投老归欤寄此生。"]},{"t":"句 其三","f":"五言古诗","c":["昔时江令宅，今日段侯家。"]},{"t":"句 其十五","f":"五言古诗","c":["乞米助㾕镏。"]},{"t":"句 其十八","f":"七言古诗","c":["苑阆仙人何处觅，灵槎使者几时回。"]},{"t":"句","f":"七言古诗","c":["周迥莫有千株叶。"]},{"t":"岁晚","f":"五言律诗","c":["月映林塘澹，风含笑语凉。","俯窥怜绿净，小立伫幽香。","携幼寻新的，扶衰坐野航。","延缘久未已，岁晚惜流光。"]},{"t":"题回峰寺诗","f":"五言律诗","c":["山势欲压海，禅扃向此开。","鱼龙腥不到，日月影先来。","树色秋擎出，钟声浪答回。","何期乘吏役，暂此拂尘埃。"]},{"t":"次韵游山门寺望文脊山","f":"五言古诗","c":["宣城百山间，文脊尤奇峰。","拔出飞鸟上，图画难为容。","闻昔有幽人，扪萝追赤松。","遗形此古室，孤坐鹿裘重。","人去邈不反，洞壑空藏龙。","侧行苍崖烟，俯仰求灵踪。","游者如可得，甘弃万户封。","安能久尘土，倾倒相迎逢。"]},{"t":"秋兴有感","f":"五言绝句","c":["宿雨清畿甸，朝阳丽帝城。","丰年人乐业，陇上踏歌声。"]},{"t":"别和甫赴南徐","f":"七言绝句","c":["都城落日马萧萧，雨压春风暗柳条。","天际归艎那可望，只将心寄海门潮。"]},{"t":"次韵再游城西李园","f":"七言律诗","c":["京师花木类多奇，常恨春归人未归。","车马喧喧走尘土，园林处处锁芳菲。","残红已落香犹在，羁客多伤涕自挥。","我亦悠悠无事者，约君联骑访郊圻。"]},{"t":"送致政朱郎中东归","f":"七言律诗","c":["平生不省问田园，白首忘怀道更尊。","已上印书通北阙，稍留冠盖饯东门。","冯唐老有为郎恋，疏广终无任子恩。","今日荣归人所羡，两儿腰绶拥高轩。"]},{"t":"寄程给事","f":"七言律诗","c":["忆昔都门手一携，春禽初向苧萝啼。","梦回金殿风光别，吟到银河月影低。","舞急锦腰迎十八，酒酣金盏照东西。","何时得遂扁舟去，邂逅从君访剡溪。"]},{"t":"送程公辟得谢归姑苏","f":"七言律诗","c":["东归行路叹贤哉，碧落新除宠上才。","白傅林塘传画去，吴王花鸟入诗来。","唱酬自有微之在，谈笑应容逸少陪。","除此两翁相见外，不知三径为谁开。"]},{"t":"和叔才岸傍古庙","f":"五言律诗","c":["树老垂缨乱，祠荒向水开。","偶人经雨踣，古屋为风摧。","野鸟栖尘座，渔郎奠竹杯。","欲传山鬼曲，无奈楚词哀。"]},{"t":"送王郎中知江阴","f":"七言律诗","c":["持归霄汉青绫被，去看吴都白马潮。","叠鼓渡江寒浪伏，鸣铙入境野云飘。","鱼穿杨柳誇鲸脍，人采芙蓉学细腰。","家有三槐为太守，弟兄谁似李文饶。"]},{"t":"三月十日韩子华招饮归城","f":"七言古诗","c":["清明晓赴韩侯家，自买白杏丁香花。","雀眼涂金银篾笼，贮在当庭呼舞娃。","舞娃聊捧笑向客，不顾插坏新乌纱。","朝来我舍报生子，贺劝大白浮红霞。","酒狂有持梧桐板，暴谑一似渔阳挝。","袒裼击鼓祢处士，当时偶脱猛虎牙。","褊衷不容又何益，鹦鹉洲上空蒹葭。"]},{"t":"句 其二","f":"七言古诗","c":["浓绿万枝红一点，动人春色不须多。"]},{"t":"明妃曲二首 其二","f":"七言古诗","c":["明妃初嫁与胡儿，毡车百两皆胡姬。","含情欲说独无处，传与琵琶心自知。","黄金捍拨春风手，弹看飞鸿劝胡酒。","汉宫侍女暗垂泪，沙上行人却回首。","汉恩自浅胡自深，人生乐在相知心。","可怜青冢已芜没，尚有哀弦留至今。"]},{"t":"彼狂","f":"七言古诗","c":["上古杳默无人声，日月不忒山川平。","人与鸟兽相随行，祖孙一死十百生。","万物不给乃相兵，伏羲画法作后程。","渔虫猎兽宽群争，势不得已当经营。","非以示世为聪明，方分类别物有名。","夸贤尚功列耻荣，蛊伪日巧雕元精。","至言一出众辄惊，上智闭匿不敢成。","因时就俗救刖黥，惜哉彼狂以文鸣。","强取色乐要聋盲，震荡沈浊终无清。","诙诡徒乱圣人氓，岂若泯默死蚕耕。"]},{"t":"寄题郢州白雪楼","f":"七言古诗","c":["折杨黄华笑者多，阳春白雪和者少。","知音四海无几人，况乃区区郢中小。","千载相传始欲慕，一时独唱谁能晓。","古心以此分冥冥，俚耳至今徒扰扰。","朱楼碧瓦何年有，榱桷连空欲惊矫。","郢人烂漫醉浮云，郢女参差蹑飞鸟。","丘墟馀响难再得，栏槛兹名复谁表。","我来欲歌声更吞，石城寒江暮云绕。"]},{"t":"送谢师宰赴任楚州 其二","f":"七言律诗","c":["昆崙一支流向东，七月八月船如风。","爱君少壮此行乐，恨我留连成老翁。","神头两岸水无穷，伏槛荷花满地红。","当时不得君携手，今日山川在眼中。"]},{"t":"与道原过西庄遂游宝乘道原游西庵遂至草堂宝乘寺二首 其二","f":"五言律诗","c":["亲朋会合少，时序感伤多。","胜践聊为乐，清谈可当歌。","微风淡水竹，净日暖烟萝。","兴极犹难尽，当如薄暮何。"]},{"t":"发馆陶","f":"五言律诗","c":["促辔数残更，似闻鸡一鸣。","春风马上梦，沙路月中行。","笳鼓远多思，衣裘寒始轻。","稍知田父稳，灯火闭柴荆。"]},{"t":"和王微之秋浦望齐山感李太白杜牧之","f":"七言律诗","c":["齐山置酒菊花开，秋浦闻猿江上哀。","此地流传空笔墨，昔人埋没已蒿莱。","平生志业无高论，末世篇章有逸才。","尚得使君驱五马，与寻陈迹久徘徊。"]},{"t":"寄题思轩","f":"七言律诗","c":["名郎此地昔徘徊，天诱良孙接踵来。","万屋尚歌馀泽在，一轩还向旧堂开。","右军笔墨空残沼，内史文章祇废台。","邑子从今誇胜事，岂论王谢世称才。"]},{"t":"除夜寄舍弟","f":"七言律诗","c":["一尊聊有天涯忆，百感翻然醉里眠。","酒醒灯前犹是客，梦回江北已经年。","佳时流落真何得，胜事蹉跎只可怜。","唯有到家寒食在，春风因泛滪溪船。"]},{"t":"题黄司理园","f":"五言绝句","c":["为忆去年梅，凌寒特地来。","闰前空腊尽，浑未有花开。"]},{"t":"泊雁","f":"五言律诗","c":["泊雁鸣深渚，收霞落晚川。","柝随风敛阵，楼映月低弦。","漠漠汀帆转，幽幽岸火然。","壑危通细路，沟曲绕平田。"]},{"t":"竹里","f":"七言绝句","c":["竹里编茅倚石根，竹茎疏处见前村。","闲眠尽日无人到，自有春风为扫门。"]},{"t":"耿天骘惠梨次韵奉酬三首 其一","f":"七言绝句","c":["故人家果独难忘，秋实初成便得尝。","直使紫花形味胜，岂能终日望咸阳。"]},{"t":"耿天骘惠梨次韵奉酬三首 其二","f":"七言绝句","c":["淮圃新阴百亩凉，分甘每得助秋尝。","张公大谷虽云美，谁肯苞苴出晋阳。"]},{"t":"耿天骘惠梨次韵奉酬三首 其三","f":"七言绝句","c":["甘滋南北共传誇，栽接还如老圃家。","谁谓交梨非外奖，因君浇灌已萌芽。"]},{"t":"北山有怀","f":"七言绝句","c":["香火因缘寄此山，主恩投老更人间。","伤心踯躅冈头路，明日春风自往还。"]},{"t":"定林院","f":"七言绝句","c":["穷谷经春不识花，新松老柏自攲斜。","慇勤更上山头望，白下城中有几家。"]},{"t":"独卧二首 其一","f":"七言绝句","c":["谁有锄耰不自操，可怜园地满蓬蒿。","欲寻春物无蹊径，独卧南床白日高。"]},{"t":"独卧二首 其二","f":"七言绝句","c":["茅檐午影转悠悠，门闭青苔水乱流。","百啭黄鹂看不见，海棠无数出墙头。"]},{"t":"仓颉","f":"词","c":["仓颉造书，不诂自明。","于乎多言，祇误后生。"]},{"t":"句 其一","f":"七言古诗","c":["衰俗易高名已振，险途难尽学须强。"]},{"t":"句 其五","f":"七言古诗","c":["内史文章只废台。"]},{"t":"句 其六","f":"七言古诗","c":["凌晓常行云气中。"]},{"t":"句 其十三","f":"七言古诗","c":["人生万事反覆多，道路后先能几何。"]},{"t":"句 其十四","f":"七言古诗","c":["浥霜火齐累累熟，噀露金苞冉冉香。"]},{"t":"句 其十六","f":"七言古诗","c":["雪底黄精兴不疏。"]},{"t":"句 其十七","f":"七言古诗","c":["周回莫有千株叶。"]},{"t":"玉簪","f":"七言绝句","c":["瑶池仙子宴流霞，醉里遗簪幻作花。","万斛浓香山麝馥，随风吹落到君家。"]},{"t":"句","f":"词","c":["衰俗易高名已振，险途难尽学须强。","浓绿万枝红一点，动人春色不须多。","昔时江令宅，今日段侯家。","隐几先生未忘物，葛陂犹问化龙身。","内史文章只废台。","凌晓常行云气中。","霜筠雪竹钟山寺，投老归欤寄此生。","夕阳到处花偏暖。","青山扪虱坐，黄鸟挟书眠。","萧萧抟黍声中日，漠漠舂锄影外天。","人生万事反覆多，道路后先能几何。","浥霜火齐累累熟，噀露金苞冉冉香。","乞米助㾕镏。","雪底黄精兴不疏。","周回莫有千株叶。","苑阆仙人何处觅，灵槎使者几时回。"]},{"t":"甘露歌","f":"词","c":["尽日含毫难比兴。","都无色可并。","万里晴天何处来。","真是屑琼瑰。"]},{"t":"甘露歌","f":"词","c":["天寒日暮山谷里。","的砾愁成水。","池上渐多枝上稀。","唯有故人知。"]},{"t":"菩萨蛮","f":"词","c":["数家茅屋闲临水。","单衫短帽垂杨里。","今日是何朝。","看予度石桥。","梢梢新月偃。","午醉醒来晚。","何物最关情。","黄鹂三两声。"]},{"t":"渔家傲","f":"词","c":["平岸小桥千嶂抱。","柔蓝一水萦花草。","茅屋数间窗窈窕。","尘不到。","时时自有春风扫。","午枕觉来闻语鸟。","敧眠似听朝鸡早。","忽忆故人今总老。","贪梦好。","茫然忘了邯郸道。"]},{"t":"望江南・忆江南","f":"词","c":["三界里，有取总灾危。","普愿众生同我愿，能於空有善思惟。","三宝共住持。"]},{"t":"清平乐","f":"词","c":["留春不住。","费尽莺儿语。","满地残红宫锦污。","昨夜南园风雨。","小怜初上琵琶。","晓来思绕天涯。","不肯画堂朱户，春风自在杨花。"]}]};